def fetch_te_world_lei(countries):
    """v1.262.0. Read the OECD Composite Leading Indicator for the given countries off
    TradingEconomics' STATIC per-country pages, using the same regex-on-stripped-HTML pattern
    _te() proves against this host every run. Returns {country: value}. CLI is amplitude-adjusted
    around 100, so anything outside 80..120 is nonsense and is rejected. Never raises."""
    out = {}
    for name in countries:
        ent = _TE_LEI_COUNTRIES.get(name)
        if not ent:
            continue
        slug, disp = ent
        try:
            rr = requests.get('https://tradingeconomics.com/%s/composite-leading-indicator' % slug,
                              headers={'User-Agent': UA}, timeout=12)
            if rr.status_code != 200:
                log(f'  [TE lei] {name} -> HTTP {rr.status_code}')
                continue
            txt = re.sub(r'<[^>]+>', ' ', rr.text)
            m = re.search(r'Composite Leading Indicator in ' + re.escape(disp)
                          + r'[^0-9\-]{0,60}(\d{2,3}(?:\.\d{1,2})?)', txt, re.I)
            if not m:
                log(f'  [TE lei] {name} -> value not matched on page')
                continue
            v = float(m.group(1))
            if not (80.0 <= v <= 120.0):
                log(f'  [TE lei] {name} = {v} outside sane CLI band 80..120 -- ignored')
                continue
            out[name] = round(v, 2)
        except Exception as e:
            log(f'  [TE lei] {name} failed: {type(e).__name__}')
    # v1.314.7 VERIFIED PROXY FALLBACKS for the two countries the OECD CLI no longer serves:
    # OECD compiles CLIs only for G20 + Spain + zone aggregates -- Switzerland's was DISCONTINUED
    # (FRED CHELOLITONOSTSAM dead 2022-11) and FRED's EA19 series likewise. Both proxies verified
    # live with real fetches before wiring: Euro-area -> TE economic-optimism-index (EC's Economic
    # Sentiment Indicator, mean=100 composite, June-2026 print 95.0); Switzerland -> TE
    # business-confidence (KOF Economic Barometer, ETH Zurich's leading composite, mean=100,
    # 96.1 Mar-2026). Same static-page regex pattern _te() proves on this host every run. The proxy
    # basis is stamped so the tab never implies these are the OECD CLI. Wider sanity band (both
    # composites dipped to ~50-65 in 2020, outside the CLI's 80..120).
    fetch_te_world_lei.last_notes = {}
    _FALLBACKS = {
        'Euro-area':   ('euro-area', 'economic-optimism-index',
                        # v1.314.11: the page's stable prose says 'Economic Optimism Index In the
                        # Euro Area decreased to 96.60 points' (real fetch 2026-07-27); accept both
                        # labels and anchor on the value's own 'points' suffix so a year can't match.
                        r'Economic (?:Optimism Index|Sentiment Indicator)[\s\S]{0,160}?'
                        r'(\d{2,3}(?:\.\d{1,2})?)\s*points',
                        'ESI (EC survey) proxy \u2014 OECD CLI discontinued', (50.0, 140.0)),
        'Switzerland': ('switzerland', 'business-confidence',
                        r'KOF (?:Economic Barometer|Leading Indicators?)[^0-9]{0,90}?(\d{2,3}(?:\.\d{1,2})?)',
                        'KOF Economic Barometer proxy \u2014 OECD CLI discontinued', (50.0, 140.0)),
    }
    for name, (slug, page, pat, note, band) in _FALLBACKS.items():
        if name in out or name not in countries:
            continue
        try:
            rr = requests.get(f'https://tradingeconomics.com/{slug}/{page}',
                              headers={'User-Agent': UA}, timeout=12)
            if rr.status_code != 200:
                log(f'  [TE lei proxy] {name} ({page}) -> HTTP {rr.status_code}')
                warn(f'[lei diag] {name}: {page} HTTP {rr.status_code}, body[:80]={rr.text[:80]!r}')
                continue
            txt = re.sub(r'<[^>]+>', ' ', rr.text)
            m = re.search(pat, txt, re.I)
            if not m:
                log(f'  [TE lei proxy] {name} ({page}) -> value not matched')
                # v1.314.8 DIAG: page reached but regex missed -- ship the snippet around the label
                # so the real prose is visible from data.json and the pattern is fixed on evidence.
                _lbl = 'Sentiment Indicator' if 'optimism' in page else 'KOF'
                _i = txt.find(_lbl)
                _snip = txt[max(0, _i - 20):_i + 120].strip() if _i >= 0 else txt[:140].strip()
                warn(f'[lei diag] {name}: {page} HTTP 200 but pattern missed; '
                     f'label_found={_i >= 0}; snippet={_snip!r}')
                continue
            v = float(m.group(1))
            if not (band[0] <= v <= band[1]):
                log(f'  [TE lei proxy] {name} = {v} outside sane band {band} -- ignored')
                _ctx = txt[max(0, m.start() - 20):m.end() + 40].strip()
                warn(f'[lei diag] {name}: {page} matched {v} OUTSIDE band {band}; '
                     f'context={_ctx[:60]!r}')
                continue
            out[name] = round(v, 2)
            fetch_te_world_lei.last_notes[name] = note
            log(f'  [TE lei proxy] {name} = {v} ({note})')
        except Exception as e:
            log(f'  [TE lei proxy] {name} failed: {type(e).__name__}')
            warn(f'[lei diag] {name}: {page} EXCEPTION {type(e).__name__}: {str(e)[:80]}')
    if out:
        log('  [TE lei] rescued from TradingEconomics (OECD CLI): '
            + ', '.join(f'{k}={v}' for k, v in sorted(out.items())))
    return out


def fetch_te_econ(keys):
    """v1.261.0. Second rescue tier: read US macro figures off TradingEconomics' STATIC pages using
    the EXACT regex-on-stripped-HTML pattern _te() already proves against this host every run for
    Pakistan. One GET per key (only for keys FRED AND TradingView both failed, so normally zero).
    Sanity-banded. Never raises."""
    out = {}
    for key in keys:
        ent = _TE_ECON_MAP.get(key)
        if not ent:
            continue
        slug, label = ent
        try:
            rr = requests.get('https://tradingeconomics.com/united-states/' + slug,
                              headers={'User-Agent': UA}, timeout=12)
            if rr.status_code != 200:
                log(f'  [TE econ] {key} ({slug}) -> HTTP {rr.status_code}')
                continue
            txt = re.sub(r'<[^>]+>', ' ', rr.text)
            m = re.search(label + r'[^0-9\-]{0,60}(-?\d{1,4}(?:\.\d{1,2})?)', txt, re.I)
            if not m:
                log(f'  [TE econ] {key} ({slug}) -> label "{label}" not matched')
                continue
            v = float(m.group(1))
            lo, hi = _TE_ECON_BANDS.get(key, (-1e9, 1e9))
            if not (lo <= v <= hi):
                log(f'  [TE econ] {key} = {v} outside sane band {lo}..{hi} -- ignored')
                continue
            out[key] = round(v, 2)
        except Exception as e:
            log(f'  [TE econ] {key} ({slug}) failed: {type(e).__name__}')
    if out:
        log('  [TE econ] rescued from TradingEconomics: '
            + ', '.join(f'{k}={v}' for k, v in sorted(out.items())))
    return out


def fetch_tv_econ(keys):
    """v1.325.0 (was v1.259.0). Read US macro LEVELS from TradingView's ECONOMICS namespace for the
    given scanner keys. ONE batched POST per candidate universe, through the identical symbols-POST
    call this scanner already proves every run for TVC:RUT and every price it fetches -- no new
    plumbing, no new dependency, no new credential.

    v1.325.0 fixes the universe. v1.324.0 posted ECONOMICS: tickers to /america/scan (US EQUITIES),
    which cannot resolve them, so this returned {} on every run and the whole FRED->TV swap was dead
    on arrival while looking perfectly healthy (the fallback is byte-identical, which is exactly why
    it hid). We now walk _TV_ECON_UNIVERSES in order and stop at the first universe that returns a
    usable value. Every attempt emits a capped diag into meta.warnings so the next run identifies the
    working universe from data.json alone -- the runner's own Actions log is HTTP 403 to us.

    Returns {key: float} for whatever came back inside its sanity band. NEVER raises: any failure
    path returns {} and the caller falls straight back to FRED, byte-identical to v1.323.0."""
    pairs = [(k, _TV_ECON_MAP[k]) for k in keys if k in _TV_ECON_MAP]
    if not pairs:
        return {}
    tickers = [sym for _, sym in pairs]
    attempts = []
    for universe, extra in _TV_ECON_UNIVERSES:
        out = {}
        code = rows_n = None
        head = ''
        try:
            payload = {'symbols': {'tickers': tickers}, 'columns': ['close']}
            payload.update(extra)
            r = requests.post('https://scanner.tradingview.com/%s/scan' % universe,
                              json=payload, headers={'User-Agent': UA}, timeout=20)
            code = r.status_code
            if code != 200:
                head = (r.text or '')[:80]
                attempts.append('%s:HTTP%s' % (universe, code))
                warn('[TV econ diag] %s/scan HTTP %s, body[:80]=%r' % (universe, code, head))
                continue
            rows = (r.json().get('data') or [])
            rows_n = len(rows)
            by_sym = {}
            for i, row in enumerate(rows):
                sym = row.get('s') or (tickers[i] if i < len(tickers) else None)
                d = row.get('d') or []
                if sym and d:
                    by_sym[sym] = d[0]
            for key, sym in pairs:
                v = by_sym.get(sym)
                if not isinstance(v, (int, float)):
                    continue
                lo, hi = _TV_ECON_BANDS.get(key, (-1e9, 1e9))
                if not (lo <= float(v) <= hi):
                    log('  [TV econ] %s (%s) = %s outside sane band %s..%s -- ignored'
                        % (key, sym, v, lo, hi))
                    continue
                out[key] = round(float(v), 2)
            if out:
                warn('[TV econ ok] universe=%s serving %s' % (universe, ', '.join(sorted(out))))
                log('  [TV econ] %s/scan served %d level(s): ' % (universe, len(out))
                    + ', '.join('%s=%s' % (k, v) for k, v in sorted(out.items())))
                return out
            attempts.append('%s:rows%s/usable0' % (universe, rows_n))
            warn('[TV econ diag] %s/scan HTTP 200, rows=%s, no usable value for %s'
                 % (universe, rows_n, tickers[:2]))
        except Exception as e:
            attempts.append('%s:%s' % (universe, type(e).__name__))
            warn('[TV econ diag] %s/scan %s: %s' % (universe, type(e).__name__, str(e)[:80]))
    log('  [TV econ] no universe served the ECONOMICS namespace this run (%s) '
        '-- FRED keeps every level, no regression' % '; '.join(attempts))
    return {}


def fetch_us_macros():
    import re
    log('Fetching US macros from FRED...')
    if not FRED_KEY:
        warn('FRED_API_KEY not set, using last-good US macros')
        return EXISTING.get('macros', {}).get('us', {})

    try:
        from fredapi import Fred
        fred = Fred(api_key=FRED_KEY)

        series = {
            'fed_rate':       'DFEDTARU',
            'core_pce':       'PCEPILFE',
            'cpi_yoy':        'CPIAUCNS',   # v1.283.0 AUDIT FIX: headline (NSA) basis. The SA
                                             # series (CPIAUCSL) computed 3.73%% while the official
                                             # June headline every source quotes was 3.5%% -- the
                                             # tile must match the number the world compares against.
            'ppi_yoy':        'PPIFIS',    # PPI Final Demand (headline PPI, SA) -> YoY like CPI
            'ppi_core_yoy':   'PPIFES',    # PPI Final Demand less food & energy (core PPI) -> YoY
            'us_10y':         'DGS10',
            'us_2y':          'DGS2',
            'unemployment':   'UNRATE',
            'umcsi':          'UMCSENT',
            'mfg_emp':        'MANEMP',
            'gdp_growth':     'A191RL1Q225SBEA',
            'industrial_prod':'INDPRO',
            'hy_spread':      'BAMLH0A0HYM2',
            'permits':        'PERMIT',
        }

        out = {}
        _fred_failed_keys = []      # v1.259.0: keys FRED could not deliver -> TradingView rescue

        # v1.324.0 FRED->TV LEVEL SWAP (owner-instructed, to save time). TradingView ECONOMICS
        # serves these LEVELS in ONE ~3s batched POST (the call this scanner proves every run for
        # prices), while FRED swings 15-101s on latency and caused the 10m22s outlier run. TV is
        # now PRIMARY for the verified mapped keys; FRED still fetches every OTHER series (the
        # trend arrows need FRED series). cpi_yoy is EXCLUDED -- it keeps its full FRED series
        # path (cpi_diag + trend fields) plus the existing v1.285.0 official-headline override,
        # so nothing is double-handled. TV failure/empty -> _tv_pre stays {} and everything below
        # is byte-identical to before (regression-safe). Honest trade, v1.263.0 world_lei
        # precedent: a TV-served key shows no fresh _mom trend that run (level is current-day).
        TV_ECON_PRIMARY = True     # one-line revert to FRED-first
        _tv_pre = {}
        if TV_ECON_PRIMARY:
            try:
                _tv_pre = {k: v for k, v in (fetch_tv_econ(list(_TV_ECON_MAP)) or {}).items()
                           if isinstance(v, (int, float)) and k != 'cpi_yoy'}
                if _tv_pre:
                    log('  [TV econ primary] serving levels for ' + ', '.join(sorted(_tv_pre)))
            except Exception:
                _tv_pre = {}

        def _fred_series(sid):
            # v1.11: throttle + retry-with-backoff to avoid FRED 429 'Too Many Requests'.
            # No new source needed — same free API key, just paced (3 tries: 0/1.5/4s).
            last = None
            for attempt, backoff in enumerate((0, 1.5, 4.0)):
                if backoff:
                    time.sleep(backoff)
                try:
                    return fred.get_series(sid).dropna()
                except Exception as e:
                    last = e
                    _em = str(e).lower()
                    # F2 REAL FIX (v1.253.0). The old classifier decided transient-vs-hard by STRING
                    # MATCHING the exception message -- and run-651 proved it broken: 4 series failed
                    # with an EMPTY message ("FRED core_pce (PCEPILFE) failed: None"), 'none' matched
                    # no marker, so every one was ruled NON-transient and raised on attempt 1 with
                    # ZERO retries. The retry loop has therefore never fired for this failure mode.
                    # (I previously struck F2 as "already closed at v1.66.0" after reading the code
                    # and seeing a retry loop -- I verified the code existed, not that it works.)
                    # INVERTED: retry EVERYTHING by default, and only refuse to retry the small set
                    # of provably PERMANENT errors. A wrong series id is a code bug we would see once
                    # and costs 5.5s of retries -- cheap; a silently-dropped macro series corrupts the
                    # compass every run -- expensive. Default to the cheap mistake.
                    _permanent = ('bad request' in _em or '400' in _em or 'not exist' in _em
                                  or 'invalid series' in _em or 'api key' in _em or '403' in _em)
                    if _permanent:
                        raise
                    # v1.258.0 CIRCUIT BREAKER. v1.253.0 inverted this to "retry everything", which
                    # RECOVERS a flaky series (industrial_prod came back, warnings 4 -> 0) -- but it
                    # costs 5.5s of backoff per failed series, and that is fine for a BLIP and awful
                    # when FRED is DOWN. A source that has failed repeatedly is not flaky, it is out;
                    # retrying the rest of the list just buys the same answer slower. After
                    # _FRED_FAIL_LIMIT distinct failures in one run, stop retrying and take last-good
                    # immediately -- keeping the recovery benefit for blips while capping the damage.
                    if _FRED_FAILS[0] >= _FRED_FAIL_LIMIT:
                        raise
                    continue   # anything else (incl. an empty/None message) -> wait and retry
            raise last
        # v1.264.0 PARALLEL PREFETCH. The loop below is UNCHANGED -- every YoY computation,
        # trend, band and error path is byte-identical. Only the FETCHING is now concurrent:
        # all series are pulled up front through _fred_gate() (2 req/s, FRED's own ceiling)
        # and the loop then reads them from cache instead of blocking on each in turn.
        # 15 x (0.6s sleep + ~4.7s wait) = 78.9s  ->  15 / 2 req/s ~= 8s + latency.
        _pre = {}
        try:
            import concurrent.futures as _cf
            _FRED_NEXT_SLOT[0] = 0.0
            def _pull(_sid):
                _fred_gate()
                return _fred_series(_sid)
            with _cf.ThreadPoolExecutor(max_workers=FRED_WORKERS) as _ex:
                _futs = {_ex.submit(_pull, _sid): _k for _k, _sid in series.items() if _k not in _tv_pre}
                for _f in _cf.as_completed(_futs):
                    _k = _futs[_f]
                    try:
                        _pre[_k] = _f.result()
                    except Exception as _pe:
                        _pre[_k] = _pe          # re-raised in the loop -> same error path as before
            log(f'  [FRED] prefetched {sum(1 for v in _pre.values() if not isinstance(v, Exception))}'
                f'/{len(series)} series in parallel ({FRED_WORKERS} workers, gate 2 req/s)')
        except Exception as _pfe:
            log(f'  [FRED] parallel prefetch unavailable ({type(_pfe).__name__}) -- serial fallback')
            _pre = {}
        for key, sid in series.items():
            try:
                if key in _tv_pre:   # v1.324.0: TV-primary level; FRED series deliberately skipped
                    out[key] = _tv_pre[key]
                    out[key + '_date'] = str(dt.date.today())
                    out[key + '_source'] = 'tradingview'
                    log('  + ' + key + ' = ' + str(out[key]) + ' (TV primary; FRED skipped)')
                    continue
                if key in _pre:
                    s = _pre[key]
                    if isinstance(s, Exception):
                        raise s
                else:
                    time.sleep(0.6)            # serial fallback -- unchanged original path
                    s = _fred_series(sid)
                if len(s) > 0:
                    val = float(s.iloc[-1])
                    if key in ('core_pce', 'cpi_yoy', 'ppi_yoy', 'ppi_core_yoy'):
                        if len(s) >= 13:
                            val = round(((s.iloc[-1] / s.iloc[-13]) - 1) * 100, 2)
                            # v1.284.0 DIAGNOSTIC (owner audit: tile 3.88 vs official 3.5 with
                            # BOTH bases tried -- no more guessing): persist the exact arithmetic
                            # (last 14 raw index points + the division pair) so the next run
                            # names the defect from evidence.
                            if key == 'cpi_yoy':
                                try:
                                    out['cpi_diag'] = {
                                        'sid': sid,
                                        'points': [[str(ix.date()), round(float(v2), 3)]
                                                   for ix, v2 in list(s.items())[-14:]],
                                        'pair': [round(float(s.iloc[-13]), 3), round(float(s.iloc[-1]), 3)],
                                        'computed': val}
                                except Exception:
                                    pass
                        else:
                            val = round(val, 2)
                    else:
                        val = round(val, 2)
                    out[key] = val
                    out[f'{key}_date'] = str(s.index[-1].date())
                    if key in ('us_10y','us_2y','hy_spread'):
                        for _tk,_tv in _series_trend([round(float(x),2) for x in s.values[-64:]], w=(5,21,63)).items():
                            out[f'{key}_{_tk}'] = _tv
                    # Wave T3: cadence-matched MoM/QoQ/YoY trend on the macro PRINT series,
                    # backfilled from the FRED series so it is live day-1. CPI/PCE trend the
                    # YoY *rate* (acceleration), not the index level; GDP is quarterly.
                    try:
                        if key in ('core_pce','cpi_yoy','ppi_yoy','ppi_core_yoy') and len(s) >= 25:
                            _idx=[float(x) for x in s.values]
                            _yoy=[round((_idx[i]/_idx[i-12]-1)*100,2) for i in range(12,len(_idx))]
                            for _tk,_tv in _print_trend(_yoy[-25:], [('mom',1),('qoq',3),('yoy',12)]).items():
                                out[f'{key}_{_tk}'] = _tv
                        elif key == 'gdp_growth' and len(s) >= 2:
                            for _tk,_tv in _print_trend([round(float(x),2) for x in s.values[-9:]], [('qoq',1),('yoy',4)]).items():
                                out[f'{key}_{_tk}'] = _tv
                        elif key in ('unemployment','umcsi','mfg_emp','industrial_prod','permits') and len(s) >= 2:
                            for _tk,_tv in _print_trend([round(float(x),2) for x in s.values[-25:]], [('mom',1),('qoq',3),('yoy',12)]).items():
                                out[f'{key}_{_tk}'] = _tv
                    except Exception as _e:
                        pass
                    log(f'  ✓ {key} = {out[key]}')
            except Exception as e:
                _FRED_FAILS[0] += 1
                _fred_failed_keys.append(key)   # v1.259.0: candidate for the TradingView rescue
                warn(f'FRED {key} ({sid}) failed: {type(e).__name__}: {e!r}'
                     + (f'  [FRED circuit breaker OPEN after {_FRED_FAILS[0]} failures -- '
                        f'remaining series take last-good without retrying]'
                        if _FRED_FAILS[0] >= _FRED_FAIL_LIMIT else ''))
                lg = safe_get(EXISTING, 'macros', 'us', key)
                if lg is not None:
                    out[key] = lg
                    log(f'  · {key}: kept last-good = {lg}')

        # ── v1.259.0 TRADINGVIEW ECONOMICS RESCUE ────────────────────────────────────────────
        # FRED first, ALWAYS: when it works nothing here runs and not one value changes. This only
        # fires for the keys FRED just FAILED on, and it beats the alternative it replaces --
        # last-good is yesterday's number, TradingView is today's, off the same underlying agency
        # (BLS/Fed). Verified live 2026-07-15: USIRYY already had JUNE inflation while FRED's
        # CPIAUCSL was still on MAY. One batched POST through the identical symbols-POST call this
        # scanner already proves every run for TVC:RUT and every price it fetches.
        # HONEST LIMIT: a rescued key gets its LEVEL but no _mom/_qoq trend, because TradingView
        # hands over the figure rather than the series the trend is computed from. The compass
        # SCORES on the level, so the indicator stays in the composite instead of silently dropping
        # out (the v1.253.0 dropout) -- it just won't show its trend arrow that day. Stated, not hidden.
        # v1.314.7 UMCSI STALENESS OVERRIDE: FRED's UMCSENT lags UMich's own publication schedule --
        # the audit found the print TWO releases behind (2026-05 while June final + July prelim were
        # out). This is not a FRED *failure* (the fetch succeeds with old data) so the rescue chain
        # below never fires. When the FRED print is >45 days old, the proven fetch_te_econ
        # consumer-confidence read (slug verified on TE's own index, same host _te() scrapes every
        # run) overrides the LEVEL; FRED's series still supplies the umcsi_mom/_qoq/_yoy trend fields.
        try:
            _ud = out.get('umcsi_date')
            _uage = None
            if _ud:
                _uage = (dt.date.today() - dt.date.fromisoformat(str(_ud)[:10])).days
            if out.get('umcsi') is None or _uage is None or _uage > 45:
                _te_u = fetch_te_econ(['umcsi']) or {}
                _uv = _te_u.get('umcsi')
                if isinstance(_uv, (int, float)) and 0 < _uv < 200:
                    log(f'  \u2713 umcsi override: FRED print {_uage}d old -> TE current {_uv} '
                        f'(was {out.get("umcsi")})')
                    out['umcsi'] = _uv
                    out['umcsi_date'] = str(dt.date.today())
                    out['umcsi_source'] = 'tradingeconomics (fresher than FRED UMCSENT)'
        except Exception as _ue:
            log(f'  \u00b7 umcsi staleness override skipped: {_ue}')
        if _fred_failed_keys:
            _rescuable = [k for k in _fred_failed_keys if k in _TV_ECON_MAP]
            if _rescuable:
                log(f'  [rescue] FRED missed {_fred_failed_keys}; trying TradingView for {_rescuable}')
                _got = fetch_tv_econ(_rescuable) or {}
                for _k, _v in _got.items():
                    _was = out.get(_k)
                    out[_k] = _v; out[f'{_k}_date'] = str(dt.date.today())
                    out[f'{_k}_source'] = 'tradingview'
                    log(f'  ✓ {_k} rescued from TradingView = {_v}'
                        + (f'  (replaces last-good {_was})' if _was is not None else ''))
            # v1.261.0 SECOND TIER: whatever TradingView could not give, ask TradingEconomics --
            # static HTML, and the only candidate PROVEN from this runner (_te does it every scan).
            _still = [k for k in _fred_failed_keys if k not in out or out.get(f'{k}_source') != 'tradingview']
            _still = [k for k in _still if k in _TE_ECON_MAP and out.get(f'{k}_source') != 'tradingview']
            if _still:
                log(f'  [rescue] still missing after TradingView: {_still}; trying TradingEconomics')
                for _k, _v in (fetch_te_econ(_still) or {}).items():
                    _was = out.get(_k)
                    out[_k] = _v; out[f'{_k}_date'] = str(dt.date.today())
                    out[f'{_k}_source'] = 'tradingeconomics'
                    log(f'  ✓ {_k} rescued from TradingEconomics = {_v}'
                        + (f'  (replaces last-good {_was})' if _was is not None else ''))
            _unrescued = [k for k in _fred_failed_keys
                          if k not in _TV_ECON_MAP and k not in _TE_ECON_MAP]
            if _unrescued:
                log(f'  · no verified TradingView/TradingEconomics source for {_unrescued} -- last-good stands')

        # -- v1.285.0 CPI OFFICIAL-HEADLINE OVERRIDE (evidence-dictated) -----------------------
        # The v1.284.0 cpi_diag PROVED the FRED arithmetic correct on FRED's own index
        # (321.465 -> 333.952 = 3.8844%) yet != the officially ANNOUNCED June rate (3.5%) that
        # every news source quotes -- so the mismatch is the SOURCE, not the math. The tile's
        # display value now prefers TradingView ECONOMICS:USIRYY (the announced rate itself,
        # verified carrying June on release day, v1.259.0 note) whenever it is available and
        # sane; the FRED index series is KEPT for trend math and cpi_diag records both numbers
        # so the audit trail never disappears. FRED-computed value remains the fallback.
        try:
            _cpi_off = fetch_tv_econ(['cpi_yoy']) or {}
            _ov = _cpi_off.get('cpi_yoy')
            if _ov is not None and 0.0 < float(_ov) < 25.0:
                if isinstance(out.get('cpi_diag'), dict):
                    out['cpi_diag']['fred_computed'] = out.get('cpi_yoy')
                    out['cpi_diag']['official_tv'] = round(float(_ov), 2)
                    out['cpi_diag']['displayed'] = 'official (TV ECONOMICS:USIRYY)'
                out['cpi_yoy'] = round(float(_ov), 2)
                log(f"  [cpi] official headline override: {out['cpi_yoy']} (FRED index-derived kept in cpi_diag)")
            else:
                # v1.287.0: TV missed twice live -> second link: TradingEconomics (proven from
                # this runner every scan; the inflation-cpi page carries the announced rate).
                # FRED's index-derived value remains the final fallback.
                _te = {}
                try:
                    _te = fetch_te_econ(['cpi_yoy']) or {}
                except Exception:
                    _te = {}
                _tv2 = _te.get('cpi_yoy')
                if _tv2 is not None and 0.0 < float(_tv2) < 25.0:
                    if isinstance(out.get('cpi_diag'), dict):
                        out['cpi_diag']['fred_computed'] = out.get('cpi_yoy')
                        out['cpi_diag']['official_te'] = round(float(_tv2), 2)
                        out['cpi_diag']['displayed'] = 'official (TradingEconomics)'
                    out['cpi_yoy'] = round(float(_tv2), 2)
                    log(f"  [cpi] official headline via TradingEconomics: {out['cpi_yoy']}")
                elif isinstance(out.get('cpi_diag'), dict):
                    out['cpi_diag']['official_tv_status'] = 'TV USIRYY + TE both unavailable this run -- FRED index-derived value displayed'
        except Exception as _ce:
            log(f'  [cpi] headline override skipped: {type(_ce).__name__}')
            if isinstance(out.get('cpi_diag'), dict):
                out['cpi_diag']['official_tv_status'] = f'override crashed: {type(_ce).__name__}'

        if out.get('us_10y') is not None and out.get('us_2y') is not None:
            out['us_2s10s'] = round(out['us_10y'] - out['us_2y'], 2)
        # S&P 500 LEVEL (FRED 'SP500', daily close) — the US benchmark for the Results 'vs index'
        # (alpha) read = how much a name/sector is beating the market over the SAME window. Stored as
        # the current level + a compact dated history so append_history can fill the index level onto
        # each history day (KSE-100 is already snapshotted natively; the S&P 500 was the missing half).
        try:
            _sp = _fred_series('SP500')
            if len(_sp) > 0:
                out['sp500'] = round(float(_sp.iloc[-1]), 2)
                out['sp500_date'] = str(_sp.index[-1].date())
                out['sp500_hist'] = {str(d.date()): round(float(v), 2) for d, v in list(_sp.items())[-90:]}
                log(f'  \u2713 sp500 = {out["sp500"]}')
        except Exception as e:
            warn(f'FRED sp500 (SP500) failed: {e}')
            lg = safe_get(EXISTING, 'macros', 'us', 'sp500')
            if lg is not None:
                out['sp500'] = lg
                out['sp500_hist'] = safe_get(EXISTING, 'macros', 'us', 'sp500_hist') or {}
                log(f'  \u00b7 sp500: kept last-good = {lg}')
        # Live oil — v1.154.0: TradingView futures PRIMARY (fast, no Yahoo throttle/crumb-poisoning),
        # Yahoo then FRED as fallback. TV serves spot only, so when TV wins we carry the WoW/MoM/QoQ
        # oil trend from last-good (never blank) — Yahoo still recomputes trend when it fills a gap.
        oil = fetch_tv_oil(['wti', 'brent'])
        _oil_missing = [k for k in ('wti', 'brent') if k not in oil]
        if _oil_missing:
            _yh_oil = fetch_live_oil()
            for _k in _oil_missing:
                for _suf in ('', '_source', '_date', '_wow', '_mom', '_qoq',
                             '_wow_dir', '_mom_dir', '_qoq_dir'):
                    _kk = _k + _suf
                    if _kk in _yh_oil:
                        oil[_kk] = _yh_oil[_kk]
        for _k in ('wti', 'brent'):                       # TV served price but no trend -> carry last-good trend
            if _k in oil and f'{_k}_wow' not in oil:
                for _suf in ('_wow', '_mom', '_qoq', '_wow_dir', '_mom_dir', '_qoq_dir'):
                    _lg = safe_get(EXISTING, 'macros', 'us', f'{_k}{_suf}')
                    if _lg is not None:
                        oil[f'{_k}{_suf}'] = _lg
        for key, fred_id in (('wti', 'DCOILWTICO'), ('brent', 'DCOILBRENTEU')):
            if key in oil:
                out[key] = oil[key]
                out[f'{key}_source'] = oil[f'{key}_source']
                out[f'{key}_date']   = oil.get(f'{key}_date')
                for _w in ('wow', 'mom', 'qoq'):  # Wave T3 oil trend: carry the backfilled trend fields through the merge
                    if f'{key}_{_w}' in oil:
                        out[f'{key}_{_w}'] = oil[f'{key}_{_w}']
                    if f'{key}_{_w}_dir' in oil:
                        out[f'{key}_{_w}_dir'] = oil[f'{key}_{_w}_dir']
            else:
                try:
                    s = _fred_series(fred_id)   # F2: same retry/backoff as the main series loop
                    if len(s) > 0:
                        out[key] = round(float(s.iloc[-1]), 2)
                        out[f'{key}_source'] = f'fred:{fred_id} (may lag)'
                        out[f'{key}_date']   = str(s.index[-1].date())
                        warn(f'{key} live source missed; FRED value may be stale')
                except Exception as e:
                    warn(f'{key} FRED fallback failed: {e}')
                    lg = safe_get(EXISTING, 'macros', 'us', key)
                    if lg is not None:
                        out[key] = lg
                        out[f'{key}_source'] = 'last-good'

        try:
            if out.get('brent') and out.get('wti'):
                out['brent_wti_spread'] = round(out['brent'] - out['wti'], 2)
                log(f'  ✓ Brent-WTI spread = {out["brent_wti_spread"]}')
            # v1.314.9 ROLL-FREE OIL TREND: the v1.314.8 diag PROVED TV's scan endpoint serves zero
            # rows for the TVC continuous symbols, so the roll-free basis is FRED's official EIA
            # continuous SPOT series (same ids as the fallback above) -- immune to futures roll by
            # construction. Always-on: emits {key}_spot (latest official spot + date) and _spot_wow /
            # _spot_mom computed from the series itself. The live tile keeps the futures print.
            try:
                for _ok, _fid in (('wti', 'DCOILWTICO'), ('brent', 'DCOILBRENTEU')):
                    try:
                        _sr = _fred_series(_fid).dropna()
                        if len(_sr) < 2:
                            continue
                        _v = round(float(_sr.iloc[-1]), 2)
                        out[f'{_ok}_spot'] = _v
                        out[f'{_ok}_spot_date'] = str(_sr.index[-1].date())
                        if len(_sr) >= 6:
                            out[f'{_ok}_spot_wow'] = round((float(_sr.iloc[-1]) / float(_sr.iloc[-6]) - 1) * 100, 2)
                        if len(_sr) >= 22:
                            out[f'{_ok}_spot_mom'] = round((float(_sr.iloc[-1]) / float(_sr.iloc[-22]) - 1) * 100, 2)
                        if len(_sr) >= 64:   # v1.328.0: quarter read, so the qoq span can be re-based too
                            out[f'{_ok}_spot_qoq'] = round((float(_sr.iloc[-1]) / float(_sr.iloc[-64]) - 1) * 100, 2)
                        log(f'  ✓ {_ok}_spot (FRED roll-free) = {_v} '
                            f'wow {out.get(f"{_ok}_spot_wow")}% mom {out.get(f"{_ok}_spot_mom")}%')
                    except Exception as _se:
                        log(f'  · {_ok}_spot roll-free trend miss: {type(_se).__name__}')
                # v1.328.0: re-base the oil CHANGE fields onto the roll-free spot series just fetched.
                # Placed here deliberately -- same function, same scope, `out` already holds both the
                # futures trends (merged above) and the spot trends (just written), so there is no
                # main()-order dependency to get wrong.
                _n_rb = _apply_rollfree_oil_trends(out)
                if not _n_rb:
                    log('  · oil trends left on the futures basis (no roll-free spot series this run)')
            except Exception:
                pass
        except Exception:
            pass

        # US INDEX LEVELS — NDX + Dow from FRED (same mechanism as SP500), Russell-2000 from TradingView
        # (no free FRED Russell series; v1.99.0 probe: FRED NASDAQ100/DJIA OK, TVC:RUT returns the level).
        # Display-only — feeds the dashboard US Forward Outlook panel (was on dated snapshots). Last-good safe.
        for key, fred_id in (('ndx', 'NASDAQ100'), ('dow', 'DJIA')):
            try:
                s = _fred_series(fred_id)
                if len(s) > 0:
                    out[key] = round(float(s.iloc[-1]), 2)
                    out[f'{key}_date'] = str(s.index[-1].date())
                    log(f'  \u2713 {key} ({fred_id}) = {out[key]}')
            except Exception as e:
                warn(f'FRED {key} ({fred_id}) failed: {e}')
                lg = safe_get(EXISTING, 'macros', 'us', key)
                if lg is not None:
                    out[key] = lg
                    out[f'{key}_date'] = safe_get(EXISTING, 'macros', 'us', f'{key}_date')
        try:
            r = requests.post('https://scanner.tradingview.com/america/scan',
                              json={'symbols': {'tickers': ['TVC:RUT']}, 'columns': ['close']},
                              headers={'User-Agent': UA}, timeout=20)
            _rut = None
            if r.status_code == 200:
                _d = (r.json().get('data') or [])
                if _d and _d[0].get('d'):
                    _rut = _d[0]['d'][0]
            if isinstance(_rut, (int, float)) and 500 < _rut < 20000:
                out['rut'] = round(float(_rut), 2)
                out['rut_date'] = str(dt.date.today())
                log(f'  \u2713 rut (TVC:RUT) = {out["rut"]}')
            else:
                raise ValueError(f'TVC:RUT returned {_rut}')
        except Exception as e:
            warn(f'Russell-2000 (TVC:RUT) failed: {e}')
            lg = safe_get(EXISTING, 'macros', 'us', 'rut')
            if lg is not None:
                out['rut'] = lg
                out['rut_date'] = safe_get(EXISTING, 'macros', 'us', 'rut_date')

        # ARAB LIGHT — the owner's stated oil benchmark (World Bank 'Crude oil, Dubai' monthly proxy).
        # Monthly cadence; display-only alongside WTI/Brent. Last-good safe.
        try:
            _al, _alm, _als, _albr = fetch_arab_light()
            if _al is not None:
                out['arab_light'] = _al
                out['arab_light_month'] = _alm
                out['arab_light_source'] = _als
                if _albr is not None and _albr > 0:
                    # v1.314.7: Dubai-Brent spread from the SAME CMO month -> feeds the live estimate
                    out['arab_light_spread'] = round(_albr - _al, 2)
                    out['arab_light_spread_month'] = _alm
                log(f'  \u2713 Arab Light (Dubai proxy) = {_al} $/bbl ({_alm})')
            else:
                lg = safe_get(EXISTING, 'macros', 'us', 'arab_light')
                if lg is not None:
                    out['arab_light'] = lg
                    out['arab_light_month'] = safe_get(EXISTING, 'macros', 'us', 'arab_light_month')
                    out['arab_light_source'] = 'last-good'
                    _lgs = safe_get(EXISTING, 'macros', 'us', 'arab_light_spread')
                    if _lgs is not None:
                        out['arab_light_spread'] = _lgs
                        out['arab_light_spread_month'] = safe_get(EXISTING, 'macros', 'us', 'arab_light_spread_month')
                    log(f'  \u00b7 Arab Light: kept last-good = {lg}')
            # v1.314.7 LIVE ESTIMATE: monthly CMO is honest but ~1-2 months lagged; the live read is
            # live Brent minus the last known Dubai-Brent monthly spread, LABELLED an estimate. The
            # official monthly value stays in arab_light untouched; consumers that need freshness
            # (E&P trigger, devaluation input) read live-first with monthly fallback, basis stated.
            try:
                # v1.348.0 BASIS PIN: the SAME OSP config the E&P trigger uses -- one spread, one basis,
                # everywhere. The CMO Dubai-Brent monthly spread stays stored above as context only.
                _sp = ARAB_LIGHT_DIFF_USD
                _br = out.get('brent')
                if isinstance(_br, (int, float)) and _br > 0:
                    out['arab_light_live'] = round(_br - _sp, 2)
                    out['arab_light_live_note'] = ('pinned basis: live Brent %.2f minus Aramco OSP '
                                                   'differential %.2f (config, updated on monthly OSP release)' % (_br, _sp))
                    log(f"  \u2713 Arab Light LIVE estimate = {out['arab_light_live']} $/bbl "
                        f"(Brent {_br} - spread {_sp})")
            except Exception as _ale:
                log(f'  \u00b7 Arab Light live estimate skipped: {_ale}')
        except Exception as e:
            warn(f'Arab Light failed: {e}')

        # US rotary rig count (F1) — third-party source: EIA (US gov) republishes the Baker Hughes
        # count as monthly "Crude Oil & Natural Gas Rotary Rigs in Operation" (TOTAL oil+gas; oil-only
        # is BH-proprietary & bot-blocked at TE/YCharts). Data is monthly + the page is heavy, so
        # cadence-gate to weekly (like ETF/Zacks): ~0 cost most runs, the rare fetch gets a real read window.
        _rig_prev = safe_get(EXISTING, 'macros', 'us', 'us_oil_rigs')
        _rig_utc = safe_get(EXISTING, 'macros', 'us', 'us_rigs_utc')
        _rig_age = None
        if _rig_utc:
            try:
                _rig_age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(str(_rig_utc).replace('Z', ''))).days
            except Exception:
                _rig_age = None
        if _rig_prev is not None and _rig_age is not None and _rig_age < 7:
            out['us_oil_rigs'] = _rig_prev
            out['us_rigs_utc'] = _rig_utc
            log(f'  → US rigs skipped (EIA fetch {_rig_age}d ago, <7d) — last-good {_rig_prev}')
        else:
            try:
                rr = requests.get('https://www.eia.gov/dnav/ng/hist/e_ertrr0_xr0_nus_cm.htm',
                                  headers={'User-Agent': UA}, timeout=(4, 12))
                if rr.status_code == 200:
                    t = re.sub(r'<[^>]+>', ' ', rr.text).replace('&nbsp;', ' ')
                    cut = t.find('No Data Reported')
                    if cut > 0:
                        t = t[:cut]
                    vals = [int(n.replace(',', '')) for n in re.findall(r'\d[\d,]{1,5}', t)]
                    for v in reversed(vals):           # most-recent plausible rig value; skip year tokens
                        if 100 <= v <= 6000 and not (1900 <= v <= 2100):
                            out['us_oil_rigs'] = v
                            out['us_rigs_utc'] = dt.datetime.utcnow().isoformat() + 'Z'
                            log(f'  ✓ US rotary rigs (EIA, total oil+gas): {v}')
                            break
            except Exception as e:
                log(f'  · US rigs (EIA): {e}')
            if out.get('us_oil_rigs') is None and _rig_prev is not None:
                out['us_oil_rigs'] = _rig_prev
                log('  · US rigs: EIA unreachable; using last-good')

        # FOMC / Fed monetary-policy announcements (live — official Fed press-release RSS)
        try:
            import feedparser
            ffeed = feedparser.parse('https://www.federalreserve.gov/feeds/press_monetary.xml')
            items = []
            for e in ffeed.entries[:25]:
                pub = None
                if getattr(e, 'published_parsed', None):
                    pub = dt.datetime(*e.published_parsed[:6]).date().isoformat()
                items.append({'title': (getattr(e, 'title', '') or '').strip(),
                              'link':  getattr(e, 'link', '') or '',
                              'date':  pub})
            fomc = None
            for it in items:
                t = it['title'].lower()
                if 'fomc' in t or 'federal open market' in t or 'monetary policy' in t:
                    fomc = it; break
            if fomc is None and items:
                fomc = items[0]
            if fomc:
                tl = fomc['title'].lower()
                stance = ('QT' if any(w in tl for w in ('reduce', 'runoff', 'reducing', 'taper'))
                          else 'QE' if any(w in tl for w in ('purchase', 'expand its', 'increase its holdings'))
                          else None)
                days = None
                if fomc.get('date'):
                    try:
                        days = (dt.date.today() - dt.date.fromisoformat(fomc['date'])).days
                    except Exception:
                        days = None
                out['fomc'] = {'title': fomc['title'], 'link': fomc['link'], 'date': fomc['date'],
                               'days_ago': days, 'stance': stance, 'recent': items[:5]}
                log(f'  \u2713 FOMC: {fomc.get("date")} \u2014 {fomc["title"][:60]}')
        except Exception as e:
            log(f'  \u00b7 FOMC RSS (last-good): {e}')
            _swallow('fomc.fetch', exc=e)   # v1.288.0: the failure class rides meta['swallowed']
            lg = safe_get(EXISTING, 'macros', 'us', 'fomc')
            if lg is not None:
                out['fomc'] = lg
            # v1.288.0 (old-backlog confirm, owner-approved): fomc has sat null with no explanation.
            # If the feed produced nothing AND there is no last-good, say so in the data -- and the
            # next run's meta['swallowed']/fomc_status names whether the Fed RSS is reachable at all.
            if out.get('fomc') is None:
                out['fomc_status'] = f'FOMC RSS failed ({type(e).__name__}) and no last-good exists -- see meta.swallowed fomc.fetch'

        # v1.288.0: the success-but-empty path must also explain itself (feed parsed, zero usable
        # entries, no exception) -- otherwise fomc simply stays null with no trace either way.
        if out.get('fomc') is None and 'fomc_status' not in out:
            out['fomc_status'] = 'Fed RSS parsed but yielded no usable entries this run (no last-good either)'

        log(f'  Total US macros: '
            f'{len([k for k in out if not k.endswith(("_date","_source"))])}')
        return out

    except Exception as e:
        log(f'  US macros FAILED: {e}')
        traceback.print_exc()
        return EXISTING.get('macros', {}).get('us', {})


# =============================================================
# 2. PSX MACRO
# =============================================================
def _kse_sane(v):
    """Accept only index-magnitude numbers (rejects share prices and most volumes)."""
    try:
        v = float(v)
        return v if KSE_MIN < v < KSE_MAX else None
    except Exception:
        return None


def _kse_ts_to_date(ts):
    try:
        ts = float(ts)
        if ts > 1e12:
            ts /= 1000.0
        return str(dt.datetime.utcfromtimestamp(ts).date())
    except Exception:
        return None


def _kse_grab(text):
    """Find the KSE-100 index value in an HTML page. Prefers a decimal number
    (the index prints as 171651.48; share volumes are integers) to avoid
    false-matching a volume figure that happens to sit in the index range."""
    import re
    anchor = re.search(r'KSE\s*-?\s*100', text, re.I)
    if not anchor:
        return None
    window = text[anchor.end(): anchor.end() + 400]
    for pat in (r'[\d,]{5,}\.\d+', r'[\d,]{5,}'):   # decimal first, then integer fallback
        for num in re.findall(pat, window):
            v = _kse_sane(num.replace(',', ''))
            if v is not None:
                return round(v, 2)
    return None


def _kse_extract_ts(rows):
    """Pull (value, date_str) from a dps.psx timeseries 'data' array. Pure."""
    if not rows:
        return None, None
    last = rows[-1]
    val = None
    date_str = None
    if isinstance(last, (list, tuple)):
        if len(last) >= 1:
            date_str = _kse_ts_to_date(last[0])
        if len(last) >= 5:
            val = _kse_sane(last[4])
        if val is None and len(last) >= 2:
            val = _kse_sane(last[1])
    return (round(val, 2) if val is not None else None), date_str


def fetch_kse100():
    """KSE-100 index level.
    PRIMARY: TradingView official close (PSX:KSE100). The dps.psx `int` series is INTRADAY — its
      LAST tick under-reports the official session close (observed 178182 vs the real 180232 close,
      the index ran into the close after the feed's last recorded tick), and the dps `eod` index
      series is frozen at 2021. TradingView is the only runner-reachable source that carries the
      official close (~15min delayed; posts after the session), mirroring the PSX stock-price feed.
    FALLBACK: dps.psx int (intraday last tick — may lag the close) then eod, then (caller) last-good.
    A manual override in psx_macros_manual.json ('kse100') wins over all of this (applied by caller)."""
    headers = {'User-Agent': UA, 'Accept': 'application/json'}
    today = str(dt.date.today())
    # PRIMARY — TradingView PSX:KSE100 official close (mirrors the futures/ETF symbols-POST pattern).
    # Query a few candidate index symbols and LOG all returned, but only TRUST PSX:KSE100 — so if TV
    # uses a different code the run log reveals it without us using a wrong index.
    try:
        payload = {'symbols': {'tickers': ['PSX:KSE100', 'PSX:KSE30', 'PSX:KSEALL']},
                   'columns': ['close']}
        r = requests.post('https://scanner.tradingview.com/pakistan/scan',
                          json=payload, headers={'User-Agent': UA}, timeout=20)
        if r.status_code == 200:
            rows = {d.get('s'): (d.get('d') or [None])[0] for d in r.json().get('data', [])}
            log(f'  · KSE-100 TradingView index symbols -> {rows}')
            v = _kse_sane(rows.get('PSX:KSE100'))
            if v is not None:
                return round(v, 2), 'tradingview:KSE100 (official close)', today
        else:
            log(f'  · KSE-100 TradingView HTTP {r.status_code}')
    except Exception as e:
        log(f'  · KSE-100 TradingView miss: {e}')

    # FALLBACK — dps.psx int (intraday last tick; may lag the official close) then eod.
    best = None  # (val, date_str, src)
    for path, label in (('int', 'psx-dps:int (intraday last tick — may lag official close)'),
                        ('eod', 'psx-dps:eod')):
        try:
            r = requests.get(f'https://dps.psx.com.pk/timeseries/{path}/KSE100',
                             headers=headers, timeout=12)
            if r.status_code == 200:
                j = r.json()
                rows = j.get('data') if isinstance(j, dict) else j
                v, d = _kse_extract_ts(rows)
                if v is not None:
                    if best is None or (d and best[1] and d > best[1]) or (d and not best[1]):
                        best = (v, d, label)
        except Exception as e:
            log(f'  · KSE-100 dps/{path} miss: {e}')

    if best is not None:
        return best[0], best[2], (best[1] or today)
    return None, None, None


def fetch_psx_macros():
    log('Fetching PSX macros...')
    out = EXISTING.get('macros', {}).get('psx', {}).copy()
    import re
    headers = {'User-Agent': UA}

    # KSE-100: a manual override in psx_macros_manual.json ('kse100', optionally 'kse100_date')
    # WINS — the official PSX close, user-set, guaranteed correct (use it if the live feed is ever
    # wrong). Default (no override) = the live fetch (TradingView official close -> dps fallback).
    _man_kse = None
    try:
        with open('psx_macros_manual.json') as _mf:
            _man_kse = (json.load(_mf) or {}).get('kse100')
    except Exception:
        _man_kse = None
    if _man_kse is not None and (KSE_MIN < float(_man_kse) < KSE_MAX):
        val, src, dstr = round(float(_man_kse), 2), 'manual override (official PSX close)', \
            (safe_get(EXISTING, 'macros', 'psx', 'kse100_date') or str(dt.date.today()))
        try:
            with open('psx_macros_manual.json') as _mf:
                _md = (json.load(_mf) or {}).get('kse100_date')
            if _md:
                dstr = _md
        except Exception:
            pass
    else:
        val, src, dstr = fetch_kse100()
    if val is not None:
        out['kse100'] = val
        out['kse100_source'] = src
        out['kse100_date'] = dstr
        log(f'  ✓ KSE-100 ({src}): {val} (as of {dstr})')
        try:  # Wave T3: KSE-100 trend (accrues per session; dedup-by-date so same-session re-runs don't double-append)
            _kh = _push_hist(out.get('kse100_hist'), dstr, val)
            out['kse100_hist'] = _kh
            for _k, _v in _hist_trend(_kh, w=(1, 5, 21)).items():
                out['kse100_' + _k] = _v
        except Exception:
            pass
    else:
        lg = safe_get(EXISTING, 'macros', 'psx', 'kse100')
        if lg is not None:
            out['kse100'] = lg
            out['kse100_source'] = 'last-good (STALE)'
            out['kse100_date'] = safe_get(EXISTING, 'macros', 'psx', 'kse100_date')
            warn(f'KSE-100 all live sources failed; using STALE last-good {lg}')
        else:
            out['kse100'] = None
            warn('KSE-100 unavailable and no last-good value')

    # USD/PKR: v1.158.0 TradingView-PRIMARY for spot (FX_IDC:USDPKR), Yahoo for the trend series
    # + fallback spot. If TV serves the level, Yahoo still supplies WoW/MoM trend; if TV misses,
    # Yahoo carries both; if Yahoo is rate-limited, TV spot still stands. Never blanks.
    _pk_tv = None
    try:
        _pk = fetch_index_tv({'usd_pkr': 'FX_IDC:USDPKR'}, markets=('forex',))
        _v = (_pk.get('usd_pkr') or {}).get('px')
        if _v and 200 < _v < 400:
            _pk_tv = _v
            out['usd_pkr'] = _v
            out['usd_pkr_source'] = 'tradingview:FX_IDC:USDPKR'
            log(f'  ✓ USD/PKR (TV FX_IDC:USDPKR): {_v}')
    except Exception as e:
        log(f'  · USD/PKR TV miss (Yahoo fallback): {str(e)[:60]}')
    try:
        import yfinance as yf
        h = yf.Ticker('USDPKR=X').history(period='6mo')
        if len(h) > 0:
            if _pk_tv is None:
                out['usd_pkr'] = round(float(h['Close'].iloc[-1]), 2)
                log(f'  ✓ USD/PKR (Yahoo fallback): {out["usd_pkr"]}')
            for _tk,_tv in _series_trend([round(float(x),2) for x in h['Close'].values[-64:]], w=(5,21,63)).items():
                out['usd_pkr_'+_tk] = _tv
    except Exception as e:
        if _pk_tv is None:
            warn(f'USD/PKR failed: {e}')

    try:
        r = _retry_get('https://www.sbp.org.pk/m_policy/index.asp',
                       headers=headers, timeout=15, tries=3, base=1.0)
        if r.status_code == 200:
            m = re.search(r'(\d{1,2}\.\d{1,2})\s*(?:percent|%)', r.text, re.I)
            if m:
                out['sbp_rate'] = float(m.group(1))
                log(f'  ✓ SBP rate (SBP official): {out["sbp_rate"]}%')
    except Exception as e:
        log(f'  · SBP rate: {e}')
    if out.get('sbp_rate') is None:
        lg = safe_get(EXISTING, 'macros', 'psx', 'sbp_rate')
        if lg is not None:
            out['sbp_rate'] = lg

    # CPI YoY — primary: TheGlobalEconomy (PBS-sourced, monthly, fetchable & parseable),
    # then PBS direct, then TE (below), then last-good. The _tge helper reads the most-recent
    # row of a TheGlobalEconomy per-indicator page and is reusable for other PSX macros.
    def _tge(slug, diag=False):
        try:
            rr = requests.get(f'https://www.theglobaleconomy.com/Pakistan/{slug}/',
                              headers={'User-Agent': UA}, timeout=15)
            if rr.status_code != 200:
                if diag: log(f'    · [diag] TGE {slug}: HTTP {rr.status_code}')
                return None
            txt = re.sub(r'<[^>]+>', ' ', rr.text)
            txt = txt.replace('&nbsp;', ' ').replace('&nbsp', ' ')  # entity survives tag-strip; year/month joined by it
            txt = re.sub(r'\s+', ' ', txt)            # collapse newlines/tabs so the row is contiguous
            i = txt.find('Recent values')
            seg = txt[i:i + 500] if i >= 0 else txt
            # accept "YYYY Mon <val>" or "Mon YYYY <val>"; values may carry commas
            m = re.search(r'(?:(?:19|20)\d{2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)|'
                          r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(?:19|20)\d{2})'
                          r'\s+(-?[\d,]+(?:\.\d+)?)', seg)
            if not m:
                if diag: log(f'    · [diag] TGE {slug}: 200 len={len(rr.text)} hasRecent={i>=0} seg={seg[:170]!r}')
                return None
            return float(m.group(1).replace(',', ''))
        except Exception as e:
            if diag: log(f'    · [diag] TGE {slug}: {type(e).__name__} {str(e)[:80]}')
            return None
    try:
        v = _tge('inflation_annual', diag=False)  # CPI YoY %, monthly; site now JS-walled, kept as cheap probe in case it reverts
        if v is not None:
            out['pak_cpi'] = v
            log(f'  ✓ Pak CPI YoY (TheGlobalEconomy): {v}%')
        else:
            log('  → Pak CPI: TheGlobalEconomy now JS-rendered (unparseable) — using manual/last-good')
    except Exception as e:
        log(f'  · Pak CPI (TheGlobalEconomy): {e}')
    # PBS live monthly CPI (SDMX XML) - AUTHORITATIVE, overwrites the pre-seeded last-good (out carries it from line ~603,
    # so an `if is None` guard would never fire). Manual override (psx_macros_manual.json 'pak_cpi') runs AFTER this and wins.
    _cpi = fetch_pbs_cpi()
    if _cpi and _cpi.get('yoy') is not None:
        _prior = out.get('pak_cpi')
        out['pak_cpi'] = _cpi['yoy']
        out['pak_cpi_index'] = _cpi.get('index')
        out['pak_cpi_mom'] = _cpi.get('mom')
        out['pak_cpi_as_of'] = _cpi.get('as_of')
        out['pak_cpi_source'] = 'pbs_sdmx'
        log(f'  ✓ Pak CPI YoY (PBS live): {_cpi["yoy"]}% (index {_cpi.get("index")}, MoM {_cpi.get("mom")}%, as of {_cpi.get("as_of")}; prior {_prior})')
    elif out.get('pak_cpi') is None:
        lg = safe_get(EXISTING, 'macros', 'psx', 'pak_cpi')
        if lg is not None:
            out['pak_cpi'] = lg

    # F4 source resolution: CPI is now live-monthly via TheGlobalEconomy. REER / Current Account /
    # Fiscal have NO free monthly fetchable feed (SBP/PBS=PDF; FRED Pakistan=annual-only; TE blocks
    # bots; TheGlobalEconomy & World Bank carry these three only annually). They stay best-effort TE
    # → last-good → Tab-1 manual (update quarterly from the AKD/Topline economy report).

    # F4/F3: best-effort live fetch (free, Trading Economics) for the slow-moving Pakistan
    # macros that had no live source. Fully guarded — on ANY failure the last-good fallbacks
    # below apply, so this can never break the run. Validates on the live run (TE may block
    # bots; last-good remains the reliable backstop — spot-check against broker monthlies).
    # F4 (v1.52): manual-override slot. REER / current-account / fiscal-balance have no free
    # monthly feed — maintain them quarterly from the AKD/Topline economy report in
    # psx_macros_manual.json (repo root). Manual values WIN: the TE block below only fetches when
    # out[key] is still None, so seeding here short-circuits it. Fully guarded — file absent = no-op.
    try:
        with open('psx_macros_manual.json') as _mf:
            _man = json.load(_mf) or {}
        for _k in ('reer', 'pak_ca', 'pak_fiscal', 'pak_cpi'):
            _v = _man.get(_k)
            if _v is not None:
                out[_k] = _v
                log(f'  ✓ {_k} (manual override): {_v}')
    except FileNotFoundError:
        pass
    except Exception as _e:
        log(f'  · psx_macros_manual.json ignored ({_e})')

    def _te(slug, label):
        try:
            rr = requests.get('https://tradingeconomics.com/pakistan/' + slug,
                              headers={'User-Agent': UA}, timeout=12)
            if rr.status_code != 200:
                return None
            txt = re.sub(r'<[^>]+>', ' ', rr.text)
            m = re.search(label + r'[^0-9\-]{0,40}(-?\d{1,4}(?:\.\d{1,2})?)', txt, re.I)
            return float(m.group(1)) if m else None
        except Exception:
            return None
    try:
        if out.get('pak_cpi') is None:
            v = _te('inflation-cpi', 'Inflation Rate')
            if v is not None: out['pak_cpi'] = v; log(f'  ✓ Pak CPI (TE): {v}%')
        if out.get('reer') is None:
            v = _te('real-effective-exchange-rate', 'Real Effective')
            if v is not None: out['reer'] = v; log(f'  ✓ REER (TE): {v}')
        if out.get('pak_ca') is None:
            v = _te('current-account', 'Current Account')
            if v is not None: out['pak_ca'] = v; log(f'  ✓ Current account (TE): {v}')
        if out.get('pak_fiscal') is None:
            v = _te('government-budget', 'Government Budget')
            if v is not None: out['pak_fiscal'] = v; log(f'  ✓ Fiscal balance (TE): {v}% GDP')
        # SBP FX reserves: PUBLIC weekly figure (every broker FMR / bank report / business paper). Sourced
        # MANUALLY like reer/pak_ca/pak_fiscal -- psx_macros_manual.json overrides, else the in-repo baseline
        # constant, else last-good. No SBP scraping: the ecodata page is a link directory and forex.pdf broke
        # on SBP's Jul-2026 site revamp; the number is trivially available from any FMR, so keep it lean.
        _man_res = None
        try:
            with open('psx_macros_manual.json') as _mf:
                _man_res = (json.load(_mf) or {}).get('sbp_reserves')
        except Exception:
            _man_res = None
        if _man_res is None:
            _man_res = SBP_RESERVES_MANUAL
        if _man_res is not None:
            out['sbp_reserves'] = _man_res
            out['sbp_reserves_source'] = 'manual'
            out['sbp_reserves_as_of'] = SBP_RESERVES_AS_OF
            log(f'  ✓ SBP reserves (manual/FMR): {_man_res}bn as on {SBP_RESERVES_AS_OF} (update from any broker FMR / psx_macros_manual.json)')
        # G4 (v1.246.0) IMPORT COVER = reserves / monthly import bill -> MONTHS.
        # Both inputs are manual-by-design (see IMPORT_BILL_MANUAL_MN); this is arithmetic, not a fetch.
        _man_bill = None
        try:
            with open('psx_macros_manual.json') as _mf2:
                _mj = json.load(_mf2) or {}
                _man_bill = _mj.get('import_bill_mn')
                _bill_as_of = _mj.get('import_bill_as_of') or IMPORT_BILL_AS_OF
        except Exception:
            _man_bill, _bill_as_of = None, IMPORT_BILL_AS_OF
        if _man_bill is None:
            _man_bill = IMPORT_BILL_MANUAL_MN
        try:
            if out.get('sbp_reserves') is not None and _man_bill:
                out['import_bill_mn'] = round(float(_man_bill), 1)
                out['import_bill_as_of'] = _bill_as_of
                out['import_cover'] = round((float(out['sbp_reserves']) * 1000.0) / float(_man_bill), 2)
                out['import_cover_source'] = 'computed: reserves / monthly import bill'
                _ic = out['import_cover']
                log(f"  ✓ Import cover: {_ic} months  (reserves ${out['sbp_reserves']}bn / "
                    f"${_man_bill}mn a month; {_bill_as_of})"
                    + ('  ** BELOW the 2.5-month trigger **' if _ic < 2.5
                       else '  (below the 3-month rule of thumb)' if _ic < 3.0 else ''))
        except Exception as _ice:
            log(f'  · Import cover not computed: {_ice}')

        if out.get('sbp_reserves') is None:
            v = _te('foreign-exchange-reserves', 'Foreign Exchange Reserves')
            if v is not None: out['sbp_reserves'] = round(v/1000.0, 2) if v > 1000 else v; log(f'  ✓ SBP reserves (TE): {out["sbp_reserves"]}')
    except Exception as e:
        log(f'  · TE Pakistan macros (best-effort): {e}')

    if out.get('sbp_reserves') is None:
        lg = safe_get(EXISTING, 'macros', 'psx', 'sbp_reserves')
        if lg is not None:
            out['sbp_reserves'] = lg
    # T1: value-change-dedup reserves history + WoW/MoM/QoQ trend (SBP weekly data, daily runs)
    if out.get('sbp_reserves') is not None:
        _prior_src = safe_get(EXISTING, 'macros', 'psx', 'sbp_reserves_source')
        if out.get('sbp_reserves_source') == 'sbp_ecodata' and _prior_src != 'sbp_ecodata':
            # basis switch (manual / last-good -> live ecodata): start the history fresh at the live value
            # so the one-time basis change cannot register as a weekly move (re-baseline, runs once).
            _rh = []
            log(f'  · SBP reserves history re-baselined onto the live ecodata basis ({out["sbp_reserves"]})')
        else:
            _rh = [h if isinstance(h, dict) else {'d': None, 'v': h}
                   for h in (safe_get(EXISTING, 'macros', 'psx', 'sbp_reserves_hist') or [])]
        if not _rh or _rh[-1].get('v') != out['sbp_reserves']:
            _rh.append({'d': out.get('sbp_reserves_as_of'), 'v': out['sbp_reserves']})
        _rh = _rh[-160:]
        out['sbp_reserves_hist'] = _rh
        for _k, _v in _series_trend([h['v'] for h in _rh if isinstance(h, dict) and h.get('v') is not None]).items():
            out['sbp_reserves_'+_k] = _v

    if out.get('reer') is None:
        lg = safe_get(EXISTING, 'macros', 'psx', 'reer')
        if lg is not None:
            out['reer'] = lg

    # v1.11: pak_ca and pak_fiscal have no live source yet — seed last-good so the
    # Gold tab's Pakistan factors don't silently fall back to Tab-1 manual values.
    for _k in ('pak_ca', 'pak_fiscal', 'neer'):
        if out.get(_k) is None:
            _lg = safe_get(EXISTING, 'macros', 'psx', _k)
            if _lg is not None:
                out[_k] = _lg

    _manual = [k for k in ('reer', 'pak_ca', 'pak_fiscal') if out.get(k) is not None]
    log(f'  → REER/CA/Fiscal: no free monthly feed — manual/last-good (quarterly from AKD/Topline). CPI via TheGlobalEconomy when parsed, else last-good. Carried: {_manual or "none"}')

    return out


