def fetch_etf_meta(etf):
    """3Y return + expense ratio for an ETF via Yahoo. Guarded; returns {y3, expense} (None if missing)."""
    out = {'y3': None, 'expense': None}
    try:
        import yfinance as _yf
        t = _yf.Ticker(etf)
        try:
            h = t.history(period='3y')
            c = h['Close'].dropna() if (h is not None and not h.empty) else None
            if c is not None and len(c) > 2:
                out['y3'] = round((float(c.iloc[-1]) / float(c.iloc[0]) - 1) * 100, 1)
        except Exception:
            pass
        try:
            info = t.info or {}
            ne = info.get('netExpenseRatio')           # Yahoo: already in PERCENT (0.60 = 0.60%)
            ar = info.get('annualReportExpenseRatio')  # Yahoo: a FRACTION (0.006 = 0.60%)
            ex = float(ne) if ne is not None else (float(ar) * 100 if ar is not None else None)
            if ex is not None:
                if ex > 5:        # no ETF charges >5%; guard against any unit surprise
                    ex /= 100
                out['expense'] = round(ex, 2)
        except Exception:
            pass
    except Exception as e:
        log(f'    · meta fetch failed for {etf}: {e}')
    return out

_ETF_DIAG = {'done': False}
def _parse_holdings(rows):
    out = []
    for row in (rows or []):
        if not isinstance(row, dict):
            continue
        sym = row.get('asset') or row.get('symbol') or row.get('s') or row.get('ticker')
        wt  = (row.get('weightPercentage') if row.get('weightPercentage') is not None else
               row.get('weight') if row.get('weight') is not None else
               row.get('w') if row.get('w') is not None else
               row.get('as') if row.get('as') is not None else
               row.get('assetsPercent') if row.get('assetsPercent') is not None else
               row.get('percent') if row.get('percent') is not None else row.get('assetPercent'))
        if sym and wt is not None:
            try:
                tk = str(sym).upper().strip().lstrip('$').strip()
                if tk:
                    out.append({'ticker': tk, 'weight': float(str(wt).replace('%','').replace(',','').strip())})
            except Exception:
                pass
    return out

def _etf_estate_status(isin):
    """v1.320.0 -- OBJECTIVE per-fund domicile + estate/inheritance status, deterministic from the
    ISIN country prefix. This is a factual attribute of the FUND (any non-US-resident faces the same),
    NOT personalised tax advice -- every note ends 'verify with a qualified adviser'. Returns
    {domicile, estate_status, tax_note}. No fetch. IE/LU/JE... = estate-safe UCITS; US = US-situs
    estate tax; KR = Korean inheritance tax."""
    p = str(isin or '')[:2].upper()
    UCITS = {'IE':'Ireland','LU':'Luxembourg','JE':'Jersey','GG':'Guernsey','IM':'Isle of Man',
             'GB':'United Kingdom','FR':'France','DE':'Germany','NL':'Netherlands','CH':'Switzerland',
             'ES':'Spain','IT':'Italy','SE':'Sweden','FI':'Finland','AT':'Austria','BE':'Belgium'}
    if p == 'US':
        return {'domicile': 'United States', 'estate_status': 'US-SITUS',
                'tax_note': ('US-domiciled: US estate tax applies to US-situs assets above the $60,000 '
                             'non-resident-alien threshold; dividends withheld at 30% vs 15% on Irish UCITS. '
                             'Tactical use only; keep total US-situs under ~$60k. Verify with a qualified adviser.')}
    if p == 'KR':
        return {'domicile': 'South Korea', 'estate_status': 'KRX-KOREAN-TAX',
                'tax_note': ('KRX-listed: Korean inheritance tax up to 50% on Korean-situs assets, with '
                             'non-residents limited to the ~KRW 200m (~$148k) basic deduction. Tactical only. '
                             'Verify with a qualified adviser.')}
    if p in UCITS:
        return {'domicile': UCITS[p], 'estate_status': 'SAFE-UCITS',
                'tax_note': ('Non-US, non-Korean situs: outside US estate tax and Korean inheritance tax. '
                             'Irish/Luxembourg UCITS is the estate-safe core wrapper. Verify with a qualified adviser.')}
    return {'domicile': (p or 'Unknown'), 'estate_status': 'NON-US-SITUS',
            'tax_note': ('Non-US, non-Korean situs (outside US estate tax); confirm the specific jurisdiction. '
                         'Verify with a qualified adviser.')}


def fetch_us_index_returns():
    """v1.333.0: US benchmark YTD/1Y so consensus picks can be judged against the market, not just each
    other. ONE POST through the proven TVC symbols-scan pattern (identical to the RUT/econ fetches already
    in this file) -- SPX/NDX/DJI Perf.YTD + Perf.Y. Best-effort: returns {} on any failure, never raises,
    never blocks the run; caller (build_recommended) fails OPEN on a miss (never drops a name for lack of
    a benchmark, only for a benchmark it BEAT)."""
    _map = {'sp500': 'TVC:SPX', 'nasdaq': 'TVC:NDX', 'dow': 'TVC:DJI'}
    out = {}
    try:
        payload = {'symbols': {'tickers': list(_map.values())}, 'columns': ['Perf.YTD', 'Perf.Y']}
        r = requests.post('https://scanner.tradingview.com/america/scan',
                          json=payload, headers={'User-Agent': UA}, timeout=15)
        if r.status_code != 200:
            warn('[index returns] TVC:SPX/NDX/DJI HTTP %s' % r.status_code)
            return {}
        by_sym = {}
        for row in (r.json().get('data') or []):
            sym = row.get('s'); d = row.get('d') or []
            if sym and len(d) == 2:
                by_sym[sym] = {'ytd': d[0], 'ret_1y': d[1]}
        for key, sym in _map.items():
            v = by_sym.get(sym)
            if v and isinstance(v.get('ytd'), (int, float)):
                out[key] = {'ytd': round(float(v['ytd']), 2),
                            'ret_1y': round(float(v['ret_1y']), 2) if isinstance(v.get('ret_1y'), (int, float)) else None}
        if out:
            log('  [index returns] ' + ', '.join('%s YTD %.1f%%' % (k, v['ytd']) for k, v in out.items()))
        else:
            warn('[index returns] SPX/NDX/DJI resolved 0/3 -- outperformance gate will fail open')
    except Exception as e:
        warn('[index returns] failed: %s' % type(e).__name__)
    return out


def _sector_avg_perf(data):
    """v1.333.0: median YTD per sector from foundation_universe (perf_ytd already fetched every run --
    zero new cost). This is the honest baseline a Turnaround/small-cap consensus pick must beat: 'above
    the sector average' means above what its OWN sector actually did, not an arbitrary bar."""
    from statistics import median
    by_sec = {}
    for r in (data.get('foundation_universe') or []):
        sec = r.get('sector'); y = r.get('perf_ytd')
        if sec and isinstance(y, (int, float)):
            by_sec.setdefault(sec, []).append(y)
    return {sec: round(median(vals), 2) for sec, vals in by_sec.items() if vals}



def _stamp_rebalance_top_picks(data):
    """v1.334.0/v1.335.0: pipeline-order-safe post-pass -- runs AFTER build_recommended so data['recommended']
    is populated. Stamps TWO things onto live_investment.rebalance: top_picks (top 5 consensus stocks,
    real analyst target-upside where covered, diversification tag vs the owner's current tilt) and
    top_etfs (v1.335.0: real investable ETFs from etf_recommendations whose sector is in the SAME Booming
    band the reco[] prose already discusses -- the rebalancing card named theme scores but never a single
    fund; now it does). Wrapped by the caller; a missing consensus/live_investment leaves both untouched."""
    li = data.get('live_investment')
    rec = (data.get('recommended') or {}).get('stocks') or []
    if not li or not rec:
        return
    rb = li.get('rebalance')
    if not isinstance(rb, dict):
        return
    tce_map = {r.get('ticker'): r for r in (data.get('tce_us') or []) if r.get('ticker')}
    # v1.334.0: diversification basis -- the owner's book is concentrated in semis/Asia-Tech; a pick in
    # the SAME GICS/TV sector family deepens that, anything else genuinely diversifies. Deterministic,
    # stated on the tab (never implied), reusing the sector string already on each consensus pick.
    _CONCENTRATED_SECTORS = {'Electronic Technology', 'Technology Services', 'Information Technology'}
    picks = []
    for s in rec[:5]:
        tk = s.get('ticker')
        t = tce_map.get(tk) or {}
        up = ((t.get('streams') or {}).get('analyst_detail') or {}).get('target_upside_pct')
        sec = s.get('sector')
        # v1.408.0: tag reads the LOOK-THROUGH tech concentration (Asia-Tech + US-Tech buckets of the
        # honest tilt), not the whole-fund label -- the book is ~56%% tech split US/Asia, not '64%% Asia'.
        _lt = ((data.get('live_investment') or {}).get('rebalance') or {}).get('tilt') or {}
        _tech_conc = round((_lt.get('Asia-Tech') or 0) + (_lt.get('US-Tech') or 0))
        _conc_txt = (' (look-through: tech is ~%d%% of the book, split US/Asia)' % _tech_conc) if _tech_conc else ''
        div = (('deepens your semis/tech exposure' + _conc_txt)
               if sec in _CONCENTRATED_SECTORS else
               ('diversifies away from your tech concentration' + _conc_txt)) if sec else 'sector unknown'
        picks.append({
            'ticker': tk, 'name': s.get('name'), 'sector': sec,
            'conviction': s.get('conviction'), 'agree': s.get('agree'),
            'ytd_pct': s.get('ytd_pct'), 'ret_1y': s.get('ret_1y'),
            'analyst_upside_pct': (round(float(up), 1) if isinstance(up, (int, float)) else None),
            'upside_note': ('12-month analyst consensus price-target upside' if up is not None
                             else 'not covered by analyst consensus this run'),
            'diversification': div,
        })
    rb['top_picks'] = picks
    rb['top_picks_note'] = (
        'Top %d consensus picks by engine agreement, with each one\'s analyst-consensus upside (where '
        'covered) and whether it would diversify your book or deepen its existing Asia-Tech/semis '
        'concentration. Not a recommendation to trade -- context for the rebalancing question above.'
        % len(picks))
    # v1.335.0: BOOMING ETFs -- real investable funds for the sectors the reco[] prose already names as
    # Booming (Energy/Financials/Industrials this run), so the rebalancing question has an actual fund to
    # act on, not just a score. door=='sector' + signal-in-Booming-band is the SAME tag etf_recommendations
    # already carries; ranked by live YTD; empty match -> top_etfs=[], never fabricated.
    etf_picks = []
    for e in (data.get('etf_recommendations') or []):
        if e.get('door') != 'sector':
            continue
        sig = e.get('signal')
        f = e.get('fund') or {}
        _band = next((s.get('band') for s in (data.get('sector_booming') or [])
                      if isinstance(s, dict) and s.get('sector') == sig), None)
        if _band != 'Booming':
            continue
        etf_picks.append({
            'name': f.get('name'), 'isin': f.get('isin'), 'ter': f.get('ter'), 'sector': sig,
            'ytd_pct': (f.get('live_ytd') if f.get('live_ytd') is not None else f.get('ytd')),
            'ret_1y': f.get('live_ret_1y'), 'estate_status': f.get('estate_status'),
        })
    etf_picks.sort(key=lambda x: -(x.get('ytd_pct') if isinstance(x.get('ytd_pct'), (int, float)) else -1e9))
    rb['top_etfs'] = etf_picks[:3]
    rb['top_etfs_note'] = ('Investable UCITS funds for the sector(s) currently Booming (' + ', '.join(sorted(
        {s.get('sector') for s in (data.get('sector_booming') or []) if isinstance(s, dict) and s.get('band') == 'Booming'}
    )) + ') -- a real way to act on the theme score above, not just a read on it.') if etf_picks else None




def build_psx_macro_narrative(data, existing=None):
    """Wave R core (v1.349.0): the Pakistan macro STORY, from levers already live in the payload.
    Pure consolidation -- no fetch. Plain language by design: each line is a fact + what it means."""
    try:
        p = (data.get('macros') or {}).get('psx') or {}
        ss = ((data.get('sector_selection') or {}).get('psx') or {})
        ec = ((data.get('econ_clock') or {}).get('psx') or {})
        rate = p.get('sbp_rate'); cpi = p.get('pak_cpi'); pkr = p.get('usd_pkr')
        rsv = p.get('sbp_reserves'); cov = p.get('import_cover'); reer = p.get('reer')
        ca = p.get('pak_ca'); fis = p.get('pak_fiscal')
        zone = ss.get('zone'); rr = ss.get('real_rate_pp')
        fired = [t.get('id') for t in (ss.get('triggers') or []) if t.get('fired')]
        lines = []
        if rate is not None:
            lines.append({'topic': 'Policy rate', 'value': '%.1f%%' % rate,
                'story': ('SBP is holding at %.1f%% -- %s zone. %s' % (rate, (zone or '?').title(),
                  ('After inflation, savers earn %+.1fpp in real terms -- money stays expensive, favouring banks and cash-rich names over leveraged cyclicals.' % rr) if isinstance(rr,(int,float)) else ''))})
        if cpi is not None:
            lines.append({'topic': 'Inflation', 'value': '%.1f%%' % cpi,
                'story': ('CPI at %.1f%% is %s the 11%% defensive trigger%s' % (cpi,
                  'below' if cpi < 11 else 'above',
                  ' -- the inflation tilt is OFF; the defensive stance is rate-driven, not price-driven.' if cpi < 11 else ' -- the defensive inflation tilt is ON.'))})
        if pkr is not None:
            _r = ('%.1f' % reer) if isinstance(reer,(int,float)) else '?'
            lines.append({'topic': 'Currency', 'value': 'PKR %.0f/USD' % pkr,
                'story': ('Rupee near %.0f with REER at %s -- %s' % (pkr, _r,
                  ('above 100 means the rupee is rich vs trading partners; devaluation pressure builds slowly rather than imminently.' if isinstance(reer,(int,float)) and reer > 100 else 'no strong over/under-valuation signal.')))})
        if rsv is not None:
            lines.append({'topic': 'Reserves', 'value': '$%.1fB' % rsv,
                'story': ('SBP reserves of $%.1fB cover about %.1f months of imports -- %s' % (rsv, cov or 0,
                  ('below the 3-month adequacy line: external buffers remain thin, keeping the IMF anchor and import discipline central.' if (cov or 0) < 3 else 'at/above the 3-month adequacy line.')))})
        if ca is not None or fis is not None:
            _catxt = ('current account %+0.1fB USD (surplus helps reserves)' % (ca/1000.0)) if isinstance(ca,(int,float)) else ''
            _fistxt = ('fiscal deficit ~%.1f%% of GDP' % fis) if isinstance(fis,(int,float)) else ''
            lines.append({'topic': 'External & fiscal', 'value': '--',
                'story': ('%s%s%s.' % (_catxt, '; ' if _catxt and _fistxt else '', _fistxt))})
        _fired_txt = (', '.join(fired) if fired else 'none')
        headline = ('Pakistan: %s zone, triggers fired: %s. %s' % ((zone or '?').title(), _fired_txt,
                    (ec.get('quadrant_plain') or '')))
        out = {'headline': headline, 'regime': zone, 'quadrant': ec.get('quadrant'),
               'fired': fired, 'lines': lines,
               'basis': 'consolidated from live macros.psx + sector_selection + econ_clock (no new fetches)'}
        log('  [PSX narrative] %s | %d lines' % ((zone or '?'), len(lines)))
        return out
    except Exception as _e:
        log('  [PSX narrative] failed: %s' % type(_e).__name__)
        return (existing or {}).get('psx_macro_narrative') or {}




