# v1.373.0: TV ETF holdings via the Business-Recorder XHR technique. TV is already reachable from the runner
# every scan, so no consent wall applies. Tries the internal components endpoints with browser-fetch headers.
_TV_HOLDINGS_ENDPOINTS = [
    ('post', 'https://scanner.tradingview.com/america/scan'),   # some builds accept a fund components query
]
def fetch_tv_etf_holdings(sym):
    """Return ([tickers], diag). Business-Recorder headers make TV serve data, not the SPA shell. Robust to
    TV's JSON shapes; captures format on miss. Fail-open."""
    import json as _json
    _sym = (sym or '').upper()
    # v1.382.0: exchange-qualified symbol (AMEX-IVV), confirmed from owner's DevTools capture.
    _TV_EXCH = {'IVV': 'AMEX', 'ITOT': 'AMEX', 'VTI': 'AMEX', 'IWM': 'AMEX', 'SPY': 'AMEX', 'VOO': 'AMEX'}
    _ex = _TV_EXCH.get(_sym, 'AMEX')
    _qs = '%s-%s' % (_ex, _sym)   # e.g. AMEX-IVV
    _hdrs = {'User-Agent': UA,
             'Accept': 'application/json, text/plain, */*',
             'X-Requested-With': 'XMLHttpRequest',
             'Sec-Fetch-Site': 'same-origin', 'Sec-Fetch-Mode': 'cors', 'Sec-Fetch-Dest': 'empty',
             'Origin': 'https://www.tradingview.com',
             'Referer': 'https://www.tradingview.com/symbols/%s/holdings/' % _qs}
    # v1.382.0: holdings API endpoints, exchange-qualified (the XHR the page actually makes).
    _urls = ['https://www.tradingview.com/api/v1/symbols/%s/holdings/' % _qs,
             'https://www.tradingview.com/api/v1/symbols/%s/components/' % _qs,
             'https://www.tradingview.com/symbols/%s/holdings/' % _qs]
    for _u in _urls:
        try:
            _r = requests.get(_u, headers=_hdrs, timeout=25, allow_redirects=True)
            _txt = _r.text or ''
            _ct = _r.headers.get('Content-Type', '')[:50]
            _diag = {'url': _u[:70], 'http': _r.status_code, 'ctype': _ct, 'bytes': len(_txt),
                     'head': _txt[:200], 'n': 0}
            if _r.status_code != 200 or not _txt:
                continue
            # try JSON
            try:
                _j = _json.loads(_txt)
            except Exception:
                continue   # HTML shell -> next url
            _tks = _extract_tv_tickers(_j)
            if _tks:
                return _tks, {'url': _u[:70], 'http': 200, 'n': len(_tks), 'src': 'tv'}
            # v1.377.0: JSON parsed but no tickers -> capture the shape so the parser can be finalised
            _diag = {'url': _u[:70], 'http': 200, 'n': len(_tks), 'src': 'tv',
                     'top_keys': list(_j.keys())[:22] if isinstance(_j, dict) else 'not-dict'}
            # v1.379.0: capture each candidate container so the TRUE holdings array is identified
            if isinstance(_j, dict):
                for _ck in ('results', 'render_results', 'extra_data', 'symbol_info'):
                    _cv = _j.get(_ck)
                    if _cv is not None:
                        _diag['k_' + _ck] = str(_cv)[:220]
            return _tks, _diag
        except Exception as _e:
            _diag = {'url': _u[:70], 'http': type(_e).__name__, 'n': 0}
    return [], _diag

_TV_JUNK = {'NAME', 'META', 'NULL', 'NONE', 'DATA', 'TYPE', 'VALUE', 'TITLE', 'LABEL', 'ROBOTS',
            'INDEX', 'TICKER', 'SYMBOL', 'RESULTS', 'TRUE', 'FALSE', 'USD', 'CASH'}
def _tv_row_ticker(row):
    """Pull a US ticker from one TV results row, whatever its shape. Rejects metadata false positives."""
    if isinstance(row, dict):
        for _k in ('symbol', 'ticker', 's'):   # v1.379.0: drop 'name' -- it matched metadata
            _v = row.get(_k)
            if isinstance(_v, str):
                _t = _v.split(':')[-1].strip().upper()
                if 1 <= len(_t) <= 6 and _t.replace('.', '').isalpha() and _t not in _TV_JUNK:
                    return _t
        # some TV rows carry a 'd' array of column values with a symbol string inside
        _d = row.get('d')
        if isinstance(_d, list):
            for _c in _d:
                if isinstance(_c, str) and ':' in _c:
                    _t = _c.split(':')[-1].strip().upper()
                    if 1 <= len(_t) <= 6 and _t.replace('.', '').isalpha() and _t not in _TV_JUNK:
                        return _t
    elif isinstance(row, str):
        _t = row.split(':')[-1].strip().upper()
        if 1 <= len(_t) <= 6 and _t.replace('.', '').isalpha() and _t not in _TV_JUNK:
            return _t
    return None

_TV_WEIGHT_KEYS = ('weight', 'weight_pct', 'percent', 'percentage', 'allocation', 'shares', 'w', 'pct')
def _looks_like_holding(row):
    """A constituent row has a symbol/ticker AND a numeric weight/shares field. Metadata rows don't."""
    if not isinstance(row, dict):
        return False
    if not _tv_row_ticker(row):
        return False
    for _wk in _TV_WEIGHT_KEYS:
        _v = row.get(_wk)
        if isinstance(_v, (int, float)):
            return True
        if isinstance(_v, str):
            try:
                float(_v.replace('%', '').replace(',', '')); return True
            except Exception:
                pass
    # some TV rows carry values in a 'd' array alongside the symbol -> treat as holding if 'd' present
    if isinstance(row.get('d'), list) and _tv_row_ticker(row):
        return True
    return False

def _tv_all_arrays(obj, _depth=0, _acc=None):
    """Collect every list in the JSON tree (bounded depth)."""
    if _acc is None: _acc = []
    if _depth > 8: return _acc
    if isinstance(obj, list):
        _acc.append(obj)
        for _v in obj:
            if isinstance(_v, (list, dict)): _tv_all_arrays(_v, _depth + 1, _acc)
    elif isinstance(obj, dict):
        for _v in obj.values():
            if isinstance(_v, (list, dict)): _tv_all_arrays(_v, _depth + 1, _acc)
    return _acc

def _extract_tv_tickers(obj, _depth=0):
    """v1.381.0: positively identify the constituent array anywhere in the JSON."""
    _arrays = _tv_all_arrays(obj)
    # 1) prefer the array with the MOST rows that look like real holdings (symbol + weight)
    _best = None; _best_n = 0
    for _arr in _arrays:
        _hits = [r for r in _arr if _looks_like_holding(r)]
        if len(_hits) > _best_n:
            _best_n = len(_hits); _best = _hits
    if _best and _best_n >= 5:
        return list(dict.fromkeys(t for t in (_tv_row_ticker(r) for r in _best) if t))
    # 2) fallback: largest array of symbol-bearing rows (no weight requirement)
    _best = None; _best_n = 0
    for _arr in _arrays:
        _tks = [t for t in (_tv_row_ticker(r) for r in _arr) if t]
        if len(_tks) > _best_n:
            _best_n = len(_tks); _best = _tks
    return list(dict.fromkeys(_best or []))



