# v1.412.0: series IDs verified from SEC filing-index pages; EDGAR serves filings per series.
_NPORT_SERIES = {'EWY': 'S000004258', 'EWT': 'S000004261'}
_ISIN_ALIAS = {'2330': 'TSM', '005930': 'Samsung', '000660': 'SKHynix', '2317': 'HonHai', '2454': 'MediaTek'}

def _isin_local_code(isin):
    """Local exchange code from an ISIN: TW0002330008 -> 2330, KR7005930003 -> 005930."""
    _i = str(isin or '').strip().upper()
    try:
        if _i.startswith('TW') and len(_i) == 12:
            return _i[5:9]
        if _i.startswith('KR') and len(_i) == 12:
            return _i[3:9]
    except Exception:
        pass
    return None


def fetch_nport_by_series(series_id):
    """Latest NPORT-P holdings for one SEC series: atom -> accession -> primary_doc.xml -> (codes, weights, cash)."""
    import re as _re
    import requests as _rq
    import xml.etree.ElementTree as _ET
    _hd = {'User-Agent': 'MHK-Dashboard research muhammadhammadkhan1973@gmail.com'}
    try:
        _atom = _rq.get('https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=%s&type=NPORT-P'
                        '&dateb=&owner=include&count=5&output=atom' % series_id, headers=_hd, timeout=30).text
        _acc = _re.search(r'<accession-n\w*>([0-9\-]{18,22})</', _atom)
        _cik = _re.search(r'/Archives/edgar/data/(\d+)/', _atom)
        if not _acc or not _cik:
            return [], [], None, {'err': 'atom_no_accession'}
        _accn = _acc.group(1)
        _url = ('https://www.sec.gov/Archives/edgar/data/%s/%s/primary_doc.xml'
                % (_cik.group(1), _accn.replace('-', '')))
        _xml = _rq.get(_url, headers=_hd, timeout=45).text
        _xml = _re.sub(r'xmlns(:\w+)?="[^"]*"', '', _xml)
        _xml = _re.sub(r'<(/?)\w+:', r'<\1', _xml)
        _xml = _re.sub(r'\s\w+:(\w+=")', r' \1', _xml)
        _root = _ET.fromstring(_xml)
        _codes, _wts, _cash = [], [], 0.0
        for _sec in _root.iter('invstOrSec'):
            _nm = (_sec.findtext('name') or '').strip()
            _isin_el = _sec.find('.//isin')
            _isin = _isin_el.get('value') if _isin_el is not None else (_sec.findtext('.//isin') or '')
            _pct = _sec.findtext('pctVal')
            _cat = (_sec.findtext('assetCat') or '').strip().upper()
            try:
                _pv = float(_pct)
            except Exception:
                continue
            if _cat == 'STIV':
                _cash += _pv
                continue
            _code = _isin_local_code(_isin)
            _label = _ISIN_ALIAS.get(_code) or _code or (_nm[:10].replace(' ', '') if _nm else None)
            if _label:
                _codes.append(_label)
                _wts.append((_label, round(_pv, 3)))
        _wts.sort(key=lambda x: -x[1])
        return _codes, _wts[:60], round(_cash, 2), {'ok': True, 'accession': _accn}
    except Exception as _e:
        return [], [], None, {'err': type(_e).__name__}



def fetch_edgar_nport_holdings(ticker):
    """Full holdings for a US ETF via edgartools. Returns ([tickers], diag). Fail-open."""
    try:
        import os as _os
        from edgar import Company as _Company, set_identity as _set_identity
        from edgar.funds.reports import FundReport as _FundReport
        from edgar.funds import Fund as _Fund
    except Exception as _ie:
        return [], {'src': 'edgar', 'n': 0, 'err': 'import:' + type(_ie).__name__}
    try:
        if not _EDGAR_READY[0]:
            _set_identity('MHK-Dashboard research muhammadhammadkhan1973@gmail.com')
            _EDGAR_READY[0] = True
        # v1.404.0: the v1.403 Fund() path is REMOVED -- proven (live run + offline source analysis) to
        # resolve the wrong series for 19/30 ETFs (returns S&P 500 for SOXX). The deterministic
        # series-NAME match below is the validated path.
        _tkru0 = (ticker or '').upper()
        # v1.412.0: series-direct path for the foreign twins (no US tickers in their rows; series verified).
        if _tkru0 in _NPORT_SERIES:
            _sc, _sw, _scash, _sd = fetch_nport_by_series(_NPORT_SERIES[_tkru0])
            if len(_sc) >= 10:
                if _sw:
                    _EDGAR_EXTRA[_tkru0] = {'weights': _sw, 'cash_pct': _scash}
                return _sc[:400], {'src': 'edgar', 'n': len(_sc), 'matched': 'series', 'series_id': _NPORT_SERIES[_tkru0]}
            # series path failed -> fall through to the trust scan (honest fallback)
        _co = _Company(_NPORT_CIK[_tkru0]) if _tkru0 in _NPORT_CIK else _Company(_tkru0)
        _fs = _co.get_filings(form='NPORT-P')
        if _fs is None or len(_fs) == 0:
            return [], {'src': 'edgar', 'n': 0, 'err': 'no_nport'}
        # v1.404.0: deterministic SERIES-NAME matching. The filing's general_info.series_name identifies
        # the fund; match it against the ETF's official-name keywords. No ticker map needed.
        _BROAD = {'IVV', 'ITOT', 'VTI', 'VOO', 'SPY', 'IWB', 'RSP', 'SCHB'}
        _tkru = (ticker or '').upper()
        _keys = _NPORT_NAME_KEYS.get(_tkru)
        _best = []
        _scan_n = 0; _fail_n = 0; _names_seen = []
        for _k in range(min(250 if _tkru in _NPORT_CIK else 20, len(_fs))):
            try:
                _scan_n += 1
                _filing = _fs[_k]
                _fr = _FundReport.from_filing(_filing)
                if _fr is None:
                    _fail_n += 1
                    continue
                _sname = ''
                try:
                    _sname = (getattr(_fr.general_info, 'series_name', '') or '').lower()
                except Exception:
                    _sname = ''
                if _sname and len(_names_seen) < 6 and _sname not in _names_seen:
                    _names_seen.append(_sname[:44])
                _name_hit = bool(_keys) and _sname and all(_w in _sname for _w in _keys)
                if _name_hit:
                    _df = _fr.investment_data()
                    _tks = _edgar_df_tickers(_df)
                    if len(_tks) >= 10:   # v1.405.0: a real fund has >=10 tickered holdings; 1-2 = ticker-less filing
                        try:
                            _wp, _cp = _edgar_df_weights(_df)
                            if _wp:
                                _EDGAR_EXTRA[_tkru] = {'weights': _wp, 'cash_pct': _cp}
                        except Exception:
                            pass
                        return _tks, {'src': 'edgar', 'n': len(_tks), 'matched': 'name', 'series': _sname[:40]}
                if _tkru in _BROAD:
                    _df = _fr.investment_data()
                    _tks = _edgar_df_tickers(_df)
                    if len(_tks) > len(_best):
                        _best = _tks
                        try:
                            _wp, _cp = _edgar_df_weights(_df)
                            if _wp:
                                _EDGAR_EXTRA[_tkru] = {'weights': _wp, 'cash_pct': _cp}
                        except Exception:
                            pass
            except Exception:
                _fail_n += 1
                continue
        if _best and _tkru in _BROAD:
            return _best, {'src': 'edgar', 'n': len(_best), 'matched': False}
        return [], {'src': 'edgar', 'n': 0, 'err': 'no_series_name_match',
                    'scanned': _scan_n, 'parse_fails': _fail_n, 'filings_total': len(_fs),
                    'names_seen': _names_seen}
    except Exception as _e:
        return [], {'src': 'edgar', 'n': 0, 'err': type(_e).__name__}

_EDGAR_EXTRA = {}   # v1.408.0: {ETF: {'weights': [(ticker, pct), ...], 'cash_pct': float}} captured per fetch
def _edgar_df_weights(df):
    """(ticker, pct_value) pairs + cash%% (STIV rows) from an investment_data DataFrame. Fail-open."""
    try:
        import pandas as _pd
        if df is None or len(df) == 0:
            return [], None
        cols = set(df.columns)
        pairs = []
        if 'ticker' in cols and 'pct_value' in cols:
            for _, _r in df.iterrows():
                if str(_r.get('asset_category') or '').strip().upper() == 'STIV':
                    continue   # cash sleeve rows are not equity weights
                _t = str(_r.get('ticker') or '').strip().upper()
                try:
                    _p = float(_r.get('pct_value'))
                except Exception:
                    continue
                if _t and _t not in ('NAN', 'NONE', 'NULL') and _t.replace('.', '').replace('-', '').isalnum() and 1 <= len(_t) <= 6 and _p == _p:
                    pairs.append((_t, round(_p, 3)))
            pairs.sort(key=lambda x: -x[1])
        cash = None
        if 'asset_category' in cols and 'pct_value' in cols:
            try:
                _cs = df[df['asset_category'].astype(str).str.upper() == 'STIV']['pct_value'].astype(float).sum()
                cash = round(float(_cs), 2)
            except Exception:
                cash = None
        return pairs[:60], cash
    except Exception:
        return [], None


def _edgar_df_tickers(df):
    """Pull US equity tickers from an edgartools investment_data DataFrame."""
    try:
        if df is None or len(df) == 0:
            return []
    except Exception:
        return []
    _cols = {str(c).lower(): c for c in getattr(df, 'columns', [])}
    _tcol = _cols.get('ticker') or _cols.get('symbol')
    _out = []
    if _tcol is not None:
        for _v in df[_tcol].tolist():
            if not _v:
                continue
            _t = str(_v).split(':')[-1].strip().upper()
            if _t in ('NAN', 'NONE', 'NULL', ''):
                continue
            if 1 <= len(_t) <= 6 and _t.replace('.', '').replace('-', '').isalnum() and _t not in _TV_JUNK:
                _out.append(_t)
    return list(dict.fromkeys(_out))


def fetch_sec_nport_holdings(ticker):
    """Full holdings for a US ETF via SEC EDGAR N-PORT. Returns ([tickers], diag). Fail-open."""
    import re as _re
    _cik = None
    try:
        _cik = _sec_ticker_to_cik(ticker)
        if not _cik:
            return [], {'src': 'nport', 'n': 0, 'err': 'no_cik', 'map': _NPORT_DIAG.get('cik_map_size'), 'hasIVV': _NPORT_DIAG.get('has_IVV'), 'exch_ok': _NPORT_DIAG.get('exch_ok'), 'exch_rows': _NPORT_DIAG.get('exch_rows'), 'exch_type': _NPORT_DIAG.get('exch_type')}
        _sub = _sec_get('https://data.sec.gov/submissions/CIK%s.json' % _cik)
        if not _sub:
            return [], {'src': 'nport', 'n': 0, 'err': 'no_submissions'}
        _rec = (_sub.get('filings') or {}).get('recent') or {}
        _forms = _rec.get('form') or []
        _accs = _rec.get('accessionNumber') or []
        _docs = _rec.get('primaryDocument') or []
        # v1.395.0: collect the recent NPORT-P filings (a trust files one per series); we pick the
        # filing whose parsed holdings have the MOST equity tickers -> that's the big index fund.
        _nport_list = []
        for _i, _f in enumerate(_forms):
            if _f and _f.upper().startswith('NPORT-P'):
                _nport_list.append((_accs[_i], _docs[_i] if _i < len(_docs) else 'primary_doc.xml'))
            if len(_nport_list) >= 8:   # cap: only need to scan the recent handful
                break
        if not _nport_list:
            return [], {'src': 'nport', 'n': 0, 'err': 'no_nport_filing'}
        _best_tks = []; _best_acc = None
        for _acc, _pdoc in _nport_list:
            _accnodash = _acc.replace('-', '')
            _base = 'https://www.sec.gov/Archives/edgar/data/%s/%s' % (int(_cik), _accnodash)
            _raw = (_pdoc or 'primary_doc.xml').split('/')[-1]
            _xml = _sec_get('%s/%s' % (_base, _raw), is_json=False)
            if not _xml or 'invstOrSec' not in _xml:
                _xml = _sec_get('%s/primary_doc.xml' % _base, is_json=False)
            if not _xml:
                continue
            _tks = _parse_nport_xml(_xml)
            if len(_tks) > len(_best_tks):
                _best_tks = _tks; _best_acc = _acc
            if len(_best_tks) >= 100:   # found the big index fund; stop scanning
                break
        if _best_tks:
            return _best_tks, {'src': 'nport', 'n': len(_best_tks), 'acc': _best_acc}
        return [], {'src': 'nport', 'n': 0, 'err': 'parse_0', 'scanned': len(_nport_list)}
        _acc = _pdoc = None   # (unreached; legacy below)
        for _i, _f in enumerate(_forms):
            if _f and _f.upper().startswith('NPORT-P'):
                _acc = _accs[_i]; _pdoc = _docs[_i] if _i < len(_docs) else 'primary_doc.xml'
                break
        if not _acc:
            return [], {'src': 'nport', 'n': 0, 'err': 'no_nport_filing'}
        _accnodash = _acc.replace('-', '')
        _base = 'https://www.sec.gov/Archives/edgar/data/%s/%s' % (int(_cik), _accnodash)
        # v1.392.0: force the RAW xml. primaryDocument may be an xslFormNPORT-P/ styled HTML path.
        _cands = []
        if _pdoc:
            _raw = _pdoc.split('/')[-1]                 # strip xslFormNPORT-P/ prefix if present
            _cands.append('%s/%s' % (_base, _raw))
        _cands.append('%s/primary_doc.xml' % _base)     # canonical raw name
        _xml = None; _used = None
        for _cu in _cands:
            _try = _sec_get(_cu, is_json=False)
            if _try and _try.lstrip()[:5].lower() != '<!doc' and 'invstOrSec' in _try:
                _xml = _try; _used = _cu; break
            if _try and _used is None:
                _xml = _try; _used = _cu   # keep first non-empty as fallback for diag
        if not _xml:
            return [], {'src': 'nport', 'n': 0, 'err': 'no_xml', 'url': (_used or _cands[0])[:90]}
        _tks = _parse_nport_xml(_xml)
        if _tks:
            return _tks, {'src': 'nport', 'n': len(_tks), 'acc': _acc}
        return [], {'src': 'nport', 'n': 0, 'err': 'parse_0', 'n_invst': _NPORT_DIAG.get('n_invst'), 'first_block': _NPORT_DIAG.get('first_block'), 'xml_err': _NPORT_DIAG.get('xml_err')}
    except Exception as _e:
        return [], {'src': 'nport', 'n': 0, 'err': type(_e).__name__}

def _parse_nport_xml(xml_text):
    """Parse N-PORT primary_doc.xml -> list of US tickers. v1.393.0: capture real structure on miss."""
    import xml.etree.ElementTree as _ET, re as _re
    _t = _re.sub(r'xmlns(:\w+)?="[^"]+"', '', xml_text)
    _t = _re.sub(r'(<\/?)\w+:', r'\1', _t)          # strip tag namespace prefixes
    _t = _re.sub(r'\s\w+:(\w+=)', r' \1', _t)        # v1.394.0: strip ATTRIBUTE namespace prefixes (the ParseError cause)
    try:
        _root = _ET.fromstring(_t)
    except Exception as _pe:
        _NPORT_DIAG['xml_err'] = type(_pe).__name__ + ':' + str(_pe)[:60]
        return []
    _secs = list(_root.iter('invstOrSec'))
    _NPORT_DIAG['n_invst'] = len(_secs)
    if _secs:
        _NPORT_DIAG['first_block'] = _ET.tostring(_secs[0], encoding='unicode')[:600]
    _out = []
    for _sec in _secs:
        _tk = None
        _ids = _sec.find('identifiers')
        if _ids is not None:
            _tt = _ids.find('ticker')
            if _tt is not None:
                _tk = (_tt.get('value') or _tt.text or '').strip().upper()
        if not _tk:
            continue
        _tk = _tk.split(':')[-1]
        if 1 <= len(_tk) <= 6 and _tk.replace('.', '').replace('-', '').isalnum() and _tk not in _TV_JUNK:
            _out.append(_tk)
    return list(dict.fromkeys(_out))


def build_moat_cover(existing=None):
    """v1.361.0: real ETF holdings for moat confirmation, via the proven fetch_etf_holdings. Broad funds
    (VTI/ITOT/IWB) plus every-sector ETFs so most moat names -- large AND mid cap -- appear in at least one
    real top holdings list. 5-day cache; returns {etf: [tickers]}."""
    prev = ((existing or {}).get('moat_cover') or {})
    cache = dict(prev.get('by_etf') or {})
    stamp = prev.get('as_of')
    fresh = False
    try:
        if stamp:
            fresh = (dt.datetime.now(dt.timezone.utc) - dt.datetime.fromisoformat(str(stamp).replace('Z', '+00:00'))).total_seconds() < 5 * 86400
    except Exception:
        fresh = False
    # v1.366.0: a pre-deep-holdings cache (no deep_diag) must refresh once so the broad CSV runs.
    # v1.373.0: carry only once TV deep holdings have succeeded; else refresh to retry the fetch.
    # v1.384.0: carry only once ninja deep holdings succeeded (n>=50); else refresh to retry.
    # v1.401.0: carry only if the cache already covers the full deep-ETF set (else the new sector ETFs
    # would never fetch). _DEEP_ETFS is defined below; mirror it here for the coverage check.
    _DEEP_TARGETS = ('IVV', 'ITOT', 'VTI', 'QQQ', 'VGT', 'KBE', 'VNQ', 'SCHD', 'QUAL',
                     'EWY', 'EWT')   # v1.414.0: KSTR removed (owner's KSTR is UCITS -> justETF path);
                     # XBI removed too -- it name-matches only to top-25 (never >=50), so requiring it
                     # would break the carry every run. Targets = exactly the funds PROVEN to go deep.   # v1.408.0: only funds PROVEN to name-match gate the carry
                     # (SPDRs/iShares sector filings are ticker-less -> honest top-25; requiring them would
                     # force a futile refetch every run). New KSTR/EWY/EWT force ONE refresh to fetch them.
    _pdd = (prev.get('deep_diag') or {})
    _deep_have = set(k for k, v in _pdd.items() if isinstance(v, dict) and (v.get('n', 0) or 0) >= 50)
    _deep_ok = _deep_have.issuperset(set(_DEEP_TARGETS))
    if fresh and cache and _deep_ok:
        log('  [MOAT cover] carried (fresh <5d, all %d deep ETFs present)' % len(_DEEP_TARGETS))
        return prev
    got = 0
    for etf in MOAT_COVER_ETFS:
        try:
            rows = fetch_etf_holdings(etf) or []
            tks = [str(r.get('ticker') or '').upper() for r in rows if r.get('ticker')]
            if tks:
                cache[etf] = tks; got += 1
        except Exception:
            pass
    # v1.373.0: BROAD funds via TV holdings (Business-Recorder technique). TV is runner-reachable.
    # v1.387.0: BROAD funds -- SEC EDGAR N-PORT first (free, full holdings), then paid-API fallbacks.
    # v1.400.0: deep EDGAR holdings for the broad funds AND the sector/thematic ETFs the bridge maps to.
    _DEEP_ETFS = ('IVV', 'ITOT', 'VTI', 'QQQ', 'SOXX', 'SMH', 'XLK', 'VGT', 'IGV', 'XLE', 'XLF', 'KRE',
                  'KBE', 'XLV', 'XBI', 'IBB', 'IHI', 'XLI', 'PPA', 'ITA', 'XLB', 'XLP', 'XLY', 'XLU',
                  'XLRE', 'VNQ', 'IWM', 'SCHD', 'MTUM', 'QUAL', 'EWY', 'EWT')
    deep_diag = {}
    for _bt in _DEEP_ETFS:
        _tks, _info = [], {}
        try:
            _tks, _info = fetch_edgar_nport_holdings(_bt)   # v1.396.0: edgartools first
        except Exception as _ee:
            _info = {'src': 'edgar', 'n': 0, 'err': type(_ee).__name__}
        if len(_tks) < 50:
            try:
                _st, _si = fetch_sec_nport_holdings(_bt)
                if len(_st) > len(_tks): _tks, _info = _st, _si
            except Exception as _se:
                pass
        if len(_tks) < 50:   # still shallow -> try finnhub then ninja
            try:
                _ft, _fi = fetch_finnhub_etf_holdings(_bt)
                if len(_ft) > len(_tks): _tks, _info = _ft, _fi
            except Exception: pass
        if len(_tks) < 50:
            try:
                _nt, _ni = fetch_ninja_etf_holdings(_bt)
                if len(_nt) > len(_tks): _tks, _info = _nt, _ni
            except Exception: pass
        deep_diag[_bt] = _info
        if _tks and len(_tks) > len(cache.get(_bt) or []):   # v1.405.0: monotonic -- never worse over better
            cache[_bt] = _tks
    log('  [MOAT cover] fetched %d/%d top-25 ETFs + broad deep: %s'
        % (got, len(MOAT_COVER_ETFS), {k: (v or {}).get('n', 0) for k, v in deep_diag.items()}))
    return {'by_etf': cache, 'as_of': dt.datetime.now(dt.timezone.utc).isoformat(),
            'n_etfs': len(cache), 'deep_diag': deep_diag,
            # v1.408.0: real per-holding weights + fund cash sleeve from the same N-PORT filings.
            'deep_weights': {**((prev.get('deep_weights')) or {}), **{k: v['weights'] for k, v in _EDGAR_EXTRA.items() if v.get('weights')}},
            'deep_cash': {**((prev.get('deep_cash')) or {}), **{k: v['cash_pct'] for k, v in _EDGAR_EXTRA.items() if v.get('cash_pct') is not None}}}



def build_etf_holdings_index(data):
    """v1.397.0: ONE canonical ETF-holdings index for the whole dashboard.
    Reads the real EDGAR/broad holdings already in moat_cover.by_etf and produces:
      {'by_stock': {TICKER: [etfs...]}, 'holder_count': {TICKER: n}, 'n_etfs': N, 'n_stocks': M, 'as_of': ...}
    Any tab can ask 'which ETFs hold X' or 'how many funds hold X' from this single source."""
    cover = ((data.get('moat_cover') or {}).get('by_etf') or {})
    wz = ((data.get('wave_z') or {}).get('fund_cache') or {})
    by_stock = {}
    for _etf, _tks in cover.items():
        if not isinstance(_tks, list):
            continue
        for _t in _tks:
            _u = str(_t or '').upper()
            if _u:
                by_stock.setdefault(_u, set()).add(_etf)
    # union in wave_z fund holdings if present (same shape: fund -> [tickers])
    for _fund, _info in (wz.items() if isinstance(wz, dict) else []):
        _tks = _info.get('holdings') if isinstance(_info, dict) else _info
        if isinstance(_tks, list):
            for _t in _tks:
                _u = str(_t or '').upper()
                if _u:
                    by_stock.setdefault(_u, set()).add(_fund)
    out_by_stock = {k: sorted(v) for k, v in by_stock.items()}
    holder_count = {k: len(v) for k, v in out_by_stock.items()}
    return {
        'by_stock': out_by_stock,
        'holder_count': holder_count,
        'n_etfs': len(cover),
        'n_stocks': len(out_by_stock),
        'as_of': dt.datetime.now(dt.timezone.utc).isoformat(),
    }

def etf_holders_for(data, ticker, limit=10):
    """Convenience accessor any builder can call: list of ETFs holding `ticker`."""
    idx = (data.get('etf_holdings_index') or {}).get('by_stock') or {}
    return (idx.get(str(ticker or '').upper()) or [])[:limit]


def build_moat_universe(data, existing=None):
    """Wave MOAT (v1.357.0): the moat watchlist with (1) live returns tracked forward from first-seen
    for the US names via the proven america/scan endpoint, (2) every-engine cross-reference (IM3, Zacks,
    TipRanks, whale, Explosive/Turnaround/M1/Multibagger/TCE/WaveZ flags), (3) ETF-conviction confirm
    (file n_etfs + which tracked funds actually hold it, from wave_z.fund_cache). No fabricated data:
    non-US names show the file's static 1Y; live column only where the endpoint returns a price."""
    prev = ((existing or {}).get('moat') or {})
    prev_rows = {r.get('isin'): r for r in (prev.get('rows') or [])}
    today = dt.date.today().isoformat()

    # --- cross-ref indexes from existing engines (all already in the payload) ---
    det = data.get('im3_detail') or {}
    im3_book = {}
    for _src in ('explosive_us', 'tce_us', 'psx_candidates'):
        for _r in (data.get(_src) or []):
            if isinstance(_r, dict) and _r.get('ticker') and isinstance(_r.get('im3'), dict):
                im3_book.setdefault(_r['ticker'], _r['im3'])
    def _im3grade(tk):
        g = (det.get(tk) or {})
        if g.get('grade'): return g.get('grade'), g.get('pct')
        b = im3_book.get(tk) or {}
        return b.get('grade'), b.get('pct')
    zk = {}
    for _r in ((data.get('zacks_radar') or {}).get('rows') or []):
        if isinstance(_r, dict) and _r.get('ticker'): zk[_r['ticker']] = _r.get('zacks_rank') or _r.get('rank')
    tr = ((data.get('tipranks') or {}).get('by_ticker') or {})
    wh = ((data.get('whale_13f') or {}).get('by_ticker') or {})
    def _flagset(src_key, field='ticker'):
        out = set()
        node = data.get(src_key)
        rows = node if isinstance(node, list) else ((node or {}).get('rows') or (node or {}).get('stocks') or [])
        for _r in rows:
            if isinstance(_r, dict) and _r.get(field): out.add(_r[field])
        return out
    f_expl = _flagset('explosive_us'); f_turn = set()
    for _r in (data.get('explosive_us') or []):
        if isinstance(_r, dict) and _r.get('ticker') and 'TURNAROUND' in str(_r.get('verdict', '')).upper():
            f_turn.add(_r['ticker'])
    f_m1 = set((data.get('m1_buylist') or {}).keys()) if isinstance(data.get('m1_buylist'), dict) else _flagset('m1_buylist')
    f_mb = _flagset('m2_watch') | _flagset('us_multibagger')
    f_tce = _flagset('tce_us')
    wz_common = {c.get('ticker') for c in ((data.get('wave_z') or {}).get('common') or []) if isinstance(c, dict)}
    fund_cache = ((data.get('wave_z') or {}).get('fund_cache') or {})
    # v1.361.0: holders = REAL ETF holdings from moat_cover UNION wave_z cache (no file dependency)
    holders = {}
    cover_by_etf = ((data.get('moat_cover') or {}).get('by_etf') or {})
    for _etf, _tks in cover_by_etf.items():
        for _h in _tks:
            holders.setdefault(_h, []).append(_etf)
    for _fsym, _fc in fund_cache.items():
        for _h in (_fc.get('holdings') or []):
            holders.setdefault(_h, []).append(_fsym)
    # dedup per ticker
    for _k in list(holders.keys()):
        holders[_k] = sorted(set(holders[_k]))

    # --- live price fetch (US tickers) via the proven endpoint, chunked ---
    # v1.358.0: america/scan resolves EXCHANGE-PREFIXED symbols only. Prefix NASDAQ:<t> (this request
    # resolves NYSE-listed names too, same as the foundation-universe call). Pull the ready 'Perf.Y'
    # 1-year column alongside close/change.
    tickers = [r[2] for r in _MOAT_SEED if r[2]]
    live = {}
    _mdiag = {'http': {}, 'n_returned': 0, 'n_matched': 0, 'sent': len(tickers)}
    try:
        # v1.359.0: america/scan resolves EXACT exchange prefixes only, and moat names span NASDAQ +
        # NYSE. We don't carry each name's exchange, so send BOTH candidates (NASDAQ:<t> AND NYSE:<t>);
        # the real one resolves, the wrong one is simply absent from data (no error, no cost). This is
        # how america/scan is meant to be queried for a mixed-exchange list -- proven by the foundation
        # universe call, which resolves both exchanges under markets:['america'].
        _cands = []
        for t in tickers:
            _cands.append('NASDAQ:%s' % t); _cands.append('NYSE:%s' % t)
        for i in range(0, len(_cands), 100):
            chunk = _cands[i:i+100]
            r = requests.post('https://scanner.tradingview.com/america/scan',
                              json={'symbols': {'tickers': chunk}, 'columns': ['close', 'change', 'Perf.Y', 'Perf.YTD']},
                              headers={'User-Agent': UA}, timeout=30)
            _mdiag['http'][str(r.status_code)] = _mdiag['http'].get(str(r.status_code), 0) + 1
            if r.status_code == 200:
                _rows = (r.json().get('data') or [])
                _mdiag['n_returned'] += len(_rows)
                for row in _rows:
                    sym = str(row.get('s', '')).split(':')[-1]
                    dvals = row.get('d') or []
                    if dvals and isinstance(dvals[0], (int, float)):
                        live[sym] = {'px': round(float(dvals[0]), 2),
                                     'chg': round(float(dvals[1]), 2) if len(dvals) > 1 and isinstance(dvals[1], (int, float)) else None,
                                     'perf_y': round(float(dvals[2]), 2) if len(dvals) > 2 and isinstance(dvals[2], (int, float)) else None,
                                     'perf_ytd': round(float(dvals[3]), 2) if len(dvals) > 3 and isinstance(dvals[3], (int, float)) else None}
                        _mdiag['n_matched'] += 1
    except Exception as _me:
        _mdiag['error'] = type(_me).__name__
        log('  [MOAT] live price fetch failed: %s (static returns retained)' % type(_me).__name__)
    if tickers and _mdiag['n_matched'] == 0:
        warn('[moat] 0/%d US names resolved live -- http=%s returned=%d (see moat.diag)'
             % (len(tickers), _mdiag['http'], _mdiag['n_returned']))

    rows = []
    n_live = 0
    for rec in _MOAT_SEED:
        name, isin, tk, n_etfs, mcap, pe, divy, ret1y, maxdd, sector, country, ucits_file = rec
        pr = prev_rows.get(isin) or {}
        row = {'name': name, 'isin': isin, 'ticker': tk, 'n_etfs': n_etfs,
               'mcap_m_eur': mcap, 'pe': pe, 'div_yld': divy,
               'ret_1y_file': ret1y, 'maxdd_1y': maxdd, 'sector': sector, 'country': country}
        # forward return tracking (US names with a live price)
        lv = live.get(tk) if tk else None
        if lv:
            n_live += 1
            row['px'] = lv['px']; row['chg_pct'] = lv['chg']
            base = pr.get('base_px')
            base_date = pr.get('base_date')
            if base is None:
                base = lv['px']; base_date = today
            row['base_px'] = base; row['base_date'] = base_date
            row['ret_since'] = round((lv['px'] / base - 1) * 100, 2) if base else None
            if lv.get('perf_y') is not None: row['ret_1y_live'] = lv['perf_y']
            if lv.get('perf_ytd') is not None: row['ret_ytd_live'] = lv['perf_ytd']
        else:
            row['base_px'] = pr.get('base_px'); row['base_date'] = pr.get('base_date')
            row['ret_since'] = pr.get('ret_since')
            row['static'] = True   # no live endpoint -> file figure is the only return
        # engine cross-refs
        if tk:
            g, gp = _im3grade(tk)
            row['im3_grade'] = g; row['im3_pct'] = gp
            row['zacks'] = zk.get(tk)
            _tr = tr.get(tk)
            if _tr: row['tipranks'] = _tr.get('consensus'); row['tr_upside'] = _tr.get('upside_pct')
            _wh = wh.get(tk)
            if _wh and _wh.get('n_whales'): row['whale'] = {'dir': _wh.get('dir'), 'n': _wh.get('n_whales')}
            flags = []
            if tk in f_expl: flags.append('Explosive')
            if tk in f_turn: flags.append('Turnaround')
            if tk in f_m1: flags.append('M1')
            if tk in f_mb: flags.append('Multibagger')
            if tk in f_tce: flags.append('TCE')
            if tk in wz_common: flags.append('WaveZ')
            row['engine_flags'] = flags
            row['fund_holders'] = holders.get(tk, [])[:8]
        # v1.360.0: UCITS ETFs (from the owner's file) that list this name among major holdings,
        # plus US ETFs from wave_z that actually hold it live (real top-25). Both are ETF-ownership
        # confirmation; file matches are a floor (file lists only top ~4 per fund).
        row['ucits_file'] = ucits_file or []
        row['etf_holders_live'] = holders.get(tk, [])[:10] if tk else []
        rows.append(row)

    # leaders: highest by the best available return (live since-tracking if present else file 1Y)
    def _score(r): 
        return r.get('ret_since') if r.get('ret_since') is not None else (r.get('ret_1y_file') or -999)
    leaders = sorted(rows, key=lambda r: -(_score(r) if _score(r) is not None else -999))[:20]
    leader_isins = [r['isin'] for r in leaders]

    # v1.362.0: rank live UCITS ETFs by how many top-return moat leaders they hold (full columns kept)
    import re as _re2
    _pool = []
    for _k in ('etf_momentum_watch', 'etf_emerging_themes_watch', 'etf_hydrogen_watch', 'etf_metals_etc_watch'):
        for _e in (data.get(_k) or []):
            if isinstance(_e, dict) and _e.get('isin') and _e.get('holdings'):
                _pool.append(_e)
    _lead = sorted([r for r in rows if (r.get('ret_1y_live') if r.get('ret_1y_live') is not None else r.get('ret_1y_file')) is not None],
                   key=lambda r: -((r.get('ret_1y_live') if r.get('ret_1y_live') is not None else r.get('ret_1y_file')) or -999))[:40]
    _lead_names = [(r['name'].split(',')[0].split(' Inc')[0].split(' Corp')[0].strip().lower(),
                    r.get('ticker'), (r.get('ret_1y_live') if r.get('ret_1y_live') is not None else r.get('ret_1y_file'))) for r in _lead]
    _seen_isin = set(); _top_etfs = []
    for _e in _pool:
        _iid = _e.get('isin')
        if _iid in _seen_isin: continue
        _h = (_e.get('holdings') or '').lower()
        _hits = [(nm, tk, rt) for (nm, tk, rt) in _lead_names if nm and len(nm) > 3 and nm in _h]
        if not _hits: continue
        _seen_isin.add(_iid)
        _top_etfs.append({'name': _e.get('name'), 'isin': _iid, 'ter': _e.get('ter'),
                          'ytd': _e.get('live_ytd') if _e.get('live_ytd') is not None else _e.get('ytd'),
                          'ret_1y': _e.get('live_ret_1y') if _e.get('live_ret_1y') is not None else _e.get('ret_1y'),
                          'category': _e.get('category') or _e.get('theme') or _e.get('segment'),
                          'estate_status': _e.get('estate_status'), 'domicile': _e.get('domicile'),
                          'n_holdings': _e.get('n_holdings'), 'holdings': _e.get('holdings'),
                          'n_leaders': len(_hits),
                          'leaders_held': [{'tk': tk, 'name': nm.title(), 'ret': rt} for (nm, tk, rt) in _hits[:6]]})
    _top_etfs.sort(key=lambda x: (-x['n_leaders'], -((x.get('ret_1y') or -999))))
    log('  [MOAT] %d names | %d live-tracked (US) | %d with engine grade | leaders top ret %.0f%%'
        % (len(rows), n_live, sum(1 for r in rows if r.get('im3_grade')),
           (_score(leaders[0]) if leaders else 0) or 0))
    return {'rows': rows, 'leader_isins': leader_isins, 'diag': _mdiag,
            'top_etfs': _top_etfs[:25],
            'n_total': len(rows), 'n_live': n_live,
            'as_of': dt.datetime.now(dt.timezone.utc).isoformat(),
            'note': 'wide-moat watchlist; US names live-tracked forward from first-seen, non-US show file 1Y; engine columns are cross-references, MOAT membership is not itself a score'}


def build_wave_z(data, existing=None):
    """v1.353.0 WAVE Z: rank the curated US ETF+MF seed lists on Zacks, take the #1s, intersect their
    top holdings -> the names the top-ranked funds own in common. All-Zacks (ranks AND holdings), the
    proven flatten-then-regex pattern, loud diagnostics, 5-day per-fund cache."""
    import re as _re, json as _json
    prev = ((existing or {}).get('wave_z') or {})
    cache = dict(prev.get('fund_cache') or {})
    diag = {'http': {}, 'rank_parse_fail': 0, 'holdings_parse_fail': 0, 'holdings_mode': {}}
    today = dt.date.today()

    def _flat(txt):
        t = _re.sub(r'<[^>]+>', ' ', txt or '')
        t = t.replace('&amp;', '&').replace('&nbsp;', ' ')
        return _re.sub(r'\s+', ' ', t)

    def _fetch(url):
        try:
            r = requests.get(url, headers={'User-Agent': UA}, timeout=14)
            diag['http'][str(r.status_code)] = diag['http'].get(str(r.status_code), 0) + 1
            return r.text if (r.status_code == 200 and r.text) else None
        except Exception as _fe:
            diag['http'][type(_fe).__name__] = diag['http'].get(type(_fe).__name__, 0) + 1
            return None

    def _rank_of(sym, kind):
        c = cache.get(sym)
        if c and c.get('as_of'):
            try:
                if (today - dt.date.fromisoformat(c['as_of'])).days < 5:
                    return c.get('rank')
            except Exception:
                pass
        url = ('https://www.zacks.com/funds/etf/%s/profile' % sym if kind == 'etf'
               else 'https://www.zacks.com/funds/mutual-fund/quote/%s' % sym)
        raw = _fetch(url)
        if raw is None:
            return (c or {}).get('rank')
        t = _flat(raw)
        m = _re.search(r'(\d)\s*-\s*Strong Buy of 5|Strong Buy\s+1\b|(\d)\s*-\s*(?:Strong Buy|Buy|Hold|Sell|Strong Sell)\s+of\s+5', t)
        rk = None
        m2 = _re.search(r'(\d)\s*-\s*(Strong Buy|Buy|Hold|Sell|Strong Sell)\s+of\s+5', t)
        if m2:
            rk = int(m2.group(1))
        elif 'NA View All Zacks' in t or ' Rank NA ' in t:
            rk = None
        else:
            diag['rank_parse_fail'] += 1
        cache[sym] = {'rank': rk, 'as_of': today.isoformat(), 'kind': kind,
                      'holdings': (c or {}).get('holdings')}
        return rk

    def _holdings_of(sym, kind):
        # v1.354.0: Zacks /holding tables are JS-loaded (proven by raw-page fetch: 'Loading Data...').
        # ETFs -> the EXISTING stockanalysis holdings fetcher (server-rendered, confirmed live).
        # Mutual funds -> no free machine-readable source exists; rank-chips only, recorded in diag.
        if kind != 'etf':
            diag['mf_holdings'] = 'no-free-source (Zacks JS-only; tested 2026-08-05)'
            return []
        c = cache.get(sym) or {}
        if c.get('holdings') and c.get('as_of'):
            try:
                if (today - dt.date.fromisoformat(c['as_of'])).days < 5:
                    return c['holdings']
            except Exception:
                pass
        got = []
        try:
            rows = fetch_etf_holdings(sym) or []
            got = [str(r.get('ticker') or '').upper() for r in rows if r.get('ticker')][:15]
            if got:
                diag['holdings_mode']['stockanalysis'] = diag['holdings_mode'].get('stockanalysis', 0) + 1
        except Exception as _he:
            diag['http'][type(_he).__name__] = diag['http'].get(type(_he).__name__, 0) + 1
        got = [g for g in got if g not in ('ETF', 'NA', 'USD', 'FUND', 'CASH')]
        if not got:
            diag['holdings_parse_fail'] += 1
        cache.setdefault(sym, {})['holdings'] = got
        cache[sym]['as_of'] = today.isoformat()
        return got

    rank1 = {'etfs': [], 'mfs': []}
    for sym in WAVE_Z_ETFS:
        if _rank_of(sym, 'etf') == 1: rank1['etfs'].append(sym)
    for sym in WAVE_Z_MFS:
        if _rank_of(sym, 'mf') == 1: rank1['mfs'].append(sym)

    counts = {}
    for sym in rank1['etfs'][:10]:
        for h in _holdings_of(sym, 'etf'):
            counts.setdefault(h, set()).add(sym)
    # v1.354.0: MF holdings unavailable free -- intersection runs over the #1 ETFs; MF chips still shown.
    common = sorted(({'ticker': k, 'n_funds': len(v), 'funds': sorted(v)}
                     for k, v in counts.items() if len(v) >= 2),
                    key=lambda x: -x['n_funds'])[:40]

    log('  [Wave Z] rank-1: %d ETFs %s / %d MFs %s | common holdings (>=2 funds): %d'
        % (len(rank1['etfs']), rank1['etfs'][:6], len(rank1['mfs']), rank1['mfs'][:4], len(common)))
    if not rank1['etfs'] and not rank1['mfs']:
        warn('[wave z] zero rank-1 funds parsed -- http=%s rank_fail=%d (see wave_z.diag)'
             % (diag['http'], diag['rank_parse_fail']))
    return {'rank1': rank1, 'common': common,
            'universe': {'etfs_checked': len(WAVE_Z_ETFS), 'mfs_checked': len(WAVE_Z_MFS)},
            'fund_cache': cache, 'diag': diag,
            'as_of': dt.datetime.now(dt.timezone.utc).isoformat(),
            'note': 'names held in common by Zacks #1-ranked funds from the curated US seed lists; universe surfacing only -- not a scoring input'}


def fetch_tipranks_overlay(data, existing=None):
    """v1.350.0 (owner-instructed): TipRanks analyst consensus overlay for the TOP US names on the
    recommended list. DISPLAY-ONLY by prior head-to-head verdict (Zacks beat TipRanks on both live
    disagreements) -- this never enters any score. Server-rendered /forecast pages, sentence-anchor
    parses validated against a real fetched page before this was written. 3-day TTL, EXISTING-carried,
    every failure soft + warn-quiet."""
    import re as _re
    out = dict(((existing or {}).get('tipranks') or {}).get('by_ticker') or {})
    picks = ['APD'] + [r.get('ticker') for r in ((data.get('recommended') or {}).get('stocks') or [])
             if isinstance(r, dict) and r.get('market') != 'PSX' and ':' not in str(r.get('ticker') or '')
             and str(r.get('ticker')).upper() != 'APD'][:25]   # v1.421.0: APD always covered (NetBenefits)
    # v1.439.0: every Policy-Catalyst radar ticker joins the display-only pool so each radar chip
    # can show analyst context (owner). Order-safe: this overlay runs at the tail AFTER
    # build_policy_catalyst (verified 25765 > 25514 in runtime order); dedup preserves cache TTLs.
    _radar = []
    for _cat, _its in ((data.get('policy_catalyst') or {}).get('by_category') or {}).items():
        for _it in (_its or []):
            for _t in (_it.get('tickers') or []):
                if _t.get('ticker'): _radar.append(_t['ticker'])
    picks = list(dict.fromkeys(picks + _radar))
    today = dt.date.today()
    fetched = 0
    _diag = {'http': {}, 'parse_fail': 0, 'sample_head': None}   # v1.351.0: failure modes must be visible
    for tk in picks:
        try:
            prev = out.get(tk)
            if prev and prev.get('as_of'):
                try:
                    if (today - dt.date.fromisoformat(prev['as_of'][:10])).days < 3:
                        continue   # cache fresh -- no request
                except Exception:
                    pass
            r = requests.get('https://www.tipranks.com/stocks/%s/forecast' % tk.lower(),
                             headers={'User-Agent': UA}, timeout=12)
            _diag['http'][str(r.status_code)] = _diag['http'].get(str(r.status_code), 0) + 1
            if r.status_code != 200 or not r.text:
                # v1.440.0 miss-cache (D-122 family): non-200 names refetched every scan forever;
                # record the miss under the same 3-day TTL. Index shows no TR chip without consensus.
                out[tk] = {'as_of': today.isoformat(), 'miss': True, 'http': r.status_code}
                continue
            # v1.352.0: the runner gets RAW html -- flatten it so the validated sentence anchors match.
            t = _re.sub(r'<[^>]+>', ' ', r.text)
            t = t.replace('&amp;', '&').replace('&nbsp;', ' ').replace('&#36;', '$')
            t = _re.sub(r'\s+', ' ', t)
            m1 = _re.search(r'consensus rating of (Strong Buy|Moderate Buy|Buy|Hold|Moderate Sell|Sell|Strong Sell)', t)
            m2 = _re.search(r'based on (\d+) buy ratings?, (\d+) hold ratings? and (\d+) sell ratings?', t)
            m3 = _re.search(r'average price target is \$([\d,\.]+) with a high forecast of \$([\d,\.]+) and a low forecast of \$([\d,\.]+)', t)
            m4 = _re.search(r'represents an? ([\-\d\.]+)% (?:change|Increase|Decrease)', t)
            if not (m1 and m3):
                _diag['parse_fail'] += 1
                if _diag['sample_head'] is None:
                    _diag['sample_head'] = (t or '')[:160]
                # v1.352.0 fallback: meta-description count -- proven present in the raw head by the diag.
                _mn = _re.search(r'based on (\d+) analysts', t)
                if _mn:
                    out[tk] = {'n_analysts': int(_mn.group(1)), 'as_of': today.isoformat(), 'partial': True}
                else:
                    # v1.440.0: full parse miss (bot-shield shells) cached under the same TTL
                    out[tk] = {'as_of': today.isoformat(), 'miss': True}
                continue
            _f = lambda x: float(str(x).replace(',', '').rstrip('.'))
            rec = {'consensus': m1.group(1),
                   'pt_avg': _f(m3.group(1)), 'pt_high': _f(m3.group(2)), 'pt_low': _f(m3.group(3)),
                   'as_of': today.isoformat()}
            if m2:
                rec['buy'], rec['hold'], rec['sell'] = int(m2.group(1)), int(m2.group(2)), int(m2.group(3))
            if m4:
                try: rec['upside_pct'] = float(m4.group(1))
                except Exception: pass
            out[tk] = rec
            fetched += 1
        except Exception as _te:
            warn('[tipranks] %s: %s' % (tk, type(_te).__name__))
    # prune tickers no longer on the list (keeps the store honest and small)
    keep = set(picks)
    out = {k: v for k, v in out.items() if k in keep}
    log('  [TipRanks] overlay: %d cached, %d freshly fetched (top-25 recommended US)' % (len(out), fetched))
    if picks and fetched == 0 and not out:
        warn('[tipranks] 0/%d fetched -- http=%s parse_fail=%d (see tipranks.diag in data.json)'
             % (len(picks), _diag['http'] or 'no-response', _diag['parse_fail']))
    return {'by_ticker': out, 'as_of': dt.datetime.now(dt.timezone.utc).isoformat(), 'diag': _diag,
            'note': 'display-only overlay; never a scoring input (head-to-head verdict: Zacks)'}


def build_sector_selection(data, existing=None):
    """Wave S (v1.344.0): the sector-selection verdict for BOTH markets, from the canonical methodology.
    PSX: SBP rate-zone (doc A.3/A.5) + five live triggers + backtested B/S/G allocation for both risk
    profiles. US: the A.4 Keynesian quadrant longs/shorts, reusing econ_clock's already-computed quadrant
    verbatim (D-110). Pure consolidation -- no fetch; every input already lives in the payload."""
    out = {}
    psx_m = (data.get('macros') or {}).get('psx') or {}
    us_m = (data.get('macros') or {}).get('us') or {}
    ec = data.get('econ_clock') or {}

    # ---------------- PSX side ----------------
    try:
        rate = psx_m.get('sbp_rate')
        cpi = psx_m.get('pak_cpi')
        arab = us_m.get('arab_light_live') or us_m.get('arab_light')  # v1.348.0: pinned live basis first
        prior_rate = (((existing or {}).get('macros') or {}).get('psx') or {}).get('sbp_rate')
        if rate is not None:
            r = float(rate)
            if r >= 11.0:   zone, color = 'RED', '#B91C1C'
            elif r >= 9.0:  zone, color = 'YELLOW', '#B45309'
            elif r >= 7.0:  zone, color = 'LIGHT GREEN', '#15803D'
            else:           zone, color = 'DARK GREEN', '#166534'
        else:
            zone, color = None, None
        _ALLOC = {  # doc A.5, backtested: zone -> {profile: (bonds, stocks, gold)}
            'DARK GREEN':  {'high': (0, 100, 0),  'low': (15, 70, 15)},
            'LIGHT GREEN': {'high': (10, 80, 10), 'low': (25, 50, 25)},
            'YELLOW':      {'high': (20, 60, 20), 'low': (30, 40, 30)},
            'RED':         {'high': (40, 20, 40), 'low': (50, 0, 50)},
        }
        triggers = []
        if isinstance(cpi, (int, float)) and cpi >= 11.0:
            triggers.append({'id': 'A', 'label': 'Inflation >= 11% -- defensive tilt',
                             'value': round(float(cpi), 2), 'fired': True})
        else:
            triggers.append({'id': 'A', 'label': 'Inflation >= 11% -- defensive tilt',
                             'value': (round(float(cpi), 2) if isinstance(cpi, (int, float)) else None), 'fired': False})
        _b_fired = isinstance(arab, (int, float)) and float(arab) > 60.0
        triggers.append({'id': 'B', 'label': 'Arab Light > $60 -- overweight E&P (30% single-sector cap)',
                         'value': (round(float(arab), 2) if isinstance(arab, (int, float)) else None), 'fired': bool(_b_fired)})
        _a_fired = triggers[0]['fired']
        triggers.append({'id': 'C', 'label': 'A + B together -- defensive book, E&P-led',
                         'value': None, 'fired': bool(_a_fired and _b_fired)})
        _rd = _rh = False
        if rate is not None and isinstance(prior_rate, (int, float)):
            _rd = float(rate) < float(prior_rate)
            _rh = float(rate) > float(prior_rate)
        triggers.append({'id': 'D', 'label': 'SBP rate CUT since prior run -- increase Banks',
                         'value': (float(prior_rate) if isinstance(prior_rate, (int, float)) else None), 'fired': bool(_rd)})
        triggers.append({'id': 'E', 'label': 'SBP rate HIKE since prior run -- raise T-Bills',
                         'value': (float(prior_rate) if isinstance(prior_rate, (int, float)) else None), 'fired': bool(_rh)})
        real_rate = (round(float(rate) - float(cpi), 2)
                     if isinstance(rate, (int, float)) and isinstance(cpi, (int, float)) else None)
        alloc = _ALLOC.get(zone) if zone else None
        out['psx'] = {
            'zone': zone, 'zone_color': color,
            'favored': ['Banks', 'E&P', 'Fertilizer', 'Utility/Power', 'Chemicals'] if zone == 'RED' else
                       (['Banks', 'E&P', 'Fertilizer', 'Cement', 'IT/Export'] if zone == 'YELLOW' else
                        ['Cement', 'Autos', 'Steel', 'Textiles', 'Cyclicals']),
            'triggers': triggers,
            'allocation': ({'high': {'bonds': alloc['high'][0], 'stocks': alloc['high'][1], 'gold': alloc['high'][2]},
                            'low':  {'bonds': alloc['low'][0],  'stocks': alloc['low'][1],  'gold': alloc['low'][2]}}
                           if alloc else None),
            'real_rate_pp': real_rate,
            'inputs': {'sbp_rate': rate, 'pak_cpi': cpi, 'arab_light': arab, 'prior_sbp_rate': prior_rate},
            'basis': 'SBP rate-zone map (doc A.3) + backtested B/S/G allocation (doc A.5); triggers from live macros',
        }
    except Exception as _e:
        out['psx'] = ((existing or {}).get('sector_selection') or {}).get('psx')
        log('  [Sector Selection] PSX side failed: %s' % type(_e).__name__)

    # ---------------- US side ----------------
    try:
        quad = ((ec.get('us') or {}).get('quadrant') or '').upper() or None
        _MAP = {  # doc A.4, verbatim
            'GOLDILOCKS': {'longs': ['Financials', 'Industrials', 'Technology', 'Materials', 'Commodities', 'Pro-cyclical/EM FX'],
                           'shorts': ['Utilities', 'Staples', 'Health Care', 'TIPS', 'Long Bonds', 'DXY']},
            'REFLATION': {'longs': ['Financials', 'Industrials', 'Energy', 'Consumer Discretionary', 'Commodities', 'EM FX'],
                          'shorts': ['Utilities', 'Staples', 'Real Estate', 'Communications', 'Long Bonds', 'DXY']},
            'DISINFLATION': {'longs': ['Utilities', 'Staples', 'Health Care', 'Real Estate', 'Long Bonds', 'DXY'],
                             'shorts': ['Financials', 'Industrials', 'Technology', 'Materials', 'Commodities']},
            'STAGFLATION': {'longs': ['Utilities', 'Staples', 'Communications', 'Long Bonds', 'TIPS', 'Commodities', 'DXY/G10 FX'],
                            'shorts': ['Financials', 'Industrials', 'Energy', 'Consumer Discretionary', 'EM FX']},
        }
        m = _MAP.get(quad)
        out['us'] = ({'quadrant': quad, 'longs': m['longs'], 'shorts': m['shorts'],
                      'source': 'econ_clock quadrant (computed once, reused verbatim -- D-110) + doc A.4 longs/shorts'}
                     if m else ((existing or {}).get('sector_selection') or {}).get('us'))
    except Exception as _e:
        out['us'] = ((existing or {}).get('sector_selection') or {}).get('us')
        log('  [Sector Selection] US side failed: %s' % type(_e).__name__)

    _pz = (out.get('psx') or {}).get('zone'); _uq = (out.get('us') or {}).get('quadrant')
    log('  [Sector Selection] PSX zone=%s | US quadrant=%s | triggers fired: %s'
        % (_pz, _uq, ','.join(t['id'] for t in ((out.get('psx') or {}).get('triggers') or []) if t.get('fired')) or 'none'))
    return out


def build_recommended(data):
    """Component D (v1.323.0) -- the dashboard UNANIMOUS verdict: stocks and ETFs its OWN engines agree on.
    Pure consolidation, no fetch. conviction = how many independent engines surface a name; only names >=2
    engines agree on are recommended, ranked by that agreement. Reads the estate/canon-stamped ETF rows so
    every recommended fund already carries ytd_pct/n_holdings/estate_status. Emits data['recommended']."""
    fmap = {r.get('ticker'): r for r in (data.get('foundation_universe') or []) if r.get('ticker')}
    def _zrank(tk):
        z = (data.get('zacks_ranks') or {}).get(tk)
        if isinstance(z, dict): return z.get('rank') or z.get('zacks_rank')
        return z if isinstance(z, (int, float)) else None
    whale_tk = set()
    for _c in ((data.get('whale_13f') or {}).get('consensus_buys') or []):
        _t = _c.get('ticker') if isinstance(_c, dict) else None
        if _t: whale_tk.add(_t)
    # v1.332.0: live explosive-screen perf, preferred over the foundation-only figure (small-caps below
    # foundation_universe's $2bn floor otherwise showed 0.0%%; explosive_us carries a real Perf.YTD/Perf.Y now).
    exmap = {r.get('ticker'): r for r in (data.get('explosive_us') or []) if r.get('ticker')}
    # v1.333.0: outperformance gate inputs for the Turnaround + small-cap sources.
    idx_ret = data.get('index_returns') or {}
    sec_avg = _sector_avg_perf(data)
    # v1.335.0: moved UP from the ranking-modifier pass below so the SAME computation feeds both the new
    # Sector-Booming source (here) and the existing +0.5 rank bonus (unchanged, reads this same dict).
    band_by_sec = {s.get('sector'): s.get('band') for s in (data.get('sector_booming') or []) if isinstance(s, dict)}
    gmap = globals().get('_M1_FINE_TO_GICS', {})
    eng = {}
    def _add(tk, label, name=None, sector=None):
        if not tk: return
        e = eng.setdefault(tk, {'name': name, 'sector': sector, 'agree': []})
        if label not in e['agree']: e['agree'].append(label)
        if name and not e.get('name'): e['name'] = name
        if sector and not e.get('sector'): e['sector'] = sector
    for r in (data.get('explosive_us') or []):
        # v1.337.0 FIX: was `'EXPLOSIVE' in verdict` -- a substring match that ALSO caught every
        # 'NOT EXPLOSIVE...' verdict (NOT EXPLOSIVE contains the substring EXPLOSIVE), falsely
        # crediting an Explosive engine to stocks the screen had actually rejected. startswith is exact.
        if str(r.get('verdict', '')).upper().startswith('EXPLOSIVE'): _add(r.get('ticker'), 'Explosive', r.get('name'), r.get('sector'))
    for r in (data.get('tce_us') or []):
        if str(r.get('tier')).upper() == 'HIGH': _add(r.get('ticker'), 'TCE-HIGH', r.get('name'), r.get('sector'))
    for r in (data.get('us_multibagger') or []): _add(r.get('ticker'), 'Multibagger', r.get('name'), r.get('sector'))
    for r in ((data.get('global_discovery') or {}).get('picks') or []): _add(r.get('ticker'), 'Discovery', r.get('name'), r.get('sector'))
    for r in ((data.get('m1_buylist') or {}).get('buys') or []): _add(r.get('ticker'), 'M1-Buy', r.get('name'), r.get('sector'))
    for tk in whale_tk: _add(tk, 'Whale-consensus')
    # v1.332.0: the dedicated M2 turnaround lane (Signal-T fired: TTM profit crossing loss->profit or rising
    # 2+ consecutive quarters) was computed but never read here, so a genuine inflection that missed the
    # stricter EXPLOSIVE growth gate was invisible in the consensus. Read as its own source so it shows
    # alongside growth picks rather than being silently dropped.
    turnaround_tk = set()
    for r in ((data.get('m2_watch') or {}).get('watch_turnaround_full') or []):
        _add(r.get('ticker'), 'Turnaround', r.get('name'), r.get('sector'))
        if r.get('ticker'): turnaround_tk.add(r.get('ticker'))
    # v1.335.0: Booming-sector stocks were computed but NEVER a source -- only a +0.5 bonus on names
    # already in via another engine, so 818/826 Booming-sector names (incl. XOM/CVX/JPM/BAC/CAT) were
    # invisible to Tab 19. Read straight from foundation_universe (already fetched, zero new cost); the
    # standing >=2-engine rule still gates entry, so this surfaces genuine crossovers, not a name dump.
    for r in (data.get('foundation_universe') or []):
        _tk = r.get('ticker')
        if _tk and band_by_sec.get(gmap.get(r.get('sector'), r.get('sector'))) == 'Booming':
            _add(_tk, 'Sector-Booming', r.get('name'), r.get('sector'))
    # v1.337.0: Banks-tab source -- owner asked to trace which Banks-tab names (banks + non-bank
    # financials, the SAME pool the Banks tab itself renders) could reach Tab 19, tagged for
    # traceability. One tag only, like any other source -- the standing >=2-engine rule is unchanged,
    # being on the Banks tab is not itself a second opinion.
    for r in (data.get('explosive_us') or []):
        _is_bank_row = bool(r.get('is_bank')) or str(r.get('verdict', '')).upper().startswith('FINANCIAL')
        _is_fin_row = _is_bank_row or 'financ' in str(r.get('sector', '')).lower()
        if _is_fin_row:
            _add(r.get('ticker'), 'Banks-tab', r.get('name'), r.get('sector'))
    # v1.338.0: Narrative-tab source -- narr_tk (Tab 18's live-narrative tickers) was only ever a
    # +0.25 ranking bonus on names that already qualified elsewhere, same flaw already fixed for
    # Sector-Booming/Turnaround. Read the SAME narr_tk set the ranking-modifier pass below already
    # builds (moved up here, reused by both -- one computation, two consumers, exactly the v1.335.0
    # band_by_sec pattern) as a real, gated source. One tag only, standing >=2-engine rule unchanged.
    _narr_tk_early = set()
    for _th in ((data.get('narratives') or {}).get('themes') or []):
        if not isinstance(_th, dict):
            continue
        for _af in (_th.get('affected') or []):
            _nt = _af.get('ticker') if isinstance(_af, dict) else _af
            if isinstance(_nt, str) and _nt:
                _narr_tk_early.add(_nt)
    _fmap_for_narr = {r.get('ticker'): r for r in (data.get('foundation_universe') or []) if r.get('ticker')}
    for _tk in _narr_tk_early:
        _fr = _fmap_for_narr.get(_tk) or exmap.get(_tk) or {}
        _add(_tk, 'Narrative-tab', _fr.get('name'), _fr.get('sector'))
    for tk in list(eng):
        zr = _zrank(tk)
        try:
            if zr is not None and float(zr) <= 2: eng[tk]['agree'].append('Zacks#%d' % int(float(zr)))
        except Exception: pass
    stocks = []
    for tk, e in eng.items():
        if len(e['agree']) < 2: continue
        f = fmap.get(tk, {}); xr = exmap.get(tk, {})
        _ytd = (xr.get('perf_ytd') if xr.get('perf_ytd') is not None else f.get('perf_ytd'))
        _sec = e.get('sector') or f.get('sector') or xr.get('sector')
        # v1.333.0: OUTPERFORMANCE GATE -- owner: turnarounds and small-caps must beat their sector AND
        # the market indices, not just show up on the engine count. Applies only to the two sources added
        # in v1.332.0 (Turnaround lane; small-cap = ticker absent from foundation_universe, i.e. below its
        # $2bn floor) -- core Explosive/TCE-HIGH/M1-Buy/Zacks/Whale/Multibagger/Discovery picks are untouched.
        _is_turnaround_only = (tk in turnaround_tk) and not any(a in ('Explosive', 'TCE-HIGH', 'M1-Buy') for a in e['agree'])
        _is_smallcap = (tk not in fmap) and (tk in exmap)
        _vs_sector = _vs_sp = _vs_nd = _vs_dow = None
        if _is_turnaround_only or _is_smallcap:
            if _ytd is not None:
                _savg = sec_avg.get(_sec)
                if _savg is not None: _vs_sector = round(_ytd - _savg, 2)
                _sp = (idx_ret.get('sp500') or {}).get('ytd')
                _nd = (idx_ret.get('nasdaq') or {}).get('ytd')
                _dw = (idx_ret.get('dow') or {}).get('ytd')
                if _sp is not None: _vs_sp = round(_ytd - _sp, 2)
                if _nd is not None: _vs_nd = round(_ytd - _nd, 2)
                if _dw is not None: _vs_dow = round(_ytd - _dw, 2)
                # fail OPEN: only reject when we HAVE a comparison and it says the pick lagged; a missing
                # comparison (sector or index data absent) never drops a name for lack of data.
                _checks = [x for x in (_vs_sector, _vs_sp, _vs_nd, _vs_dow) if x is not None]
                if _checks and any(x < 0 for x in _checks):
                    continue  # underperforms at least one available benchmark -- drop from consensus
        stocks.append({'ticker': tk, 'name': e.get('name') or f.get('name') or xr.get('name') or tk,
                       'sector': _sec,
                       'conviction': len(e['agree']), 'agree': e['agree'],
                       'ytd_pct': _ytd,
                       'ret_1y': (xr.get('perf_1y') if xr.get('perf_1y') is not None else f.get('perf_1y')),
                       'analyst_reco': f.get('recommendation_mark'),
                       'vs_sector_pct': _vs_sector, 'vs_sp500_pct': _vs_sp,
                       'vs_nasdaq_pct': _vs_nd, 'vs_dow_pct': _vs_dow})
    # v1.324.0 (Component E): cross-tab RANKING MODIFIERS -- a recommended name whose sector the
    # Tab 15 engine reads Booming/Favoured gets +0.5, and a name inside a live Tab 18 narrative
    # gets +0.25, on top of its engine-agreement conviction. Additive bonus only; never removes
    # a name. This is the propagation layer: the tabs finally reinforce each other.
    # band_by_sec / gmap: reuse the v1.335.0 copy computed earlier in this function (one calc, two consumers)
    # narr_tk: reuse the v1.338.0 copy computed earlier in this function (one calc, two consumers)
    narr_tk = _narr_tk_early
    for s in stocks:
        _mods = []
        _bonus = 0.0
        _g = gmap.get(s.get('sector'), s.get('sector'))
        _b = band_by_sec.get(_g)
        if _b in ('Booming', 'Favoured'):
            _bonus += 0.5
            _mods.append('sector ' + str(_b))
        if s.get('ticker') in narr_tk:
            _bonus += 0.25
            _mods.append('live narrative')
        s['modifiers'] = _mods
        s['rank_score'] = round(s['conviction'] + _bonus, 2)
    stocks.sort(key=lambda x: (-x.get('rank_score', x.get('conviction', 0)),
                               -(x.get('ret_1y') if isinstance(x.get('ret_1y'), (int, float)) else -1e9)))
    etf = {}
    def _adde(isin, label, row):
        if not isin: return
        e = etf.setdefault(isin, {'agree': [], 'row': {}})
        if label not in e['agree']: e['agree'].append(label)
        for k in ('name', 'ter', 'ytd_pct', 'ret_1y', 'n_holdings', 'estate_status', 'domicile', 'tax_note'):
            if row.get(k) is not None and e['row'].get(k) is None: e['row'][k] = row.get(k)
    for r in (data.get('etf_recommendations') or []):
        _adde((r.get('fund') or {}).get('isin'), 'World-ETF-Rec', r.get('fund') or {})
    # v1.336.0: Tab 21's dual-lens classification, replicated exactly (index.html's _BOOM_THEME_GICS +
    # sector_booming forward band + best-fund-per-theme) so the two tabs can never silently disagree.
    _BOOM_THEME_GICS = {
        'Artificial Intelligence': 'Information Technology', 'Cybersecurity': 'Information Technology',
        'Quantum Computing': 'Information Technology', 'Memory & Storage': 'Information Technology',
        'Datacenter & Grid Build-out': 'Industrials', 'Space': 'Industrials',
        'Lithium, Rare Earth & Battery': 'Materials', 'Metals Miners': 'Materials', 'Uranium & Nuclear': 'Energy',
    }
    _by_theme = {}
    for _f in (data.get('etf_emerging_themes_watch') or []):
        _by_theme.setdefault(_f.get('theme'), []).append(_f)
    for _t, _fs in _by_theme.items():
        _gics = _BOOM_THEME_GICS.get(_t)
        if band_by_sec.get(_gics) not in ('Booming', 'Favoured'):
            continue
        _best = max(_fs, key=lambda f: f.get('live_ret_1y') if isinstance(f.get('live_ret_1y'), (int, float)) else -1e9)
        _adde(_best.get('isin'), 'Tab21-Booming', {
            'name': _best.get('name'), 'ter': _best.get('ter'),
            'ytd_pct': (_best.get('live_ytd') if _best.get('live_ytd') is not None else _best.get('ytd')),
            'ret_1y': _best.get('live_ret_1y'), 'estate_status': _best.get('estate_status'),
        })
    for i, r in enumerate(data.get('etf_momentum_watch') or []):
        if i < 20: _adde(r.get('isin'), 'Momentum-top20', r)
    for r in ((data.get('etf_explosive_verified') or {}).get('etfs') or []):
        _adde(r.get('isin'), 'Explosive-verified', r)
    # v1.339.0: five genuine fund-to-picks proxy trackers, computed every run by build_m1m2_etf_proxies
    # and never read here before -- each flags a fund whose UNDERLYING HOLDINGS include the dashboard's
    # own confirmed stock picks (a real signal, not a repeat of the stock-side tags). Same 2-source gate.
    for _tk_key, _lbl in (('m1_etf_tracker', 'M1-ETF'), ('m2_etf_tracker', 'M2-Turnaround-ETF'),
                           ('m2_quality_etf_tracker', 'M2-Quality-ETF'),
                           ('explosive_etf_tracker', 'Explosive-ETF'), ('tce_etf_tracker', 'TCE-ETF')):
        for r in (data.get(_tk_key) or []):
            _adde(r.get('isin'), _lbl, r)
    etfs = []
    for isin, e in etf.items():
        if len(e['agree']) < 2: continue
        row = dict(e['row']); row.update({'isin': isin, 'conviction': len(e['agree']), 'agree': e['agree']})
        etfs.append(row)
    etfs.sort(key=lambda x: (-x['conviction'], -(x.get('ret_1y') if isinstance(x.get('ret_1y'), (int, float)) else -1e9)))
    data['recommended'] = {
        'as_of': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        # v1.338.0: cap raised 40->100 (genuine-source growth from Sector-Booming/Turnaround/Banks-tab/
        # Narrative-tab means >40 real 2-engine picks is now common, not an edge case) and n_stocks/n_etfs
        # now read the SAME post-truncation list actually carried in the payload, so the reported count
        # can never again disagree with what's delivered (owner caught: log said 77, payload had 40).
        'stocks': stocks[:150], 'etfs': etfs[:25],
        'n_stocks': len(stocks[:150]), 'n_etfs': len(etfs[:25]),
        'note': ("The dashboard own verdict: names/funds that >=2 independent engines agree on, ranked by "
                 "agreement then 1Y return. Stocks join via Explosive / TCE-HIGH / Multibagger / Discovery / "
                 "M1-Buy / Zacks#1-2 / Whale-consensus; ETFs via World-ETF-Rec / Momentum / Explosive-verified. "
                 "Merit-based, not personalised advice."),
    }
    log('[Recommended] %d stocks (>=2 engines) + %d ETFs consolidated' % (len(stocks), len(etfs)))
    return data['recommended']


def fetch_etf_holdings(etf):
    """v1.319.0 -- ETF holdings via stockanalysis.com's server-rendered holdings PAGE (G5 revival).
    The old /api/symbol/e/{ETF}/holdings JSON endpoint is dead (0/30 for months); the human page
    /etf/{ticker}/holdings/ still serves the TOP-25 constituents as a parseable HTML table (Symbol
    linked /stocks/<slug>/ + % weight), free, Finnhub-sourced, refreshed daily. Top-25 across 30
    ETFs is ample for a cross-ETF consensus overlap, ONE uniform parser for every issuer, and the
    host is already reachable from the runner (the quarterly-financials engine uses it). Confirmed
    live 2026-07-30 by direct fetch (SOXX: AMD 8.84 / NVDA 8.56 / MU 8.29 ...).
    Returns [{ticker, weight}] or [] (card stays 'not sourced', never a fabricated holding)."""
    import re as _re
    diag = not _ETF_DIAG['done']
    _url = 'https://stockanalysis.com/etf/%s/holdings/' % str(etf).lower()
    result = []
    try:
        r = requests.get(_url, headers={'User-Agent': UA, 'Accept': 'text/html,*/*'}, timeout=20)
        if diag:
            log('    \u00b7 [diag] sa-page %s: HTTP %s len %d' % (etf, r.status_code, len(r.text or '')))
        if r.status_code == 200 and r.text:
            # ROW-WISE parse so each symbol stays paired with its OWN weight: every holding <tr>
            # links the symbol as /stocks/<slug>/ and carries a NN.NN% weight cell in the same row.
            # Sector/country breakdown rows have percents but NO /stocks/ link -> skipped by design.
            for _row in _re.split(r'<tr', r.text):
                _sm = _re.search(r'/stocks/([A-Za-z0-9.\-]+)/"[^>]*>\s*([A-Za-z0-9.\-]+)\s*<', _row)
                if not _sm:
                    continue
                _wm = _re.search(r'>\s*([0-9]{1,2}(?:\.[0-9]{1,2})?)\s*%', _row)
                if not _wm:
                    continue
                try:
                    _w = float(_wm.group(1))
                except Exception:
                    continue
                _tk = (_sm.group(2) or _sm.group(1)).strip().upper()
                if _tk and 0.0 < _w <= 100.0:
                    result.append({'ticker': _tk, 'weight': _w})
        if diag:
            log('    \u00b7 [diag] sa-page %s: parsed %d holdings' % (etf, len(result)))
    except Exception as _e:
        if diag:
            log('    \u00b7 [diag] sa-page %s: EXC %s' % (etf, _e))
    if diag:
        _ETF_DIAG['done'] = True
    return result

# ===================== iShares / BlackRock authoritative holdings (ISIN-keyed) =====================
# v1.152.0: emerging-theme UCITS funds have NO US-listed sibling, so stockanalysis 404s them. Their
# holdings ARE public -- on the ISSUER'S own site. iShares (5 of our funds) publishes a daily holdings
# CSV at /uk/individual/en/products/{PID}/{slug}/1506575576011.ajax?fileType=csv&fileName=holdings&dataType=fund
# (1506575576011 is the fixed UK/individual site token, same for every UK fund). The v1.151 product-screener
# lookup 500'd on the runner, so we DROP it: each fund's {PID}/{slug} is pinned below (confirmed from
# ishares.com product pages), keyed by ISIN -> cannot collide, no extra network hop. A failure yields []
# (card stays 'not sourced'), never a fabricated or wrong-fund holding.
_ISHARES_PRODUCTS = {
    'IE00BG0J4C88': ('297843', 'ishares-digital-security-ucits-etf-fund'),  # Digital Security (Acc)  LOCK
    'IE00BG0J4841': ('305642', 'ishares-digital-security-ucits-etf'),       # Digital Security (Dist) SHLD
    'IE000C6ITGC8': ('345953', 'ishares-quantum-computing-ucits-etf'),      # Quantum Computing (Acc) QANT
    'IE000A9G9R73': ('351117', 'ishares-space-technologies-ucits-etf'),     # Space Technologies (Acc) STRR
    'IE000X59ZHE2': ('338777', 'ishares-ai-infrastructure-ucits-etf'),      # AI Infrastructure (Acc) AINF
    'IE000DR59CI3': ('335844', 'ishares-energy-storage-hydrogen-ucits-etf'),# Energy Storage & Hydrogen (Acc) STOR (v1.214.3: was mis-routed to stockanalysis 'STOR' = wrong/delisted US ticker -> 0 holdings; iShares issuer-direct like AINF; PID/slug confirmed from ishares.com product page)
}

def _parse_ishares_csv(text):
    import csv, io
    _lines = (text or '').splitlines()
    _hdr = None
    for _i, _ln in enumerate(_lines[:15]):
        if 'Ticker' in _ln and 'Name' in _ln:
            _hdr = _i; break
    if _hdr is None:
        return []
    _rdr = csv.DictReader(io.StringIO('\n'.join(_lines[_hdr:])))
    _CASH = {'-', '', 'USD', 'GBP', 'EUR', 'CASH', 'CASH_USD', 'MMFUNDS', 'XTSLA', 'BGXS'}
    _out = []
    for _row in _rdr:
        _tk = str(_row.get('Ticker') or '').strip().strip('"')
        # drop cash / derivative rows via the Asset Class column when iShares provides it
        _acol = next((_k for _k in _row.keys() if _k and 'asset class' in _k.strip().lower()), None)
        _acls = str(_row.get(_acol) if _acol else '').strip().lower()
        if _acls and (('cash' in _acls) or ('derivative' in _acls) or ('money market' in _acls)):
            continue
        _wcol = next((_k for _k in _row.keys() if _k and _k.strip().lower().startswith('weight')), None)
        _w = str(_row.get(_wcol) if _wcol else '').replace('%', '').replace(',', '').strip()
        try:
            _wf = float(_w)
        except Exception:
            continue
        if _tk and _tk.upper() not in _CASH and _wf > 0:
            # v1.219.1: the CSV has ALWAYS carried Name + Exchange -- they were discarded, which is
            # why STOR's Japanese lines (Murata 6981, TDK 6762, Resonac 4004, Asahi Kasei 3407)
            # displayed as raw codes AND got mis-classified as Taiwan by the bare-4-digit guess.
            _nm = str(_row.get('Name') or '').strip().strip('\"')
            _ecol = next((_k for _k in _row.keys() if _k and _k.strip().lower() in ('exchange', 'exchange name')), None)
            _lcol = next((_k for _k in _row.keys() if _k and _k.strip().lower() == 'location'), None)
            _out.append({'ticker': _tk.upper(), 'weight': _wf, 'name': (_nm or None),
                         'exchange': (str(_row.get(_ecol) or '').strip() or None) if _ecol else None,
                         'location': (str(_row.get(_lcol) or '').strip() or None) if _lcol else None})
    return _out

def fetch_ishares_holdings(isin):
    """iShares/BlackRock authoritative holdings by ISIN -> [{ticker, weight}] (top by weight) or [].
    ISIN -> pinned (PID, slug); builds the fund's own daily holdings CSV. No screener hop, no collision."""
    _ent = _ISHARES_PRODUCTS.get((isin or '').upper())
    if not _ent:
        return []
    _pid, _slug = _ent
    _url = ('https://www.ishares.com/uk/individual/en/products/%s/%s/1506575576011.ajax'
            '?fileType=csv&fileName=holdings&dataType=fund' % (_pid, _slug))
    try:
        _r = requests.get(_url, headers={'User-Agent': UA, 'Accept': 'text/csv,*/*'}, timeout=30)
        _rows = _parse_ishares_csv(_r.text) if (_r.status_code == 200 and _r.text) else []
        log('    · [diag] iShares %s pid=%s: HTTP %s len %d -> %d holdings'
            % (isin, _pid, _r.status_code, len(_r.text or ''), len(_rows)))
        return _rows
    except Exception as _e:
        log('    · [diag] iShares %s pid=%s EXC %s' % (isin, _pid, _e))
        return []

# v1.365.0: broad-market iShares funds -> FULL issuer holdings CSV (US site). Covers the moat mid-caps that
# top-25 page scrapes can never reach. Separate from the UK pinned path so that proven fetcher is untouched.
_ISHARES_BROAD = {}   # v1.372.0: CONCLUDED unreachable from the runner (5 methods tried) -- disabled to
                      # stop the per-scan retry. Re-populate only with a source proven to serve automation.

def fetch_ishares_broad_holdings(ticker):
    """FULL holdings for a broad iShares US fund via BlackRock's own daily CSV (authoritative, not top-25).
    Returns [tickers] or []. Loud-diag friendly: returns (tickers, http_status) via attribute on failure is
    avoided -- caller reads the count. Fail-open."""
    _ent = _ISHARES_BROAD.get((ticker or '').upper())
    if not _ent:
        return [], None
    _pid, _slug = _ent
    _url = ('https://www.ishares.com/us/products/%s/%s/1467271812596.ajax'
            '?fileType=csv&fileName=%s_holdings&dataType=fund' % (_pid, _slug, ticker.upper()))
    try:
        # v1.370.0: iShares sets consent server-side -> use a SESSION. Step 1: hit the disclaimer-accept
        # entry so the server drops the real consent cookie into the jar. Step 2: fetch the CSV reusing it.
        _sess = requests.Session()
        _sess.headers.update({'User-Agent': UA})
        try:
            _sess.get('https://www.ishares.com/us/product-screener/product-screener-v3.1.jsn'
                      '?siteEntryPassthrough=true&dcrPath=/templatedata/config/product-screener-v3/data/en/us-one/product-screener',
                      timeout=25, allow_redirects=True)
            _sess.get('https://www.ishares.com/us/products/%s?siteEntryPassthrough=true' % _pid,
                      timeout=25, allow_redirects=True)
        except Exception:
            pass
        # v1.371.0: the Business-Recorder move -- present the request as the browser's in-page fetch so
        # the server returns DATA, not the SPA/terms shell. XHR header + AJAX accept + fetch metadata.
        _hdrs = {'Accept': 'text/csv,application/csv,application/json,text/plain,*/*',
                 'X-Requested-With': 'XMLHttpRequest',
                 'Sec-Fetch-Site': 'same-origin', 'Sec-Fetch-Mode': 'cors', 'Sec-Fetch-Dest': 'empty',
                 'Referer': 'https://www.ishares.com/us/products/%s' % _pid}
        _r = _sess.get(_url, headers=_hdrs, timeout=35, allow_redirects=True)
        _txt = _r.text or ''
        # v1.371.0: if it still handed back the shell, retry once WITHOUT redirects (the terms page is a
        # redirect; the raw .ajax may serve csv directly to the XHR call).
        if _txt.lstrip()[:9].lower().startswith('<!doctype'):
            try:
                _r2 = _sess.get(_url, headers=_hdrs, timeout=35, allow_redirects=False)
                if _r2.status_code == 200 and _r2.text and not _r2.text.lstrip()[:9].lower().startswith('<!doctype'):
                    _r = _r2; _txt = _r2.text or ''
            except Exception:
                pass
        _is_html = _txt.lstrip()[:9].lower().startswith('<!doctype') or _txt.lstrip()[:5].lower().startswith('<html')
        _base_info = {'http': _r.status_code, 'bytes': len(_txt),
                      'ctype': _r.headers.get('Content-Type', '')[:60],
                      'final_url': str(getattr(_r, 'url', ''))[:160],
                      'head': _txt[:200], 'html_wall': _is_html}
        if _r.status_code != 200 or not _txt or _is_html:
            _base_info['n'] = 0
            return [], _base_info
        _rows = _parse_ishares_csv(_txt.lstrip('\ufeff'))   # v1.369.0: iShares CSVs carry a BOM
        _tks = [str(x.get('ticker') or '').upper() for x in _rows if x.get('ticker')]
        _tks = [t for t in _tks if (t and t.isalnum()) or ('.' in t)]
        _base_info['n'] = len(_tks)
        if not _tks:
            _lines = _txt.splitlines()
            _base_info['hdr_line'] = next((ln for ln in _lines[:25] if 'icker' in ln or 'ISIN' in ln or 'Name' in ln), None)
        return _tks, _base_info
    except Exception as _e:
        return [], type(_e).__name__


# =================== end iShares / BlackRock authoritative holdings ===================

def build_etf_overlap(rank12_etfs, holdings_map, zacks_top_tickers, top_n=ETF_OVERLAP_TOP_N):
    """Aggregate holdings across Zacks #1/#2 ETFs. conviction = blend(weight, breadth) with a
    Zacks-confirmed boost. Pure logic / unit-tested. Returns ranked top-N consensus stocks."""
    agg = {}
    for e in rank12_etfs:
        tk = e['etf']
        for h in holdings_map.get(tk, []):
            s = (h.get('ticker') or '').upper().strip()
            if not s or len(s) > 6 or s == tk:
                continue
            a = agg.setdefault(s, {'weight_sum':0.0, 'etfs':set()})
            a['weight_sum'] += float(h.get('weight') or 0)
            a['etfs'].add(tk)
    n_etf = max(len(rank12_etfs), 1)
    max_w = max((a['weight_sum'] for a in agg.values()), default=1.0) or 1.0
    zset = set(zacks_top_tickers or [])
    rows = []
    for s, a in agg.items():
        breadth = len(a['etfs'])
        w_norm = a['weight_sum'] / max_w
        b_norm = breadth / n_etf
        zc = s in zset
        conviction = round(100*(0.55*w_norm + 0.35*b_norm) + (10 if zc else 0), 1)
        rows.append({'ticker': s, 'etf_count': breadth, 'agg_weight': round(a['weight_sum'],2),
                     'conviction': conviction, 'zacks_confirmed': zc, 'in_etfs': sorted(a['etfs'])[:8]})
    rows.sort(key=lambda r: (-r['conviction'], -r['etf_count'], -r['agg_weight']))
    top = rows[:top_n]
    tot_w = sum(r['agg_weight'] for r in top) or 1.0
    for r in top:
        r['alloc_pct'] = round(r['agg_weight'] / tot_w * 100, 2)   # mirror-able weight across the shown names
    return top
# =====================================================================================

def fetch_zacks_sectors(survivors=None):
    """Scrape per-ticker Zacks rank for the fixed S&P universe + scan survivors (deduped),
    keep #1/#2, group by GICS sector. Returns {sector:{rank1,rank2,top,total,pct_top,top_tickers}}."""
    # Build universe: fixed list (with known sector) + survivors (sector from their record)
    uni = {}  # ticker -> gics sector
    for sec, tickers in ZACKS_SECTOR_UNIVERSE.items():
        for t in tickers:
            uni[t] = sec
    if survivors:
        for r in survivors:
            tk = r.get('ticker'); g = _gics_from_yahoo(r.get('sector'))
            if tk and g and tk not in uni:
                uni[tk] = g
    tickers = sorted(uni.keys())
    log(f'=== Zacks sector scrape: {len(tickers)} tickers (~{len(tickers)*2.5/60:.0f} min) ===')
    sectors = {s: {'rank1':0,'rank2':0,'top':0,'total':0,'pct_top':0.0,'top_tickers':[]}
               for s in ZACKS_SECTOR_UNIVERSE}
    fails = 0
    ranks = {}   # P7: per-ticker {ticker: zacks_rank 1..5} for the US Explosive #1/#2 chip
    for i, tk in enumerate(tickers):
        sec = uni[tk]
        if sec not in sectors:
            sectors[sec] = {'rank1':0,'rank2':0,'top':0,'total':0,'pct_top':0.0,'top_tickers':[]}
        try:
            time.sleep(0.4)  # v1.117.0: was 2.5s -> 0.4s (6x faster; 988s -> ~168s)
            d = requests.get(f'https://quote-feed.zacks.com/index?t={tk}',
                             headers={'User-Agent':'Mozilla/5.0'}, timeout=15).json()
            rec = d.get(tk, {}) or {}
            rank = rec.get('zacks_rank')
            rank = int(rank) if rank not in (None,'','null') else None
            if rank is not None: ranks[tk] = rank
            sectors[sec]['total'] += 1
            if rank == 1:
                sectors[sec]['rank1'] += 1; sectors[sec]['top'] += 1; sectors[sec]['top_tickers'].append(tk)
            elif rank == 2:
                sectors[sec]['rank2'] += 1; sectors[sec]['top'] += 1; sectors[sec]['top_tickers'].append(tk)
        except Exception:
            fails += 1
    for s, v in sectors.items():
        v['pct_top'] = round(v['top']/v['total']*100, 1) if v['total'] else 0.0
    log(f'  Zacks sector scrape done: {fails} failures of {len(tickers)}')
    return sectors, ranks

