def probe_etf_screener():
    """LOGGING-ONLY. For each European UCITS-listing segment (uk/germany/netherlands/switzerland/france):
    (A) minimal-column pass (name/close/Perf.YTD, type=fund, sort Perf.YTD desc) -> confirms the segment
        returns ETFs RANKED by return + logs the top 5 (eyeball: UCITS vs leveraged/inverse);
    (B) on the first segment that returns rows, a PER-COLUMN availability probe (append each candidate to the
        safe minimal set; HTTP 200 = TV serves it) for the fields the live build needs -- aum/nav_total
        (quality floor), isin (buyable mapping), description/currency, Perf.6M/Perf.3M -- so the engine is
        built only on columns TV actually serves. Never raises; wrapped by the caller."""
    if not ETF_SCREENER_PROBE:
        return
    import requests as _rq
    log('  [ETF screener probe] can we live-rank UCITS ETFs by return? (goal: drop the quarterly ETF_Universe.xlsx upload)')
    _markets = ['uk', 'germany', 'netherlands', 'switzerland', 'france']
    _min_cols = ['name', 'description', 'close', 'Perf.YTD']
    _first_ok = None
    for _mkt in _markets:
        try:
            _pa = {"columns": _min_cols,
                   "filter": [{"left": "type", "operation": "equal", "right": "fund"}],
                   "sort": {"sortBy": "Perf.YTD", "sortOrder": "desc"},
                   "range": [0, 10], "markets": [_mkt]}
            _r = _rq.post(f'https://scanner.tradingview.com/{_mkt}/scan',
                          json=_pa, headers={'User-Agent': UA}, timeout=30)
            _rows, _tot = [], 0
            if _r.status_code == 200:
                _j = _r.json()
                _rows = _j.get('data', []) or []
                _tot = _j.get('totalCount', len(_rows))
            log(f'    · [{_mkt}] type=fund sort Perf.YTD: HTTP {_r.status_code}  total~{_tot}  shown {len(_rows)}')
            for _d in _rows[:5]:
                _rec = dict(zip(_min_cols, _d.get('d', [])))
                log(f'        {str(_d.get("s","?")):24s} YTD={_rec.get("Perf.YTD")}  close={_rec.get("close")}  {str(_rec.get("description"))[:40]}')
            if _rows and _first_ok is None:
                _first_ok = _mkt
        except Exception as _e:
            log(f'    · [{_mkt}] minimal pass FAILED: {type(_e).__name__} {str(_e)[:70]}')
    # Pass B -- per-column availability, only on the first working segment (lean: ~8 extra calls total)
    if _first_ok:
        log(f'  [ETF screener probe] per-column availability on [{_first_ok}] (which fields does TV serve for the live build?):')
        for _cand in ['aum', 'nav_total', 'isin', 'currency', 'fundamental_currency_code',
                      'Perf.6M', 'Perf.3M', 'expense_ratio', 'typespecs']:
            try:
                _cols = _min_cols + [_cand]
                _pb = {"columns": _cols,
                       "filter": [{"left": "type", "operation": "equal", "right": "fund"}],
                       "sort": {"sortBy": "Perf.YTD", "sortOrder": "desc"},
                       "range": [0, 3], "markets": [_first_ok]}
                _r = _rq.post(f'https://scanner.tradingview.com/{_first_ok}/scan',
                              json=_pb, headers={'User-Agent': UA}, timeout=30)
                if _r.status_code == 200:
                    _rows = _r.json().get('data', []) or []
                    _v = dict(zip(_cols, _rows[0].get('d', []))).get(_cand) if _rows else None
                    log(f'        {_cand:28s} SERVED (HTTP 200)  sample={str(_v)[:44]}')
                else:
                    log(f'        {_cand:28s} not served (HTTP {_r.status_code})')
            except Exception as _e:
                log(f'        {_cand:28s} probe error: {type(_e).__name__} {str(_e)[:50]}')
    else:
        log('  [ETF screener probe] no segment returned rows with type=fund -- next probe will retry without the type filter and log the types present.')
    log('  [ETF screener probe] done. If segments return ranked UCITS ETFs with aum+isin+Perf served, the live self-discovering engine + LEI/diffusion gate can be built and the quarterly upload retired.')


