RECESSION_SERIES = {
    'sahm':           'SAHMREALTIME',
    'recession_prob': 'RECPROUSM156N',
    'yc_2y':          'T10Y2Y',
    'yc_3m':          'T10Y3M',
    'gdpnow':         'GDPNOW',
    'claims':         'ICSA',
}


def _ff_us_events(events, limit=12):
    """Filter the ForexFactory faireconomy weekly calendar to upcoming high/medium
    impact US (USD) releases. Pure. No 'actual' field — FF omits it until release;
    realized values come from FRED."""
    out = []
    if not isinstance(events, list):
        return out
    for e in events:
        if not isinstance(e, dict):
            continue
        if str(e.get('country', '')).upper() != 'USD':
            continue
        if str(e.get('impact', '')).lower() not in ('high', 'medium'):
            continue
        out.append({'title': e.get('title'), 'date': e.get('date'),
                    'impact': e.get('impact'), 'forecast': e.get('forecast'),
                    'previous': e.get('previous'), 'actual': e.get('actual')})   # v1.429.0
    out.sort(key=lambda x: (0 if str(x.get('impact', '')).lower() == 'high' else 1,
                            str(x.get('date') or '')))
    return out[:limit]


def _econ_num(v):
    """'0.2%' / '202K' / '-0.4%' / '54.7' -> float, else None."""
    try:
        t = str(v or '').strip().replace('%', '').replace(',', '')
        m = 1.0
        if t.upper().endswith('K'):
            m, t = 1e3, t[:-1]
        elif t.upper().endswith('M'):
            m, t = 1e6, t[:-1]
        elif t.upper().endswith('B'):
            m, t = 1e9, t[:-1]
        return float(t) * m if t not in ('', '-') else None
    except Exception:
        return None


# v1.430.0: actuals via FRED for released calendar events (verified series ids only).
_ECON_FRED_MAP = {
    'CPI m/m':        ('CPIAUCSL', 'mom_pct'),
    'Core CPI m/m':   ('CPILFESL', 'mom_pct'),
    'CPI y/y':        ('CPIAUCSL', 'yoy_pct'),
    'Core CPI y/y':   ('CPILFESL', 'yoy_pct'),
    'Unemployment Claims': ('ICSA', 'level_k'),
    # v1.433.0: PPI ids VERIFIED against FRED's own series pages 2026-08-14 (D-126 satisfied):
    # PPIFIS = PPI by Commodity: Final Demand (headline, SA monthly); PPIFES = Final Demand
    # Less Foods and Energy (= Core PPI). Same mom_pct index-ratio math as CPI.
    'PPI m/m':        ('PPIFIS', 'mom_pct'),
    'Core PPI m/m':   ('PPIFES', 'mom_pct'),
    'Retail Sales m/m':    ('RSAFS', 'mom_pct'),
    'Prelim UoM Consumer Sentiment': ('UMCSENT', 'level_1dp'),
}

def _fred_latest_vals(sid, n):
    """Small standalone FRED pull (existing key/library); returns last n values + last obs date."""
    try:
        from fredapi import Fred
        ser = Fred(api_key=FRED_KEY).get_series(sid).dropna()
        if ser is None or len(ser) < n:
            return None, None
        return list(ser[-n:]), ser.index[-1].date()
    except Exception:
        return None, None

# ============================ US GROWTH DASHBOARD (v1.435.0) ============================
# Owner: "unemployment rates or other indicators which show economy growing or not, plus a
# trend -- and all numbers third-party validated." Every tile: FRED series (id verified
# against FRED's own pages 2026-08-14), 13 periods of history for a sparkline, 3-period
# direction, plain verdict, source + as-of on its face. GDPNow carries the honest
# "nowcast -- early-quarter, volatile" label, is cross-checked against FRED's independent
# republication (GDPNOW), and ACTUAL GDP (BEA A191RL1Q225SBEA) renders beside it so
# nowcast and reality can never be confused. Composite: N of M signals expanding.
_USG_SERIES = [
    # (fred_id, label, unit, kind, good_when_falling)
    ('UNRATE',   'Unemployment Rate',          '%',   'level_m',  True),
    ('PAYEMS',   'Jobs Added (Nonfarm)',       'K',   'diff_m',   False),
    ('IC4WSA',   'Jobless Claims (4-wk avg)',  'K',   'level_w',  True),
    ('INDPRO',   'Industrial Production y/y',  '%',   'yoy_m',    False),
    ('RSAFS',    'Retail Sales y/y',           '%',   'yoy_m',    False),
]

def build_us_growth(existing_gdpnow=None):
    """US growth strip: FRED-only, verified ids, 13-pt history per tile + composite verdict."""
    out = {'as_of': dt.datetime.utcnow().strftime('%Y-%m-%d'), 'tiles': [],
           'source': 'FRED, Federal Reserve Bank of St. Louis (series id on every tile)'}
    if not FRED_KEY:
        out['note'] = 'FRED key absent'
        return out
    expanding = 0; total = 0
    for sid, label, unit, kind, good_falls in _USG_SERIES:
        need = 26 if kind == 'yoy_m' else 14
        vals, last_date = _fred_latest_vals(sid, need)
        if not vals:
            out['tiles'].append({'id': sid, 'label': label, 'error': 'fetch failed'}); continue
        if sid in ('IC4WSA',):
            vals = [v / 1000.0 for v in vals]   # v1.436.0: FRED serves claims as raw counts (199,000); tile unit is K
        if kind == 'diff_m':
            # PAYEMS level is ALREADY in thousands (FRED units), so the monthly diff IS jobs-in-K -- no scaling.
            pts = [round((vals[i] - vals[i-1]), 1) for i in range(1, len(vals))][-13:]
        elif kind == 'yoy_m':
            pts = [round((vals[i] / vals[i-12] - 1) * 100, 2) for i in range(12, len(vals))][-13:]
        else:
            pts = [round(v, 2) for v in vals[-13:]]
        latest = pts[-1]; ago3 = pts[-4] if len(pts) >= 4 else pts[0]
        chg3 = round(latest - ago3, 2)
        direction = 'rising' if chg3 > (0.05 if unit == '%' else 5) else ('falling' if chg3 < -(0.05 if unit == '%' else 5) else 'flat')
        good = (direction == 'falling') if good_falls else (direction == 'rising')
        if direction == 'flat':
            verdict = 'steady'
        else:
            verdict = ('improving' if good else 'worsening')
        if verdict != 'worsening':
            expanding += 1
        total += 1
        out['tiles'].append({'id': sid, 'label': label, 'unit': unit, 'latest': latest,
                             'as_of': str(last_date), 'points': pts, 'chg_3m': chg3,
                             'dir': direction, 'verdict': verdict,
                             'good_when': ('falling' if good_falls else 'rising'),
                             'src': 'FRED:' + sid})
    # --- ACTUAL GDP (quarterly, BEA via FRED) ---
    gvals, gdate = _fred_latest_vals('A191RL1Q225SBEA', 13)
    if gvals:
        gpts = [round(v, 1) for v in gvals]
        out['gdp_actual'] = {'latest': gpts[-1], 'as_of': str(gdate), 'points': gpts,
                             'src': 'FRED:A191RL1Q225SBEA (BEA, measured GDP)',
                             'verdict': 'growing' if gpts[-1] > 0 else 'contracting'}
        if gpts[-1] > 0: expanding += 1
        total += 1
    # --- GDPNow: honest nowcast label + independent cross-check ---
    nvals, ndate = _fred_latest_vals('GDPNOW', 6)
    gn = {'label': 'GDPNow (Atlanta Fed nowcast)',
          'note': 'Early-quarter nowcast -- volatile until late in the quarter; not measured growth.'}
    if existing_gdpnow is not None:
        gn['value'] = existing_gdpnow; gn['src'] = 'Atlanta Fed (dashboard feed)'
    if nvals:
        gn['fred_value'] = round(nvals[-1], 2); gn['fred_as_of'] = str(ndate)
        if existing_gdpnow is not None:
            gn['cross_ok'] = abs(float(existing_gdpnow) - nvals[-1]) <= 0.5
            gn['cross_note'] = ('two independent pipes agree' if gn['cross_ok']
                                else 'SOURCES DISAGREE -- Atlanta feed %.2f vs FRED %.2f' % (float(existing_gdpnow), nvals[-1]))
    out['gdpnow'] = gn
    out['composite'] = {'expanding': expanding, 'total': total,
                        'verdict': ('growing' if total and expanding >= total * 0.6
                                    else ('slowing' if total and expanding <= total * 0.4 else 'mixed'))}
    return out
# ========================== end US growth dashboard ==========================


def stamp_policy_tickers(data):
    """v1.437.0 (owner: the radar 'doesn't tell me the effect on the stocks -- coloured
    indicators, present position, YTD and 1-year returns'). Stamp px / ytd / y1 onto every
    policy_catalyst ticker link. Two sources, cheapest first:
      1. foundation_universe (already fetched, price/perf_ytd/perf_1y on every row) -- zero cost,
         covers the US-listed names.
      2. The proven per-symbol GET (fetch_tv_symbol_quote, the v1.327.0 DevTools-captured call)
         for the OTC ADRs + NYSE:TSM that the US screen universe excludes -- ~7 GETs, each
         try/except'd, honest nulls on miss (never fabricates, never blocks the radar).
    Display-only stamps; the radar stays a watch layer, never a screen (D-121)."""
    pc = data.get('policy_catalyst') or {}
    items = pc.get('items') or []
    if not items:
        log('  [policy px] radar empty at call time -- nothing to stamp')   # v1.438.0: never silent
        return
    # v1.437.0 AUDIT CATCH: the index renders from pc['by_category'], not pc['items'] -- and after any
    # copy/serialize step those can be INDEPENDENT dicts. Walk BOTH structures so the stamp is visible
    # wherever the renderer reads; double-stamping shared references is harmless.
    tick_dicts = []
    for it in items:
        tick_dicts.extend(it.get('tickers') or [])
    for _cat, _its in (pc.get('by_category') or {}).items():
        for it in (_its or []):
            tick_dicts.extend(it.get('tickers') or [])
    fu = {r.get('ticker'): r for r in (data.get('foundation_universe') or []) if isinstance(r, dict)}
    _EXCH = {'RYCEY': 'OTC', 'RNMBY': 'OTC', 'BAESY': 'OTC', 'FINMY': 'OTC',
             'THLLY': 'OTC', 'SAABY': 'OTC', 'TSM': 'NYSE'}
    fetched = {}
    n_fu = n_tv = n_miss = 0
    for t in tick_dicts:
        if True:
            tk = t.get('ticker')
            r = fu.get(tk)
            if r and r.get('price') is not None:
                t['px'] = round(float(r['price']), 2)
                t['ytd'] = round(float(r['perf_ytd']), 1) if r.get('perf_ytd') is not None else None
                t['y1'] = round(float(r['perf_1y']), 1) if r.get('perf_1y') is not None else None
                t['px_src'] = 'tv_universe'
                n_fu += 1
                continue
            if tk not in fetched:
                q = fetch_tv_symbol_quote('%s:%s' % (_EXCH.get(tk, 'NYSE'), tk),
                                          fields=('close', 'Perf.YTD', 'Perf.Y'))
                fetched[tk] = q if isinstance(q, dict) else None
            q = fetched[tk]
            if q and q.get('close') is not None:
                t['px'] = round(float(q['close']), 2)
                t['ytd'] = round(float(q['Perf.YTD']), 1) if q.get('Perf.YTD') is not None else None
                t['y1'] = round(float(q['Perf.Y']), 1) if q.get('Perf.Y') is not None else None
                t['px_src'] = 'tv_quote'
                n_tv += 1
            else:
                n_miss += 1
    pc['px_note'] = 'prices+returns stamped: %d from the US screen universe, %d via per-symbol quotes%s' % (
        n_fu, n_tv, (', %d unpriced' % n_miss) if n_miss else '')
    log('  [policy px] %s' % pc['px_note'])


def _enrich_econ_actuals(cal):
    """Fill c['actual'] for RELEASED, mapped, still-blank US events. Mutates rows in place."""
    if not FRED_KEY or not isinstance(cal, list):
        return cal
    now = dt.datetime.now(dt.timezone.utc)
    filled = 0
    for c in cal:
        if not isinstance(c, dict) or str(c.get('actual') or '').strip():
            continue
        sid_mode = _ECON_FRED_MAP.get(str(c.get('title') or '').strip())
        if not sid_mode:
            continue
        try:
            edt = dt.datetime.fromisoformat(str(c.get('date')))
            if edt.tzinfo is None:
                edt = edt.replace(tzinfo=dt.timezone.utc)
        except Exception:
            continue
        if now < edt:
            continue                                   # not released yet
        sid, mode = sid_mode
        need = 13 if mode == 'yoy_pct' else (2 if mode == 'mom_pct' else 1)
        vals, last_obs = _fred_latest_vals(sid, max(need, 1))
        if not vals or last_obs is None:
            continue
        max_age = 10 if mode == 'level_k' else 45
        if (now.date() - last_obs).days > max_age:
            continue                                   # FRED not updated yet -- fill next run
        try:
            if mode == 'mom_pct':
                c['actual'] = '%.1f%%' % ((vals[-1] / vals[-2] - 1.0) * 100.0)
            elif mode == 'yoy_pct':
                c['actual'] = '%.1f%%' % ((vals[-1] / vals[0] - 1.0) * 100.0)
            elif mode == 'level_k':
                c['actual'] = '%dK' % round(vals[-1] / 1000.0)
            else:
                c['actual'] = '%.1f' % vals[-1]
            c['actual_src'] = 'FRED:' + sid
            filled += 1
        except Exception:
            continue
    if filled:
        log('  [Econ announced] %d actuals computed from FRED' % filled)
    return cal



def merge_econ_announced(data, cal):
    """v1.429.0: persist released events (actual present) with their dates; 14-day window."""
    prev = EXISTING.get('econ_announced') or []
    seen = {(x.get('title'), str(x.get('date'))[:16]) for x in prev if isinstance(x, dict)}
    out = [x for x in prev if isinstance(x, dict)]
    for c in (cal or []):
        if not isinstance(c, dict) or not str(c.get('actual') or '').strip():
            continue
        key = (c.get('title'), str(c.get('date'))[:16])
        if key in seen:
            continue
        a, f = _econ_num(c.get('actual')), _econ_num(c.get('forecast'))
        surprise = None
        if a is not None and f is not None:
            surprise = 'above' if a > f else ('below' if a < f else 'inline')
        out.append({'title': c.get('title'), 'date': c.get('date'), 'impact': c.get('impact'),
                    'actual': c.get('actual'), 'forecast': c.get('forecast'),
                    'previous': c.get('previous'), 'surprise': surprise})
        seen.add(key)
    _cut = (dt.datetime.utcnow() - dt.timedelta(days=14)).date().isoformat()
    out = [x for x in out if str(x.get('date') or '')[:10] >= _cut]
    out.sort(key=lambda x: str(x.get('date') or ''), reverse=True)
    data['econ_announced'] = out[:60]
    if out:
        log('  [Econ announced] %d released events on record (14d window)' % len(out))
    return out



def _recession_assess(sig):
    """Rule-based composite from the FRED signals. Pure + transparent.
    Returns (risk_label, score_0_100, triggers)."""
    triggers = []
    score = 0

    def _num(key):
        v = (sig.get(key) or {}).get('value')
        try:
            return float(v)
        except Exception:
            return None

    sahm = _num('sahm')
    if sahm is not None and sahm >= 0.50:
        triggers.append('Sahm rule triggered (>=0.50)'); score += 45
    elif sahm is not None and sahm >= 0.30:
        triggers.append('Sahm rising (>=0.30)'); score += 20

    yc2 = _num('yc_2y'); yc3 = _num('yc_3m')
    if (yc2 is not None and yc2 < 0) or (yc3 is not None and yc3 < 0):
        triggers.append('Yield curve inverted'); score += 20

    prob = _num('recession_prob')
    if prob is not None:
        if prob >= 50:
            triggers.append('NBER-style probability high (%d%%)' % round(prob)); score += 25
        elif prob >= 25:
            triggers.append('Recession probability elevated (%d%%)' % round(prob)); score += 12

    gdp = _num('gdpnow')
    if gdp is not None and gdp < 0:
        triggers.append('GDPNow negative (%.1f%%)' % gdp); score += 15

    score = min(score, 100)
    if score >= 60 or (sahm is not None and sahm >= 0.50):
        risk = 'HIGH'
    elif score >= 25:
        risk = 'ELEVATED'
    else:
        risk = 'LOW'
    return risk, score, triggers


def fetch_recession():
    """US recession watch (Wave C). FRED recession series + the ForexFactory weekly
    economic calendar via the faireconomy export host (the FF main site is
    Cloudflare-walled). Never raises; falls back to last-good per part."""
    prev = EXISTING.get('recession', {}) or {}
    out = {'signals': {}, 'calendar': prev.get('calendar', []),
           'source': 'FRED + faireconomy',
           '_fetched_utc': dt.datetime.utcnow().isoformat() + 'Z'}

    if FRED_KEY:
        try:
            from fredapi import Fred
            fred = Fred(api_key=FRED_KEY)
            # ── v1.268.0 PARALLEL PREFETCH (run 212: this block took 152.7s) ─────────────────
            # Identical disease to fetch_us_macros before v1.264.0: 6 series pulled ONE AT A TIME
            # with time.sleep(0.5) between each. I fixed it there and left this one serial.
            # Same cure: _fred_gate() paces starts at 2 req/s (FRED's own ceiling) so the pool
            # can overlap safely. The loop below is UNCHANGED -- same values, same last-good, same
            # warnings -- it just reads prefetched series instead of blocking on each in turn.
            _rpre = {}
            try:
                import concurrent.futures as _rcf
                def _rpull(_sid):
                    _fred_gate()
                    return fred.get_series(_sid).dropna()
                with _rcf.ThreadPoolExecutor(max_workers=len(RECESSION_SERIES)) as _rex:
                    _rf = {_rex.submit(_rpull, _s): _k for _k, _s in RECESSION_SERIES.items()}
                    for _fut in _rcf.as_completed(_rf):
                        _k = _rf[_fut]
                        try:
                            _rpre[_k] = _fut.result()
                        except Exception as _re:
                            _rpre[_k] = _re
                log(f'  [recession] prefetched '
                    f'{sum(1 for v in _rpre.values() if not isinstance(v, Exception))}'
                    f'/{len(RECESSION_SERIES)} series in parallel (gate 2 req/s)')
            except Exception as _rpe:
                log(f'  [recession] parallel prefetch unavailable ({type(_rpe).__name__}) -- serial')
                _rpre = {}
            for key, sid in RECESSION_SERIES.items():
                try:
                    if key in _rpre:
                        s = _rpre[key]
                        if isinstance(s, Exception):
                            raise s
                    else:
                        time.sleep(0.5)          # unchanged serial fallback
                        s = fred.get_series(sid).dropna()
                    if len(s) > 0:
                        out['signals'][key] = {'value': round(float(s.iloc[-1]), 2),
                                               'date': str(s.index[-1].date())}
                except Exception as e:
                    warn(f'recession FRED {key} ({sid}) failed: {e}')
                    lg = (prev.get('signals') or {}).get(key)
                    if lg is not None:
                        out['signals'][key] = lg
        except Exception as e:
            warn(f'recession FRED init failed: {e}')
            out['signals'] = prev.get('signals', {})
    else:
        out['signals'] = prev.get('signals', {})

    try:
        r = requests.get('https://nfs.faireconomy.media/ff_calendar_thisweek.json',
                         headers={'User-Agent': UA, 'Accept': 'application/json'}, timeout=12)
        ctype = r.headers.get('Content-Type', '')
        if r.status_code == 200 and 'json' in ctype.lower():
            cal = _ff_us_events(r.json())
            if cal:
                out['calendar'] = cal
                log(f'  ✓ Recession calendar: {len(cal)} high-impact US releases (faireconomy)')
        else:
            warn('FF calendar non-JSON (rate-limited?) — keeping last-good calendar')
    except Exception as e:
        warn(f'FF calendar failed: {e} — keeping last-good calendar')

    risk, score, triggers = _recession_assess(out['signals'])
    out['risk'] = risk
    out['score'] = score
    out['triggers'] = triggers
    log(f'  ✓ Recession watch: {risk} (score {score}) — {len(out["signals"])} FRED signals, '
        f'{len(out.get("calendar", []))} calendar events')
    return out


def track_shortlists(data, existing):
    """Wave T - PER-ITEM SHORTLIST PERFORMANCE TRACKER. For every tab that shortlists/recommends a
    stock (US + PSX screen survivors, US Explosive picks, US/PSX TCE tiers), records the date + price
    the name was FIRST seen on that tab, then updates its current price + % return-since each run; when
    a name drops off a tab its last-known reading is FROZEN (still_listed=false) - prices are never
    re-fetched for dropped names (honest fetch-free limitation), and a name without a price is skipped
    (never fabricated). SECTORS are tracked as a drift-free equal-weight basket = the AVERAGE of the
    per-name returns-since-first-seen of the tracked stocks in that sector (a new name enters at 0%, so
    membership churn cannot fake a jump); labelled as 'average of tracked names', not a sector index.
    Stored INSIDE data.json as data['shortlist_tracking'] so it persists via the SAME commit the
    workflow already makes. DISPLAY/DATA ONLY: never touches screening/scoring/TCE/the frozen prediction
    ledger -> respects the Sept freeze. Fully guarded (never raises; carries last-good on any error)."""
    try:
        today = dt.date.today().isoformat()
        prev = (existing.get('shortlist_tracking') or {})
        stocks = {k: dict(v) for k, v in (prev.get('stocks') or {}).items() if isinstance(v, dict)}

        def _px(row, pmap):
            tk = row.get('ticker')
            for cand in (pmap.get(tk), row.get('price'), row.get('close'), row.get('last'),
                         (row.get('streams') or {}).get('price') if isinstance(row.get('streams'), dict) else None):
                try:
                    v = float(cand)
                    if v > 0:
                        return round(v, 4)
                except (TypeError, ValueError):
                    continue
            return None

        # v1.103.0/v1.104.0 (Wave PB readiness): the conviction signal for each pick. A name re-scores
        # every run, so its entry-day grade is unrecoverable later. NEW rows are stamped at true first-seen
        # (signal_date == first_date). Rows that predate this capture get TODAY's conviction stamped ONCE,
        # honestly dated signal_date = today (!= first_date) so Wave PB can tell a true-entry grade from a
        # first-observed grade. entry_bench is keyed to the row's REAL first_date (looked up from the
        # rolling history store) so alpha_since pairs correctly with pct_since (both span first_date->today).
        # Guarded: any missing field is simply absent (never fabricated).
        _macros = (data.get('macros') or {})
        _bench_dates = sorted((h.get('date'), h) for h in (data.get('history') or [])
                              if isinstance(h, dict) and h.get('date'))
        def _bench_at(d, mkt):
            if not d:
                return None
            key = 'sp500' if mkt == 'US' else 'kse100'
            best = None
            for dd, h in _bench_dates:               # nearest row at/earlier than d (honest: None if pre-history)
                if dd <= d: best = h
                else: break
            if best:
                v = best.get(key)
                if isinstance(v, (int, float)) and v > 0:
                    return round(float(v), 2)
            return None
        def _entry_signal(row, mkt, fdate):
            sig = {}
            try:
                im = row.get('im3') if isinstance(row.get('im3'), dict) else None
                if im:
                    if im.get('grade') is not None: sig['entry_grade'] = im.get('grade')
                    if im.get('pct')   is not None: sig['entry_pct']   = im.get('pct')
                    val = im.get('valuation')
                    if isinstance(val, dict) and (val.get('label') or val.get('tier')):
                        sig['entry_val'] = val.get('label') or val.get('tier')
                if row.get('tier'):                     sig['entry_tier']     = str(row.get('tier')).upper()
                if row.get('strength_score') is not None: sig['entry_strength'] = row.get('strength_score')
                b = _bench_at(fdate, mkt)
                if b is None and fdate == today:        # new row, history not yet carrying today -> live macro
                    lv = ((_macros.get('us') or {}).get('sp500') if mkt == 'US'
                          else (_macros.get('psx') or {}).get('kse100'))
                    if isinstance(lv, (int, float)) and lv > 0: b = round(float(lv), 2)
                if b is not None: sig['entry_bench'] = b
            except Exception:
                pass
            return sig
        # current benchmark level per market (for the stored alpha-since-recommended)
        _cur_bench = {'US':  ((_macros.get('us')  or {}).get('sp500')),
                      'PSX': ((_macros.get('psx') or {}).get('kse100'))}

        # price maps from the candidate lists (the authoritative current price per market)
        us_px  = {r.get('ticker'): r.get('price') for r in (data.get('us_candidates') or []) if isinstance(r, dict)}
        psx_px = {r.get('ticker'): r.get('price') for r in (data.get('psx_candidates') or []) if isinstance(r, dict)}

        # Sector BACKFILL map: ETF-consensus large-caps enter the TCE pool from the ETF-overlap
        # list (ticker+name+weight only, NO sector), so their tracked rows would show a blank
        # sector. Harvest ticker->sector from EVERY sector-bearing list already in data.json
        # (explosive_us/psx, us/psx_candidates, tce_us/psx, etc.) so a name with no sector of its
        # own inherits the one the rest of the scan already knows. Display-only; never fabricated
        # (a name absent everywhere stays blank). First non-empty wins.
        sec_map = {}
        for _v in data.values():
            if isinstance(_v, list):
                for _r in _v:
                    if isinstance(_r, dict):
                        _tk = _r.get('ticker'); _sc = _r.get('sector')
                        if _tk and _sc and _tk not in sec_map:
                            sec_map[_tk] = _sc

        # assemble (tab, market, pmap, rows-iterable) for every shortlisting tab, both markets
        feeds = [
            ('US Screen Survivors', 'US', us_px, data.get('us_candidates') or []),
            ('PSX Screen Survivors', 'PSX', psx_px, data.get('psx_candidates') or []),
        ]
        # US Explosive: only positively-classified picks (not NOT-EXPLOSIVE / INSUFFICIENT / PARTIAL / bank)
        _POS = ('EXPLOSIVE', 'QUALITY-GROWTH', 'INFLECTION')
        exp_us = [r for r in (data.get('explosive_us') or [])
                  if isinstance(r, dict) and str(r.get('verdict', '')).upper().startswith(_POS)]
        feeds.append(('US Explosive', 'US', us_px, exp_us))
        # TCE tiers (HIGH / WATCH) both markets
        for mkt, key, pmap in (('US', 'tce_us', us_px), ('PSX', 'tce_psx', psx_px)):
            for tier in ('HIGH', 'WATCH'):
                rows = [r for r in (data.get(key) or [])
                        if isinstance(r, dict) and str(r.get('tier', '')).upper() == tier]
                feeds.append((f'{mkt} TCE {tier}', mkt, pmap, rows))
        # v1.209.0: forward hit-rate tracking for the M2 watch lanes (Bottoms Up M2 tab) --
        # every flagged name stamps first-seen date + price, so the lane's real early-catch
        # performance becomes measurable (the honest counterpart of the 9-stock panel).
        _m2w = data.get('m2_watch') or {}
        feeds.append(('US M2 Turnaround', 'US', us_px, _m2w.get('watch_turnaround') or []))
        feeds.append(('US M2 Quality', 'US', us_px, _m2w.get('watch_quality') or []))

        seen_keys = set()
        for tab, mkt, pmap, rows in feeds:
            for row in rows:
                if not isinstance(row, dict):
                    continue
                tk = row.get('ticker')
                if not tk:
                    continue
                price = _px(row, pmap)
                if price is None:
                    continue                              # never fabricate a price
                k = f'{tab}|{tk}'
                seen_keys.add(k)
                rec = stocks.get(k)
                if rec and rec.get('first_price'):
                    rec['last_date'] = today
                    rec['last_price'] = price
                    rec['pct_since'] = round((price / rec['first_price'] - 1) * 100, 2)
                    rec['still_listed'] = True
                    rec['sector'] = row.get('sector') or sec_map.get(tk) or rec.get('sector', '')
                    # v1.104.0: make sure every live row carries a conviction snapshot, honestly dated.
                    if 'signal_date' not in rec:
                        if ('entry_grade' in rec or 'entry_tier' in rec or 'entry_strength' in rec):
                            # stamped at true first-seen by v1.103.0 -> it IS entry conviction
                            rec['signal_date'] = rec.get('first_date', today)
                            _b = _bench_at(rec.get('first_date'), mkt)   # repair bench to the real entry day
                            if _b is not None: rec['entry_bench'] = _b
                        else:
                            # predates the capture -> stamp TODAY's conviction, dated today (not first_date)
                            rec.update(_entry_signal(row, mkt, rec.get('first_date', today)))
                            rec['signal_date'] = today
                    # durable alpha: pick move minus its benchmark over the SAME window (first_date->today)
                    _eb = rec.get('entry_bench'); _cb = _cur_bench.get(mkt)
                    if isinstance(_eb, (int, float)) and isinstance(_cb, (int, float)) and _eb > 0:
                        rec['alpha_since'] = round(rec['pct_since'] - (_cb / _eb - 1) * 100, 2)
                else:
                    _new = {
                        'tab': tab, 'ticker': tk, 'market': mkt,
                        'sector': row.get('sector') or sec_map.get(tk, ''),
                        'first_date': today, 'first_price': price,
                        'last_date': today, 'last_price': price,
                        'pct_since': 0.0, 'still_listed': True,
                    }
                    _new.update(_entry_signal(row, mkt, today))   # true entry conviction + benchmark
                    _new['signal_date'] = today                   # == first_date -> trustworthy as entry
                    if 'entry_bench' in _new:
                        _new['alpha_since'] = 0.0
                    stocks[k] = _new
        # names no longer on their tab: freeze last-known (no re-fetch)
        for k, rec in stocks.items():
            if k not in seen_keys:
                rec['still_listed'] = False
        # prune dropped records older than ~400 days to bound size
        cutoff = (dt.date.today() - dt.timedelta(days=400)).isoformat()
        stocks = {k: v for k, v in stocks.items()
                  if v.get('still_listed') or (v.get('last_date') or '') >= cutoff}

        # SECTORS: drift-free equal-weight basket = avg of per-name pct_since of still-listed tracked names
        prev_sectors = (prev.get('sectors') or {})
        groups = {}   # {gk: {ticker: pct}} - dedupe by ticker so a name on several tabs counts ONCE
        for rec in stocks.values():
            if not rec.get('still_listed'):
                continue
            sec = (rec.get('sector') or '').strip()
            if not sec:
                continue
            groups.setdefault(f'{rec["market"]}|{sec}', {})[rec['ticker']] = rec['pct_since']
        sectors = {}
        for gk, by_tk in groups.items():
            mkt, sec = gk.split('|', 1)
            pcts = list(by_tk.values())
            old = prev_sectors.get(gk) if isinstance(prev_sectors.get(gk), dict) else {}
            sectors[gk] = {
                'market': mkt, 'sector': sec,
                'first_date': old.get('first_date', today),
                'last_date': today,
                'n_names': len(pcts),
                'pct_since': round(sum(pcts) / len(pcts), 2),
                'still_listed': True,
                'basis': 'equal-weight avg of tracked names since first seen',
            }
        # carry sectors that dropped out this run as frozen
        for gk, old in prev_sectors.items():
            if gk not in sectors and isinstance(old, dict):
                old = dict(old); old['still_listed'] = False
                sectors[gk] = old

        data['shortlist_tracking'] = {'stocks': stocks, 'sectors': sectors, 'last_run': today}
        n_live = sum(1 for v in stocks.values() if v.get('still_listed'))
        n_sig  = sum(1 for v in stocks.values() if 'signal_date' in v)
        n_true = sum(1 for v in stocks.values() if v.get('signal_date') and v.get('signal_date') == v.get('first_date'))
        log(f'  [Wave T shortlist] {len(stocks)} stock-rows tracked ({n_live} live, {n_sig} conviction-stamped '
            f'[{n_true} at true entry]) across {len(set(v["tab"] for v in stocks.values()))} tabs; {len(sectors)} sector baskets')
    except Exception as e:
        log(f'  [Wave T shortlist] skipped ({type(e).__name__}: {str(e)[:60]})')
        if isinstance(existing.get('shortlist_tracking'), dict):
            data['shortlist_tracking'] = existing['shortlist_tracking']


# ---------------------------------------------------------------------------
# Wave PK-D - PSX PKR-DEVALUATION ALERT (DISPLAY/DATA-ONLY multi-signal basket)
# Reads the PSX macro dict the scanner already fetches and scores a
# watch / elevated / high read from five signals. NEVER touches screening,
# scoring, IM3, TCE tiers, the frozen ledger, or admission -> respects the
# Sept freeze. Pure + fully guarded (never raises). The thresholds below are
# DEFAULTS for owner calibration - change a single constant to retune.
# Each signal contributes 0 (off) / 1 (mild) / 2 (strong); the sum -> a level.
# ---------------------------------------------------------------------------
PKD_RUPEE_MOM_MILD      = 2.0     # USD/PKR up >2% MoM  -> PKR weakening (mild)
PKD_RUPEE_MOM_STRONG    = 5.0     # USD/PKR up >5% MoM  -> PKR weakening (strong)
PKD_RUPEE_QOQ_MILD      = 5.0     # or USD/PKR up >5% QoQ -> mild
PKD_RESERVES_MOM_MILD   = -5.0    # SBP reserves down >5% MoM  -> mild
PKD_RESERVES_MOM_STRONG = -10.0   # SBP reserves down >10% MoM -> strong
PKD_REER_MILD           = 103.0   # REER >103 -> rupee mildly overvalued
PKD_REER_STRONG         = 108.0   # REER >108 -> stretched (correction-prone)
PKD_SBP_RATE_DEFENSIVE  = 11.0    # owner's standing defensive policy-rate line
PKD_LEVEL_WATCH         = 1       # summed score 1-2  -> watch
PKD_LEVEL_ELEVATED      = 3       # summed score 3-4  -> elevated
PKD_LEVEL_HIGH          = 5       # summed score >=5  -> high
# v1.314.32 Wave PK-D deepening: the two STREET-LEVEL early-warning signals this session
# shipped as their own Tab-4 cards (kerb premium, Karachi-vs-world gold premium) now SCORE
# into the basket. Both are classic pre-devaluation reads: the kerb (open-market) dollar
# premium widens before official devaluations, and local gold outrunning world parity prices
# devaluation expectation directly. Thresholds set conservatively (a calm reading scores 0,
# so today's level is unchanged); level cut-offs kept ABSOLUTE (additive, never a downgrade).
PKD_KERB_MILD           = 1.5     # kerb premium >1.5% over interbank -> street pressure (mild)
PKD_KERB_STRONG         = 3.0     # kerb premium >3.0% -> strong pre-devaluation stress
PKD_GOLD_MILD           = 3.0     # Karachi gold >3% over world parity -> devaluation expectation (mild)
PKD_GOLD_STRONG         = 6.0     # Karachi gold >6% over world parity -> strong

def _pkd_num(v):
    """Coerce to float or None; drops NaN. Never raises."""
    try:
        if v is None:
            return None
        f = float(v)
        return f if f == f else None
    except (TypeError, ValueError):
        return None

def compute_psx_devaluation(psx):
    """Wave PK-D: PURE multi-signal PKR-devaluation read off the PSX macro dict.
    Returns {level, score, max_score, as_of, signals{name:{points,value,note}}}.
    DISPLAY/DATA-ONLY -> never feeds screening/scoring/IM3/TCE. Fully guarded:
    any bad input yields a safe 'none'-shaped dict instead of raising."""
    try:
        psx = psx or {}
        sig = {}

        # 1) Rupee slope - USD/PKR RISING = PKR weakening (depreciation).
        mom = _pkd_num(psx.get('usd_pkr_mom'))
        qoq = _pkd_num(psx.get('usd_pkr_qoq'))
        pts = 0
        if mom is not None and mom >= PKD_RUPEE_MOM_STRONG:
            pts = 2
        elif mom is not None and mom >= PKD_RUPEE_MOM_MILD:
            pts = 1
        elif qoq is not None and qoq >= PKD_RUPEE_QOQ_MILD:
            pts = 1
        _mtxt = (f'{mom:+.1f}% MoM' if mom is not None else 'MoM n/a')
        sig['rupee_slope'] = {'points': pts, 'value': _pkd_num(psx.get('usd_pkr')),
            'note': f'USD/PKR {psx.get("usd_pkr")} ({_mtxt}); rising = rupee weakening'}

        # 2) Reserves falling - SBP FX reserves declining.
        rmom = _pkd_num(psx.get('sbp_reserves_mom'))
        pts = 0
        if rmom is not None and rmom <= PKD_RESERVES_MOM_STRONG:
            pts = 2
        elif rmom is not None and rmom <= PKD_RESERVES_MOM_MILD:
            pts = 1
        _rtxt = (f'{rmom:+.1f}% MoM' if rmom is not None else 'MoM n/a')
        sig['reserves_fall'] = {'points': pts, 'value': _pkd_num(psx.get('sbp_reserves')),
            'note': f'Pakistan\u2019s foreign cash reserves ${psx.get("sbp_reserves")}bn ({_rtxt}); falling = pressure on the rupee'}

        # 3) REER stretch - rupee overvalued on real-effective terms.
        reer = _pkd_num(psx.get('reer'))
        pts = 0
        if reer is not None and reer >= PKD_REER_STRONG:
            pts = 2
        elif reer is not None and reer >= PKD_REER_MILD:
            pts = 1
        sig['reer_stretch'] = {'points': pts, 'value': reer,
            'note': (f'Rupee value {reer} vs trading partners (100 = fair); above {PKD_REER_MILD:.0f} is too expensive, above {PKD_REER_STRONG:.0f} is stretched'
                     if reer is not None else 'REER n/a')}

        # 4) SBP policy rate - owner's standing defensive line.
        rate = _pkd_num(psx.get('sbp_rate'))
        pts = 1 if (rate is not None and rate >= PKD_SBP_RATE_DEFENSIVE) else 0
        sig['sbp_rate'] = {'points': pts, 'value': rate,
            'note': (f'SBP policy rate {rate}%; >={PKD_SBP_RATE_DEFENSIVE:.0f}% = defensive stance'
                     if rate is not None else 'SBP rate n/a')}

        # 5) Current-account / import-cover stress - WHEN SOURCED.
        # pak_ca has no comparable free monthly unit yet, so it is SURFACED but
        # NOT scored by default (contributes 0) until calibrated with the owner.
        ca = _pkd_num(psx.get('pak_ca'))
        sig['ca_stress'] = {'points': 0, 'value': ca,
            'note': (f'Current account {ca} (not scored - threshold to calibrate)'
                     if ca is not None else 'Current account n/a (when sourced)')}

        # 6) PKR WoW momentum from history store (v1.121.0 Wave R)
        # Reads last 2 usd_pkr readings from EXISTING['history'] to compute WoW slope.
        # 0 pts if <2 days history; 1 pt mild (>0.5% WoW); 2 pts strong (>1.5% WoW).
        _hist = (psx.get('_history_ref') or [])
        _pkr_now = _pkd_num(psx.get('usd_pkr'))
        _pkr_prev = None
        if isinstance(_hist, list) and len(_hist) >= 2:
            for _h in reversed(_hist[:-1]):
                if isinstance(_h, dict) and _h.get('usd_pkr') is not None:
                    _pkr_prev = _pkd_num(_h['usd_pkr']); break
        pts = 0
        _wow_pct = None
        if _pkr_now is not None and _pkr_prev is not None and _pkr_prev > 0:
            _wow_pct = round((_pkr_now - _pkr_prev) / _pkr_prev * 100, 2)
            if _wow_pct >= 1.5: pts = 2
            elif _wow_pct >= 0.5: pts = 1
        _wow_txt = (f'{_wow_pct:+.2f}% WoW' if _wow_pct is not None else 'WoW n/a (<2 history days)')
        sig['pkr_wow'] = {'points': pts, 'value': _pkr_now,
            'note': f'PKR WoW slope: {_wow_txt}; >+0.5% = mild, >+1.5% = strong depreciation'}

        # 7) KERB PREMIUM - the open-market (street) USD premium over the official
        # interbank rate. This widens BEFORE official devaluations = the classic
        # forward-looking street-stress signal. Read from the live psx_kerb feed
        # (stamped onto the psx dict at the call-site; None -> 0, never penalises).
        kerb = _pkd_num(psx.get('_kerb_premium'))
        pts = 0
        if kerb is not None and kerb >= PKD_KERB_STRONG:
            pts = 2
        elif kerb is not None and kerb >= PKD_KERB_MILD:
            pts = 1
        _ktxt = (f'{kerb:+.2f}% over interbank' if kerb is not None else 'kerb premium n/a')
        sig['kerb_premium'] = {'points': pts, 'value': kerb,
            'note': (f'Street (open-market) dollar sits {_ktxt}; a widening premium '
                     f'(>{PKD_KERB_MILD:.1f}% mild, >{PKD_KERB_STRONG:.1f}% strong) is the classic '
                     f'signal that shows up before an official devaluation'
                     if kerb is not None else 'Street-dollar premium n/a (live feed pending)')}

        # 8) GOLD PREMIUM - Karachi gold vs world parity. Local gold outrunning the
        # world price is devaluation EXPECTATION being priced by the street directly.
        # Read from the live psx_bullion feed (stamped at the call-site).
        gold = _pkd_num(psx.get('_gold_premium'))
        pts = 0
        if gold is not None and gold >= PKD_GOLD_STRONG:
            pts = 2
        elif gold is not None and gold >= PKD_GOLD_MILD:
            pts = 1
        _gtxt = (f'{gold:+.2f}% vs world parity' if gold is not None else 'gold premium n/a')
        sig['gold_premium'] = {'points': pts, 'value': gold,
            'note': (f'Karachi gold is {_gtxt}; local gold running ahead of the world price '
                     f'(>{PKD_GOLD_MILD:.1f}% mild, >{PKD_GOLD_STRONG:.1f}% strong) means the street '
                     f'is pricing rupee weakness ahead'
                     if gold is not None else 'Karachi-vs-world gold premium n/a (live feed pending)')}

        score = sum(s['points'] for s in sig.values())
        max_score = 13  # rupee(2)+reserves(2)+reer(2)+rate(1)+CA(0)+pkr_wow(2)+kerb(2)+gold(2)
        if score >= PKD_LEVEL_HIGH:
            level = 'high'
        elif score >= PKD_LEVEL_ELEVATED:
            level = 'elevated'
        elif score >= PKD_LEVEL_WATCH:
            level = 'watch'
        else:
            level = 'none'

        return {'level': level, 'score': score, 'max_score': max_score,
                'as_of': dt.date.today().isoformat(), 'signals': sig}
    except Exception:
        return {'level': 'none', 'score': 0, 'max_score': 13,
                'as_of': dt.date.today().isoformat(), 'signals': {}, 'error': 'compute failed'}

_MOMENTUM_FRAMES = {}   # v1.216.0: {market: {ticker: OHLCV frame}} exported read-only by run_tce
# v1.247.0 WAVE PSXD: {ticker: [deduped <=14d headline strings]} exported read-only by _tce_news for
# PSX names only. SAME mechanical-export pattern as _MOMENTUM_FRAMES above: the headlines are ALREADY
# fetched, date-filtered and deduped every run by the proven Google-News-PK + Business-Recorder read;
# they were counted for s1_news and then DISCARDED. Exporting them costs ZERO new fetches and touches
# no TCE stream/score/tier/threshold -- the September freeze is untouched.
_PSX_NEWS_TITLES = {}

def _rsi_full(closes, p=14):
    """Full Wilder RSI series (same math as the COT _wilder_rsi, but every point). None-padded head."""
    n = len(closes)
    if n < p + 1:
        return [None] * n
    d = [closes[i] - closes[i - 1] for i in range(1, n)]
    g = [max(x, 0) for x in d]; l = [max(-x, 0) for x in d]
    out = [None] * (p)                      # first p closes have no RSI
    ag = sum(g[:p]) / p; al = sum(l[:p]) / p
    out.append(100.0 if al == 0 else round(100 - 100 / (1 + ag / al), 2))
    for i in range(p, len(d)):
        ag = (ag * (p - 1) + g[i]) / p; al = (al * (p - 1) + l[i]) / p
        out.append(100.0 if al == 0 else round(100 - 100 / (1 + ag / al), 2))
    return out                              # len == n

def _rsi_ma_cross(closes, p=14, ma_w=14, recent=3):
    """RSI(p) vs SMA(ma_w) of RSI: current values, state, and whether a cross happened in the last
    `recent` bars. Returns None when the series is too short to judge honestly."""
    closes = [c for c in closes if c is not None]
    if len(closes) < p + ma_w + recent + 2:
        return None
    rsi = _rsi_full(closes, p)
    ma = [None] * len(rsi)
    for i in range(len(rsi)):
        w = [r for r in rsi[max(0, i - ma_w + 1):i + 1] if r is not None]
        if len(w) == ma_w:
            ma[i] = round(sum(w) / ma_w, 2)
    pairs = [(r, m) for r, m in zip(rsi, ma) if r is not None and m is not None]
    if len(pairs) < recent + 2:
        return None
    sides = [1 if r > m else (-1 if r < m else 0) for r, m in pairs]
    signal, days_ago = None, None
    last = sides[-1]
    if last != 0:
        k = 2                                   # walk back through the current run (zeros = neutral touch)
        while k <= len(sides) and sides[-k] in (last, 0):
            k += 1
        if k <= len(sides) and sides[-k] == -last and (k - 1) <= recent:
            signal = 'BULLISH CROSS' if last > 0 else 'BEARISH CROSS'
            days_ago = k - 1
    r_now, m_now = pairs[-1]
    return {'rsi': round(r_now, 1), 'rsi_ma': round(m_now, 1),
            'state': 'above' if r_now > m_now else ('below' if r_now < m_now else 'flat'),
            'signal': signal, 'days_ago': days_ago, 'px': round(closes[-1], 2)}

def build_momentum_signals(data, existing):
    """v1.216.0 MOMENTUM LAYER -- (a) RSI x MA breakout: RSI(14) crossing its own 14-period average
    (cross up = momentum breakout, cross down = breakdown), computed IMMEDIATELY for the US TCE pool +
    PSX candidates from the 6mo frames the TCE batch already downloaded (read-only reuse, zero new
    fetches, frozen TCE untouched) and for the metals/DXY complex from the existing {key}_pxseries
    daily-close store; (b) 200-DMA SLOPE: a small daily momentum_store snapshots each tracked symbol's
    TV-served SMA200 so the slope (is the 200-day line itself rising or falling) goes live once >=3
    run-days accrue -- honest 'accruing' until then, same pattern as Wave T."""
    try:
        out = {'as_of': dt.date.today().isoformat(), 'rsi_ma': {}, 'ma200_slope': {}}
        # ---- (a) RSI x MA: stocks from the TCE frames ----
        for market in ('us', 'psx'):
            rows = []
            frames = _MOMENTUM_FRAMES.get(market) or {}
            for tk, fr in frames.items():
                try:
                    closes = [float(x) for x in fr['Close'].dropna().tolist()]
                except Exception:
                    continue
                r = _rsi_ma_cross(closes)
                if r:
                    r['ticker'] = tk
                    rows.append(r)
            rows.sort(key=lambda x: (x['signal'] is None, x.get('days_ago') or 9, -(x['rsi'] or 0)))
            out['rsi_ma'][market] = rows
        # ---- (a) RSI x MA: metals/DXY from the stored daily-close series ----
        met = (data.get('macros') or {}).get('metals') or {}
        mrows = []
        for key, label in (('gold_px', 'Gold'), ('silver_px', 'Silver'), ('platinum_px', 'Platinum'),
                           ('palladium_px', 'Palladium'), ('copper_px', 'Copper'), ('dxy', 'US Dollar (DXY)')):
            ser = [h.get('v') for h in (met.get(f'{key}_pxseries') or []) if isinstance(h, dict)]
            r = _rsi_ma_cross(ser)
            if r:
                r['ticker'] = label
                mrows.append(r)
            else:
                mrows.append({'ticker': label, 'pending': True, 'pts': len([v for v in ser if v is not None])})
        out['rsi_ma']['metals'] = mrows
        # ---- (b) 200-DMA slope store: snapshot today's TV-served SMA200 per tracked symbol ----
        store = list((existing or {}).get('momentum_store') or [])
        syms = {}
        for key in ('gold_px', 'silver_px', 'platinum_px', 'palladium_px', 'copper_px', 'dxy'):
            s = met.get(f'{key}_sma200')
            if s is not None:
                syms[key] = round(float(s), 4)
        for h in ((data.get('live_investment') or {}).get('holdings') or []):
            s = h.get('live_sma200') if h.get('live_sma200') is not None else h.get('sma200')
            if s is not None and h.get('ticker'):
                syms[h['ticker']] = round(float(s), 4)
        for f in (data.get('etf_momentum_watch') or []):
            s = f.get('live_sma200') if isinstance(f, dict) else None
            tk = (f.get('ticker') or f.get('isin')) if isinstance(f, dict) else None
            if s is not None and tk:
                syms[tk] = round(float(s), 4)
        today = dt.date.today().isoformat()
        store = [d0 for d0 in store if d0.get('date') != today]
        store.append({'date': today, 's200': syms})
        store = store[-60:]
        data['momentum_store'] = store
        # slope once >=3 stored days: latest vs the closest snapshot >=5 days back (or the oldest)
        srows, status = [], 'accruing'
        if len(store) >= 3:
            status = 'live'
            base = store[max(0, len(store) - 6)]['s200']
            span = min(5, len(store) - 1)
            for sym, now in store[-1]['s200'].items():
                then = base.get(sym)
                if then:
                    pct = round((now / then - 1) * 100, 3)
                    srows.append({'sym': sym, 'slope_pct': pct, 'span_days': span,
                                  'dir': 'rising' if pct > 0.10 else ('falling' if pct < -0.10 else 'flat')})
            srows.sort(key=lambda x: -abs(x['slope_pct']))
        out['ma200_slope'] = {'status': status, 'store_days': len(store), 'span_note':
                              '200-DMA level change over the last ~5 run-days', 'rows': srows}
        n_us = sum(1 for r in out['rsi_ma'].get('us', []) if r.get('signal'))
        n_px = sum(1 for r in out['rsi_ma'].get('psx', []) if r.get('signal'))
        n_mt = sum(1 for r in out['rsi_ma'].get('metals', []) if r.get('signal'))
        log(f"  [Momentum] RSI\u00d7MA: us {n_us} cross / {len(out['rsi_ma'].get('us', []))} scanned, "
            f"psx {n_px}/{len(out['rsi_ma'].get('psx', []))}, metals {n_mt} cross; "
            f"200-DMA slope: {out['ma200_slope']['status']} (day {len(store)}, needs 3+)")
        data['momentum'] = out
    except Exception as e:
        warn(f'Momentum layer failed ({e}) -- carrying last-good')
        if (existing or {}).get('momentum'):
            data['momentum'] = existing['momentum']
        if (existing or {}).get('momentum_store') and 'momentum_store' not in data:
            data['momentum_store'] = existing['momentum_store']


PB_CROWDED_MULT = 0.90   # v1.257.0: weight multiplier for a name the tracked institutions already crowd into


def build_pb_portfolio(data, existing):
    """v1.220.0 WAVE PB FRONT HALF -- the portfolio-construction engine + paper-forward track.
    Assembles two rules-based MODEL portfolios (paper, not orders) from engines that already run:
      US:  m1_buylist buys, weighted by strength (im3_pct/keystone), tilted by TCE tier, momentum
           state (RSI x MA), and Zacks; cash buffer set by the US diffusion phase.
      PSX: psx_topdown buys, weighted by strength pct, tilted by TCE tier, momentum and valuation;
           the owner's DEFENSIVE rule applies -- SBP rate >= 11%% -> larger cash buffer + bank tilt.
    Floor 5%% / cap 20%% per name, weights normalised to (100 - cash). A daily paper ledger
    (pb_track, date-deduped, cap 200) chains each book's NAV from 100 at inception and normalises
    S&P 500 and KSE-100 to the same base -- the LIVE half of PB; the backtest half waits for the
    history store to deepen. Wrapped; carries last-good."""
    try:
        today = dt.date.today().isoformat()
        mom = ((data.get('momentum') or {}).get('rsi_ma') or {})

        def _mom_mult(mk, tk):
            for r in (mom.get(mk) or []):
                if r.get('ticker') == tk:
                    if r.get('signal') == 'BEARISH CROSS':
                        return 0.70, 'momentum breakdown'
                    if r.get('signal') == 'BULLISH CROSS':
                        return 1.10, 'fresh breakout'
                    return (0.85, 'momentum soft') if r.get('state') == 'below' else (1.0, 'momentum ok')
            return 1.0, None

        def _tce_tier(rows, tk):
            for r in (rows or []):
                if r.get('ticker') == tk:
                    return r.get('tier')
            return None

        # v1.257.0 CROWDING TILT (owner decision, this session; D-PB-RULES entry recorded).
        # A name most of the tracked institutions ALREADY hold is a crowded trade: the thesis is
        # consensus, the obvious buyers have bought, and the marginal buyer is scarcer. v1.245.0
        # shipped the crowded FLAG (a chip on the tab) but DELIBERATELY did not touch weights,
        # because changing a weight changes a SCORE -- which the owner's D-PB-RULES say needs its
        # own version + Decision Record entry. He has now approved it, so the flag becomes a tilt.
        # STILL NOT A FILTER: a crowded name is never dropped, it is sized DOWN by 10%%. Context,
        # not a veto -- the same principle the flag shipped under.
        # PRIOR-RUN SOURCE, and this is not a shortcut: build_pb_portfolio runs at main() line 1182
        # and build_whale_13f at 1186, so THIS run's crowd data does not exist yet at this point
        # (verified against main()'s real call order, per the pipeline-order rule). Reading EXISTING
        # is correct anyway for the same reason the ETF-consensus and Wave-O sources do it -- 13F
        # filings are QUARTERLY and land 45 days after quarter-end, so yesterday's parse IS today's
        # truth. No reordering, no new fetch, and an empty map is a clean no-op.
        _crowd = ((existing or {}).get('whale_13f') or {}).get('crowd_by_ticker') or {}
        _n_whales = ((existing or {}).get('whale_13f') or {}).get('n_whales') or 0

        def _compose(cands, mk, tce_rows, cash_w, extra_tilt):
            raw, notes = {}, {}
            _crowded_hits = []
            for c in cands:
                tk = c.get('ticker')
                if not tk or c.get('price') in (None, 0):
                    continue
                s = c.get('im3_pct') or c.get('pct') or c.get('keystone') or 50.0
                m, mnote = _mom_mult(mk, tk)
                tier = _tce_tier(tce_rows, tk)
                tmult = 1.15 if tier == 'HIGH' else 1.0
                xmult, xnote = extra_tilt(c)
                # v1.257.0 crowding tilt -- sized down, never dropped
                _cw = _crowd.get(tk) or {}
                cmult, cnote = 1.0, None
                if _cw.get('crowded'):
                    cmult = PB_CROWDED_MULT
                    _h = _cw.get('n_holders')
                    cnote = ('already crowded (%s of %s big investors own it) \u2192 sized down %d%%'
                             % (_h, _n_whales or '?', round((1 - PB_CROWDED_MULT) * 100)))
                    _crowded_hits.append(f'{tk}({_h})')
                raw[tk] = max(float(s), 1.0) * m * tmult * xmult * cmult
                why = [f"strength {round(float(s))}"]
                if tier == 'HIGH': why.append('TCE HIGH')
                if mnote: why.append(mnote)
                if xnote: why.append(xnote)
                if cnote: why.append(cnote)
                notes[tk] = {'why': ' \u00b7 '.join(why), 'price': float(c['price']),
                             'name': c.get('name'), 'sector': c.get('sector')}
            if _crowded_hits:
                log(f"  [PB] {mk.upper()} crowding tilt applied to {len(_crowded_hits)} name(s) "
                    f"(x{PB_CROWDED_MULT}): {', '.join(_crowded_hits)}")
            if not raw:
                return None
            eq = 100.0 - cash_w
            tot = sum(raw.values())
            w = {tk: eq * v / tot for tk, v in raw.items()}
            for _ in range(6):                                  # cap 20 / floor 5, renormalise
                over = {tk: v for tk, v in w.items() if v > 20.0}
                if not over:
                    break
                spare = sum(v - 20.0 for v in over.values())
                for tk in over: w[tk] = 20.0
                under = {tk: v for tk, v in w.items() if v < 20.0}
                ut = sum(under.values()) or 1.0
                for tk in under: w[tk] += spare * under[tk] / ut
            w = {tk: v for tk, v in w.items() if v >= 5.0 or len(w) <= 5}
            tot2 = sum(w.values()) or 1.0
            w = {tk: round(eq * v / tot2, 2) for tk, v in w.items()}
            rows = [{'ticker': tk, 'weight': w[tk], 'why': notes[tk]['why'],
                     'name': notes[tk]['name'], 'sector': notes[tk]['sector'],
                     'price': notes[tk]['price']} for tk in sorted(w, key=lambda k: -w[k])]
            return {'rows': rows, 'cash': round(cash_w, 1)}

        # ---- US book ----
        phase = str(((data.get('us_diffusion') or {}).get('phase')) or 'Neutral')
        us_cash = 5.0 if phase == 'Expansion' else (20.0 if phase == 'Contraction' else 10.0)
        def _us_tilt(c):
            z = c.get('zacks')
            try:
                if z is not None and float(z) <= 2:
                    return 1.10, 'Zacks Buy'
            except Exception:
                pass
            return 1.0, None
        us_book = _compose(((data.get('m1_buylist') or {}).get('buys') or []), 'us',
                           data.get('tce_us'), us_cash, _us_tilt)
        if us_book:
            us_book['regime'] = f"US diffusion phase: {phase} -> {us_cash:.0f}% cash buffer"

        # ---- PSX book (owner rule: SBP >= 11%% = defensive) ----
        sbp = ((data.get('macros') or {}).get('psx') or {}).get('sbp_rate')
        defensive = (sbp is not None and float(sbp) >= 11.0)
        px_cash = 15.0 if defensive else 8.0
        def _px_tilt(c):
            mult, note = 1.0, None
            if defensive and c.get('is_bank'):
                mult, note = 1.25, 'bank (defensive tilt)'
            v = str(c.get('valuation') or '')
            if not c.get('is_bank'):
                if v.lower().startswith('attract'):
                    mult *= 1.10; note = (note + ' \u00b7 ' if note else '') + 'attractive valuation'
                elif v.lower().startswith('rich'):
                    mult *= 0.90; note = (note + ' \u00b7 ' if note else '') + 'rich valuation'
            return mult, note
        px_book = _compose(((data.get('psx_topdown') or {}).get('buys') or []), 'psx',
                           data.get('tce_psx'), px_cash, _px_tilt)
        if px_book:
            px_book['regime'] = (f"SBP {sbp}% >= 11% -> DEFENSIVE: {px_cash:.0f}% cash + bank tilt"
                                 if defensive else f"SBP {sbp}% < 11% -> normal: {px_cash:.0f}% cash")

        # ---- paper-forward ledger ----
        track = list((existing or {}).get('pb_track') or [])
        spy = ((data.get('macros') or {}).get('us') or {}).get('sp500')
        kse = ((data.get('macros') or {}).get('psx') or {}).get('kse100')
        def _mark(prev, book, key):
            if not prev or not book:
                return 100.0
            pw, ppx = prev[key].get('w') or {}, prev[key].get('px') or {}
            px_now = {r['ticker']: r['price'] for r in book['rows']}
            r_tot, w_used = 0.0, 0.0
            for tk, w0 in pw.items():
                p0, p1 = ppx.get(tk), px_now.get(tk)
                if p0 and p1:
                    r_tot += (w0 / 100.0) * (p1 / p0 - 1.0)
                    w_used += w0
            return round(prev[key].get('nav', 100.0) * (1.0 + r_tot), 4)
        prev = track[-1] if track else None
        if prev and prev.get('date') == today:
            prev = track[-2] if len(track) >= 2 else None
        entry = {'date': today, 'spy': spy, 'kse': kse}
        for key, book in (('us', us_book), ('psx', px_book)):
            if book:
                entry[key] = {'w': {r['ticker']: r['weight'] for r in book['rows']},
                              'px': {r['ticker']: r['price'] for r in book['rows']},
                              'nav': _mark(prev, book, key) if prev and prev.get(key) else 100.0}
        track = [e for e in track if e.get('date') != today]
        track.append(entry)
        data['pb_track'] = track[-200:]
        first = data['pb_track'][0]
        def _norm(now, base):
            return round(100.0 * now / base, 2) if (now and base) else None
        tr = {'inception': first.get('date'), 'days': len(data['pb_track']),
              'us_nav': (entry.get('us') or {}).get('nav'), 'spy_norm': _norm(spy, first.get('spy')),
              'psx_nav': (entry.get('psx') or {}).get('nav'), 'kse_norm': _norm(kse, first.get('kse'))}
        tr['us_alpha'] = (round(tr['us_nav'] - tr['spy_norm'], 2)
                          if (tr['us_nav'] is not None and tr['spy_norm'] is not None) else None)
        tr['psx_alpha'] = (round(tr['psx_nav'] - tr['kse_norm'], 2)
                           if (tr['psx_nav'] is not None and tr['kse_norm'] is not None) else None)
        data['pb'] = {'as_of': today, 'us': us_book, 'psx': px_book, 'track': tr,
                      'note': 'Paper model portfolio built by fixed rules from the live engines. Not orders.'}
        # ---- v1.240.0 WAVE PB BACK-HALF: backtest vs SPY / KSE-100 over the accrued history ----
        # Computes cumulative return, benchmark return, alpha and max drawdown from the pb_track
        # series (each entry already carries chained us/psx NAV + raw spy/kse index levels). Honest
        # 'accruing' until ~30 days of depth exist; fills automatically as the store deepens (same
        # build-now/auto-populate pattern as WoW/MoM). Reads only data['pb_track'] -- no new fetch.
        def _bt(series, navkey, benchkey):
            pts = []
            for e in series:
                nav = (e.get(navkey) or {}).get('nav'); b = e.get(benchkey)
                if nav is not None and b:
                    try: pts.append((e.get('date'), float(nav), float(b)))
                    except Exception: pass
            if len(pts) < 2:
                return {'days': len(pts), 'ready': False, 'ret_pct': None,
                        'bench_ret_pct': None, 'alpha_pct': None, 'max_dd_pct': None,
                        'start': (pts[0][0] if pts else None), 'end': (pts[-1][0] if pts else None)}
            nav0, navL = pts[0][1], pts[-1][1]; b0, bL = pts[0][2], pts[-1][2]
            ret = (navL / nav0 - 1.0) * 100 if nav0 else None
            bret = (bL / b0 - 1.0) * 100 if b0 else None
            alpha = (ret - bret) if (ret is not None and bret is not None) else None
            peak = pts[0][1]; mdd = 0.0
            for _d, nav, _b in pts:
                if nav > peak: peak = nav
                dd = (nav / peak - 1.0) * 100 if peak else 0.0
                if dd < mdd: mdd = dd
            return {'days': len(pts), 'ready': len(pts) >= 20,
                    'ret_pct': round(ret, 2) if ret is not None else None,
                    'bench_ret_pct': round(bret, 2) if bret is not None else None,
                    'alpha_pct': round(alpha, 2) if alpha is not None else None,
                    'max_dd_pct': round(mdd, 2), 'start': pts[0][0], 'end': pts[-1][0]}
        try:
            _series = data.get('pb_track') or []
            _us_bt = _bt(_series, 'us', 'spy'); _px_bt = _bt(_series, 'psx', 'kse')
            _days = max(_us_bt['days'], _px_bt['days'])
            _bnote = (f'{_days} trading days of live paper-book history vs benchmarks.'
                      if _days >= 20 else
                      f'Accruing: {_days} day(s) since inception; a stable backtest read needs ~30. '
                      'Fills automatically as the daily store deepens.')
            data['pb']['backtest'] = {'us': _us_bt, 'psx': _px_bt, 'days': _days,
                                      'ready': _us_bt['ready'] or _px_bt['ready'],
                                      'benchmarks': {'us': 'S&P 500', 'psx': 'KSE-100'},
                                      'note': _bnote}
        except Exception as _bte:
            if (existing or {}).get('pb', {}).get('backtest'):
                data['pb']['backtest'] = existing['pb']['backtest']
        log(f"  [PB] paper book: us {len((us_book or {}).get('rows') or [])} names/{(us_book or {}).get('cash')}% cash, "
            f"psx {len((px_book or {}).get('rows') or [])} names/{(px_book or {}).get('cash')}% cash; "
            f"track day {tr['days']} (us nav {tr['us_nav']} vs spy {tr['spy_norm']}, psx {tr['psx_nav']} vs kse {tr['kse_norm']})")
    except Exception as e:
        warn(f'PB build failed ({e}) -- carrying last-good')
        for k in ('pb', 'pb_track'):
            if (existing or {}).get(k) and k not in data:
                data[k] = existing[k]


def append_history(data, existing):
    """Wave T - rolling DAILY HISTORY STORE. Appends a compact snapshot of the scan-time-only data
    points (the ones with NO external time series to backfill from - KSE-100, margin-financing total,
    USD/PKR, policy rate, candidate/HIGH counts, etc.) to data['history'], deduped by date (the last
    run that day wins), capped to the last 400 days. Stored INSIDE data.json so it persists via the
    same commit the workflow already makes - no extra file, no daily.yml change. DISPLAY/DATA ONLY:
    never touches screening/scoring/TCE -> respects the Sept freeze. Fully guarded (never raises)."""
    try:
        psx = (data.get('macros') or {}).get('psx') or {}
        us  = (data.get('macros') or {}).get('us') or {}
        met = (data.get('macros') or {}).get('metals') or {}
        mts = (data.get('psx_mts') or {}).get('market') or {}
        def _len(key):
            v = data.get(key); return len(v) if isinstance(v, list) else None
        def _tier(key, tier):
            v = data.get(key)
            return sum(1 for r in v if isinstance(r, dict) and r.get('tier') == tier) if isinstance(v, list) else None
        snap = {
            'date': dt.date.today().isoformat(),
            'kse100': psx.get('kse100'),
            'sp500': us.get('sp500'),
            'usd_pkr': psx.get('usd_pkr'),
            'sbp_rate': psx.get('sbp_rate'),
            'mts_total_mn': mts.get('total_mn'),
            'mts_change_pct': mts.get('change_pct'),
            'gold_px': met.get('gold_px'),
            'dxy': met.get('dxy'),
            'wti': us.get('wti'),
            'us_10y': us.get('us_10y'),
            'recession_score': (data.get('recession') or {}).get('score'),
            'us_candidates_n': _len('us_candidates'),
            'psx_candidates_n': _len('psx_candidates'),
            'us_tce_high_n': _tier('tce_us', 'HIGH'),
            'psx_tce_high_n': _tier('tce_psx', 'HIGH'),
            # Wave T enrichment v1.120.0 — macro breadth + sector leadership
            'us_diffusion_net': (data.get('us_diffusion') or {}).get('net'),
            'lei_expansion_count': sum(
                1 for v in (data.get('world_lei') or {}).values()
                if isinstance(v, dict) and v.get('signal') == 'expansion'
            ) or None,
            'sector_top': ((data.get('sector_booming') or [{}])[0].get('sector')
                           if data.get('sector_booming') else None),
            'sector_top_score': ((data.get('sector_booming') or [{}])[0].get('score')
                                 if data.get('sector_booming') else None),
            'hy_spread': us.get('hy_spread'),
            'core_pce': us.get('core_pce'),
            # Wave T v1.176.0 — global market breadth (countries above 200-DMA) so the Allocation-Zone
            # breadth indicator can trend day-over-day like the macro cards.
            'global_breadth_abv': sum(1 for r in (data.get('country_rs') or [])
                                      if isinstance(r, dict) and r.get('above_200dma') is True) or None,
            'global_breadth_tot': sum(1 for r in (data.get('country_rs') or [])
                                      if isinstance(r, dict) and r.get('above_200dma') is not None) or None,
        }
        # Wave T (universal): generically capture EVERY numeric scalar from the macro namespaces under
        # flat path keys (us.<k>/psx.<k>/metals.<k>), so compute_trends can emit a trend for ANY field —
        # not just the curated ones above. Skip derived/helper fields (already carry their own trend) so
        # we never "trend a trend". Curated short keys above are left intact (they already have history).
        _SKIP = ('_hist', '_wow', '_mom', '_qoq', '_yoy', '_dir', '_sma', '_series',
                 '_spark', '_pctile', '_as_of', '_source', '_ts', '_slope', '_rsi', '_cross')
        for _ns, _d in (('us', us), ('psx', psx), ('metals', met)):
            if not isinstance(_d, dict):
                continue
            for _k, _v in _d.items():
                if not isinstance(_v, (int, float)) or isinstance(_v, bool):
                    continue
                if any(_s in _k for _s in _SKIP):
                    continue
                _path = f'{_ns}.{_k}'
                if _path not in snap:
                    snap[_path] = _v
        hist = existing.get('history')
        if not isinstance(hist, list):
            hist = []
        hist = [h for h in hist if isinstance(h, dict) and h.get('date') != snap['date']]
        # Wave T: seed the newly-captured namespaced fields onto the most-recent PRIOR snapshot using
        # last run's macros (existing['macros'] = the prior data.json), so every generic field has a
        # prior data point and TRENDS on the very first run — instead of showing 'pending' until a
        # second day accrues. setdefault only fills gaps, so real captured values are never clobbered.
        if hist:
            _prior = max(hist, key=lambda h: h.get('date') or '')
            _ex_m = existing.get('macros') or {}
            for _ns in ('us', 'psx', 'metals'):
                _exd = _ex_m.get(_ns) or {}
                if not isinstance(_exd, dict):
                    continue
                for _k, _v in _exd.items():
                    if (isinstance(_v, (int, float)) and not isinstance(_v, bool)
                            and not any(_s in _k for _s in _SKIP)):
                        _prior.setdefault(f'{_ns}.{_k}', _v)
        # v1.314.7 ONE-TIME OIL HISTORY PURGE: prior rows stored front-month futures prints whose
        # contract-roll jumps corrupted the Brent WoW/MoM (impossible -25.7% vs a real +23% market).
        # At the continuous-source cutover, strip the roll-contaminated oil keys from every PRIOR row
        # exactly once, so trends restart clean from real continuous prints. The marker _oil_basis
        # rides the snapshot (string -> compute_trends ignores it) and prevents any repeat purge.
        snap['_oil_basis'] = 'cont'
        if not any(isinstance(h, dict) and h.get('_oil_basis') == 'cont' for h in hist):
            _purged = 0
            for h in hist:
                if isinstance(h, dict):
                    for _ok in ('wti', 'us.wti', 'us.brent'):
                        if _ok in h:
                            del h[_ok]
                            _purged += 1
            if _purged:
                log(f'  [Wave T history] one-time oil purge: {_purged} roll-contaminated '
                    f'wti/brent point(s) removed (continuous-source cutover)')
        hist.append(snap)
        hist.sort(key=lambda h: h.get('date') or '')
        data['history'] = hist[-400:]
        # Backfill the S&P 500 level onto any earlier history row that predates the sp500 field,
        # from the FRED SP500 dated series, so the US 'vs index' read has a benchmark level at each
        # pick's first-seen date (KSE-100 is snapshotted natively). Display/data-only.
        _sp_hist = us.get('sp500_hist') or {}
        if isinstance(_sp_hist, dict) and _sp_hist:
            for _h in data['history']:
                if isinstance(_h, dict) and _h.get('sp500') is None and _h.get('date') in _sp_hist:
                    _h['sp500'] = _sp_hist[_h['date']]
        log(f'  [Wave T history] {snap["date"]}: {len(data["history"])} day(s) stored '
            f'(kse100={snap["kse100"]}, usd/pkr={snap["usd_pkr"]}'
            f', diffusion_net={snap["us_diffusion_net"]}'
            f', lei_exp={snap["lei_expansion_count"]}'
            f', sector_top={snap["sector_top"]} {snap["sector_top_score"]})')
    except Exception as e:
        log(f'  [Wave T history] skipped ({type(e).__name__}: {str(e)[:50]})')
        if isinstance(existing.get('history'), list):
            data['history'] = existing['history']


def compute_trends(data):
    """Wave T (universal trend layer) — emit data['trends']: for EVERY numeric scalar captured in the
    rolling history store, a trend read {v, prev, delta, pct, dir, days, as_of, basis}. The trend is the
    change since the value LAST MOVED, which is honest for BOTH daily series (day-over-day) and monthly
    prints stored daily (shows the real last step + how many days ago, not a fake daily zero). One central
    table so the dashboard can show a trend cell next to any live number via trendChip(path) — universal
    coverage at the data layer, no per-field wiring. Display/data-only; never touches screening/scoring/TCE
    (respects the Sept freeze). Fully guarded (never raises)."""
    try:
        hist = data.get('history')
        if not isinstance(hist, list) or not hist:
            return
        rows = sorted([h for h in hist if isinstance(h, dict) and h.get('date')],
                      key=lambda h: h.get('date') or '')
        if not rows:
            return
        latest = rows[-1]
        today = latest.get('date')

        def _num(x):
            return isinstance(x, (int, float)) and not isinstance(x, bool)

        trends = {}
        for k, cur in latest.items():
            if k == 'date' or not _num(cur):
                continue
            prev = None
            prev_date = None
            seen = 1
            for h in reversed(rows[:-1]):
                pv = h.get(k)
                if not _num(pv):
                    continue
                seen += 1
                if pv != cur:
                    prev = pv
                    prev_date = h.get('date')
                    break
                if prev_date is None:      # equal-but-present: anchor for "flat in range"
                    prev_date = h.get('date')
            if prev is None:
                trends[k] = {'v': cur, 'prev': None, 'delta': 0, 'pct': 0, 'dir': 'flat',
                             'days': None, 'as_of': prev_date,
                             'basis': 'flat' if seen > 1 else 'pending'}
                continue
            delta = round(cur - prev, 4)
            pct = round((cur - prev) / abs(prev) * 100, 2) if prev not in (0, None) else None
            try:
                days = (dt.date.fromisoformat(today) - dt.date.fromisoformat(prev_date)).days
            except Exception:
                days = None
            trends[k] = {'v': cur, 'prev': prev, 'delta': delta, 'pct': pct,
                         'dir': 'up' if delta > 0 else ('down' if delta < 0 else 'flat'),
                         'days': days, 'as_of': prev_date, 'basis': 'change'}
        data['trends'] = trends
        _live = sum(1 for t in trends.values() if t['basis'] == 'change')
        log(f'  [Wave T trends] {len(trends)} field(s) in trend table, {_live} with a live move '
            f'(kse100={trends.get("kse100", {}).get("dir")}, usd_pkr={trends.get("usd_pkr", {}).get("dir")}, '
            f'sp500={trends.get("sp500", {}).get("dir")}, gold_px={trends.get("gold_px", {}).get("dir")})')
    except Exception as e:
        log(f'  [Wave T trends] skipped ({type(e).__name__}: {str(e)[:60]})')


