def _tge_lei(country_slug, indicator='leading-economic-index', diag=True):
    """Fetch a single leading economic indicator value from theglobaleconomy.com.
    Same scraping pattern as the Pakistan CPI _tge() already proven on the runner.
    Returns (value_float, date_str) or (None, None) on failure.
    country_slug examples: 'Japan', 'South-Korea', 'United-States', 'United-Kingdom',
    'China', 'Canada', 'Australia', 'Germany', 'Brazil', 'Taiwan', 'New-Zealand',
    'Switzerland', 'India'."""
    try:
        import requests as _req
        _UA = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
               '(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36')
        url = f'https://www.theglobaleconomy.com/{country_slug}/{indicator}/'
        rr = _req.get(url, headers={'User-Agent': _UA}, timeout=20)
        if rr.status_code != 200:
            if diag:
                log(f'  [LEI-TGE] {country_slug}/{indicator}: HTTP {rr.status_code}')
            return None, None
        import re as _re
        txt = _re.sub(r'<[^>]+>', ' ', rr.text)
        txt = txt.replace('&nbsp;', ' ').replace('&nbsp', ' ')
        txt = _re.sub(r'\s+', ' ', txt)
        i = txt.find('Recent values')
        seg = txt[i:i+600] if i >= 0 else txt[:600]
        # Extract date: "YYYY Mon" or "Mon YYYY"
        dm = _re.search(
            r'((?:(?:19|20)\d{2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec))|'
            r'(?:(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(?:19|20)\d{2}))',
            seg)
        # Extract value after date
        vm = _re.search(
            r'(?:(?:19|20)\d{2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)|'
            r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(?:19|20)\d{2})'
            r'\s+(-?[\d,]+(?:\.\d+)?)',
            seg)
        val  = float(vm.group(1).replace(',', '')) if vm else None
        date = dm.group(1).strip() if dm else None
        if diag:
            log(f'  [LEI-TGE] {country_slug}: val={val} date={date} hasRecent={i>=0}')
        return val, date
    except Exception as _e:
        if diag:
            log(f'  [LEI-TGE] {country_slug}: {type(_e).__name__}: {str(_e)[:60]}')
        return None, None


def fetch_world_lei():
    """v1.123.1: Restored FRED fredapi for OECD CLI. TGE was JS-rendered — returns
    empty HTML shell to requests.get(); 0/13 fetched on runner (confirmed 2026-06-29).
    FRED fredapi already proven + has retry/backoff (_fred_series pattern).
    12 countries: original 8 + South Korea + Germany + India + Brazil.
    Taiwan excluded (not OECD member — no CLI series). NZ excluded (no FRED series).
    Guarded per-country; miss omits entry; full crash returns {}.
    DATA-only; never touches screen / scoring / TCE / frozen ledger."""
    _LEI_SERIES = {
        'Australia':   'AUSLOLITONOSTSAM',
        'Canada':      'CANLOLITONOSTSAM',
        'China':       'CHNLOLITONOSTSAM',
        'Euro-area':   'EA19LOLITONOSTSAM',  # may be stale — series discontinued; kept + flagged
        'Japan':       'JPNLOLITONOSTSAM',
        'Switzerland': 'CHELOLITONOSTSAM',
        'UK':          'GBRLOLITONOSTSAM',
        'USA':         'USALOLITONOSTSAM',
        # v1.123.1: 4 new OECD members added
        'South Korea': 'KORLOLITONOSTSAM',
        'Germany':     'DEULOLITONOSTSAM',
        'India':       'INDLOLITONOSTSAM',
        'Brazil':      'BRALOLITONOSTSAM',
        # Taiwan: not an OECD member — no CLI series
        # New Zealand: no FRED series (confirmed v1.119.0)
    }
    out = {}
    # ── v1.263.0 INVERTED: TradingEconomics FIRST, FRED only for the gaps ──────────────────
    # The owner asked TWICE to make the alternative PRIMARY and I kept FRED first, building a
    # rescue that only fired on FAILURE. Run 1258 proves why that was useless: 481.9s total with
    # ZERO errors and ZERO warnings -- FRED did not fail, it was just SLOW. Same code, same
    # countries, five measured runs: 3.7s / 32.4s / 66.7s / 183.0s. A failure-only rescue can
    # never touch that. This makes TE primary, which is what he actually asked for.
    # TESTED FIRST (tradingeconomics.com/japan/composite-leading-indicator, real bytes 2026-07-15):
    # same OECD series, monthly, "Amplitude adjusted, Long-term average = 100" -- identical to
    # FRED's LOLITONOSTSAM -- static HTML, fresher (Jun-2026). 12 static GETs ~6s vs 32-183s.
    # HONEST TRADE, not hidden: FRED returns the SERIES so it regresses a real 6-month slope +
    # momentum; TE returns the print, so a TE country carries lei + signal but slope/momentum
    # are None and trend is 'n/a'. The World Economy tab's lei/signal are preserved. Any country
    # TE misses still goes to FRED below and keeps the FULL series maths -- nothing is lost, only
    # the common path gets fast. Set TE_LEI_PRIMARY=False to revert to FRED-first instantly.
    if TE_LEI_PRIMARY:
        try:
            _te_vals = fetch_te_world_lei(list(_LEI_SERIES.keys())) or {}
            _te_notes = getattr(fetch_te_world_lei, 'last_notes', {}) or {}
            for _c, _v in _te_vals.items():
                out[_c] = {
                    'lei': round(float(_v), 3), 'slope': None, 'trend': 'n/a',
                    'momentum': None,
                    'signal': 'expansion' if float(_v) > 100 else 'contraction',
                    'as_of': str(dt.date.today()),
                    'source': ('tradingeconomics (%s)' % _te_notes[_c]) if _c in _te_notes
                              else 'tradingeconomics',
                }
            log(f'  [World LEI] TradingEconomics (PRIMARY): {len(out)}/{len(_LEI_SERIES)} countries')
        except Exception as _tee:
            log(f'  [World LEI] TE primary failed ({type(_tee).__name__}) -- FRED will do all 12')
    _todo = {k: v for k, v in _LEI_SERIES.items() if k not in out}
    if _todo:
        log(f'  [World LEI] FRED for the {len(_todo)} TE missed: {sorted(_todo)}')
    try:
        if not _todo:
            raise StopIteration            # nothing left for FRED -- skip the whole block
        from fredapi import Fred as _Fred
        _fred = _Fred(api_key=FRED_KEY)
        for country, series_id in _todo.items():
            try:
                s = _fred.get_series(series_id, observation_start='2020-01-01')
                s = s.dropna()
                if len(s) < 4:
                    log(f'  [World LEI] {country}: insufficient data ({len(s)} obs) — skip')
                    continue
                # v1.314.7 ZOMBIE-SERIES GUARD: FRED keeps discontinued OECD series online (EA19 and
                # Switzerland's CLI both died 2022-11) and this leg was re-writing those 3.7-year-old
                # values every run. A "leading" indicator >400 days old is not a reading, it is a relic.
                try:
                    _age = (dt.date.today() - dt.date.fromisoformat(str(s.index[-1])[:10])).days
                    if _age > 400:
                        log(f'  [World LEI] {country}: FRED series stale {_age}d (discontinued) — skip')
                        continue
                except Exception:
                    pass
                vals  = list(s.values)
                dates = [str(d)[:10] for d in s.index]
                latest = vals[-1]
                prev1  = vals[-2]
                avg3   = sum(vals[-3:]) / 3
                avg6   = sum(vals[-6:]) / 6 if len(vals) >= 6 else sum(vals) / len(vals)
                slope  = round(avg3 - avg6, 4)
                mom    = round(latest - prev1, 4)
                trend  = 'rising' if slope > 0 else ('falling' if slope < 0 else 'flat')
                signal = 'expansion' if latest > 100 else 'contraction'
                out[country] = {
                    'lei':      round(latest, 3),
                    'slope':    slope,
                    'trend':    trend,
                    'momentum': mom,
                    'signal':   signal,
                    'as_of':    dates[-1],
                }
            except Exception as _e:
                log(f'  [World LEI] {country} skip: {type(_e).__name__}: {str(_e)[:50]}')
        log(f'  [World LEI] {len(out)}/{len(_LEI_SERIES)} countries after FRED')
    except StopIteration:
        log('  [World LEI] FRED skipped entirely -- TradingEconomics covered all 12')
    except Exception as e:
        log(f'  [World LEI] FRED fetch failed: {type(e).__name__}: {str(e)[:60]}')
    # v1.262.0 RESCUE: fill ONLY the countries FRED did not return, from TradingEconomics'
    # static per-country OECD-CLI pages (tested 2026-07-15: same OECD series, monthly,
    # amplitude-adjusted LTA=100 -- identical to FRED's LOLITONOSTSAM -- and fresher).
    # FRED healthy -> _missing is empty -> zero calls, zero change. A rescued country gets its
    # LEVEL and its expansion/contraction signal, but slope/momentum stay None because TE hands
    # the print rather than the series the slope is regressed from -- stated, not hidden, and
    # far better than the country vanishing from the grid entirely.
    # (v1.262.0's failure-only TE rescue removed in v1.263.0 -- TE now runs FIRST above, so a
    #  second pass would be dead code. FRED remains the fallback for anything TE misses.)
    # Phase 1: enrich with IMF 2026 GDP forecast + World Bank 2024 current account
    # Hardcoded quarterly — update from imf.org/en/Publications/WEO each quarter
    _IMF_GDP = {'Australia':1.6,'Canada':1.4,'China':4.6,'Euro-area':0.8,
                'Japan':0.6,'Switzerland':1.2,'UK':1.1,'USA':1.8,
                'South Korea':2.3,'Germany':0.1,'India':6.5,'Brazil':2.2}
    _WB_CA   = {'Australia':-1.4,'Canada':-0.7,'China':2.1,'Euro-area':2.8,
                'Japan':3.5,'Switzerland':8.2,'UK':-3.1,'USA':-3.3,
                'South Korea':3.9,'Germany':5.8,'India':-1.2,'Brazil':-2.4}
    for _c in list(out):
        out[_c]['gdp_forecast']       = _IMF_GDP.get(_c)
        out[_c]['current_account_pct'] = _WB_CA.get(_c)
    return out


# ─── WAVE PSXD (v1.247.0): Pakistani material-event families ─────────────────
# The US side reads 8-K item codes straight from SEC EDGAR. Pakistan has NO equivalent
# machine-readable feed: BOTH official paths (psx.com.pk/announcement/corporate-announcements
# and dps.psx.com.pk/announcements/companies) render their rows via JavaScript/POST and return
# ZERO rows in raw HTML -- verified 2026-07-15 by fetching both pages directly, NOT assumed from
# a search snippet (the snippet showed rows the page does not serve). The broker path was checked
# too: scstrade.com/MarketStatistics/MS_Announcements.aspx is an ASP.NET postback -- its ticker
# strip is server-rendered but its announcements table is empty in raw HTML. Sarmaaya publishes
# exactly the insider-transaction list we want, but it is a PSX-*authorized redistributor* and its
# robots.txt DISALLOWS automated access, so it is off-limits by rule. None of the three mature PSX
# libraries (psx-data-reader / psxdata / PSX-MCP-Server) scrape announcements at all.
# => The structured feed is LICENSED, not merely awkward. See D-PSXD-LICENSED.
# What IS legitimately available and already proven live in this pipeline: the Pakistani financial
# press. So event detection reads the SAME headlines the TCE news layer already pulls per PSX name
# every run (Google-News-PK + Business Recorder, both live-confirmed by [news diag]).
# HONEST SCOPE, stated on the tab: this is HEADLINE-LEVEL event detection, not a filing parse.
# It catches material events well; it does NOT carry insider share counts or buy/sell direction --
# director dealings are routine and rarely make the news. That half needs a licensed feed.
_PSXD_FAMILIES = [
    ('adverse',    'Trouble reported', (
        'suspend', 'suspension', 'default', 'penalt', 'investigat', 'probe', 'resign',
        'auditor', 'delist', 'winding up', 'closure', 'shut down', 'shuts', 'halt',
        'fraud', 'inquiry', 'show cause', 'non-compliance', 'writ', 'litigation')),
    ('results',    'Earnings news', (
        'profit', 'loss', 'earnings', 'eps', 'result', 'revenue', 'turnaround',
        'bottom line', 'margin')),
    ('expansion',  'Growth / new capacity', (
        'discover', 'production', 'explorat', 'award', 'expansion', 'expand', 'commission',
        'new plant', 'capacity', 'contract', 'agreement', 'mou', 'licence', 'license')),
    ('corporate',  'Ownership / deal news', (
        'acquisit', 'acquire', 'merger', 'merge', 'bid ', 'stake', 'divest', 'disposal',
        'subsidiar', 'joint venture', 'takeover', 'buyout', 'demerger')),
    ('payout',     'Cash returned to holders', (
        'dividend', 'bonus', 'right shares', 'payout', 'buyback', 'buy-back')),
    ('insider',    'Insider / sponsor dealing', (
        # PSX Rulebook 5.6.1(d) is the clause every director/CEO/executive dealing is filed under --
        # matching the CLAUSE is far more reliable than guessing the verb. The audit caught this:
        # "director DISCLOSES PURCHASE of shares" never matched a rigid 'director purchas'.
        '5.6.1', 'disclosure of interest', 'discloses purchase', 'discloses sale',
        'director disclos', 'substantial shareholder', 'sponsor', 'director purchas',
        'director sold', 'director buy', 'directors dealing', 'insider')),
    ('regulatory',  'Regulator / tariff decision', (
        # Pakistan-specific and MATERIAL: NEPRA/OGRA tariff determinations move utilities and E&Ps
        # more than most earnings prints. The audit caught this family missing entirely.
        'nepra', 'ogra', 'secp', 'tariff', 'determination', 'regulator', 'ruling',
        'circular debt', 'gas price', 'levy', 'subsid')),
]


# v1.248.0 SOURCE CORRECTION. The v1.247.0 live run PROVED the TCE news read cannot carry events:
# 376 "events" across 38 names, of which 94%% never named the company at all -- the identical headline
# "asia markets choppy as threat of trump hormuz levy spooks" was attached to TPLP, MACFL, PRL AND
# CNERGY, and every bank (UBL/MEBL/NBP/FABL/BAFL/BIPL/BOP) got flagged TROUBLE off a Hormuz shipping
# story. Root cause: Google-News-PK queried by a SHORT PSX ticker (TPL/GAL/PSX) returns generic
# Pakistani business news. That is fine for its real job -- counting BREADTH for s1_news -- but it is
# not company news. My v1.247.0 audit missed this because the fixture was real Mettis headlines rather
# than the ACTUAL pipeline output (the fixture rule, violated in spirit; same class as the whale mocks).
# CORRECTION: read Mettis Link News, where the PUBLISHER tags every story "(PSX: TICKER)" -- attribution
# comes from the source, not from my guessing. Verified 2026-07-15 by fetching mettisglobal.news/Equity
# directly: server-rendered, real article cards, every one carrying (PSX: TICKER) in its summary.
_METTIS_PAGES = ('https://mettisglobal.news/Equity', 'https://mettisglobal.news/latest')
_METTIS_TICKER_RE = re.compile(r'\(\s*PSX\s*:\s*([A-Z0-9]{2,12})\s*\)')
# Mettis also publishes SEO/data pages ("Price to Earnings forward of X", "Enterprise Value to Revenue
# forward of X") which name a company but report NO event -- the v1.247.0 gate test surfaced these too.
_METTIS_JUNK = ('price to earnings forward', 'enterprise value to revenue forward',
                'price to book forward', 'price to sales forward', 'forward of ')


def fetch_mettis_psx_events(pages=None, _html=None):
    """v1.248.0 WAVE PSXD-A. Read Mettis Link News (Pakistani financial wire) and return
    {TICKER: [headline, ...]} for every story the PUBLISHER tagged '(PSX: TICKER)'.
    STRUCTURE-AGNOSTIC by design: it never depends on CSS classes -- it walks anchors, reads their
    text, and keys off the (PSX: TICKER) token that appears in the story summary itself. So a Mettis
    redesign cannot silently break it. 1-2 GETs per run total (NOT per name). _html = injected page
    text, for auditing against real captured content. Never raises."""
    out = {}
    pages = pages or _METTIS_PAGES
    htmls = []
    if _html is not None:
        htmls = [_html] if isinstance(_html, str) else list(_html)
    else:
        for u in pages:
            _t = time.time()
            try:
                r = requests.get(u, headers={'User-Agent': UA}, timeout=12)
                _ms = round((time.time() - _t) * 1000)
                if r.status_code == 200 and r.text:
                    htmls.append(r.text)
                    # v1.249.0 DIAG (the [justETF diag] precedent that nailed that parse in ONE run):
                    # the first live run returned only 2 tagged names though the page shows ~10, so we
                    # cannot tell a PARSE miss from a COVERAGE gap without seeing the real numbers.
                    log(f'  [mettis diag] {u} -> HTTP 200, {len(r.text)} bytes, {_ms}ms, '
                        f"anchors={r.text.count('<a ')}, '(PSX:' occurrences={r.text.upper().count('(PSX:')}")
                else:
                    log(f'  [mettis diag] {u} -> HTTP {r.status_code} ({_ms}ms)')
            except Exception as ex:
                log(f'  [mettis diag] {u} -> {type(ex).__name__}: {ex} ({round((time.time()-_t)*1000)}ms)')
    # v1.248.0 SCOPE FIX: bs4 is imported INSIDE another function in this file, so a module-level
    # reference to BeautifulSoup raises NameError -- and the bare except below swallowed it into an
    # empty result. That is the EXACT class of bug as the index-side `esc` incident (a name borrowed
    # from another function's scope, hidden by a catch). Import locally, and make the catch LOUD.
    from bs4 import BeautifulSoup as _BS
    for html in htmls:
        try:
            soup = _BS(html, 'html.parser')
            nodes = soup.find_all('a') or []
        except Exception as _pe:
            log(f'  [PSX events] mettis parse failed: {type(_pe).__name__}: {_pe}')
            nodes = []
        for a in nodes:
            try:
                txt = a.get_text(' ', strip=True)
            except Exception:
                continue
            if not txt or 'PSX' not in txt.upper():
                continue
            m = _METTIS_TICKER_RE.search(txt)
            if not m:
                continue
            tk = m.group(1).upper()
            # headline = the card's own heading if present, else the text before the (PSX: ..) mention
            head = ''
            try:
                hn = a.find(['h1', 'h2', 'h3', 'h4', 'h5'])
                if hn:
                    head = hn.get_text(' ', strip=True)
            except Exception:
                pass
            if not head:
                head = txt[:m.start()].strip() or txt
            head = ' '.join(head.split())[:160].lower()
            if not head or any(j in head for j in _METTIS_JUNK):
                continue
            out.setdefault(tk, [])
            if head not in out[tk]:
                out[tk].append(head)
    log(f"  [mettis diag] parsed {sum(len(v) for v in out.values())} tagged stor(ies) across "
        f"{len(out)} ticker(s): {', '.join(sorted(out)[:12]) or '(none)'}")
    return out


def classify_psx_headline(title):
    """PURE. Map ONE lowercased headline to its event families. Returns [(key,label),...] --
    a headline can belong to several (e.g. a profit warning is results + adverse). Order of
    _PSXD_FAMILIES puts 'adverse' first so trouble is never buried under a neutral family."""
    t = (title or '').lower()
    out = []
    for key, label, kws in _PSXD_FAMILIES:
        if any(k in t for k in kws):
            out.append((key, label))
    return out


def build_psx_events(data, news_titles=None):
    """WAVE PSXD (v1.247.0) -- the PSX counterpart to data['mat_events'], built from the Pakistani
    press headlines the TCE news read ALREADY fetched this run (_PSX_NEWS_TITLES). ZERO new fetches.
    Emits data['psx_events'] in the SAME shape the US mat_events consumers read:
      {as_of, source, note, scope, n_names, n_events, by_ticker:{TK:{events[],has_adverse,n}}}
    DATA-only, wrapped by its caller, carries last-good. No screening/TCE/IM3/scoring touched."""
    # v1.248.0: source is Mettis (publisher-tagged '(PSX: TICKER)'), NOT the TCE news read --
    # see the v1.248.0 note above fetch_mettis_psx_events for why that source was retired here.
    titles = news_titles if news_titles is not None else _stage('psx_events.mettis_fetch', fetch_mettis_psx_events)
    by = {}
    n_ev = 0
    for tk, heads in (titles or {}).items():
        evs, adverse = [], False
        for h in (heads or []):
            fams = classify_psx_headline(h)
            if not fams:
                continue
            for key, label in fams:
                if key == 'adverse':
                    adverse = True
                evs.append({'family': key, 'label': label, 'headline': h})
        if evs:
            # de-dup identical family+headline pairs, cap for payload sanity
            seen, keep = set(), []
            for e in evs:
                sig = (e['family'], e['headline'])
                if sig in seen:
                    continue
                seen.add(sig); keep.append(e)
            by[str(tk).upper()] = {'events': keep[:12], 'has_adverse': adverse, 'n': len(keep)}
            n_ev += len(keep)
    data['psx_events'] = {
        'as_of': dt.date.today().isoformat(),
        'source': 'Mettis Link News (Pakistani financial wire) -- only stories the publisher itself '
                  'tagged with the company\'s PSX ticker, so attribution comes from the source.',
        'scope': 'Headline-level event detection on Pakistani financial-wire stories that name the company.',
        'note': 'Pakistan has no machine-readable filings feed like the US SEC: the exchange publishes '
                'company announcements only through pages that build themselves in the browser, and the '
                'one service that does publish a clean insider-dealing list is a licensed redistributor '
                'that does not permit automated access. So this reads the Pakistani financial press '
                'instead. It catches company events well. It does NOT capture how many shares a director '
                'bought or sold -- that needs a paid data feed.',
        'n_names': len(by), 'n_events': n_ev, 'by_ticker': by,
    }
    if by:
        _adv = [t for t, v in by.items() if v['has_adverse']]
        log(f"  [PSX events] {n_ev} event(s) across {len(by)} name(s)"
            + (f"; trouble flagged on {', '.join(sorted(_adv)[:6])}" if _adv else '; none adverse'))
    else:
        log('  [PSX events] no classifiable headlines this run (news read returned nothing for PSX names)')
    return data['psx_events']


def build_econ_clock(us_macros, psx_macros):
    """ECONOMY CLOCK (v1.244.0, owner: "I want a clock in graphics not a bar ... in both
    Pakistan dashboard and US dashboard"). The classic investment-cycle clock: a 2x2 of
    GROWTH x INFLATION, whose four quadrants the cycle rotates through CLOCKWISE:

          12
       DIS |  GOLD          12-3  GOLDILOCKS  growth up   / inflation low   -> shares
      -----+-----           3-6   REFLATION   growth up   / inflation high  -> energy, materials
       STAG|  REFL          6-9   STAGFLATION growth down / inflation high  -> cash, defensives
           6                9-12  DISINFLATION growth down/ inflation low   -> bonds

    US axes REUSE the dashboard's existing _m1_regime 2x2 exactly (growth = 2s10s yield-curve
    slope, inflation = core PCE vs 2.5) so the clock and the M1 sector engine can never disagree.
    PSX axes are the honest best available: Pakistan has NO live GDP/LSM feed in this pipeline,
    so growth = the KSE-100's own 3-month trend (the market pricing growth) and inflation = CPI
    vs the 7% top of SBP's target band. That basis is STATED on the tab, never implied as GDP.
    PURE/DISPLAY-only: reads already-fetched macros, touches no screening/TCE/IM3/scoring."""

    def _quad(growth_up, infl_high):
        if growth_up and not infl_high: return 'GOLDILOCKS'
        if growth_up and infl_high:     return 'REFLATION'
        if (not growth_up) and infl_high: return 'STAGFLATION'
        return 'DISINFLATION'

    # hand angle: degrees clockwise from 12 o'clock, kept inside its own quadrant and
    # tilted by how close the weaker axis sits to its flip threshold.
    def _angle(quad, g_prox, i_prox):
        g_prox = max(0.0, min(1.0, g_prox)); i_prox = max(0.0, min(1.0, i_prox))
        if quad == 'GOLDILOCKS':   return 15 + 60 * i_prox          # rising inflation -> toward REFLATION
        if quad == 'REFLATION':    return 105 + 60 * (1 - g_prox)   # fading growth   -> toward STAGFLATION
        if quad == 'STAGFLATION':  return 195 + 60 * (1 - i_prox)   # cooling inflation -> toward DISINFLATION
        return 285 + 60 * g_prox                                     # DISINFLATION: reviving growth -> GOLDILOCKS

    PLAIN = {
        'GOLDILOCKS':  'Growing with calm prices - the sweet spot',
        'REFLATION':   'Growing, but prices are climbing',
        'STAGFLATION': 'Slowing down while prices stay high - the hard corner',
        'DISINFLATION':'Slowing, but prices are cooling off',
    }
    FAVORS = {
        'GOLDILOCKS':  ['Shares generally', 'Technology', 'Shops & consumer brands'],
        'REFLATION':   ['Energy & oil', 'Raw materials & mining', 'Banks & finance', 'Industry & machinery'],
        'STAGFLATION': ['Cash & short deposits', 'Everyday essentials', 'Energy & oil', 'Gold'],
        'DISINFLATION':['Bonds', 'Utilities', 'Healthcare', 'Everyday essentials'],
    }

    out = {}

    # ---------- US : identical axes to _m1_regime ----------
    try:
        u = us_macros or {}
        slope = u.get('us_2s10s')
        if slope is None and u.get('us_10y') is not None and u.get('us_2y') is not None:
            slope = float(u['us_10y']) - float(u['us_2y'])
        slope = float(slope or 0.0)
        pce = float(u.get('core_pce') or 0.0)
        g_up = slope > 0
        i_hi = pce > 2.5
        q = _quad(g_up, i_hi)
        # proximity to the flip line: curve within +/-1.5pp, inflation within 2.5 +/-1.5pp
        g_prox = min(1.0, abs(slope) / 1.5)
        i_prox = min(1.0, abs(pce - 2.5) / 1.5)
        out['us'] = {
            'quadrant': q, 'quadrant_plain': PLAIN[q],
            'angle': round(_angle(q, g_prox, i_prox), 1),
            'growth':    {'value': round(slope, 2), 'up': g_up,
                          'label': ('Growth holding up' if g_up else 'Growth losing steam'),
                          'basis': 'the gap between 10-year and 2-year government borrowing rates'},
            'inflation': {'value': round(pce, 2), 'high': i_hi,
                          'label': ('Prices rising too fast' if i_hi else 'Prices under control'),
                          'basis': "the Fed's own preferred inflation measure (core PCE) vs its 2.5% line"},
            'favors': FAVORS[q],
            'note': 'Same growth and inflation readings that pick the sectors on the Top-Down tab.',
        }
    except Exception as e:
        log(f"  [Econ clock] US failed: {e}")

    # ---------- PSX : honest best-available axes ----------
    try:
        p = psx_macros or {}
        cpi = p.get('pak_cpi')
        qoq = p.get('kse100_qoq')      # KSE-100 quarter change (index points)
        kse = p.get('kse100')
        if cpi is None:
            raise ValueError('no pak_cpi')
        cpi = float(cpi)
        # growth proxy: the market's own 3-month direction (% of index level)
        gpct = None
        if qoq is not None and kse:
            try: gpct = (float(qoq) / float(kse)) * 100.0
            except Exception: gpct = None
        g_up = (gpct is not None and gpct > 0)
        i_hi = cpi > 7.0               # top of SBP's 5-7% target band
        q = _quad(g_up, i_hi)
        g_prox = min(1.0, abs(gpct) / 8.0) if gpct is not None else 0.5
        i_prox = min(1.0, abs(cpi - 7.0) / 5.0)
        sbp = p.get('sbp_rate')
        rr = (float(sbp) - cpi) if sbp is not None else None
        out['psx'] = {
            'quadrant': q, 'quadrant_plain': PLAIN[q],
            'angle': round(_angle(q, g_prox, i_prox), 1),
            'growth':    {'value': (round(gpct, 2) if gpct is not None else None), 'up': g_up,
                          'label': ('Market climbing over three months' if g_up else 'Market sliding over three months'),
                          'basis': "the KSE-100's own 3-month direction (Pakistan has no live growth figure in this feed)"},
            'inflation': {'value': round(cpi, 2), 'high': i_hi,
                          'label': ('Prices rising too fast' if i_hi else 'Prices under control'),
                          'basis': "Pakistan's consumer inflation against the 7% top of the State Bank's target band"},
            'favors': FAVORS[q],
            'real_rate': (round(rr, 2) if rr is not None else None),
            'note': 'Growth here is read from the market itself, not an official growth figure - stated plainly because no live Pakistani growth feed exists in this pipeline.',
        }
    except Exception as e:
        log(f"  [Econ clock] PSX failed: {e}")

    if out:
        _u = out.get('us', {}).get('quadrant', 'n/a'); _p = out.get('psx', {}).get('quadrant', 'n/a')
        log(f"  [Econ clock] US={_u}  PSX={_p}")
    return out


def compute_us_diffusion(us_macros, walcl_change=None):
    """Phase 0-B / ECONOMY COMPASS: PURE function — reads data['macros']['us'] and scores the
    macro indicators into a diffusion index (supportive=+1, neutral=0, harmful=-1). Now ALSO
    emits an ITEMIZED per-indicator contribution list ('components') so the reader can see how
    EVERY event adds or subtracts, an INFLATION x QE/QT policy-trajectory read ('policy'), and a
    plain-language 'heading' (where the economy is pointing). DATA-only, PURE, never touches
    screening / scoring / TCE. walcl_change (Fed balance-sheet weekly %chg) is optional QE/QT input."""
    if not us_macros or not isinstance(us_macros, dict):
        return {}
    def _v(k):
        return us_macros.get(k)

    comp = []
    def _add(name, lens, value, effect, note):
        # effect: +1 supportive / 0 neutral / -1 harmful; value is the raw reading (may be None-skipped by caller)
        comp.append({'indicator': name, 'lens': lens, 'value': value, 'effect': effect, 'note': note})

    # 1. Fed rate: <=4.0 supportive (accommodative), >5.5 harmful (restrictive)
    fed = _v('fed_rate')
    if fed is not None:
        e = 1 if fed <= 4.0 else (-1 if fed > 5.5 else 0)
        _add('Fed funds rate', 'Monetary', fed, e,
             'Accommodative (cut-friendly)' if e>0 else ('Restrictive (brakes on)' if e<0 else 'Moderately restrictive'))

    # 2. 10y yield: <4.5 supportive, >5.5 harmful
    y10 = _v('us_10y')
    if y10 is not None:
        e = 1 if y10 < 4.5 else (-1 if y10 > 5.5 else 0)
        _add('10-year Treasury yield', 'Monetary', y10, e,
             'Low borrowing cost — supports risk assets' if e>0 else ('High yields pressure valuations' if e<0 else 'Mid-range'))

    # 3. Yield curve (2s10s): positive = supportive (not inverted)
    yc = _v('yield_curve')
    if yc is None:
        us2 = _v('us_2y'); us10 = _v('us_10y')
        yc = (us10 - us2) if (us2 is not None and us10 is not None) else None
    if yc is not None:
        e = 1 if yc > 0 else (-1 if yc < -0.5 else 0)
        _add('Yield curve (2s10s)', 'Economy', round(yc,2), e,
             'Positive/normal — no recession flag' if e>0 else ('Deeply inverted — recession warning' if e<0 else 'Flat'))

    # 4. Core PCE: <2.5 supportive, >3.5 harmful
    pce = _v('core_pce')
    if pce is not None:
        e = 1 if pce < 2.5 else (-1 if pce > 3.5 else 0)
        _add('Core PCE (Fed gauge)', 'Inflation', pce, e,
             'At/below 2% target — cut room' if e>0 else ('Hot core — blocks cuts' if e<0 else 'Above target'))

    # 5. CPI YoY: <3 supportive, >5 harmful
    cpi = _v('cpi_yoy')
    if cpi is not None:
        e = 1 if cpi < 3 else (-1 if cpi > 5 else 0)
        _add('CPI (consumer prices)', 'Inflation', cpi, e,
             'Near target' if e>0 else ('Very hot' if e<0 else 'Above target — Fed cautious'))

    # 5b. PPI YoY: producer prices LEAD consumer prices — <3 supportive, >5 harmful (owner: track PPI + effect)
    ppi = _v('ppi_yoy')
    if ppi is not None:
        e = 1 if ppi < 3 else (-1 if ppi > 5 else 0)
        gap = (' — running ABOVE CPI (pipeline cost pressure feeding forward)'
               if (cpi is not None and ppi > cpi + 0.5) else '')
        _add('PPI (producer prices, leads CPI)', 'Inflation', ppi, e,
             ('Producer costs contained' if e>0 else ('Hot producer inflation' if e<0 else 'Producer costs elevated'))+gap)

    # 6. Unemployment: <4.5 supportive (low), >6 harmful (high)
    unemp = _v('unemployment')
    if unemp is not None:
        e = 1 if unemp < 4.5 else (-1 if unemp > 6 else 0)
        _add('Unemployment', 'Economy', unemp, e,
             'Tight labour — solid demand' if e>0 else ('High/rising joblessness' if e<0 else 'Softening labour'))

    # 7. UMCSI consumer sentiment: >80 supportive, <60 harmful
    umcsi = _v('umcsi')
    if umcsi is not None:
        e = 1 if umcsi > 80 else (-1 if umcsi < 60 else 0)
        _add('Consumer sentiment (UMich)', 'Economy', umcsi, e,
             'Confident consumer' if e>0 else ('Depressed sentiment' if e<0 else 'Middling confidence'))

    # 8. Building permits MoM trend: positive supportive
    permits = _v('permits')
    permits_mom = _v('permits_mom')
    if permits_mom is not None:
        e = 1 if permits_mom > 0 else (-1 if permits_mom < -5 else 0)
        _add('Building permits (housing)', 'Economy', permits, e,
             'Housing pipeline growing' if e>0 else ('Housing pulling back' if e<0 else 'Housing flat'))
    elif permits is not None:
        _add('Building permits (housing)', 'Economy', permits, 0, 'No trend data yet')

    # 9. Industrial production MoM: positive supportive
    ip_mom = _v('industrial_prod_mom')
    if ip_mom is not None:
        e = 1 if ip_mom > 0 else (-1 if ip_mom < -1 else 0)
        _add('Industrial production', 'Economy', _v('industrial_prod'), e,
             'Factories expanding' if e>0 else ('Factory output falling' if e<0 else 'Factory output flat'))

    # 10. GDP growth: >2 supportive, <0 harmful (recession)
    gdp = _v('gdp_growth')
    if gdp is not None:
        e = 1 if gdp > 2 else (-1 if gdp < 0 else 0)
        _add('GDP growth', 'Economy', gdp, e,
             'Healthy growth' if e>0 else ('Contracting economy' if e<0 else 'Sub-trend growth'))

    # 11. HY spread: <400bp supportive (risk-on), >700 harmful (stress)
    hy = _v('hy_spread')
    if hy is not None:
        e = 1 if hy < 400 else (-1 if hy > 700 else 0)
        _add('High-yield credit spread', 'Markets', hy, e,
             'Calm credit — risk-on' if e>0 else ('Credit stress' if e<0 else 'Neutral credit'))

    # 12. Mfg employment MoM: positive supportive
    mfg = _v('mfg_emp')
    mfg_mom = _v('mfg_emp_mom')
    if mfg_mom is not None:
        e = 1 if mfg_mom > 0 else (-1 if mfg_mom < -20 else 0)
        _add('Manufacturing jobs', 'Economy', mfg, e,
             'Factories hiring' if e>0 else ('Factory layoffs' if e<0 else 'Flat factory payrolls'))

    # 13. WTI oil: <80 supportive (not stagflationary), >100 harmful
    wti = _v('wti')
    if wti is not None:
        e = 1 if wti < 80 else (-1 if wti > 100 else 0)
        _add('Oil (WTI)', 'Inflation', wti, e,
             'Cheap energy — eases inflation' if e>0 else ('Expensive oil — stagflation risk' if e<0 else 'Moderate oil'))

    # 14. Recession probability
    rec = _v('recession_prob')
    if rec is not None:
        e = 1 if rec < 20 else (-1 if rec > 50 else 0)
        _add('Recession probability', 'Economy', rec, e,
             'Low recession odds' if e>0 else ('Elevated recession odds' if e<0 else 'Moderate recession odds'))

    # 15. Brent-WTI spread: <$5 supportive (normal), >$10 harmful (supply stress)
    brent = _v('brent') or _v('arab_light')
    if brent is not None and wti is not None:
        bw = brent - wti
        e = 1 if bw < 5 else (-1 if bw > 10 else 0)
        _add('Brent-WTI spread', 'Markets', round(bw,2), e,
             'Normal oil market' if e>0 else ('Oil supply stress' if e<0 else 'Slightly wide'))

    scores = [c['effect'] for c in comp]
    if not scores:
        return {}
    # v1.253.0 SILENT-DROPOUT FIX. run-651: FRED failed 4 series, so industrial_prod's MoM trend
    # could not be computed and the indicator VANISHED from the composite -- total went 15 -> 14
    # and nothing said so. An "every event adds or subtracts" engine must never lose a vote in
    # silence: name what is missing so the reader knows the score is on fewer inputs today.
    # All SIXTEEN indicators this function can score. My first draft of this list omitted
    # 'Brent-WTI spread' and the arithmetic did not reconcile -- so the list is now GUARDED below:
    # if an indicator is ever added above and not listed here, the run says so loudly instead of
    # quietly mis-reporting the denominator.
    _EXPECTED = ['Fed funds rate', '10-year Treasury yield', 'Yield curve (2s10s)',
                 'Core PCE (Fed gauge)', 'CPI (consumer prices)', 'PPI (producer prices, leads CPI)',
                 'Unemployment', 'Consumer sentiment (UMich)', 'Building permits (housing)',
                 'Industrial production', 'GDP growth', 'High-yield credit spread',
                 'Manufacturing jobs', 'Oil (WTI)', 'Recession probability', 'Brent-WTI spread']
    _have = {c['indicator'] for c in comp}
    _missing = [n for n in _EXPECTED if n not in _have]
    _drift = [n for n in _have if n not in _EXPECTED]
    if _drift:
        log(f'  [US Diffusion] ** _EXPECTED list is STALE -- unlisted indicator(s): {_drift} **')

    supportive = sum(1 for s in scores if s > 0)
    harmful    = sum(1 for s in scores if s < 0)
    neutral    = sum(1 for s in scores if s == 0)
    net        = supportive - harmful
    total      = len(scores)
    regime     = 'Expansion' if net > 0 else ('Contraction' if net < 0 else 'Neutral')
    accel      = supportive > (total * 0.6)

    # --- INFLATION x QE/QT policy-trajectory read (owner: connect the inflation signal to QE/QT so the
    #     reader knows where the economy is heading). Uses the inflation trio + their MoM momentum + the
    #     Fed rate stance + the Fed balance-sheet direction (walcl_change). ---
    def _mom(k): 
        m = _v(k); return m if isinstance(m,(int,float)) else None
    infl_hot   = any(x is not None and x > t for x,t in ((cpi,3),(pce,2.5),(ppi,3)))
    infl_moms  = [m for m in (_mom('cpi_yoy_mom'), _mom('core_pce_mom'), _mom('ppi_yoy_mom')) if m is not None]
    infl_accel = bool(infl_moms) and (sum(infl_moms) > 0.1)
    pipeline   = (ppi is not None and cpi is not None and ppi > cpi + 0.5)
    # QE/QT stance from the balance sheet
    if walcl_change is None:
        qt_state = 'unknown'
    elif walcl_change > 0.2:
        qt_state = 'QE-leaning (balance sheet expanding)'
    elif walcl_change < -0.2:
        qt_state = 'QT (balance sheet shrinking)'
    else:
        qt_state = 'QT paused (balance sheet flat)'
    # rate stance
    if fed is None:            rate_state = 'unknown'
    elif fed > 5.0:            rate_state = 'restrictive'
    elif fed < 3.5:            rate_state = 'accommodative'
    else:                      rate_state = 'moderately restrictive'
    infl_state = ('re-accelerating' if (infl_hot and infl_accel) else
                  'hot but stabilising' if infl_hot else
                  'cooling' if (infl_moms and sum(infl_moms) < 0) else 'contained')
    # trajectory verdict
    if infl_hot and infl_accel:
        trajectory = 'Hawkish tilt — hot, re-accelerating inflation argues for cuts on hold / higher-for-longer'
        pol_dir = 'hawkish'
    elif (infl_state in ('cooling','contained')) and rate_state in ('restrictive','moderately restrictive'):
        trajectory = 'Easing pipeline — cooling inflation lets the Fed cut; policy turning supportive'
        pol_dir = 'easing'
    else:
        trajectory = 'On hold — mixed inflation keeps the Fed patient'
        pol_dir = 'neutral'
    policy = {
        'inflation_state': infl_state, 'qt_state': qt_state, 'rate_state': rate_state,
        'pipeline_pressure': pipeline, 'direction': pol_dir, 'trajectory': trajectory,
        'cpi': cpi, 'core_pce': pce, 'ppi': ppi,
        'ppi_gt_cpi': (round(ppi - cpi, 2) if (ppi is not None and cpi is not None) else None),
        'walcl_change': walcl_change,
        'note': ('Producer prices (PPI %s) are running above consumer prices (CPI %s) — cost pressure still feeding forward.'
                 % (ppi, cpi)) if pipeline else 'Producer and consumer inflation broadly aligned.',
    }
    # plain-language heading (where the economy is pointing)
    _bd = 'broadening' if accel else 'narrow'
    heading = ('%s — %d of %d indicators supportive (%s breadth); regime %s. Inflation %s; policy %s.'
               % (('Expanding' if net>0 else 'Contracting' if net<0 else 'Balanced'),
                  supportive, total, _bd, regime, infl_state, pol_dir))

    result = {
        'net_score':   net,
        'net':         net,
        'supportive':  supportive,
        'neutral':     neutral,
        'harmful':     harmful,
        'deteriorating': harmful,
        'total':       total,
        'regime':      regime,
        'phase':       regime,
        'direction':   'Accelerating' if accel else 'Decelerating',
        'acceleration': accel,
        'components':  comp,      # NEW: itemized per-indicator +/- contributions (every event adds/subtracts)
        'expected_total': len(_EXPECTED),   # v1.253.0: what the composite scores on a healthy day
        'missing':     _missing,            # v1.253.0: indicators that could not be scored TODAY
        'policy':      policy,    # NEW: inflation x QE/QT trajectory read
        'heading':     heading,   # NEW: plain-language "where the economy is heading"
        'as_of':       us_macros.get('last_updated') or us_macros.get('_fetched_utc', ''),
    }
    log(f"  [US Diffusion] net={net:+d}  {supportive}/{total} supportive  regime={regime}  policy={pol_dir}  infl={infl_state}"
        + (f"  ** {len(_missing)} INDICATOR(S) UNAVAILABLE: {', '.join(_missing)} **" if _missing else ''))
    return result

def compute_global_sector_theme(country_rs):
    """Phase 2: World ETF Engine — re-points the booming-sector concept at GLOBAL markets.
    Reuses country_rs (already fetched, no new network call). Buckets the 13 countries into
    4 regional/thematic groups and scores each by composite momentum + 200-DMA breadth:
      Asia-Tech:       Japan, South Korea, Taiwan        (semiconductor/tech supply chain)
      Developed-West:  USA, UK, Germany, Switzerland, Canada, Australia
      Commodity-Bloc:  Brazil, Australia, Canada          (resource exporters; overlaps West)
      Emerging:        China, India, Brazil
    Score = mean(6M USD return) * 0.6 + (pct above 200-DMA) * 0.4, on a 0-100 scale.
    Returns a list of dicts sorted by score desc: theme, score, band, countries, top_country,
    avg_ret_6m, pct_above_200dma. PURE function — no network call, reuses fetched data.
    DATA-only; never touches screening / scoring / TCE / the frozen ledger."""
    _THEMES = {
        'Asia-Tech':      ['Japan', 'South Korea', 'Taiwan'],
        'Developed-West': ['USA', 'UK', 'Germany', 'Switzerland', 'Canada', 'Australia'],
        'Commodity-Bloc': ['Brazil', 'Australia', 'Canada'],
        'Emerging':       ['China', 'India', 'Brazil'],
    }
    if not country_rs:
        return []
    by_country = {r.get('country'): r for r in country_rs if r.get('country')}
    results = []
    for theme, countries in _THEMES.items():
        rows = [by_country[c] for c in countries if c in by_country]
        if not rows:
            continue
        rets = [r.get('ret_6m') for r in rows if r.get('ret_6m') is not None]
        above = [r.get('above_200dma') for r in rows if r.get('above_200dma') is not None]
        if not rets:
            continue
        avg_ret = sum(rets) / len(rets)
        pct_above = (sum(1 for a in above if a) / len(above) * 100) if above else 50.0
        # Normalise: avg_ret of +15% -> ~100 on the momentum leg; clamp 0-100
        mom_score = max(0, min(100, 50 + avg_ret * 2.5))
        score = round(mom_score * 0.6 + pct_above * 0.4, 1)
        band = ('Booming'  if score >= 75 else
                'Favoured' if score >= 60 else
                'Neutral'  if score >= 40 else
                'Lagging'  if score >= 25 else 'Avoid')
        top_country = max(rows, key=lambda r: r.get('ret_6m') or -999)
        results.append({
            'theme':            theme,
            'score':            score,
            'band':             band,
            'countries':        countries,
            'top_country':      top_country.get('country'),
            'top_country_ret6m': top_country.get('ret_6m'),
            'avg_ret_6m':       round(avg_ret, 1),
            'pct_above_200dma': round(pct_above, 1),
        })
    results.sort(key=lambda r: r['score'], reverse=True)
    log(f"  [Global Theme] {len(results)} themes scored: " +
        ' | '.join(f"{r['theme']}={r['score']}({r['band']})" for r in results))
    return results


def resolve_etf_for_signal(category_key, fallback_keys=None):
    """Phase 3: World ETF Engine — resolve a country/sector signal to a buyable UCITS ETF.
    category_key: an _ETF_CATALOG key (e.g. 'Equity South Korea', 'Equity Technology').
    fallback_keys: optional list of broader categories to try if category_key has no match
    (e.g. ['Equity Asia Pacific', 'Equity World']).
    Returns the largest-by-size qualifying fund dict {name,ter,ytd,size_m_eur,isin,dist} or
    None if no category matches. PURE function — reads only the embedded _ETF_CATALOG.
    DATA-only; never touches screening / scoring / TCE / the frozen ledger."""
    funds = _ETF_CATALOG.get(category_key)
    if funds:
        return dict(funds[0])
    for fb in (fallback_keys or []):
        funds = _ETF_CATALOG.get(fb)
        if funds:
            r = dict(funds[0])
            r['_fallback_from'] = category_key
            r['_resolved_via'] = fb
            return r
    return None


