# ── World ETF Engine v2 (v1.215.0) — live discovery + bottom-up sectors + leading-indicator gate ──
# Answers the owner's automation question end to end: (1) self-discover the leading UCITS ETFs LIVE so
# the quarterly ETF_Universe.xlsx upload is no longer required; (2) compute booming sectors BOTTOM-UP from
# the winners' own sectors -- the manual "rank stocks -> which ETFs hold them -> sectors" method, done
# directly now that every foundation stock carries its sector live (the ETF-holdings step was only a proxy
# to reach sectors); (3) GATE return-discovered themes on the leading indicators (OECD LEI + US Diffusion
# + dollar direction) so the engine CONFIRMS rather than chases. Request shape proven by the v1.214.4 probe.

# Leverage/inverse/ETP junk that dominates a raw YTD sort (probe proof: top uk row was a copper 3x short).
_ETF_LEV_RE = re.compile(r'(\b\d+(?:\.\d+)?x\b|[-+]\d+x\b|leverag|daily (?:long|short)|\bshort\b|'
                         r'\bbear\b|\bbull\b|inverse|geared|\betp\b|\betn\b)', re.I)


def _etf_is_genuine_ucits(name, typespecs=None, expense=None):
    """True only for a plain, LONG-ONLY UCITS fund. The v1.214.4 probe proved a raw Perf.YTD sort is topped
    by 3x/-5x/short ETPs, so genuine-fund isolation is mandatory: require the 'UCITS' marker, reject any
    leverage/inverse/ETP name token, and reject the high TER (~1.5-1.9%) that leveraged wrappers carry."""
    nm = (name or '')
    if 'UCITS' not in nm.upper():
        return False
    if _ETF_LEV_RE.search(nm):
        return False
    if expense is not None and expense > 1.0:
        return False
    return True


_ETF_CAT_KEYS = [
    ('Semiconductors', ('semiconduct', 'chip')), ('Technology', ('technology', 'software', ' tech ', 'ai ', 'artificial intelligence', 'robotic', 'digital')),
    ('Crypto', ('bitcoin', 'ethereum', 'crypto', 'blockchain', 'digital asset')), ('Gold & Miners', ('gold', 'silver', 'precious', 'miner')),
    ('Defence', ('defence', 'defense', 'aerospace', 'military')), ('Energy', ('energy', 'oil', 'uranium', 'nuclear', 'clean power')),
    ('Korea', ('korea',)), ('Taiwan', ('taiwan',)), ('India', ('india',)), ('China', ('china', 'hong kong')),
    ('Emerging Markets', ('emerging', 'frontier')), ('Healthcare', ('health', 'biotech', 'pharma', 'medical')),
    ('Financials', ('financ', 'bank', 'insurance')), ('Europe', ('europe', 'euro ', 'stoxx', 'dax', 'ftse')),
]


def _etf_category(name):
    """Light keyword classifier so live-discovered funds group cleanly in the existing Momentum-Watch render."""
    nm = (name or '').lower()
    for label, keys in _ETF_CAT_KEYS:
        if any(k in nm for k in keys):
            return label
    return 'Other Themes'


JUSTETF_HOLDINGS_PROBE = False   # probe done (justETF profile reachable); fetch_justetf_holdings now parses it


_JUSTETF_DIAG = {'n': 3}   # diag OFF (parsing confirmed on the 20:06 run: 23/25 filled). Set 'n':0 to re-enable.
_JUSTETF_ANCHOR = 'etf-holdings_top-holdings_container'   # confirmed on the 19:52 run: the div wrapping the Top-10 list


def fetch_justetf_holdings(isin, top=6, with_weights=False):
    """Top holdings for ANY UCITS fund by ISIN from justETF's public profile page. justETF aggregates every
    issuer's published holdings (VanEck / HSBC / Amundi / Xtrackers / Franklin / Global X / KraneShares).
    Returns 'Name1, Name2, ...' or None. Anchors on the confirmed holdings CONTAINER (data-testid), not the
    first lowercase 'holding' in the page nav (that was the v1.215.6 miss), so it reads the real constituent
    rows. Swap/synthetic ETFs have no container -> None. First 3 calls log a [justETF diag] line."""
    diag = _JUSTETF_DIAG['n'] < 3
    try:
        url = 'https://www.justetf.com/en/etf-profile.html?isin=%s' % isin
        r = requests.get(url, headers={'User-Agent': UA, 'Accept-Language': 'en'}, timeout=20)
        html = r.text or ''
        i = html.find(_JUSTETF_ANCHOR)
        if diag:
            _JUSTETF_DIAG['n'] += 1
            ctx = re.sub(r'\s+', ' ', html[i:i + 1700]) if i >= 0 else '(container not found)'
            log(f'    · [justETF diag] {isin} HTTP {r.status_code} {len(html)}B container@{i}: {ctx[:1600]}')
        if r.status_code != 200 or i < 0:
            return None
        block = html[i:i + 6000]                       # the container: header + summary + the 10 rows
        text = re.sub(r'<[^>]+>', '\n', block)
        for a, b in (('&amp;', '&'), ('&#39;', "'"), ('&#x27;', "'"), ('&nbsp;', ' ')):
            text = text.replace(a, b)
        text = re.sub(r'[ \t]+', ' ', text)
        names, seen = [], set()
        _stop = ('weight of top', 'out of', 'top 10', 'holding', 'constituent', 'name', 'weight',
                 'show', 'as of', 'sector', 'countr')
        for m in re.finditer(r'([A-Za-z][A-Za-z0-9&.,\'/\-() ]{2,50}?)\s*\n+\s*(\d{1,2}(?:\.\d{1,2})?)\s*%', text):
            nm = m.group(1).strip(" .,-\n")
            nl = nm.lower()
            if not (2 <= len(nm) <= 50) or any(s in nl for s in _stop) or nm in seen:
                continue
            seen.add(nm)
            # v1.219.0: the regex has ALWAYS captured each holding's weight (group 2) and thrown it
            # away; with_weights=True returns (name, weight_pct) pairs for the look-through, while the
            # default joined-string path stays byte-identical for every existing consumer.
            names.append((nm, float(m.group(2))) if with_weights else nm)
            if len(names) >= top:
                break
        if not names:
            return None
        return names if with_weights else ', '.join(names)
    except Exception as e:
        if diag:
            log(f'    · [justETF diag] {isin} EXC {type(e).__name__}: {str(e)[:60]}')
        return None



# v1.399.0: UCITS -> US-equivalent ETF map. Most index-tracking UCITS funds have a US sibling whose full
# holdings we already have free from EDGAR. Keyword-matched on fund name (and a few exact ISINs).
_UCITS_US_KEYWORDS = [
    (('semiconductor', 'semis', 'soxx', 'nasdaq semi'), 'SOXX'),
    (('semiconductor', 'smh', 'vaneck semi'), 'SMH'),
    (('biotech',), 'XBI'),
    (('nasdaq 100', 'nasdaq-100', 'nasdaq100'), 'QQQ'),
    (('s&p 500', 's&p500', 'sp 500', '500'), 'IVV'),
    (('total us', 'total stock', 'total market'), 'VTI'),
    (('bank',), 'KRE'),
    (('energy',), 'XLE'),
    (('technology', 'info tech', ' it '), 'XLK'),
    (('health', 'healthcare'), 'XLV'),
    (('financ',), 'XLF'),
    (('industrial',), 'XLI'),
    (('real estate', 'reit'), 'XLRE'),
    (('utilit',), 'XLU'),
    (('materials',), 'XLB'),
    (('consumer staple',), 'XLP'),
    (('consumer discretion',), 'XLY'),
    (('aerospace', 'defense', 'defence'), 'PPA'),
    (('software',), 'IGV'),
    (('momentum',), 'MTUM'),
    (('quality',), 'QUAL'),
    (('dividend',), 'SCHD'),
    (('small cap', 'smallcap', 'russell 2000'), 'IWM'),
]
def _ucits_us_equiv(name, sym=''):
    """Return the US ETF ticker whose EDGAR holdings best represent this UCITS fund, or None."""
    _n = (str(name or '') + ' ' + str(sym or '')).lower()
    for _kws, _us in _UCITS_US_KEYWORDS:
        for _k in _kws:
            if _k in _n:
                return _us
    return None


def _attach_discovery_holdings(data, existing=None):
    """Fill the live-discovery funds' 'holdings' using the EXISTING holdings plumbing -- no new source.
    Priority per fund, cheapest first:
      1) REUSE (zero fetch): match the ISIN against the embedded _MOMENTUM_WATCH (the ETF_Universe.xlsx list,
         which already carries baked-in top-holdings per fund) + the hydrogen/emerging/metals watchlists +
         recommendations + look-through funds -- all of which already carry real holdings.
      2) fetch_ishares_holdings(isin) for pinned iShares ISINs (BlackRock authoritative CSV -- the same call
         the emerging-themes list already uses).
      3) fetch_justetf_holdings(isin) -- justETF's public profile aggregates EVERY issuer's published holdings
         by ISIN (VanEck/HSBC/Amundi/Xtrackers/Franklin/Global X), covering the UCITS-only funds that have no
         US sibling and aren't pinned iShares.
    Fetched results are CACHED by ISIN in data['etf_discovery_holdings_cache'] (holdings barely move) and the
    fresh-fetch count is bounded per run so a 60-fund list never becomes 60 requests. Honest '\u2014' remains only
    where every path misses (UCITS-only funds with no US sibling + not in a watchlist/xlsx/iShares-pin)."""
    disc = data.get('etf_live_discovery') or []
    if not disc:
        return
    cache = dict((((existing or {}).get('etf_discovery_holdings_cache')) or {}))

    def _hstr(h):
        if isinstance(h, str):
            h = h.strip()
            # placeholders are NOT holdings (v1.215.10: 'not sourced' from the embedded emerging watch was
            # accepted as a real holdings string and poisoned overlapping discovery funds, e.g. AINF/IART,
            # which then never reached the iShares/justETF fetchers and rendered '\u2014' on the tab)
            return h if (h and h != '\u2014' and h.lower() not in ('not sourced', 'pending', 'n/a', 'na', '-', '--')) else None
        if isinstance(h, list):
            parts = []
            for x in h:
                if isinstance(x, dict):
                    parts.append(str(x.get('ticker') or x.get('name') or '').strip())
                else:
                    parts.append(str(x).strip())
            parts = [p for p in parts if p]
            return ', '.join(parts[:8]) if parts else None
        return None

    # ---- pass 1: reuse map from every list that already carries holdings (zero fetch) ----
    hmap = {}
    for r in _MOMENTUM_WATCH:                       # the ETF_Universe.xlsx list -> baked-in holdings
        iz, hs = r.get('isin'), _hstr(r.get('holdings'))
        if iz and hs:
            hmap.setdefault(iz.upper(), hs)
    for k in ('etf_hydrogen_watch', 'etf_emerging_themes_watch', 'etf_metals_etc_watch'):
        for r in (data.get(k) or []):
            iz, hs = r.get('isin'), _hstr(r.get('holdings') or r.get('top_holdings'))
            if iz and hs:
                hmap.setdefault(iz.upper(), hs)
    for rec in (data.get('etf_recommendations') or []):
        f = rec.get('fund') or {}
        iz, hs = f.get('isin'), _hstr(f.get('holdings') or f.get('top_holdings'))
        if iz and hs:
            hmap.setdefault(iz.upper(), hs)
    for fund in ((data.get('live_lookthrough') or {}).get('funds') or []):
        iz, hs = fund.get('isin'), _hstr(fund.get('holdings'))
        if iz and hs:
            hmap.setdefault(iz.upper(), hs)

    reuse = cached = fetched = 0
    uncovered = []
    for d in disc:
        iz = (d.get('isin') or '').upper()
        hs_h = hmap.get(iz)
        hs = hs_h or _hstr(cache.get(iz))
        if hs:
            d['holdings'] = hs
            if hs_h:
                reuse += 1
            else:
                cached += 1
        else:
            uncovered.append(d)

    # ---- pass 2/3: existing fetchers for the uncovered, bounded + cached ----
    FETCH_BUDGET = 40
    uncovered.sort(key=lambda d: (d.get('ytd') if d.get('ytd') is not None else -1e9), reverse=True)
    still = ish = jet = 0
    still_who = []
    for d in uncovered:
        iz = (d.get('isin') or '').upper()
        if fetched >= FETCH_BUDGET:
            still += 1
            still_who.append(f"{(d.get('name') or '?')[:38]} [{iz}] (budget)")
            continue
        rows = fetch_ishares_holdings(iz)                       # pinned iShares issuer CSV (existing plumbing)
        hs = _hstr(rows) if rows else None
        src = 'ishares'
        if not hs:
            hs = fetch_justetf_holdings(iz)                     # justETF: ANY issuer's published holdings, by ISIN
            src = 'justetf'
        if hs:
            d['holdings'] = hs
            cache[iz] = hs
            fetched += 1
            ish += (1 if src == 'ishares' else 0)
            jet += (1 if src == 'justetf' else 0)
        else:
            still += 1
            still_who.append(f"{(d.get('name') or '?')[:38]} [{iz}]")
    data['etf_discovery_holdings_cache'] = cache
    # v1.399.0 PHASE 3+4: UCITS->US-equivalent bridge. Any fund STILL without holdings but that tracks an
    # index with a US sibling gets that sibling's real EDGAR holdings (top names), labelled honestly.
    _hidx = (data.get('etf_holdings_index') or {}).get('by_stock') or {}
    _cover = ((data.get('moat_cover') or {}).get('by_etf') or {})
    _bridged = 0
    if _cover:
        for _d in disc:
            if _hstr(_d.get('holdings')):
                continue
            _us = _ucits_us_equiv(_d.get('name'), _d.get('sym'))
            if _us and _cover.get(_us):
                _top = _cover[_us][:10]
                if _top:
                    _d['holdings'] = ', '.join(_top)
                    _d['holdings_via'] = _us   # honest provenance for the display
                    _bridged += 1
    if _bridged:
        log('  [discovery holdings] %d UCITS funds bridged to US-equivalent EDGAR holdings' % _bridged)
    # v1.235.0: any discovery fund that got NO holdings from either fetcher is almost always SWAP-BASED
    # (synthetic) -- it holds a total-return swap, not the underlying shares, so no per-stock holdings table
    # is published (justETF/iShares correctly return nothing). Tag an honest reason so the tab shows a
    # meaningful note instead of a bare dash that reads like a fetch bug.
    for _d in disc:
        if not _hstr(_d.get('holdings')):
            _sw = ('swap' in (_d.get('name') or '').lower() or 'synthetic' in (_d.get('name') or '').lower())
            if 'swap' not in (_d.get('note') or '').lower():
                _d['note'] = (((_d.get('note') or '') + ' | ') if _d.get('note') else '') + ('swap/synthetic -- no published per-stock holdings' if _sw else 'holdings not published by issuer (may be swap-based)')
    log(f'  [discovery holdings] {reuse} reuse (xlsx/watchlist) + {cached} cache + {fetched} fetched ({ish} iShares + {jet} justETF) '
        f'/ {len(disc)} discovery funds; {still} still \u2014')
    if still_who:
        log('    \u00b7 still \u2014: ' + '; '.join(still_who))



# =============================================================
# v1.274.0 WAVE ETF-X : VERIFIED explosive-holdings ETF shortlist
# Owner-directed: "all ETFs have their holdings publicly available so it's very
# easy to shortlist UCITS ETFs carrying the Explosive tab's TOP-SCORER stocks.
# Only top scorers with ALL signals (A,B,Q) should be selected, and only those
# ETFs that actually HOLD these stocks -- verified against real published
# holdings, NOT a sector guess."
# =============================================================
_ETFX_STOP = ('inc','corp','corporation','ltd','limited','plc','co','company','sa','nv','ag',
              'holdings','holding','group','the','technologies','technology','international',
              'se','ab','as','asa','oyj','&','and','semiconductor','manufacturing','industries',
              'enterprises','solutions','systems','laboratories','pharmaceuticals')
def _etfx_norm(nm):
    """Normalise a company/holding name to a bare comparable token."""
    t = str(nm or '').lower()
    for w in _ETFX_STOP:
        t = re.sub(r'\b' + re.escape(w) + r'\b', ' ', t)
    return re.sub(r'[^a-z0-9]', '', t)

# Hand-verified name->ticker map for the mega/large caps that recur in UCITS holdings
# (the whale 13F norm->ticker bridge covers the rest at runtime).
_ETFX_MANUAL = {
    'nvidia':'NVDA','apple':'AAPL','microsoft':'MSFT','tsmc':'TSM','taiwansemiconductor':'TSM',
    'asml':'ASML','broadcom':'AVGO','micron':'MU','advancedmicrodevices':'AMD','intel':'INTC',
    'alphabet':'GOOGL','google':'GOOGL','meta':'META','amazon':'AMZN','tesla':'TSLA',
    'marvell':'MRVL','qualcomm':'QCOM','appliedmaterials':'AMAT','lamresearch':'LRCX',
    'klacorporation':'KLAC','kla':'KLAC','arm':'ARM','armholdings':'ARM','supermicro':'SMCI',
    'palantir':'PLTR','netapp':'NTAP','seagate':'STX','seagatetechnology':'STX',
    'westerndigital':'WDC','sandisk':'SNDK','mp':'MP','mpmaterials':'MP','newmont':'NEM',
    'agnicoeagle':'AEM','barrickgold':'GOLD','barrickmining':'GOLD','freeportmcmoran':'FCX',
    'delltechnologies':'DELL','dell':'DELL','eli':'LLY','elililly':'LLY','lilly':'LLY',
    'astera':'ALAB','asteralabs':'ALAB','credo':'CRDO','credotechnology':'CRDO',
    'onto':'ONTO','ontoinnovation':'ONTO','vasta':'VINP','vastaplatform':'VINP',
    'bowhead':'BOW','bowheadspecialty':'BOW','arisinfrastructure':'ASIC','aris':'ASIC',
    'assemblybiosciences':'ASMB','asm':'ASM','asminternational':'ASM',
    'stryker':'SYK','mako':'MAKO','idaho':'IDR','idahostrategic':'IDR',
}
def _etfx_name_bridge(existing):
    """Build norm->ticker from the whale 13F filings (issuers carry real names+tickers) + manual map."""
    br = dict(_ETFX_MANUAL)
    for w in (((existing or {}).get('whale_13f') or {}).get('whales') or []):
        for key in ('top_holdings','new_buys','adds','exits'):
            for h in (w.get(key) or []):
                nm, tk = h.get('norm') or h.get('issuer'), h.get('ticker')
                if nm and tk:
                    br.setdefault(_etfx_norm(nm), tk)
    return br

def build_zacks_radar(data, existing=None):
    """v1.278.0 ZACKS STRONG-BUY RADAR (owner: the 40%%-weighted Zacks signal was never used for
    DISCOVERY -- Citigroup sat at Zacks #1 in data['zacks_ranks'] surfaced nowhere). Reads the
    EXISTING weekly 306-name scrape (zero new fetching, zero runtime): every #1/#2 name is listed
    with its screen status -- prominent when the growth gates filtered it out (value/compounder
    profile or NOT-EXPLOSIVE), counted-only when it already sits on the board with a Z chip.
    ALSO stamps near_miss on explosive records failing exactly ONE of G1/G2 by <3 points with
    the other gate + A1 passing -- so an STRL-class name (rev 18%% vs the 20%% gate, OP +53%%)
    stays visible instead of vanishing into NOT-EXPLOSIVE."""
    zr = data.get('zacks_ranks') or {}
    ex = {r.get('ticker'): r for r in (data.get('explosive_us') or []) if isinstance(r, dict)}

    # --- near-miss stamping on the screened records (display chip lives in the table row) ---
    n_near = 0
    for t, r in ex.items():
        try:
            rg, og = r.get('rev_growth'), r.get('op_growth')
            cond = r.get('conditions') or {}
            a1 = cond.get('a1')
            nm = None
            if rg is not None and og is not None and a1:
                if 17.0 <= rg < 20.0 and og >= 15.0:
                    nm = {'gate': 'G1', 'by': round(20.0 - rg, 1)}
                elif 12.0 <= og < 15.0 and rg is not None and rg > 20.0:
                    nm = {'gate': 'G2', 'by': round(15.0 - og, 1)}
            r['near_miss'] = nm
            if nm:
                n_near += 1
        except Exception:
            r['near_miss'] = None

    # --- the radar itself ---
    SURFACED = ('EXPLOSIVE', 'QUALITY-GROWTH', 'INFLECTION')
    filtered_out, on_board = [], []
    for t, rank in zr.items():
        if rank not in (1, 2):
            continue
        r = ex.get(t)
        im = r.get('im3') if (r and isinstance(r.get('im3'), dict)) else None
        entry = {'ticker': t, 'rank': int(rank),
                 'im3_grade': (im or {}).get('grade'), 'im3_pct': (im or {}).get('pct')}
        if r is None:
            entry['status'] = 'outside growth screen -- value/compounder profile'
            filtered_out.append(entry)
        else:
            v = str(r.get('verdict') or '')
            if any(v.startswith(k) for k in SURFACED):
                entry['status'] = v
                on_board.append(entry)
            else:
                entry['status'] = 'screened, NOT EXPLOSIVE -- gates not met'
                entry['near_miss'] = r.get('near_miss')
                filtered_out.append(entry)
    filtered_out.sort(key=lambda e: (e['rank'], e['ticker']))

    # v1.279.0 PINK FULL-DATA ROWS (owner: 'zacks discoveries should be after yellow in pink
    # background filling all columns as green and yellow are doing'). Screened NOT-EXPLOSIVE
    # radar names are STAMPED zacks_discovery=True on their real records (the index lifts them,
    # full genuine data). Outside-screen names get explosive-SHAPED records built from the
    # ~1,900-name foundation universe ALREADY in data.json -- name, sector, price, Rev YoY (TTM),
    # EPS YoY, YTD/1Y and the 50/200-DMA trend, all real TV figures, ZERO new fetching. Fields
    # the growth screen computes from statements (OP YoY, NP YoY, signals) stay honest None --
    # the table's dash/grey conventions already explain 'not available'. g1 is judged from the
    # real revenue number; verdict = 'ZACKS DISCOVERY -- <rank label>'.
    _fidx = {}
    for _fr in (data.get('foundation_universe') or []):
        if isinstance(_fr, dict) and _fr.get('ticker'):
            _fidx[_fr['ticker']] = _fr
    _ALIAS = {'GOOGL': 'GOOG', 'GOOG': 'GOOGL', 'BRK.B': 'BRK.A'}
    rows = []
    for e in filtered_out:
        t = e['ticker']
        r = ex.get(t)
        if r is not None:                       # screened NOT-EXPLOSIVE: lift the real record
            r['zacks_discovery'] = True
            r['zacks_rank'] = e['rank']
            continue
        f = _fidx.get(t) or _fidx.get(_ALIAS.get(t, ''))
        rg = f.get('rev_growth') if f else None
        px = (f.get('price') if f else None) or (f.get('close') if f else None)
        s50, s200 = (f.get('sma50') if f else None), (f.get('sma200') if f else None)
        ma = None
        if px is not None and s200:
            ma = {'sma50': s50, 'sma200': s200,
                  'above_200dma': px > s200,
                  'above_50dma': (px > s50) if s50 else None,
                  'ext_200_pct': round((px / s200 - 1.0) * 100, 1)}
        rows.append({
            'ticker': t,
            'name': (f.get('name') if f else None) or t,
            'sector': (f.get('sector') if f else None) or '',
            'price': px,
            'rev_growth': rg, 'op_growth': None, 'np_growth': None,
            'eps_growth': f.get('eps_growth') if f else None,
            'perf_ytd': f.get('perf_ytd') if f else None,
            'perf_1y': f.get('perf_1y') if f else None,
            'perf_6m': f.get('perf_6m') if f else None,
            'perf_3m': f.get('perf_3m') if f else None,
            'ma': ma,
            'conditions': {'g1': (rg is not None and rg > 20.0) if rg is not None else None,
                           'g2': None, 'a1': None, 'c1': None},
            'signal_a': None, 'signal_b': None, 'signal_q': None, 'signal_t': None,
            'near_miss': None, 'im3': None,
            'verdict': 'ZACKS DISCOVERY \u2014 ' + ('Strong Buy' if e['rank'] == 1 else 'Buy'),
            'zacks_rank': e['rank'], 'zacks_discovery': True,
            'foundation_data': bool(f),
            # v1.281.0: a name below the $2bn foundation floor renders honestly labelled, not blank
            'note': None if f else 'below the $2bn foundation floor \u2014 market data not carried',
        })

    # v1.280.0 (owner: 'all zacks 1 and 2 should be im scored as well'): the workflow's im3
    # step now scores the pink tier too and merges grades into these rows -- but this builder
    # REBUILDS the rows every scan, which would erase them. Carry each row's im3 forward from
    # the previous run's radar (keep-last-good semantics, same as the main pass): a current-ver
    # grade carries clean; a version-mismatched grade carries MARKED stale_ver (displayed with
    # the amber 're-scoring' chip) and the workflow heals it.
    try:
        _prev = {r.get('ticker'): r.get('im3') for r in
                 ((existing or {}).get('zacks_radar') or {}).get('rows', [])
                 if isinstance(r, dict) and isinstance(r.get('im3'), dict)}
        _cv = None
        try:
            import re as _re2
            _m2 = _re2.search(r'IM3_VERSION\s*=\s*"([0-9.]+)"', open('im3_score.py').read())
            _cv = _m2.group(1) if _m2 else None
        except Exception:
            pass
        _zc = 0
        for r in rows:
            _pim = _prev.get(r['ticker'])
            if _pim and _pim.get('grade'):
                if _cv is not None and _pim.get('ver') != _cv:
                    _pim = dict(_pim, stale_ver=True)
                r['im3'] = _pim
                _zc += 1
        if _zc:
            log(f"  [Zacks radar] carried {_zc} pink-tier IM3 grade(s) forward")
    except Exception as _ce:
        log(f"  [Zacks radar] im3 carry skipped: {type(_ce).__name__}")
    # v1.281.0 (owner-approved): every pink row gets its UCITS proxy -- the same estate-tax-safe
    # Irish-ETF route every green/yellow row already carries. Pure catalog resolution
    # (resolve_ucits_proxy_for_stock), zero fetching.
    _npx = 0
    for r in rows:
        try:
            r['ucits_proxy'] = resolve_ucits_proxy_for_stock(r['ticker'], r.get('sector') or '', 'us')
            if r['ucits_proxy']:
                _npx += 1
        except Exception:
            r['ucits_proxy'] = None
    # v1.289.0 PRICE-JOIN (audit: 0/50 pink proxies carried live perf while green/yellow rows'
    # proxy lines show it). Harvest every priced ISIN already in data -- the ETF watches
    # (live_ytd) and the priced ucits_proxy dicts on explosive/tce records -- and stamp
    # ytd/ret_1y/daily_chg onto matching pink proxies. Zero new fetching; index ucitsPerf
    # renders automatically. Unmatched ISINs stay honest mapping-only lines.
    try:
        _ppool = {}
        for _wk2 in ('etf_momentum_watch', 'etf_metals_etc_watch', 'etf_hydrogen_watch',
                     'etf_emerging_themes_watch'):
            for _f in (data.get(_wk2) or []):
                if isinstance(_f, dict) and _f.get('isin') and _f.get('live_ytd') is not None:
                    _ppool.setdefault(_f['isin'], {})['ytd'] = _f['live_ytd']
        for _lk in ('explosive_us', 'tce_us'):
            for _r2 in (data.get(_lk) or []):
                _pp = _r2.get('ucits_proxy') if isinstance(_r2, dict) else None
                if isinstance(_pp, dict) and _pp.get('isin'):
                    _dst = _ppool.setdefault(_pp['isin'], {})
                    for _pf in ('ytd', 'ret_1y', 'daily_chg'):
                        if _pp.get(_pf) is not None and _pf not in _dst:
                            _dst[_pf] = _pp[_pf]
        _joined = 0
        for r in rows:
            _pr = r.get('ucits_proxy')
            if isinstance(_pr, dict) and _pr.get('isin') in _ppool:
                _pr.update(_ppool[_pr['isin']])
                _joined += 1
        if _joined:
            log(f'  [Zacks radar] price-joined {_joined} pink proxy(ies) from already-priced ISINs')
    except Exception as _pe:
        log(f'  [Zacks radar] proxy price-join skipped: {type(_pe).__name__}')
    n_lifted = sum(1 for e in filtered_out if e['ticker'] in ex)
    out = {'as_of': dt.date.today().isoformat(),
           'n_rank12': len(filtered_out) + len(on_board),
           'filtered_out': filtered_out,
           'rows': rows,
           'n_lifted': n_lifted,
           'on_board': [e['ticker'] for e in sorted(on_board, key=lambda e: e['ticker'])],
           'n_near_miss': n_near,
           'n_proxied': _npx,
           # v1.281.0: surface the SCRAPE's age (ranks refresh weekly -- the reader should see it)
           'zacks_scraped_utc': (data.get('zacks_sectors') or {}).get('_scraped_utc'),
           'note': 'weekly Zacks scrape (~306 large caps); PSX has no Zacks coverage'}
    log(f"  [Zacks radar] {len(filtered_out)} Strong-Buy name(s) off the main board -> "
        f"{len(rows)} pink foundation-data rows + {n_lifted} screened rows lifted; "
        f"{len(on_board)} already on the board; {n_near} near-miss chip(s)")
    return out


def build_explosive_etf_verified(data, existing=None):
    """Shortlist UCITS ETFs that VERIFIABLY hold the Explosive tab's strict top-scorers.

    STRICT top-scorer = EXPLOSIVE verdict AND Signal A AND Signal B AND Signal Q all firing,
    AND a strong IM3 quality grade (A or B). For each such stock we take the UCITS ETF the
    Explosive tab already assigns (ucits_proxy), FETCH that ETF's REAL published holdings
    (justETF public profile, top 25 by ISIN -- the same plumbing the ETF engine already uses),
    and CONFIRM the stock's ticker is genuinely among them via the name->ticker bridge. An ETF
    is shortlisted ONLY when its real holdings contain >=1 verified top-scorer -- never by a
    sector/thematic guess. Emitted with the SAME shape as the other ETF-tab watch lists
    (name/isin/ter/ytd/ret_1y/price + holdings) so the display reuses the existing format.
    """
    ex = [r for r in (data.get('explosive_us') or []) if isinstance(r, dict)]
    def _grade(r):
        im = r.get('im3') if isinstance(r.get('im3'), dict) else {}
        return im.get('grade')
    strict = []
    for r in ex:
        if (str(r.get('verdict', '')).startswith('EXPLOSIVE')
                and r.get('signal_a') and r.get('signal_b') and r.get('signal_q')
                and _grade(r) in ('A', 'B')):
            strict.append(r)
    if not strict:
        return {'etfs': [], 'n_top_scorers': 0, 'as_of': dt.datetime.utcnow().isoformat() + 'Z',
                'note': 'No stock currently fires all of Signal A, B and Q with a strong (A/B) quality grade.'}

    bridge = _etfx_name_bridge(existing)
    cache = dict((((existing or {}).get('etf_discovery_holdings_cache')) or {}))

    # group strict top-scorers by their assigned UCITS proxy ETF
    from collections import OrderedDict
    proxies = OrderedDict()
    for r in strict:
        up = r.get('ucits_proxy') or {}
        iz = (up.get('isin') or '').upper()
        if not iz:
            continue
        proxies.setdefault(iz, {'isin': iz, 'name': up.get('name') or iz,
                                'ter': up.get('ter'), 'ytd': up.get('ytd'),
                                'ret_1y': up.get('ret_1y'), 'price': up.get('live_price') or up.get('price'),
                                'daily_chg': up.get('daily_chg'), 'candidates': []})
        proxies[iz]['candidates'].append(r)

    def _etfx_hstr(h):
        if isinstance(h, str):
            h = h.strip()
            return h if (h and h != '\u2014' and h.lower() not in ('not sourced', 'pending', 'n/a', '-')) else None
        if isinstance(h, list):
            parts = [(x[0] if isinstance(x, (list, tuple)) else x) for x in h]
            parts = [str(x).strip() for x in parts if x]
            return ', '.join(parts) if parts else None
        return None
    out, fetched = [], 0
    ETFX_FETCH_BUDGET = 12
    for iz, p in proxies.items():
        # real holdings: reuse this run's holdings cache, else fetch top-25 from justETF
        hs = _etfx_hstr(cache.get(iz))
        if not hs and fetched < ETFX_FETCH_BUDGET:
            try:
                hs = fetch_justetf_holdings(iz, top=25)
            except Exception:
                hs = None
            if hs:
                cache[iz] = hs
            fetched += 1
        hold_names = [h.strip() for h in (hs or '').split(',') if h.strip()]
        hold_norms = {_etfx_norm(h) for h in hold_names}

        verified, unconfirmed = [], []
        for r in p['candidates']:
            tk = r.get('ticker')
            # is this ticker genuinely in the ETF's real holdings?
            found = False
            for hn in hold_norms:
                if bridge.get(hn) == tk:
                    found = True
                    break
            g = _grade(r)
            entry = {'ticker': tk, 'im3_grade': g,
                     'q_rev_g': r.get('q_rev_g'), 'q_eps_g': r.get('q_eps_g')}
            (verified if found else unconfirmed).append(entry)

        if verified:
            out.append({
                'name': p['name'], 'isin': iz, 'ter': p['ter'], 'ytd': p['ytd'],
                'ret_1y': p['ret_1y'], 'price': p['price'], 'daily_chg': p['daily_chg'],
                'holdings': hs or '', 'holdings_fetched': bool(hs),
                'n_verified': len(verified), 'verified': verified,
                'unconfirmed': unconfirmed,   # top-scorer assigned here but NOT found in real holdings (honest)
            })
    out.sort(key=lambda e: (-e['n_verified'], e['name']))
    data['etf_discovery_holdings_cache'] = cache
    tickers = sorted({v['ticker'] for e in out for v in e['verified']})
    log(f'  [ETF-X verified] {len(strict)} strict top-scorers -> {len(out)} ETF(s) with VERIFIED holdings '
        f'({fetched} fetched); tickers {", ".join(tickers) if tickers else "-"}')
    return {
        'etfs': out,
        'n_top_scorers': len(strict),
        'top_scorer_tickers': sorted({r.get('ticker') for r in strict}),
        'as_of': dt.datetime.utcnow().isoformat() + 'Z',
        'note': ('UCITS ETFs whose REAL published holdings contain an Explosive-tab top-scorer '
                 '(EXPLOSIVE verdict + Signal A + B + Q all firing + strong quality grade). '
                 'Holdings verified against justETF public profiles, not sector-matched.'),
    }

def build_live_etf_discovery(min_aum_m=0.0, per_segment=40, top_n=60):
    """LIVE self-discovering UCITS-ETF momentum list -- replaces the frozen _MOMENTUM_WATCH upload.
    Screens each European segment by Perf.YTD (proven v1.214.4 request body), keeps ONLY genuine long-only
    UCITS funds (drops leveraged/inverse/ETP), dedups by ISIN across venues (keeps the highest-YTD listing).
    Sandbox blocks TV -> confirmed on the runner from the [ETF discovery] log. AUM units are unconfirmed, so
    this run captures aum_m + logs the range rather than hard-filtering (the name/UCITS filter is the proven
    discriminator); the AUM floor is tuned next run once the log reveals the units. Returns a ranked list."""
    import requests as _rq
    _cols = ['name', 'description', 'close', 'Perf.YTD', 'Perf.6M', 'Perf.3M', 'aum', 'isin',
             'currency', 'fundamental_currency_code', 'expense_ratio', 'typespecs']
    _markets = ['uk', 'germany', 'netherlands', 'switzerland', 'france']
    by_isin = {}
    kept = dropped = floored = 0
    aums = []
    for _mkt in _markets:
        try:
            payload = {"columns": _cols,
                       "filter": [{"left": "type", "operation": "equal", "right": "fund"}],
                       "sort": {"sortBy": "Perf.YTD", "sortOrder": "desc"},
                       "range": [0, 300], "markets": [_mkt]}
            r = _rq.post(f'https://scanner.tradingview.com/{_mkt}/scan',
                         json=payload, headers={'User-Agent': UA}, timeout=40)
            if r.status_code != 200:
                log(f'  [ETF discovery] {_mkt}: HTTP {r.status_code} -- skipped'); continue
            rows = r.json().get('data', []) or []
            seg_kept = 0
            for dd in rows:
                rec = dict(zip(_cols, dd.get('d', [])))
                nm = rec.get('description') or rec.get('name')   # description = full fund name; name = bare symbol (probe-confirmed)
                if not _etf_is_genuine_ucits(nm, rec.get('typespecs'), rec.get('expense_ratio')):
                    dropped += 1; continue
                isin = rec.get('isin')
                if not isin:
                    continue
                aum = rec.get('aum')
                if aum:
                    aums.append(aum)
                if min_aum_m and aum is not None and aum < min_aum_m * 1e6:
                    floored += 1; continue
                ytd = rec.get('Perf.YTD')
                cand = {'name': nm, 'isin': isin,
                        'ytd': round(ytd, 1) if ytd is not None else None,
                        'ret_6m': round(rec['Perf.6M'], 1) if rec.get('Perf.6M') is not None else None,
                        'ret_3m': round(rec['Perf.3M'], 1) if rec.get('Perf.3M') is not None else None,
                        'aum_m': round(aum / 1e6, 1) if aum else None, 'ter': rec.get('expense_ratio'),
                        'ccy': rec.get('currency'), 'sym': dd.get('s'), 'segment': _mkt,
                        # render-compat with the existing category-grouped Momentum-Watch + isin enrichment:
                        'category': _etf_category(nm), 'live_ytd': round(ytd, 1) if ytd is not None else None,
                        # v1.303.0 sanity guard is applied to the finished list below
                        'ret_1y': None, 'note': f'live/{_mkt}', 'holdings': '—'}
                prev = by_isin.get(isin)
                if prev is None or (cand['ytd'] or -1e9) > (prev.get('ytd') or -1e9):
                    by_isin[isin] = cand
                seg_kept += 1
                if seg_kept >= per_segment:
                    break
            kept += seg_kept
        except Exception as e:
            log(f'  [ETF discovery] {_mkt} error: {type(e).__name__} {str(e)[:60]}')
    ranked = sorted(by_isin.values(), key=lambda x: x.get('ytd') or -1e9, reverse=True)[:top_n]
    for _i, _r in enumerate(ranked):
        _r['rank'] = _i + 1
    _kept_aum = [x['aum_m'] for x in ranked if x.get('aum_m') is not None]
    _kmin = f"${min(_kept_aum):.0f}M" if _kept_aum else "n/a"
    _kmax = f"${max(_kept_aum)/1000:.1f}bn" if _kept_aum else "n/a"
    log(f'  [ETF discovery] {len(ranked)} genuine UCITS ETFs discovered live '
        f'(kept {kept} pre-dedup, dropped {dropped} leveraged/ETP + {floored} below ${min_aum_m:.0f}M floor; '
        f'kept aum range {_kmin}..{_kmax}); '
        f'top: ' + ', '.join(f"{x['name'][:24]} {x['ytd']}%" for x in ranked[:5]))
    return ranked


def build_bottom_up_sectors(foundation_universe, sector_booming=None, ret_field='perf_ytd'):
    """The owner's method, LIVE and DIRECT: rank the ~1,935 foundation stocks by return, then read the
    SECTORS the winners cluster in -- a bottom-up booming-sector signal that cross-checks the top-down one.
    (The manual 'which ETFs hold the winners' step was a proxy to reach sectors; every foundation stock now
    carries its sector live, so we compute the destination directly + more accurately.) Pure, no network.
    Buckets TV sectors into the GICS 11 (via _M1_FINE_TO_GICS) so it lines up with the top-down read, and
    flags AGREEMENT: a sector booming in BOTH the bottom-up and top-down engines is a high-confidence call."""
    from collections import defaultdict
    fu = [r for r in (foundation_universe or [])
          if isinstance(r, dict) and r.get(ret_field) is not None and r.get('sector')]
    if len(fu) < 50:
        return []
    rets = sorted((r[ret_field] for r in fu), reverse=True)
    n = len(rets)
    mkt_med = rets[n // 2]
    top_cut = rets[max(0, n // 5 - 1)]          # top-quintile return threshold = "a winner"
    gmap = globals().get('_M1_FINE_TO_GICS', {})
    agg = defaultdict(lambda: {'n': 0, 'winners': 0, 'rets': [], 'top': [], 'reco': []})
    for r in fu:
        g = gmap.get(r['sector'], r['sector'])
        a = agg[g]; a['n'] += 1; a['rets'].append(r[ret_field])
        _rm = r.get('recommendation_mark')          # v1.322.0 (B): 1=Strong Buy .. 3=Strong Sell
        if isinstance(_rm, (int, float)):
            a['reco'].append(_rm)
        if r[ret_field] >= top_cut:
            a['winners'] += 1
            a['top'].append((r.get('ticker'), round(r[ret_field], 1)))
    total_winners = sum(a['winners'] for a in agg.values()) or 1
    out = []
    for g, a in agg.items():
        if a['n'] < 5:
            continue
        med = sorted(a['rets'])[len(a['rets']) // 2]
        win_share = a['winners'] / a['n']
        beat = med - mkt_med
        score = round(max(0, min(100, 55 * min(1.0, win_share * 2) + 45 * (0.5 + beat / 40))), 1)
        band = ('Booming' if score >= 70 else 'Favoured' if score >= 58 else
                'Neutral' if score >= 42 else 'Lagging' if score >= 28 else 'Avoid')
        out.append({'sector': g, 'score': score, 'band': band, 'n': a['n'], 'winners': a['winners'],
                    'winner_share': round(win_share * 100, 1),
                    'win_of_all': round(a['winners'] / total_winners * 100, 1),
                    'median_ret': round(med, 1), 'beat_mkt': round(beat, 1),
                    'analyst_reco': (round(max(0.0, min(100.0, (3.0 - (sum(a['reco'])/len(a['reco'])))/2.0*100.0)), 1) if a['reco'] else None),
                    'analyst_reco_mean': (round(sum(a['reco'])/len(a['reco']), 2) if a['reco'] else None),
                    'top_names': sorted(a['top'], key=lambda t: t[1], reverse=True)[:5]})
    out.sort(key=lambda x: x['score'], reverse=True)
    td = {s.get('sector'): s.get('band') for s in (sector_booming or [])}
    for i, o in enumerate(out):
        o['rank'] = i + 1
        tdb = td.get(o['sector'])
        o['topdown_band'] = tdb
        o['agree'] = bool(tdb and o['band'] in ('Booming', 'Favoured') and tdb in ('Booming', 'Favoured'))
    log(f"  [Bottom-up sectors] {len(out)} sectors from {n} stocks (mkt-median {mkt_med:.1f}%, winner-cut {top_cut:.1f}%); "
        + ' | '.join(f"{o['sector']}={o['score']}({o['band']}{'=TD✓' if o['agree'] else ''})" for o in out[:4]))
    return out


def build_etf_recommendations(country_rs, sector_booming, global_theme, world_lei=None, us_diffusion=None):
    """Joins World ETF Engine signals to buyable UCITS ISINs via resolve_etf_for_signal().
    v1.132.0 -- four doors + semiconductor bonus pick:
      Door 1 (country):      top 3 eligible countries by 6M USD return (Overweight/Hedge signal)
      Door 2 (sector):       top 2 US sectors (Booming then Favoured)
      Door 3 (theme):        top 2 themes x top 2 countries per theme; Asia-Tech also fires
                             a semiconductor bonus pick (VanEck SMGB IE00BMC38736)
      Door 4 (em_ex_china):  fires when Emerging Favoured/Booming but China Neutral/Avoid
    Korea/Taiwan two-door: both surface independently when Asia-Tech is Booming.
    Same-ISIN picks from multiple doors merge into one double-confirmed entry.
    PURE function -- no network call. DATA-only; never touches screening / scoring / TCE."""
    _COUNTRY_ETF_CAT = {
        'Japan': 'Equity Japan', 'India': 'Equity India', 'USA': 'Equity United States',
        'UK': 'Equity United Kingdom', 'China': 'Equity China', 'Canada': 'Equity Canada',
        'Australia': 'Equity Australia', 'Germany': 'Equity Germany', 'Brazil': 'Equity Brazil',
        'South Korea': 'Equity South Korea', 'Taiwan': 'Equity Taiwan',
        'Switzerland': 'Equity Switzerland',
    }
    _SECTOR_ETF_CAT = {
        'Materials': 'Equity Basic Materials', 'Information Technology': 'Equity Technology',
        'Energy': 'Equity Energy', 'Industrials': 'Equity Industrials',
        'Consumer Staples': 'Equity Consumer Staples', 'Health Care': 'Equity Health Care',
        'Financials': 'Equity Financials', 'Real Estate': 'Real Estate United States',
        'Consumer Discretionary': 'Equity Consumer Discretionary', 'Utilities': 'Equity Utilities',
        'Communication Services': 'Equity Telecommunication',
    }
    _THEME_COUNTRY_ORDER = {
        'Asia-Tech':      ['Taiwan', 'South Korea', 'Japan'],
        'Developed-West': ['USA', 'UK', 'Germany', 'Switzerland', 'Canada', 'Australia'],
        'Commodity-Bloc': ['Australia', 'Brazil', 'Canada'],
        'Emerging':       ['India', 'Brazil'],
    }
    recs = []
    # v1.137.0: lookup for attaching country trailing returns (3M/6M/12M, already computed by
    # fetch_country_rs -- zero new fetch) onto country-attached picks. Sector-door picks have
    # no country and correctly carry no trailing-return field (honest, not fabricated).
    _crs_by_country = {r['country']: r for r in (country_rs or []) if r.get('country')}
    try:
        # Door 1: top 3 countries by 6M USD return (Overweight/Hedge signal)
        eligible_countries = [r for r in (country_rs or [])
                               if r.get('country') and r.get('signal') in ('Overweight', 'Hedge')]
        for top_c in sorted(eligible_countries, key=lambda r: r.get('ret_6m') or -999, reverse=True)[:3]:
            cat = _COUNTRY_ETF_CAT.get(top_c['country'])
            if cat:
                fund = resolve_etf_for_signal(cat, fallback_keys=['Equity World'])
                if fund:
                    recs.append({
                        'door': 'country', 'signal': top_c['country'],
                        'reason': f"6M USD {top_c.get('ret_6m','--')}% . {top_c.get('signal','--')}",
                        'fund': fund,
                        'country_trailing': {'country': top_c['country'], 'ret_3m': top_c.get('ret_3m'),
                                              'ret_6m': top_c.get('ret_6m'), 'ret_12m': top_c.get('ret_12m')},
                    })

        # Door 2: top 2 US sectors (Booming scores highest then Favoured)
        eligible_sectors = [r for r in (sector_booming or [])
                             if r.get('band') in ('Booming', 'Favoured')]
        for top_s in sorted(eligible_sectors, key=lambda r: r.get('score') or 0, reverse=True)[:2]:
            cat = _SECTOR_ETF_CAT.get(top_s['sector'])
            if cat:
                fund = resolve_etf_for_signal(cat, fallback_keys=['Equity World'])
                if fund:
                    recs.append({
                        'door': 'sector', 'signal': top_s['sector'],
                        'reason': f"score {top_s.get('score','--')} . {top_s.get('band','--')}",
                        'fund': fund,
                    })

        # Door 3: top 2 global themes x top 2 countries (Korea/Taiwan two-door rule)
        # + semiconductor bonus pick when Asia-Tech fires (founding instruction: Korea/Taiwan semis)
        eligible_themes = [r for r in (global_theme or []) if r.get('band') in ('Booming', 'Favoured')]
        for top_t in sorted(eligible_themes, key=lambda r: r.get('score') or 0, reverse=True)[:2]:
            theme_name = top_t.get('theme', '')
            data_top = top_t.get('top_country')
            ordered = ([data_top] if data_top else []) + [
                c for c in _THEME_COUNTRY_ORDER.get(theme_name, []) if c != data_top
            ]
            n_theme = 0
            for country_name in ordered:
                if n_theme >= 2:
                    break
                cat = _COUNTRY_ETF_CAT.get(country_name)
                if cat:
                    fund = resolve_etf_for_signal(cat, fallback_keys=['Equity Asia Pacific', 'Equity World'])
                    if fund:
                        _crow = _crs_by_country.get(country_name) or {}
                        recs.append({
                            'door': 'global_theme', 'signal': theme_name,
                            'reason': (f"score {top_t.get('score','--')} . {theme_name} . "
                                       f"{country_name} {top_t.get('top_country_ret6m','--')}%"),
                            'fund': fund,
                            'country_trailing': {'country': country_name, 'ret_3m': _crow.get('ret_3m'),
                                                  'ret_6m': _crow.get('ret_6m'), 'ret_12m': _crow.get('ret_12m')},
                        })
                        n_theme += 1
            # Semiconductor bonus: VanEck SMGB surfaces when Asia-Tech is Booming/Favoured
            if theme_name == 'Asia-Tech' and n_theme > 0:
                semi_fund = resolve_etf_for_signal('Equity Semiconductors', fallback_keys=['Equity Technology'])
                if semi_fund:
                    recs.append({
                        'door': 'global_theme', 'signal': 'Semiconductors',
                        'reason': (f"score {top_t.get('score','--')} . Asia-Tech booming . "
                                   f"semiconductor pure-play UCITS (founding instruction)"),
                        'fund': semi_fund,
                    })

        # Door 4: EM ex-China -- fires when Emerging is Favoured/Booming but China is weak
        china_rs = next((r for r in (country_rs or []) if r.get('country') == 'China'), None)
        china_sig = china_rs.get('signal') if china_rs else None
        em_theme = next((t for t in (global_theme or [])
                         if t.get('theme') == 'Emerging' and t.get('band') in ('Booming', 'Favoured')), None)
        if em_theme and china_sig in ('Neutral', 'Avoid', None):
            em_ex_fund = resolve_etf_for_signal('Equity Emerging Markets ex China',
                                                fallback_keys=['Equity Emerging Markets'])
            if em_ex_fund:
                recs.append({
                    'door': 'em_ex_china', 'signal': 'EM ex-China',
                    'reason': (f"Emerging {em_theme.get('band')} but China {china_sig or 'not Overweight'} "
                               f"-- ex-China ETF preferred over broad EM"),
                    'fund': em_ex_fund,
                })

        # Merge identical ISINs -- same fund from multiple doors = genuine double-confirmation
        _by_isin = {}
        for r in recs:
            isin = r['fund']['isin']
            if isin in _by_isin:
                _by_isin[isin]['door'] = _by_isin[isin]['door'] + '+' + r['door']
                _by_isin[isin]['signal'] = _by_isin[isin]['signal'] + ' & ' + r['signal']
                _by_isin[isin]['reason'] = _by_isin[isin]['reason'] + ' . also: ' + r['reason']
                _by_isin[isin]['confirmed_count'] = _by_isin[isin].get('confirmed_count', 1) + 1
            else:
                r['confirmed_count'] = 1
                _by_isin[isin] = r
        recs = list(_by_isin.values())

        # v1.215.0 LEADING-INDICATOR GATE — the LEI/US-Diffusion/dollar signals that used to only DISPLAY
        # on Tab 15 now CONFIRM (or caution) every return-discovered pick, so the engine confirms rather
        # than chases (owner guardrail). Non-destructive: nothing is removed; each rec is annotated
        # macro_confirmed True/False + a plain reason, so the tab can rank confirmed picks above return-led.
        try:
            _lei = world_lei or {}
            _diff_exp = ((us_diffusion or {}).get('regime') == 'Expansion')
            _dollar = next((r.get('dollar_direction') for r in (country_rs or [])
                            if isinstance(r, dict) and r.get('__meta__') == 'dollar_direction'), None)
            _RISK_ON = {'Developed-West', 'Asia-Tech'}
            _DOLLAR_SENS = {'Emerging', 'Commodity-Bloc'}

            def _countries_for(_r):
                _ct = (_r.get('country_trailing') or {}).get('country')
                if _ct:
                    return [_ct]
                return _THEME_COUNTRY_ORDER.get(_r.get('signal', ''), [])
            for _r in recs:
                _reasons = []; _confirm = 0; _caution = 0
                _cs = _countries_for(_r)
                _lei_exp = [c for c in _cs if (_lei.get(c) or {}).get('signal') == 'expansion']
                if _lei_exp:
                    _confirm += 1; _reasons.append('LEI expanding: ' + '/'.join(_lei_exp))
                _sig = _r.get('signal', '')
                if _diff_exp and (_sig in _RISK_ON or 'USA' in _cs):
                    _confirm += 1; _reasons.append('US diffusion Expansion')
                if _dollar == 'Strong' and _sig in _DOLLAR_SENS:
                    _caution += 1; _reasons.append('strong-dollar headwind')
                _r['macro_confirmed'] = bool(_confirm > 0 and _caution == 0)
                _r['macro_reason'] = '; '.join(_reasons) if _reasons else 'no leading-indicator confirmation (return-led)'
            recs.sort(key=lambda r: (r.get('macro_confirmed', False), r.get('confirmed_count', 1)), reverse=True)
            _nc = sum(1 for r in recs if r.get('macro_confirmed'))
            log(f"  [ETF recs gate] {_nc}/{len(recs)} macro-confirmed "
                f"(dollar={_dollar}, diffusion={'Expansion' if _diff_exp else 'not-Expansion'})")
        except Exception as _ge:
            log(f"  [ETF recs gate] skipped: {type(_ge).__name__}: {str(_ge)[:60]}")

        log(f"  [ETF Recommendations] {len(recs)} resolved: " +
            ', '.join(f"{r['door']}:{r['signal']}->{r['fund']['name'][:30]}"
                      + (f" (x{r['confirmed_count']})" if r.get('confirmed_count',1)>1 else '')
                      for r in recs))
    except Exception as _e:
        log(f"  [ETF Recommendations] skip: {type(_e).__name__}: {str(_e)[:60]}")
    return recs


# ============================================================================================
# v1.237.0 Wave SEC -- SEC EDGAR filings layer (Form 4 insider + 8-K material events).
# ONE public pipe (data.sec.gov, no paid feed, no scraping). Verified against the live submissions
# JSON (columnar filings.recent with form/filingDate/accessionNumber/primaryDocument/items) and the
# official EDGAR ownership XML spec (transactionCode P=buy/S=sale, transactionShares,
# transactionPricePerShare, reportingOwner isOfficer/officerTitle). SEC requires a descriptive
# User-Agent + <=10 req/s; both respected. US-listed names only -- PSX names show 'n/a (not on EDGAR)'.
# DATA-only; every consumer reads these stores, TCE stays frozen (s13/s14 recorded, not scored).
# ============================================================================================
_SEC_UA = 'Portfolio Intelligence Dashboard admin@example.com'  # SEC courtesy: descriptive UA w/ contact
_SEC_HEADERS = {'User-Agent': _SEC_UA, 'Accept-Encoding': 'gzip, deflate', 'Host': 'data.sec.gov'}
_SEC_8K_WATCH = {  # 8-K item code -> plain-language adverse/material label
    '1.03': 'Bankruptcy or receivership', '4.01': 'Auditor change/dismissal',
    '4.02': 'Non-reliance on prior financials', '2.06': 'Material impairment',
    '5.02': 'Officer/director departure', '1.01': 'Material agreement (restructuring)',
    '2.05': 'Costs from exit/disposal', '2.01': 'Completion of acquisition/disposition',
    '3.01': 'Delisting notice', '2.04': 'Triggering of debt obligation',
}
_SEC_8K_ADVERSE = {'1.03', '4.01', '4.02', '2.06', '3.01', '2.04'}  # red-flag subset. v1.238.0: 5.02
# (officer/director departure) REMOVED -- it fires on routine board retirements/comp-plan changes and
# flagged 46% of names (AAPL/MSFT/META all "adverse") on the v1.237.0 live run. 5.02 stays a WATCHED
# event (neutral chip) but is no longer a red flag. True red flags: bankruptcy(1.03), auditor
# change(4.01), non-reliance(4.02), impairment(2.06), delisting(3.01), debt-default(2.04).

_CIK_MAP_CACHE = {}

def _load_cik_map():
    """ticker(upper) -> zero-padded 10-digit CIK, from the public company_tickers.json (loaded once/run)."""
    global _CIK_MAP_CACHE
    if _CIK_MAP_CACHE:
        return _CIK_MAP_CACHE
    try:
        import urllib.request, json as _json
        req = urllib.request.Request('https://www.sec.gov/files/company_tickers.json',
                                     headers={'User-Agent': _SEC_UA})
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = _json.loads(r.read().decode('utf-8'))
        m = {}
        for _k, row in raw.items():
            t = (row.get('ticker') or '').upper()
            c = row.get('cik_str')
            if t and c is not None:
                m[t] = str(c).zfill(10)
        _CIK_MAP_CACHE = m
        log(f'  [Wave SEC] CIK map loaded: {len(m)} tickers')
    except Exception as _e:
        log(f'  [Wave SEC] CIK map load FAILED ({type(_e).__name__}: {_e}) -- Wave SEC will carry last-good')
        _CIK_MAP_CACHE = {}
    return _CIK_MAP_CACHE


import threading as _sec_thr
_SEC_RATE_LOCK = _sec_thr.Lock()
_SEC_NEXT_SLOT = [0.0]

def _sec_gate(min_interval=0.14):
    """v1.238.3 GLOBAL SEC rate gate. Spaces EVERY SEC request >=0.14s apart across ALL worker
    threads (~7 req/s, safely under SEC's ~10/s ceiling) so the pool never triggers the 429
    throttle AND never runs an unbounded number of sequential GETs. The slot is reserved under
    the lock (fast, non-blocking); the actual wait happens OUTSIDE the lock, so worker threads
    still fetch concurrently -- only the request STARTS are paced. This is the fix for run 131's
    22-min blowup (0 errors but pure latency of ~4,500 sequential GETs)."""
    import time as _t
    with _SEC_RATE_LOCK:
        now = _t.time()
        slot = _SEC_NEXT_SLOT[0] if _SEC_NEXT_SLOT[0] > now else now
        _SEC_NEXT_SLOT[0] = slot + min_interval
    w = slot - _t.time()
    if w > 0:
        _t.sleep(w)


def _sec_get_json(url):
    import urllib.request, json as _json
    _sec_gate()
    req = urllib.request.Request(url, headers={'User-Agent': _SEC_UA})
    with urllib.request.urlopen(req, timeout=30) as r:
        return _json.loads(r.read().decode('utf-8'))


def _sec_get_text(url):
    import urllib.request
    _sec_gate()
    req = urllib.request.Request(url, headers={'User-Agent': _SEC_UA})
    with urllib.request.urlopen(req, timeout=30) as r:
        return r.read().decode('utf-8', 'replace')


def _form4_fetch_xml(cik, acc_nodash):
    """Return the raw Form-4 ownership XML TEXT for an accession, or None. v1.238.1: the
    v1.238.0 resolver made TWO calls per filing (index.json + the xml) -> 8 workers x 4/name x
    214 names doubled the request count and hit SEC's 429 throttle (750 'errors' last run).
    v1.238.1 tried 3 KNOWN filenames directly first -- but pro filers (Workiva wk-form4_*, Toppan
    Merrill tm*_4seq1) don't use form4.xml, so that did 3 FAILED 404-GETs before index.json,
    ballooning calls ~2.5x -> the 22-min blowup (run 131). v1.238.3 reverts to index.json-FIRST
    (2 deterministic calls), and the global _sec_gate() throttle keeps the pool <=~7 req/s so 2
    calls/filing can't 429. Validates <ownershipDocument> before accepting (no false parse)."""
    base = f'https://www.sec.gov/Archives/edgar/data/{int(cik)}/{acc_nodash}'
    # resolve via index.json (handles form4.xml, wk-form4_*, tm*_4seq1, fp*_4, edgardoc, etc.)
    try:
        idx = _sec_get_json(base + '/index.json')
    except Exception:
        return None
    best = None
    for it in ((idx.get('directory') or {}).get('item') or []):
        nm = (it.get('name') or ''); low = nm.lower()
        if not low.endswith('.xml'):
            continue
        if low.endswith('.xsd') or 'xsl' in low or (low.startswith('r') and low[1:2].isdigit()):
            continue
        if any(k in low for k in ('form4', 'ownership', 'primary_doc', '_4seq', '_4.xml', 'x4', 'edgardoc')):
            best = base + '/' + nm; break
        if best is None:
            best = base + '/' + nm
    if not best:
        return None
    try:
        txt = _sec_get_text(best)
        return txt if (txt and '<ownershipDocument' in txt) else None
    except Exception:
        return None


def _parse_form4_xml(xml_text):
    """Extract insider transactions from a Form 4 ownership XML. Returns list of dicts:
    {code, shares, price, ad, is_officer, is_director, title}. Verified field names against the
    EDGAR ownership XML spec. Uses stdlib ElementTree; tolerant of missing sub-nodes."""
    import xml.etree.ElementTree as ET
    out = []
    try:
        root = ET.fromstring(xml_text.encode('utf-8') if isinstance(xml_text, str) else xml_text)
    except Exception:
        return out
    def _txt(node, path):
        el = node.find(path)
        return (el.text or '').strip() if el is not None and el.text else ''
    # reportingOwner relationship (role) -- may be one or more owners
    is_off = is_dir = False; title = ''
    for rel in root.iter('reportingOwnerRelationship'):
        if _txt(rel, 'isOfficer') in ('1', 'true'): is_off = True
        if _txt(rel, 'isDirector') in ('1', 'true'): is_dir = True
        t = _txt(rel, 'officerTitle')
        if t: title = t
    # non-derivative transactions (open-market P/S live here)
    for tx in root.iter('nonDerivativeTransaction'):
        coding = tx.find('transactionCoding')
        amounts = tx.find('transactionAmounts')
        code = _txt(coding, 'transactionCode') if coding is not None else ''
        shares = _txt(amounts, 'transactionShares/value') if amounts is not None else ''
        price = _txt(amounts, 'transactionPricePerShare/value') if amounts is not None else ''
        ad = _txt(amounts, 'transactionAcquiredDisposedCode/value') if amounts is not None else ''
        if not code:
            continue
        try: sh = float(shares) if shares else 0.0
        except Exception: sh = 0.0
        try: pr = float(price) if price else 0.0
        except Exception: pr = 0.0
        out.append({'code': code, 'shares': sh, 'price': pr, 'ad': ad,
                    'is_officer': is_off, 'is_director': is_dir, 'title': title})
    return out


