def _li_load_config():
    try:
        import os, json as _j
        if os.path.exists('live_portfolio.json'):
            with open('live_portfolio.json') as f:
                cfg = _j.load(f)
            if cfg.get('holdings'):
                return cfg
    except Exception as e:
        log(f'  [Live Investment] live_portfolio.json unreadable ({e}) — using in-code default')
    return LIVE_PORTFOLIO_DEFAULT


def _li_price_index(data):
    """isin -> priced record already fetched THIS run (reuse, zero extra fetch).
    v1.215.2: etf_momentum_watch is LISTED LAST. Since v1.215.0 it can be the live-discovery list whose
    records carry holdings='—' (discovery doesn't fetch underlyings); with setdefault(first-wins) it was
    FIRST and shadowed the richer hydrogen/emerging/metals/tracker records for overlapping ISINs (e.g. SMH),
    stripping the underlyings string the Live-Investment forward view reads -> forward-covered collapsed 5->0.
    Order is price-neutral (same live_price per ISIN across lists); only the holdings field differs, so the
    real-holdings lists must win. Momentum-watch stays in the pool (fills funds present nowhere else)."""
    idx = {}
    for k in ('etf_hydrogen_watch', 'etf_emerging_themes_watch', 'etf_metals_etc_watch',
              'explosive_etf_tracker', 'tce_etf_tracker', 'etf_momentum_watch'):
        for r in (data.get(k) or []):
            iz = r.get('isin')
            if iz and r.get('live_price') is not None:
                idx.setdefault(iz, r)
    return idx


def _li_fx(data, existing):
    """USD per 1 unit of ccy. GBP/EUR live via the proven forex scan; AED pegged; carry last-good.
    v1.238.2: was SILENTLY riding a hardcoded 1.34/1.16 fallback (no log line, and the stored GBP
    was exactly 1.34 -> the live fetch had been missing without anyone seeing it). Now: try FX_IDC
    first, then OANDA: as an alt symbol, tag each rate live|last-good|hardcoded, and LOG the result
    so a stale rate can never again hide. GBP feeds AINF (GBP) + ITWN (GBX); a stale rate is a
    constant mis-valuation on ~$66k of the book vs IBKR."""
    fx = {'USD': 1.0, 'AED': 1.0 / _AED_PER_USD}
    prev = ((existing or {}).get('live_investment') or {}).get('fx') or {}
    src = {}
    def _one(key, syms, fallback):
        for sym in syms:
            try:
                got = fetch_index_tv({key: sym}, markets=('forex',))
                px = (got.get(key) or {}).get('px')
                if px and 0.3 < px < 3.0:   # sanity band for GBPUSD/EURUSD
                    src[key] = 'live'; return px
            except Exception:
                continue
        if prev.get(key.upper() if len(key) == 3 else key):
            pass
        pv = prev.get({'gbpusd': 'GBP', 'eurusd': 'EUR'}[key])
        if pv:
            src[key] = 'last-good'; return pv
        src[key] = 'hardcoded'; return fallback
    fx['GBP'] = _one('gbpusd', ('FX_IDC:GBPUSD', 'OANDA:GBPUSD'), 1.34)
    fx['EUR'] = _one('eurusd', ('FX_IDC:EURUSD', 'OANDA:EURUSD'), 1.16)
    fx['GBX'] = fx['GBP'] / 100.0  # pence line
    log(f"  [Live FX] GBPUSD {fx['GBP']:.4f} ({src.get('gbpusd')}) | EURUSD {fx['EUR']:.4f} "
        f"({src.get('eurusd')}) | AED pegged {1.0/_AED_PER_USD:.4f}"
        + ("  <- WARNING: FX not live, GBP/EUR holdings may drift vs IBKR"
           if 'live' not in (src.get('gbpusd'), src.get('eurusd')) else ""))
    return fx


def _li_to_usd(amt, ccy, fx):
    if amt is None:
        return None
    # v1.441.0: minor-unit currencies. GBX/GBp = pence = GBP/100; the fx table only carries GBP,
    # so an unmapped 'GBX' was silently multiplying by 1.0 -- valuing pence as dollars (ITWN's
    # fake +9,775%). Convert the minor unit to its major unit first, THEN apply the major-unit fx.
    c = (ccy or 'USD').upper()
    _MINOR = {'GBX': ('GBP', 100.0), 'GBP.': ('GBP', 100.0), 'ZAC': ('ZAR', 100.0), 'ILA': ('ILS', 100.0)}
    if c in _MINOR:
        major, div = _MINOR[c]
        return (amt / div) * fx.get(major, 1.0)
    return amt * fx.get(c, 1.0)


