def _lt_norm_name(nm):
    """Normalize a constituent name for map lookup: lowercase, punctuation out, corporate suffixes
    and trailing country words off (repeatedly), whitespace collapsed."""
    s = re.sub(r"[.,'()/&\-]", ' ', str(nm or '').lower())
    s = re.sub(r'\s+', ' ', s).strip()
    for _ in range(4):
        s2 = re.sub(r'\s+(co|ltd|inc|corp|corporation|plc|sa|nv|ag|se|spa|china|holding)$', '', s)
        if s2 == s:
            break
        s = s2
    return s

def _lt_resolve_name(nm):
    """name -> ticker via the curated map. Exact match first; then prefix-tolerant (>=8 chars) to
    absorb justETF's mid-word truncations ('Hygon Information Tech'). None = honest unresolved."""
    n = _lt_norm_name(nm)
    if not n:
        return None
    hit = _LT_NAME2TICKER.get(n)
    if hit:
        return hit
    if len(n) >= 8:
        for k, v in _LT_NAME2TICKER.items():
            if len(k) >= 8 and (n.startswith(k) or k.startswith(n)):
                return v
    return None

