def _lt_classify_exchange(tk, exchange, location=None):
    """(ticker, issuer-stated exchange/location) -> (market, tvsym) or None when the exchange
    string is absent/unrecognized (caller falls back to the bare-code _lt_classify guess)."""
    src_s = ' '.join(s for s in (exchange, location) if s).lower()
    if not src_s or not tk:
        return None
    for _sub, (_mkt, _pfx) in _LT_EXCHANGE_MAP:
        if _sub in src_s:
            code = str(tk).strip().upper().split('.')[0]
            return (_mkt, (_pfx + code) if _pfx else code)
    return None

def _lt_classify(tk):
    """underlying ticker -> (market, tvsym) best-effort. Foreign resolution is confirmed by the
    runner probe (sandbox can't reach TV); unresolved -> (None, ticker) shows honestly as no-rating."""
    if not tk:
        return (None, None)
    t = str(tk).strip().upper()
    base = t.split('.')[0]
    # issuer-file format: !EXCHANGE/CODE (e.g. !TPE/2330, !SHA/688256, !KRX/000660).
    # The 1.213.1 runner probe proved TWSE:/KRX:/SSE: resolve on TV; these names only failed
    # because the ! and / broke the suffix/isdigit checks. Map the exchange code to the proven prefix.
    if t.startswith('!') and '/' in t:
        _ex, _, _code = t[1:].partition('/')
        _code = _code.split('.')[0]
        _map = {
            'TPE': ('taiwan', 'TWSE:'), 'TAI': ('taiwan', 'TWSE:'), 'TWSE': ('taiwan', 'TWSE:'), 'TWO': ('taiwan', 'TWSE:'),
            'SHA': ('china', 'SSE:'), 'SHG': ('china', 'SSE:'), 'SHH': ('china', 'SSE:'), 'SSE': ('china', 'SSE:'),
            'SHE': ('china', 'SZSE:'), 'SHZ': ('china', 'SZSE:'), 'SZS': ('china', 'SZSE:'), 'SZSE': ('china', 'SZSE:'),
            'KRX': ('korea', 'KRX:'), 'KSC': ('korea', 'KRX:'), 'KOE': ('korea', 'KRX:'), 'KSQ': ('korea', 'KRX:'), 'KOSDAQ': ('korea', 'KRX:'),
        }
        _hit = _map.get(_ex)
        if _hit and _code:
            return (_hit[0], _hit[1] + _code)
        return (None, t)  # unknown exchange -> honest unresolved
    if t.endswith('.TW') or t.endswith('.TWO'):
        return ('taiwan', 'TWSE:' + base)
    if t.endswith('.KS') or t.endswith('.KQ'):
        return ('korea', 'KRX:' + base)
    if t.endswith('.SS') or t.endswith('.SH'):
        return ('china', 'SSE:' + base)
    if t.endswith('.SZ'):
        return ('china', 'SZSE:' + base)
    if t.isdigit():
        if len(t) == 4:
            return ('taiwan', 'TWSE:' + t)
        if len(t) == 6 and t.startswith('688'):
            return ('china', 'SSE:' + t)
        if len(t) == 6:
            return ('korea', 'KRX:' + t)
    if base.isalpha():
        return ('america', base)
    return (None, t)


def fetch_foreign_analyst(market, tvsyms):
    """One TV {market}/scan POST over an explicit symbol set -> {tvsym: {FactSet analyst fields}}.
    Same columns as the US overlay; covers the local Asian lines. {} on any miss (never fabricates)."""
    want = [s for s in dict.fromkeys(tvsyms or []) if s]
    if not want:
        return {}
    out = {}
    try:
        payload = {'symbols': {'tickers': want}, 'columns': _FOREIGN_ANALYST_COLS}
        r = requests.post('https://scanner.tradingview.com/%s/scan' % market,
                          json=payload, headers={'User-Agent': UA}, timeout=40)
        if r.status_code != 200:
            log('    · [lookthrough] %s analyst HTTP %s (%d syms)' % (market, r.status_code, len(want)))
            return {}
        ncol = len(_FOREIGN_ANALYST_COLS)
        for d in r.json().get('data', []):
            vals = d.get('d') or []
            if len(vals) == ncol and d.get('s'):
                out[d['s']] = dict(zip(_FOREIGN_ANALYST_COLS, vals))
    except Exception as e:
        log('    · [lookthrough] %s analyst EXC %s' % (market, e))
    return out


def _lt_rating_label(mark):
    """TV recommendation_mark (1..5) -> Zacks-equivalent label."""
    try:
        m = float(mark)
    except (TypeError, ValueError):
        return None
    if m <= 1.5:
        return 'Strong Buy'
    if m <= 2.5:
        return 'Buy'
    if m <= 3.5:
        return 'Hold'
    if m <= 4.5:
        return 'Sell'
    return 'Strong Sell'


def _lt_news(query, n=2):
    import urllib.parse as _up
    try:
        url = ('https://news.google.com/rss/search?q=' + _up.quote(query)
               + '&hl=en-US&gl=US&ceid=US:en')
        ents = _fetch_rss_entries(url) or []
        heads = []
        for e in ents[:n]:
            t = (e.get('title') if isinstance(e, dict) else getattr(e, 'title', None))
            lnk = (e.get('link') if isinstance(e, dict) else getattr(e, 'link', None))
            if t:
                heads.append({'title': str(t)[:170], 'link': lnk})
        return heads
    except Exception:
        return []


def build_live_lookthrough(data, existing):
    """For each of the owner's ETFs: top-10 underlyings + weights, per-holding analyst rating +
    12-mo target + upside + next-Q EPS (Asian-capable TV FactSet overlay), and holdings/exchange/
    theme news. Emits data['live_lookthrough']. First run logs a COVERAGE PROBE per holding.
    Freeze-safe/additive; wrapped; carries last-good."""
    try:
        li = data.get('live_investment') or {}
        holdings = li.get('holdings') or []
        if not holdings:
            return
        funds = []
        probe = {'holdings_ok': 0, 'holdings_miss': 0, 'rated': 0, 'unrated': 0,
                 'eps': 0, 'news': 0, 'by_market': {}}
        # 1) pull top-10 underlyings per fund
        NEWS_TOP = 5
        for h in holdings:
            tk = h.get('ticker')
            src, key = _LT_HOLDINGS_SRC.get(tk, ('sa', tk))
            unders = []
            if src == 'metal':
                funds.append({'ticker': tk, 'name': h.get('name'), 'theme': h.get('theme'),
                              'kind': 'metal', 'holdings': [],
                              'note': 'Physical precious metal — no equity holdings; forward read is the gold/silver market outlook.',
                              'theme_news': _lt_news(_LT_THEME_NEWS.get(tk, tk))})
                continue
            try:
                if src == 'ishares':
                    rows = fetch_ishares_holdings(key)
                elif src == 'justetf':
                    _isin = key or h.get('isin')
                    _pairs = fetch_justetf_holdings(_isin, top=10, with_weights=True) if _isin else None
                    # v1.219.0: weights now kept (the fetch regex always captured them); suffix-aware
                    # merge preserved on the NAME side; each name resolved to a real ticker via the
                    # curated map so the existing overlay rates these rows like any iShares fund.
                    _parts = []
                    _sfx = re.compile(r'^(Inc\.?|Ltd\.?|LLC|L\.?P\.?|Corp\.?|Co\.?|plc|PLC|S\.?A\.?|N\.?V\.?|AG|SE|SpA|Oyj|AB|ASA|KGaA|Bhd)( [A-Z][A-Za-z]{2,15})?$', re.I)
                    for _n, _w in (_pairs or []):
                        _n = (_n or '').strip()
                        if not _n:
                            continue
                        if _parts and _sfx.match(_n):
                            _pn, _pw = _parts[-1]
                            _parts[-1] = (_pn + ', ' + _n, _pw if _pw is not None else _w)
                        else:
                            _parts.append((_n, _w))
                    rows = [{'ticker': _lt_resolve_name(_n), 'name': _n,
                             'weight': (round(_w, 2) if _w is not None else None)} for _n, _w in _parts]
                else:
                    rows = fetch_etf_holdings(key) or []
            except Exception:
                rows = []
            rows = [r for r in (rows or []) if r.get('ticker') or r.get('name')][:10]
            if rows:
                probe['holdings_ok'] += 1
            else:
                probe['holdings_miss'] += 1
            for r in rows:
                _exc = _lt_classify_exchange(r.get('ticker'), r.get('exchange'), r.get('location'))
                mkt, tvsym = _exc if _exc else (_lt_classify(r.get('ticker')) if r.get('ticker') else (None, None))
                unders.append({'ticker': r.get('ticker'), 'name': r.get('name') or r.get('ticker'),
                               'weight': r.get('weight'), 'market': mkt, 'tvsym': tvsym,
                               'rating': None, 'target': None, 'upside': None, 'eps_next_q': None,
                               'ytd': None, 'ret_1y': None, 'sma50': None, 'sma200': None,
                               'news': []})
            funds.append({'ticker': tk, 'name': h.get('name'), 'theme': h.get('theme'),
                          'kind': 'equity', 'holdings': unders, 'src': ('%s:%s' % (src, key))})
        # 2) batch analyst overlay per market (america + taiwan/korea/china)
        by_market = {}
        for f in funds:
            for u in f.get('holdings', []):
                if u['market']:
                    by_market.setdefault(u['market'], set()).add(u['tvsym'] if u['market'] != 'america' else u['ticker'])
        overlay = {}
        for mkt, syms in by_market.items():
            syms = list(syms)
            probe['by_market'][mkt] = {'n': len(syms), 'matched': 0}
            try:
                if mkt == 'america':
                    got = fetch_us_analyst_block(syms) or {}
                    overlay['america'] = got
                else:
                    got = fetch_foreign_analyst(mkt, syms) or {}
                    overlay[mkt] = got
                probe['by_market'][mkt]['matched'] = len(got)
            except Exception:
                overlay[mkt] = {}
        # 3) attach rating/target/upside/next-Q EPS + per-holding news (top-N by weight)
        def _num(x):
            try:
                return float(x)
            except (TypeError, ValueError):
                return None
        for f in funds:
            hs = f.get('holdings', [])
            for i, u in enumerate(hs):
                mkt = u['market']
                rec = None
                if mkt == 'america':
                    rec = (overlay.get('america') or {}).get(u['ticker'])
                elif mkt:
                    rec = (overlay.get(mkt) or {}).get(u['tvsym'])
                    if rec and rec.get('description') and (not u.get('name') or u.get('name') == u.get('ticker')):
                        u['name'] = str(rec['description'])[:60]   # v1.219.1: real company name from TV
                if rec:
                    u['rating'] = _lt_rating_label(rec.get('recommendation_mark'))
                    u['rating_mark'] = _num(rec.get('recommendation_mark'))
                    tgt = _num(rec.get('price_target_average'))
                    px = _num(rec.get('close'))
                    u['target'] = tgt
                    u['upside'] = ((tgt / px - 1.0) * 100.0) if (tgt and px) else None
                    u['eps_next_q'] = _num(rec.get('earnings_per_share_forecast_next_fq'))
                    u['ytd']    = _num(rec.get('Perf.YTD'))
                    u['ret_1y'] = _num(rec.get('Perf.Y'))
                    u['sma50']  = _num(rec.get('SMA50'))
                    u['sma200'] = _num(rec.get('SMA200'))
                    if u.get('ytd') is not None or u.get('sma200') is not None:
                        probe['trend'] = probe.get('trend', 0) + 1
                    if u['rating']:
                        probe['rated'] += 1
                    else:
                        probe['unrated'] += 1
                    if u['eps_next_q'] is not None:
                        probe['eps'] += 1
                else:
                    probe['unrated'] += 1
                if i < NEWS_TOP:                      # per-holding company news (top weights only)
                    u['news'] = _lt_news((u['name'] or u['ticker']) + ' stock')
                    if u['news']:
                        probe['news'] += 1
            # fund-level exchange + theme news
            mkts = [u['market'] for u in hs if u['market']]
            dom = max(set(mkts), key=mkts.count) if mkts else 'america'
            f['exchange'] = dom
            f['exchange_news'] = _lt_news(_LT_EXCH_NEWS.get(dom, 'stock market'))
            f['theme_news'] = _lt_news(_LT_THEME_NEWS.get(f['ticker'], f.get('theme') or ''))
        data['live_lookthrough'] = {'as_of': dt.date.today().isoformat(), 'funds': funds, 'probe': probe,
                                    'forward_note': ('TV FactSet serves next-quarter EPS + 12-month target only; '
                                                     '6/9-month quarterly EPS is not in the free feed and shows "—".')}
        pm = probe['by_market']
        log('  [Live Lookthrough] %d fund(s); holdings %d ok/%d miss; rated %d/%d; eps %d; trend %d; news %d; markets %s'
            % (len(funds), probe['holdings_ok'], probe['holdings_miss'], probe['rated'],
               probe['rated'] + probe['unrated'], probe['eps'], probe.get('trend', 0), probe['news'],
               ', '.join('%s %d/%d' % (m, pm[m]['matched'], pm[m]['n']) for m in pm)))
        # per-holding coverage probe (first-run visibility of what actually resolved)
        for f in funds:
            for u in f.get('holdings', [])[:10]:
                log('    · [probe] %-5s %-22s w=%-5s %-8s %-14s rating=%-11s tgt=%-7s eps_nq=%s'
                    % (f['ticker'], (u['name'] or '')[:22], ('%.1f%%' % u['weight']) if u.get('weight') is not None else '—',
                       u['market'] or 'unresolved', ((u['tvsym'] or u['ticker']) or '\u2014')[:14],
                       u['rating'] or '—', ('%.0f' % u['target']) if u.get('target') else '—',
                       ('%.2f' % u['eps_next_q']) if u.get('eps_next_q') is not None else '—'))
    except Exception as e:
        log('  [Live Lookthrough] build failed (%s: %s) — carrying last-good' % (type(e).__name__, e))
        if existing and existing.get('live_lookthrough'):
            data['live_lookthrough'] = existing['live_lookthrough']


def build_li_statements(li, existing=None):
    """v1.238.2: WEEKLY + MONTHLY portfolio statements (owner request) from the daily history
    store the engine already keeps. Each statement = period NAV start/end, period P&L $/%%,
    since-inception %%, and (where per-holding px exist at both period boundaries) that period's
    best & worst holding. A period is 'complete' once a newer period has started; the most recent
    is marked in-progress. Honest 'accruing' until the first period completes. No new fetches."""
    import datetime as _sd
    hist = [h for h in (li.get('history') or []) if h.get('date') and h.get('nav')]
    if not hist:
        li['statements'] = {'weekly': [], 'monthly': [], 'note': 'no history yet'}
        return
    hist.sort(key=lambda h: h['date'])
    incept_nav = hist[0]['nav']
    isin_ticker = {h.get('isin'): h.get('ticker') for h in (li.get('holdings') or []) if h.get('isin')}

    def _key(dstr, mode):
        dt = _sd.date.fromisoformat(dstr)
        if mode == 'weekly':
            iso = dt.isocalendar()
            return '%d-W%02d' % (iso[0], iso[1])
        return dt.strftime('%Y-%m')

    def _build(mode):
        groups = {}
        for h in hist:
            groups.setdefault(_key(h['date'], mode), []).append(h)
        keys = sorted(groups)
        # v1.272.0: back out capital flows (deposits/withdrawals) so period P&L is pure market movement.
        # The 2026-07-17 AED withdrawal (-$4,999.97) was previously counted as a market LOSS in the July
        # statement and the since-inception figure -- an accounting flaw the owner's IBKR reconciliation exposed.
        _flows = ((li.get('capital') or {}).get('flows') or [])
        _incept_d = hist[0]['date'] if hist else None
        def _flow_sum(d1, d2, excl_inception=True):
            t = 0.0
            for f in _flows:
                fd = f.get('date') or ''
                if excl_inception and fd <= (_incept_d or ''):
                    continue
                if d1 <= fd <= d2:
                    t += (f.get('usd') or 0)
            return t
        out = []; prev_end = None
        for i, k in enumerate(keys):
            snaps = groups[k]; first, last = snaps[0], snaps[-1]
            base = prev_end if prev_end is not None else first['nav']
            nav_end = last['nav']
            _fl_p = _flow_sum(first['date'], last['date'])
            pnl = nav_end - base - _fl_p
            best = worst = None
            # v1.331.0: measure best/worst from the first PRICE-BEARING snapshot in the period to the
            # last one. Inception days can carry NAV-only snapshots (no per-fund px yet) -- taking snaps[0]
            # literally blanked the whole week (the W28 dash). Using the first/last snapshots that actually
            # hold prices uses the real recorded data and heals any single-day gap generically.
            _px_snaps = [_s for _s in snaps if (_s.get('px') or {})]
            best_px_start = best_px_end = None
            if len(_px_snaps) > 1:
                _pf, _pl = _px_snaps[0], _px_snaps[-1]
                best_px_start, best_px_end = _pf.get('date'), _pl.get('date')
                moves = []
                for isin, p1 in (_pl.get('px') or {}).items():
                    p0 = (_pf.get('px') or {}).get(isin)
                    if p0 and p1:
                        moves.append((isin_ticker.get(isin, isin), (p1 / p0 - 1) * 100.0))
                if moves:
                    moves.sort(key=lambda x: x[1])
                    worst = {'ticker': moves[0][0], 'pct': round(moves[0][1], 2)}
                    best = {'ticker': moves[-1][0], 'pct': round(moves[-1][1], 2)}
            out.append({
                'period': k, 'start': first['date'], 'end': last['date'], 'days': len(snaps),
                'nav_start': round(base, 2), 'nav_end': round(nav_end, 2),
                'pnl_usd': round(pnl, 2), 'pnl_pct': round(pnl / base * 100.0, 3) if base else None,
                'flows_usd': (round(_fl_p, 2) if _fl_p else 0.0),
                'since_inception_pct': (round((nav_end - incept_nav - _flow_sum(_incept_d or '', last['date'])) / incept_nav * 100.0, 3) if incept_nav else None),
                'best': best, 'worst': worst, 'complete': (i < len(keys) - 1),
                'best_px_start': best_px_start, 'best_px_end': best_px_end})
            prev_end = nav_end
        return out

    # v1.272.0 per-holding attribution: the daily history stores per-ISIN prices, so each fund's
    # dollar P&L over 7d/30d windows is reconstructable exactly (shares constant since inception).
    try:
        _fx = li.get('fx') or {}
        _last_px = (hist[-1].get('px') or {}) if hist else {}
        def _px_at(days_back):
            import datetime as _dt2
            tgt = (_dt2.date.fromisoformat(hist[-1]['date']) - _dt2.timedelta(days=days_back)).isoformat()
            cand = [s2 for s2 in hist if s2['date'] <= tgt and s2.get('px')]
            return (cand[-1]['px'] if cand else None)
        _px7, _px30 = _px_at(7), _px_at(30)
        for _h in (li.get('holdings') or []):
            _iz, _sh = _h.get('isin'), (_h.get('shares') or 0)
            _fxr = _fx.get(_h.get('ccy') or 'USD', 1.0)
            _pn = _last_px.get(_iz)
            for _tag, _pm in (('pnl_wow_usd', _px7), ('pnl_mom_usd', _px30)):
                _p0 = (_pm or {}).get(_iz) if _pm else None
                _h[_tag] = (round(_sh * (_pn - _p0) * _fxr, 2) if (_pn and _p0) else None)
    except Exception:
        pass
    weekly, monthly = _build('weekly'), _build('monthly')
    n_wk_done = sum(1 for s in weekly if s['complete'])
    n_mo_done = sum(1 for s in monthly if s['complete'])
    li['statements'] = {
        'as_of': hist[-1]['date'], 'inception': hist[0]['date'],
        'weekly': weekly, 'monthly': monthly,
        'weekly_note': None if n_wk_done else 'first full weekly statement completes at the first week-end after inception',
        'monthly_note': None if n_mo_done else 'first full monthly statement completes at month-end'}
    log(f"  [Statements] weekly {len(weekly)} ({n_wk_done} complete) | monthly {len(monthly)} "
        f"({n_mo_done} complete); from {len(hist)}-day history since {hist[0]['date']}")


