# ---- (B) World-stock scan (Phase 1) ----------------------------------------------
# Scans major world exchanges for large-cap STOCKS with the fundamental columns the
# lenses need. Region strings already proven live for the ETF/LEI scans. DEFENSIVE:
# any region that 403s / returns nothing is skipped; an empty result is a clean no-op.
_WORLD_STOCK_REGIONS = ['uk', 'germany', 'france', 'netherlands', 'switzerland',
                        'italy', 'spain', 'sweden', 'japan', 'canada', 'australia',
                        'india', 'hongkong']
_WORLD_STOCK_COLS = ['description', 'close', 'market_cap_basic', 'sector', 'currency',
                     'total_revenue_yoy_growth_ttm', 'earnings_per_share_diluted_yoy_growth_ttm',
                     'return_on_invested_capital', 'gross_margin', 'operating_margin',
                     'net_margin', 'debt_to_equity', 'price_earnings_ttm', 'dividend_yield_recent',
                     'Perf.YTD', 'Perf.Y', 'Perf.3Y', 'Perf.5Y',
                    'total_revenue_yoy_growth_fq', 'earnings_per_share_diluted_yoy_growth_fq',
                    'return_on_equity']
_WORLD_MIN_MCAP = 3_000_000_000   # $3bn floor (large/mid-cap, comparable to foundation)

def build_world_stocks(data, existing):
    """v1.313.0 — Phase 1. One paginated stock scan per major world exchange with the
    lens fundamentals. Emits data['world_stocks'] = {as_of, by_region, n, regions_live}.
    DEFENSIVE: never raises; an unreachable region is skipped; empty result carries last-good."""
    prev = (existing or {}).get('world_stocks') or {}
    try:
        recs = []
        live_regions = []
        for region in _WORLD_STOCK_REGIONS:
            try:
                payload = {
                    'columns': _WORLD_STOCK_COLS,
                    'filter': [
                        {'left': 'type', 'operation': 'equal', 'right': 'stock'},
                        {'left': 'market_cap_basic', 'operation': 'egreater', 'right': _WORLD_MIN_MCAP},
                    ],
                    'sort': {'sortBy': 'market_cap_basic', 'sortOrder': 'desc'},
                    'range': [0, 200], 'markets': [region],
                }
                r = requests.post(f'https://scanner.tradingview.com/{region}/scan',
                                  json=payload, headers={'User-Agent': UA}, timeout=30)
                if r.status_code != 200:
                    log(f'    [world-stocks] {region}: HTTP {r.status_code} — skipped')
                    continue
                batch = (r.json() or {}).get('data') or []
                if not batch:
                    continue
                n_reg = 0
                for row in batch:
                    d = dict(zip(_WORLD_STOCK_COLS, row.get('d') or []))
                    sym = row.get('s', '')                    # e.g. LSE:BA. / XETR:RHM
                    mc = d.get('market_cap_basic') or 0
                    if not mc or d.get('close') is None:
                        continue
                    recs.append({
                        'sym': sym, 'ticker': sym.split(':')[-1], 'region': region,
                        'name': d.get('description') or sym.split(':')[-1],
                        'sector': d.get('sector') or 'Unknown',
                        'currency': d.get('currency'),
                        'price': d.get('close'), 'market_cap': mc, 'market_cap_m': round(mc / 1e6),
                        'rev_growth': d.get('total_revenue_yoy_growth_ttm'),
                        'eps_growth': d.get('earnings_per_share_diluted_yoy_growth_ttm'),
                        'roic': d.get('return_on_invested_capital'),
                        'gross_margin': d.get('gross_margin'),
                        'op_margin': d.get('operating_margin'),
                        'net_margin': d.get('net_margin'),
                        'de': d.get('debt_to_equity'), 'pe': d.get('price_earnings_ttm'),
                        'div_yield': d.get('dividend_yield_recent'),
                        'ytd': d.get('Perf.YTD'), 'perf_1y': d.get('Perf.Y'),
                        'perf_3y': d.get('Perf.3Y'), 'perf_5y': d.get('Perf.5Y'),
                        'rev_growth_fq': d.get('total_revenue_yoy_growth_fq'),
                        'eps_growth_fq': d.get('earnings_per_share_diluted_yoy_growth_fq'),
                        'roe': d.get('return_on_equity'),
                    })
                    n_reg += 1
                if n_reg:
                    live_regions.append(f'{region}:{n_reg}')
            except Exception as _re:
                log(f'    [world-stocks] {region}: {type(_re).__name__} — skipped')
                continue
        # v1.313.1 FIX: strip US-company cross-listings (foreign secondary lines of US giants —
        # Micron/Lilly/Lam/Seagate showed up as 0R2T/MTE/869020 etc.) and DEDUP by company, so the
        # world universe is genuinely non-US and no name repeats across venues. Matches against the
        # ~1,900-name US foundation universe by normalized name/ticker (same idea as Whale-Watch norm).
        import re as _re
        def _wnorm(s): return _re.sub(r'[^a-z0-9]', '', (s or '').lower())
        _fu = data.get('foundation_universe') or []
        _us_names = {_wnorm(r.get('name')) for r in _fu if r.get('name')}
        _us_ticks = {(r.get('ticker') or '').upper() for r in _fu if r.get('ticker')}
        _clean = [r for r in recs
                  if _wnorm(r.get('name')) not in _us_names
                  and (r.get('ticker') or '').upper() not in _us_ticks]
        _by = {}
        for r in _clean:
            k = _wnorm(r.get('name'))
            if not k:
                continue
            if k not in _by or (r.get('market_cap') or 0) > (_by[k].get('market_cap') or 0):
                _by[k] = r
        _n_raw = len(recs)
        recs = sorted(_by.values(), key=lambda r: -(r.get('market_cap') or 0))
        log(f"  [World stocks] filtered {_n_raw} raw -> {len(_clean)} non-US -> {len(recs)} unique companies")
        # fundamentals coverage sanity (proves the feed actually carries them)
        fcov = sum(1 for r in recs if r.get('rev_growth') is not None or r.get('roic') is not None)
        data['world_stocks'] = {
            'as_of': dt.date.today().isoformat(), 'n': len(recs),
            'regions_live': live_regions, 'fund_coverage': fcov, 'recs': recs,
        }
        if not recs and prev.get('recs'):
            data['world_stocks'] = prev                      # never blank a good prior feed
        log(f"  [World stocks] {len(recs)} names across {len(live_regions)} region(s); "
            f"fundamentals on {fcov}/{len(recs) or 1}")
    except Exception as e:
        log(f'  [World stocks] failed: {e} — carrying last-good')
        data['world_stocks'] = prev


