def build_policy_catalyst(data, existing):
    """v1.313.0 — Tab 15 Policy-Catalyst. Maps current, sourced policy catalysts to the tickers
    they move, tags accessibility (US / ADR / foreign) and ENGINE OVERLAP (does the dashboard
    already surface this name on another tab?). DISPLAY/context only; additive; carries last-good."""
    prev = (existing or {}).get('policy_catalyst') or {}
    try:
        # build the set of tickers the engines already surfaced (for overlap tags)
        engine_names = set()
        for r in (data.get('explosive_us') or []):
            if isinstance(r, dict) and r.get('ticker'): engine_names.add(r['ticker'])
        for r in (data.get('us_multibagger') or []):
            if isinstance(r, dict) and r.get('ticker'): engine_names.add(r['ticker'])
        for b in ((data.get('m1_buylist') or {}).get('buys') or []):
            if b.get('ticker'): engine_names.add(b['ticker'])
        rt = data.get('recommended_tab') or {}
        for sec in [rt.get('strategic_core') or []] + list((rt.get('tactical') or {}).values()):
            for r in sec:
                if r.get('ticker'): engine_names.add(r['ticker'])
        zr = data.get('zacks_ranks') or {}
        cats = []
        n_links = 0
        for pc in _POLICY_CATALYSTS:
            tk_rows = []
            for tk, label, access in pc['tickers']:
                n_links += 1
                _fx = _POLICY_FX.get((pc['id'], tk), ('tailwind', label + '.'))   # v1.439.0
                tk_rows.append({
                    'ticker': tk, 'label': label, 'access': access,
                    'on_engine': tk in engine_names,
                    'zacks': zr.get(tk),
                    'effect': _fx[0], 'why': _fx[1],
                })
            cats.append({'id': pc['id'], 'category': pc['category'], 'headline': pc['headline'],
                         'as_of': pc['as_of'], 'source': pc['source'], 'tickers': tk_rows})
        # group by category for the tab
        by_cat = {}
        for c in cats:
            by_cat.setdefault(c['category'], []).append(c)
        data['policy_catalyst'] = {
            'as_of': dt.date.today().isoformat(),
            'note': 'Curated, dated, source-cited policy catalysts -> affected tickers. '
                    'Refreshed when policy changes. Not a screen; a watch layer.',
            'categories': list(by_cat.keys()), 'by_category': by_cat, 'items': cats,
            'n_links': n_links, 'n_categories': len(by_cat),
        }
        log(f"  [Policy catalyst] {len(cats)} catalysts / {n_links} ticker-links / {len(by_cat)} categories")
    except Exception as e:
        log(f'  [Policy catalyst] failed: {e} — carrying last-good')
        data['policy_catalyst'] = prev


# ---- (D) Global Discovery tab (Phases 2/3b/4) ------------------------------------
# Runs the SAME lens family the US engine runs, on the WORLD stock pool (+ US foundation),
# so the world tab surfaces multibaggers/moats/turnarounds — not just a moat screen.
# Overlap-check against engine tabs; amber concentration guardrail. DEFENSIVE: if the
# world feed hasn't confirmed yet, emits a 'populating' status the tab renders gracefully.
def _gd_lenses(rec):
    """Return the list of lenses a world record fires, from generic TV fundamentals only."""
    fired = []
    rg = rec.get('rev_growth'); eg = rec.get('eps_growth'); roic = rec.get('roic')
    gm = rec.get('gross_margin'); om = rec.get('op_margin')
    ytd = rec.get('ytd'); p1 = rec.get('perf_1y'); dy = rec.get('div_yield')
    # moat: durable high returns on capital + fat margins
    if isinstance(roic, (int, float)) and roic >= 15 and isinstance(gm, (int, float)) and gm >= 40:
        fired.append('moat')
    # quality-growth: strong rev + eps growth with decent margins
    if isinstance(rg, (int, float)) and rg >= 15 and isinstance(eg, (int, float)) and eg >= 15:
        fired.append('growth')
    # multibagger shape: high growth + high roic (the compounder profile)
    if isinstance(rg, (int, float)) and rg >= 25 and isinstance(roic, (int, float)) and roic >= 12:
        fired.append('multibagger')
    # momentum: strong 1-year trend
    if isinstance(p1, (int, float)) and p1 >= 40:
        fired.append('momentum')
    # turnaround: strong recent trend off a weak base (eps inflecting up hard)
    if isinstance(eg, (int, float)) and eg >= 30 and isinstance(ytd, (int, float)) and ytd >= 20:
        fired.append('turnaround')
    # income: real dividend + profitability
    if isinstance(dy, (int, float)) and dy >= 3 and isinstance(om, (int, float)) and om >= 10:
        fired.append('income')
    return fired

# ══════════════════════════════════════════════════════════════════════════════
# v1.314.0 — QUARTERLY ACCELERATION ENGINE (owner-directed, Tab 20 Global Discovery)
#   Criteria (owner's spec, streak-tiered per the workable-list recommendation):
#     - EPS growth >= 30% YoY-per-quarter, RISING/sustained for >=3 (tier), >=4, >=5..10 consecutive quarters
#     - Sales growth >= 25% YoY-per-quarter over the same run
#     - ROE 25%-50%, held in EACH of the last 3 years (stability)
#     - OMIT one-off gains: a quarter whose EPS jump is not backed by sales/margin is flagged & excluded
#     - DECELERATION ALARM: 2 consecutive quarters of slowing growth in BOTH EPS and sales -> dashboard-wide
#   Data: TV `_fq` columns (latest quarter, universe-wide — as the scanner already fetches) narrow the
#   universe to candidates; macrotrends supplies the quarterly SERIES for those candidates (backup depth).
#   Uses YoY-per-quarter (same quarter a year ago) NOT raw QoQ — seasonality-safe (raw QoQ returns ~zero,
#   proven on real ASML/TSM data in the sandbox). Live series fetch confirms on the runner (TV 403 + macrotrends
#   per-name from sandbox); the CRITERIA LOGIC is audited against real ASML/TSM quarterly data.
# ══════════════════════════════════════════════════════════════════════════════

_QA_EPS_MIN = 30.0
_QA_SALES_MIN = 25.0
_QA_NM_EPS = 25.0
_QA_NM_SALES = 20.0
_QA_ONEOFF_CAP = 300.0    # owner's "omit extraordinary gains": >300% YoY-per-quarter = base-effect/one-off, excluded
_QA_ANN_MIN = 50.0        # owner's "50% higher annual growth rates": TTM EPS or sales growth >= 50% required
_QA_ROE_LO, _QA_ROE_HI = 25.0, 50.0
_QA_XC_LO, _QA_XC_HI = 300_000_000, 10_000_000_000   # small+MID cap extra scan band (owner: include mid cap)
_QA_MOAT_ETFS = ('moat', 'motg')   # VanEck US + GLOBAL wide-moat ETFs = the full Morningstar wide-moat membership
_QA_GOAT_ISIN = 'IE00BL0BMZ89'
_QA_PINNED = ('asml', 'sivers')   # owner's always-visible names: shown pinned with live gate diagnostics
_QA_PIN_SYMS = {'NASDAQ:ASML': 'ASML', 'OMXSTO:SIVE': 'Sivers Semiconductors AB'}   # direct TV fetch, bypasses ALL market-cap floors

def _qa_norm(s):
    return re.sub(r'[^a-z0-9]', '', (s or '').lower())

def _qa_moat_match(name, moat_set):
    n = _qa_norm(name)
    if not n:
        return False
    if n in moat_set:
        return True
    for m in moat_set:
        if len(m) >= 8 and (n.startswith(m) or m.startswith(n)):
            return True
    return False

def _qa_moat_set(existing):
    """FULL Morningstar wide-moat membership: complete holdings of VanEck MOAT (US) + MOTG (Global) from
    stockanalysis.com /etf/{sym}/holdings/ (proven runner plumbing) -- these funds fully replicate the
    Morningstar Wide Moat Focus indexes, so their holdings ARE the wide-moat list. Direct morningstar.com
    scraping is server-side scrambled for non-subscribers (tested), so the index membership is the honest
    complete source. Fallback: justETF GOAT top-10 (string return parsed correctly). Cached across runs."""
    names = set()
    for sym in _QA_MOAT_ETFS:
        try:
            r = requests.get(f'https://stockanalysis.com/etf/{sym}/holdings/',
                             headers={'User-Agent': UA, 'Accept-Language': 'en'}, timeout=20)
            if r.status_code != 200 or not r.text:
                continue
            block = r.text
            # holdings table rows: ticker + company name cells; strip tags, take plausible company-name strings
            rows = re.findall(r'<tr[^>]*>(.*?)</tr>', block, re.S)
            got = 0
            for row in rows:
                cells = [re.sub(r'<[^>]+>', '', c).strip() for c in re.findall(r'<td[^>]*>(.*?)</td>', row, re.S)]
                for c in cells:
                    c = c.replace('&amp;', '&').replace('&#39;', "'")
                    if 6 <= len(c) <= 60 and re.search(r'[a-z]', c) and not re.match(r'^[\d.,%$-]+$', c):
                        names.add(_qa_norm(c)); got += 1
                        break
            log(f'    · [moat-set] {sym}: {got} holding rows parsed')
        except Exception as e:
            log(f'    · [moat-set] {sym} failed: {type(e).__name__}')
    if not names:
        try:
            h = fetch_justetf_holdings(_QA_GOAT_ISIN, top=12)
            if isinstance(h, str):
                names = {_qa_norm(x) for x in h.split(',') if x.strip()}
            elif isinstance(h, list):
                names = {_qa_norm(x if isinstance(x, str) else (x[0] if x else '')) for x in h if x}
        except Exception:
            pass
    if not names and (existing or {}).get('qaccel_moat_set'):
        names = set(existing['qaccel_moat_set'])
    return names

def _qa_extra_recs():
    """Small + MID cap acceleration universe ($300M-$10bn, sales growth >=20% filter, one bounded TV scan
    per region). Same columns as the world scan incl. TTM growth (for the annual >=50% gate)."""
    recs = []
    for region in _WORLD_STOCK_REGIONS:
        try:
            payload = {
                'columns': _WORLD_STOCK_COLS,
                'filter': [
                    {'left': 'type', 'operation': 'equal', 'right': 'stock'},
                    {'left': 'market_cap_basic', 'operation': 'egreater', 'right': _QA_XC_LO},
                    {'left': 'market_cap_basic', 'operation': 'eless', 'right': _QA_XC_HI},
                    {'left': 'total_revenue_yoy_growth_fq', 'operation': 'egreater', 'right': _QA_NM_SALES},
                ],
                'sort': {'sortBy': 'total_revenue_yoy_growth_fq', 'sortOrder': 'desc'},
                'range': [0, 80], 'markets': [region],
            }
            r = requests.post(f'https://scanner.tradingview.com/{region}/scan',
                              json=payload, headers={'User-Agent': UA}, timeout=30)
            if r.status_code != 200:
                continue
            for row in (r.json() or {}).get('data') or []:
                d = dict(zip(_WORLD_STOCK_COLS, row.get('d') or []))
                sym = row.get('s', ''); mc = d.get('market_cap_basic') or 0
                if not mc or d.get('close') is None:
                    continue
                recs.append({'sym': sym, 'ticker': sym.split(':')[-1], 'region': region,
                    'name': d.get('description') or sym.split(':')[-1], 'sector': d.get('sector') or 'Unknown',
                    'market_cap': mc, 'roe': d.get('return_on_equity'),
                    'rev_growth_fq': d.get('total_revenue_yoy_growth_fq'),
                    'eps_growth_fq': d.get('earnings_per_share_diluted_yoy_growth_fq'),
                    'rev_growth': d.get('total_revenue_yoy_growth_ttm'),
                    'eps_growth': d.get('earnings_per_share_diluted_yoy_growth_ttm'),
                    'roic': d.get('return_on_invested_capital'), 'pe': d.get('price_earnings_ttm'),
                    'ytd': d.get('Perf.YTD'), 'perf_1y': d.get('Perf.Y'), 'perf_3y': d.get('Perf.3Y'),
                    'smallcap': mc < 3_000_000_000, 'midcap': 3_000_000_000 <= mc < _QA_XC_HI})
        except Exception:
            continue
    return recs

def _qa_pinned_recs():
    """Direct TV symbols-POST for the pinned names (proven pattern used for futures/index quotes),
    so micro-caps like Sivers (~$100M, below every scan floor) always resolve with the same fields."""
    cols = ['description', 'close', 'market_cap_basic', 'sector', 'return_on_equity',
            'total_revenue_yoy_growth_fq', 'earnings_per_share_diluted_yoy_growth_fq',
            'total_revenue_yoy_growth_ttm', 'earnings_per_share_diluted_yoy_growth_ttm',
            'Perf.YTD', 'Perf.Y', 'Perf.3Y']
    out = []
    try:
        r = requests.post('https://scanner.tradingview.com/global/scan',
                          json={'symbols': {'tickers': list(_QA_PIN_SYMS.keys())}, 'columns': cols},
                          headers={'User-Agent': UA}, timeout=20)
        if r.status_code != 200:
            return out
        for row in (r.json() or {}).get('data') or []:
            d = dict(zip(cols, row.get('d') or []))
            sym = row.get('s', '')
            out.append({'sym': sym, 'ticker': sym.split(':')[-1],
                'name': d.get('description') or _QA_PIN_SYMS.get(sym) or sym,
                'region': 'pinned', 'sector': d.get('sector'),
                'market_cap': d.get('market_cap_basic'), 'roe': d.get('return_on_equity'),
                'rev_growth_fq': d.get('total_revenue_yoy_growth_fq'),
                'eps_growth_fq': d.get('earnings_per_share_diluted_yoy_growth_fq'),
                'rev_growth': d.get('total_revenue_yoy_growth_ttm'),
                'eps_growth': d.get('earnings_per_share_diluted_yoy_growth_ttm'),
                'ytd': d.get('Perf.YTD'), 'perf_1y': d.get('Perf.Y'), 'perf_3y': d.get('Perf.3Y')})
    except Exception:
        pass
    return out

def build_quarterly_acceleration(data, existing):
    """v1.314.4 -- TIGHTENED to the owner's original prompt so few names qualify. FULL tier requires ALL of:
    EPS >=30% AND sales >=25% (latest quarter vs same quarter a year ago, TV _fq -- the Explosive-tab feed);
    one-off guard (either >300% = extraordinary-gain base effect, excluded); ROE inside 25-50%; and annual
    (TTM) EPS or sales growth >=50%. NEAR-MISS (amber) = EPS >=25% & sales >=20%, one-off-guarded, ROE/annual
    not required (keeps ASML-type names visible). Universe = world large caps + small/MID-cap scan
    ($300M-$10bn). Wide-moat label from the FULL Morningstar wide-moat membership (MOAT+MOTG holdings).
    Rolling store builds the consecutive-quarter streak; deceleration alarm dashboard-wide. Defensive.
    3-year ROE stability note: TV supplies current ROE; the store accumulates ROE history for the stability
    test as scans build up (honest limitation of a single snapshot)."""
    prev = (existing or {}).get('quarterly_acceleration') or {}
    store = dict((existing or {}).get('qaccel_store') or {})
    try:
        ws = list((data.get('world_stocks') or {}).get('recs') or [])
        xc = _qa_extra_recs()
        pr = _qa_pinned_recs()
        moat_set = _qa_moat_set(existing)
        today = dt.date.today().isoformat()
        seen = set(); picks = []; alarms = []
        for r in ws + xc:
            eq = r.get('eps_growth_fq'); rq = r.get('rev_growth_fq'); roe = r.get('roe')
            tk = r.get('ticker')
            if not tk or tk in seen or not (isinstance(eq, (int, float)) and isinstance(rq, (int, float))):
                continue
            seen.add(tk)
            hist = store.get(tk) or []
            last = hist[-1] if hist else None
            if (not last) or abs((last.get('eps') if last.get('eps') is not None else -1e9) - eq) > 0.05 \
                          or abs((last.get('rev') if last.get('rev') is not None else -1e9) - rq) > 0.05:
                hist = (hist + [{'d': today, 'eps': eq, 'rev': rq, 'roe': roe}])[-12:]
                store[tk] = hist
            streak = 0
            for h in reversed(hist):
                if (h.get('eps') or 0) >= _QA_EPS_MIN and (h.get('rev') or 0) >= _QA_SALES_MIN:
                    streak += 1
                else:
                    break
            streak = min(streak, 10)
            # v1.314.10 None-guard: bf entries can carry a None leg (the v1.314.9 rev gap) and an
            # unguarded < chain raised TypeError, silently reverting the whole tab to last-good.
            def _dv(h2, k2):
                v2 = h2.get(k2)
                return v2 if isinstance(v2, (int, float)) else 0
            decel = len(hist) >= 3 \
                and _dv(hist[-1], 'eps') < _dv(hist[-2], 'eps') < _dv(hist[-3], 'eps') \
                and _dv(hist[-1], 'rev') < _dv(hist[-2], 'rev') < _dv(hist[-3], 'rev')
            if decel:
                alarms.append({'ticker': tk, 'name': r.get('name'), 'region': r.get('region')})
            oneoff = eq > _QA_ONEOFF_CAP or rq > _QA_ONEOFF_CAP
            roe_ok = isinstance(roe, (int, float)) and _QA_ROE_LO <= roe <= _QA_ROE_HI
            eg = r.get('eps_growth'); rg = r.get('rev_growth')
            ann_ok = (isinstance(eg, (int, float)) and eg >= _QA_ANN_MIN) or \
                     (isinstance(rg, (int, float)) and rg >= _QA_ANN_MIN)
            full = (eq >= _QA_EPS_MIN and rq >= _QA_SALES_MIN and not oneoff and roe_ok and ann_ok)
            near = (not full) and (not oneoff) and eq >= _QA_NM_EPS and rq >= _QA_NM_SALES
            if full or near:
                moat = 'wide' if _qa_moat_match(r.get('name'), moat_set) else None
                tier = ('elite' if streak >= 5 else 'strong' if streak >= 4 else 'watch' if streak >= 3 else 'new') if full else 'nearmiss'
                picks.append({'ticker': tk, 'sym': r.get('sym'), 'name': r.get('name'), 'region': r.get('region'),
                    'sector': r.get('sector'), 'eps_fq': round(eq, 1), 'rev_fq': round(rq, 1), 'streak': streak,
                    'tier': tier, 'roe': roe, 'roe_ok': roe_ok, 'ann_eps': eg, 'ann_rev': rg,
                    'decelerating': decel, 'moat': moat,
                    'smallcap': bool(r.get('smallcap')), 'midcap': bool(r.get('midcap')),
                    'roic': r.get('roic'), 'pe': r.get('pe'),
                    'ytd': r.get('ytd'), 'perf_1y': r.get('perf_1y'), 'perf_3y': r.get('perf_3y')})
        # ── v1.314.9 TRUE CONSECUTIVE-QUARTER BACKFILL + ACCELERATION ─────────────────────────
        # For the full-tier winners + pinned names ONLY (budget-capped), pull the PUBLISHED quarterly
        # YoY series and replace the days-old forward store with real quarters: streak becomes a
        # verified count of consecutive quarters clearing BOTH bars, and accel fires when the growth
        # RATE itself rose vs the prior quarter on BOTH lines (growth on growth). Cached 14d.
        qcache = dict((existing or {}).get('qaccel_qhist') or {})
        _bf_targets = []
        _seen_bf = set()
        for pk in picks:
            if pk['tier'] != 'nearmiss' and pk['ticker'] not in _seen_bf:
                _bf_targets.append((pk['ticker'], pk.get('sym'), pk.get('region')))
                _seen_bf.add(pk['ticker'])
        for nmp in _QA_PINNED:
            for r0 in pr + ws + xc:
                if nmp in (r0.get('name') or '').lower() and r0.get('ticker') not in _seen_bf:
                    _bf_targets.append((r0.get('ticker'), r0.get('sym'), r0.get('region')))
                    _seen_bf.add(r0.get('ticker'))
                    break
        # v1.314.12: also backfill the 3 CLOSEST near-misses -- same ranking the index's radar
        # cards use (fewest failed gates first, then strongest combined quarterly growth) -- so
        # their champion-format cards draw real per-quarter bars instead of a placeholder.
        def _nm_fails(p2):
            f2 = 0
            if not (isinstance(p2.get('eps_fq'), (int, float)) and p2['eps_fq'] >= 30): f2 += 1
            if not (isinstance(p2.get('rev_fq'), (int, float)) and p2['rev_fq'] >= 25): f2 += 1
            if (p2.get('eps_fq') or 0) > 300 or (p2.get('rev_fq') or 0) > 300: f2 += 1
            if not (isinstance(p2.get('roe'), (int, float)) and 25 <= p2['roe'] <= 50): f2 += 1
            if not ((isinstance(p2.get('ann_eps'), (int, float)) and p2['ann_eps'] >= 50)
                    or (isinstance(p2.get('ann_rev'), (int, float)) and p2['ann_rev'] >= 50)): f2 += 1
            return f2
        _nm_sorted = sorted([p2 for p2 in picks if p2.get('tier') == 'nearmiss'],
                            key=lambda p2: (_nm_fails(p2), -((p2.get('eps_fq') or 0) + (p2.get('rev_fq') or 0))))
        for p2 in _nm_sorted[:3]:
            if p2['ticker'] not in _seen_bf:
                _bf_targets.append((p2['ticker'], p2.get('sym'), p2.get('region')))
                _seen_bf.add(p2['ticker'])
        _bf_fetched = _bf_cached = _bf_miss = 0
        _accel_map = {}
        for tk, sym, region in _bf_targets:
            ent = qcache.get(tk)
            rows = None
            if ent and isinstance(ent, dict):
                try:
                    _age = (dt.date.today() - dt.date.fromisoformat(str(ent.get('at'))[:10])).days
                    if (_age <= _QA_QHIST_TTL_D and isinstance(ent.get('rows'), list)
                            and ent.get('rows') and ent.get('v') == 2):
                        # v1.314.13: an EMPTY cached rows list no longer rides the 14d TTL --
                        # empties retry each run so a source/mapping fix heals next scan.
                        rows = ent['rows']; _bf_cached += 1
                except Exception:
                    pass
            if rows is None and _bf_fetched < _QA_QHIST_BUDGET:
                rows = _sa_quarterly_growths(sym or tk, region)
                _bf_fetched += 1
                qcache[tk] = {'at': today, 'sym': sym, 'rows': rows, 'v': 2}
            if not rows:
                _bf_miss += 1
                _accel_map[tk] = {'hist_q': 0, 'accel': None, 'accel_run': 0, 'hist_src': 'forward-only'}
                continue
            # store REPLACED with the real quarterly series (oldest -> newest), marked bf
            store[tk] = [{'d': r2['q'], 'eps': r2.get('eps'), 'rev': r2.get('rev'), 'bf': 1}
                         for r2 in reversed(rows)][-12:]
            usable = [r2 for r2 in rows if r2.get('eps') is not None and r2.get('rev') is not None]
            a_run = 0
            for i in range(len(usable) - 1):
                if usable[i]['eps'] > usable[i + 1]['eps'] and usable[i]['rev'] > usable[i + 1]['rev']:
                    a_run += 1
                else:
                    break
            _accel_map[tk] = {'hist_q': len(rows), 'accel': (a_run >= 1) if len(usable) >= 2 else None,
                              'accel_run': a_run, 'hist_src': 'published-quarterly'}
        # recompute streak / tier / decel for backfilled picks off the REAL series, then re-sort below
        for pk in picks:
            am = _accel_map.get(pk['ticker'])
            if not am:
                continue
            pk.update(am)
            hist2 = store.get(pk['ticker']) or []
            st2 = 0
            for h2 in reversed(hist2):
                if (h2.get('eps') or 0) >= _QA_EPS_MIN and (h2.get('rev') or 0) >= _QA_SALES_MIN:
                    st2 += 1
                else:
                    break
            if am['hist_src'] == 'published-quarterly':
                pk['streak'] = min(st2, 10)
                pk['decelerating'] = (len(hist2) >= 3
                                      and (hist2[-1].get('eps') or 0) < (hist2[-2].get('eps') or 0) < (hist2[-3].get('eps') or 0)
                                      and (hist2[-1].get('rev') or 0) < (hist2[-2].get('rev') or 0) < (hist2[-3].get('rev') or 0))
                if pk['tier'] != 'nearmiss':
                    pk['tier'] = ('elite' if pk['streak'] >= 5 else 'strong' if pk['streak'] >= 4
                                  else 'watch' if pk['streak'] >= 3 else 'new')
        alarms = [a for a in alarms if not (_accel_map.get(a['ticker'], {}).get('hist_src') == 'published-quarterly')]
        alarms += [{'ticker': pk['ticker'], 'name': pk['name'], 'region': pk['region']}
                   for pk in picks if _accel_map.get(pk['ticker'], {}).get('hist_src') == 'published-quarterly'
                   and pk.get('decelerating')]
        data['qaccel_qhist'] = {k: v for k, v in qcache.items() if isinstance(v, dict)}
        log(f'  [Quarterly accel] backfill: {len(_bf_targets)} targets, {_bf_fetched} fetched, '
            f'{_bf_cached} cached, {_bf_miss} no-history (forward-only); '
            f'accelerating={sum(1 for v in _accel_map.values() if v.get("accel"))}')
        pinned = []
        for r in pr + ws + xc:
            nm_l = (r.get('name') or '').lower()
            if not any(p in nm_l for p in _QA_PINNED):
                continue
            eq = r.get('eps_growth_fq'); rq = r.get('rev_growth_fq'); roe = r.get('roe')
            eg = r.get('eps_growth'); rg = r.get('rev_growth')
            def _n(x): return x if isinstance(x, (int, float)) else None
            gates = {
                'eps_q': [_n(eq), _n(eq) is not None and eq >= _QA_EPS_MIN],
                'sales_q': [_n(rq), _n(rq) is not None and rq >= _QA_SALES_MIN],
                'roe_band': [_n(roe), _n(roe) is not None and _QA_ROE_LO <= roe <= _QA_ROE_HI],
                'annual50': [_n(eg) if _n(eg) is not None else _n(rg),
                             (_n(eg) is not None and eg >= _QA_ANN_MIN) or (_n(rg) is not None and rg >= _QA_ANN_MIN)],
                'no_oneoff': [None, not (_n(eq) is not None and eq > _QA_ONEOFF_CAP) and not (_n(rq) is not None and rq > _QA_ONEOFF_CAP)],
            }
            if not any(p2.get('ticker') == r.get('ticker') or _qa_norm(p2.get('name'))[:10] == _qa_norm(r.get('name'))[:10] for p2 in pinned):
                pinned.append({'ticker': r.get('ticker'), 'name': r.get('name'), 'region': r.get('region'),
                    'eps_fq': _n(eq), 'rev_fq': _n(rq), 'roe': _n(roe), 'ann_eps': _n(eg), 'ann_rev': _n(rg),
                    'ytd': r.get('ytd'), 'perf_1y': r.get('perf_1y'), 'perf_3y': r.get('perf_3y'),
                    'gates': {k: v[1] for k, v in gates.items()},
                    'n_pass': sum(1 for v in gates.values() if v[1]),
                    'moat': 'wide' if _qa_moat_match(r.get('name'), moat_set) else None,
                    **(_accel_map.get(r.get('ticker')) or {})})
        _ord = {'elite': 0, 'strong': 1, 'watch': 2, 'new': 3, 'nearmiss': 4}
        def _sort_key(p):
            if p['tier'] == 'nearmiss':
                # near-miss ranks by CLOSENESS TO PROMOTION (shortfall vs the full bars, smaller = first),
                # so names one good quarter away (e.g. ASML) sit at the top of the amber tier -- not by raw
                # growth size, which buried the closest names below the display cap.
                short = max(0.0, _QA_EPS_MIN - p['eps_fq']) + max(0.0, _QA_SALES_MIN - p['rev_fq'])
                return (_ord['nearmiss'], -(1 if p['moat'] else 0), short, -p['streak'])
            return (_ord.get(p['tier'], 5), -(1 if p['moat'] else 0), -p['streak'],
                    -(p['eps_fq'] + p['rev_fq']))
        picks.sort(key=_sort_key)
        store = {k: v for k, v in store.items() if v}
        n_full = sum(1 for p in picks if p['tier'] != 'nearmiss')
        data['qaccel_store'] = store
        data['qaccel_moat_set'] = sorted(moat_set)
        data['quarterly_acceleration'] = {
            'as_of': today, 'status': 'live',
            'note': ('Tightened to the original criteria: full tier needs EPS >=30% AND sales >=25% this quarter '
                     '(vs a year ago), NO extraordinary base-effect gains (>300% excluded), ROE inside 25-50%, '
                     'AND annual growth >=50%. Near-miss (amber) = >=25%/>=20%. Universe includes small & mid '
                     'caps ($300M-$10bn). "Wide" = full Morningstar wide-moat membership (MOAT+MOTG holdings). '
                     'Streak tiers build as names post new quarters.'),
            'criteria': {'eps_min': _QA_EPS_MIN, 'sales_min': _QA_SALES_MIN, 'oneoff_cap': _QA_ONEOFF_CAP,
                         'ann_min': _QA_ANN_MIN, 'nm_eps': _QA_NM_EPS, 'nm_sales': _QA_NM_SALES,
                         'roe_band': [_QA_ROE_LO, _QA_ROE_HI]},
            'n_qualifying': n_full, 'n_nearmiss': len(picks) - n_full,
            'n_moat': sum(1 for p in picks if p['moat']),
            'n_smallcap': sum(1 for p in picks if p['smallcap']),
            'n_midcap': sum(1 for p in picks if p['midcap']),
            'n_roe_ok': sum(1 for p in picks if p['roe_ok']), 'n_picks': len(picks),
            'pinned': pinned,
            'picks': picks[:150], 'decel_alarms': alarms}
        data['qaccel_decel_map'] = {a['ticker']: True for a in alarms}
        log(f"  [Quarterly accel] TIGHT full={n_full} nearmiss={len(picks)-n_full} moat={sum(1 for p in picks if p['moat'])} extra_scan={len(xc)} alarms={len(alarms)}")
    except Exception as e:
        log(f'  [Quarterly accel] failed: {e} -- carrying last-good')
        data['quarterly_acceleration'] = prev
        data['qaccel_store'] = store
        data['qaccel_qhist'] = (existing or {}).get('qaccel_qhist') or {}


def build_global_discovery(data, existing):
    """v1.313.0 — Phases 2/3b/4. Multi-lens screen on the world-stock pool, overlap-check vs
    engine tabs, amber concentration guardrail. Emits data['global_discovery']. If the world
    feed hasn't confirmed yet (fund_coverage 0), emits status='populating' so the tab is honest."""
    prev = (existing or {}).get('global_discovery') or {}
    try:
        ws = data.get('world_stocks') or {}
        recs = ws.get('recs') or []
        fcov = ws.get('fund_coverage') or 0
        # names the dashboard already surfaces (US engines) -> overlap tag
        engine_names = set()
        for r in (data.get('explosive_us') or []):
            if isinstance(r, dict) and r.get('ticker'): engine_names.add(r['ticker'])
        for r in (data.get('us_multibagger') or []):
            if isinstance(r, dict) and r.get('ticker'): engine_names.add(r['ticker'])

        picks = []
        for rec in recs:
            lenses = _gd_lenses(rec)
            if not lenses:
                continue
            picks.append({
                'ticker': rec.get('ticker'), 'sym': rec.get('sym'), 'name': rec.get('name'),
                'region': rec.get('region'), 'sector': rec.get('sector'),
                'lenses': lenses, 'n_lenses': len(lenses),
                'returns': {'ytd': rec.get('ytd'), '1y': rec.get('perf_1y'),
                            '3y': rec.get('perf_3y'), '5y': rec.get('perf_5y')},
                'roic': rec.get('roic'), 'rev_growth': rec.get('rev_growth'),
                'eps_growth': rec.get('eps_growth'), 'gross_margin': rec.get('gross_margin'),
                'pe': rec.get('pe'), 'div_yield': rec.get('div_yield'),
                'market_cap_m': rec.get('market_cap_m'), 'currency': rec.get('currency'),
                'overlap': rec.get('ticker') in engine_names,
                'etf_holders': etf_holders_for(data, rec.get('ticker'), 8),
                'etf_holder_count': len(etf_holders_for(data, rec.get('ticker'), 999)),
            })
        picks.sort(key=lambda p: -p['n_lenses'])

        # amber concentration guardrail: flag if any one region/sector dominates the top picks
        top = picks[:40]
        from collections import Counter as _C
        reg_mix = _C(p['region'] for p in top)
        sec_mix = _C(p['sector'] for p in top)
        guard = []
        if top:
            rmax = max(reg_mix.values()); smax = max(sec_mix.values())
            if rmax / len(top) > 0.5:
                guard.append(f'concentration: {rmax}/{len(top)} top picks in one region — diversify')
            if smax / len(top) > 0.5:
                guard.append(f'concentration: {smax}/{len(top)} top picks in one sector — diversify')

        status = 'live' if (recs and fcov) else 'populating'
        data['global_discovery'] = {
            'as_of': dt.date.today().isoformat(), 'status': status,
            'note': ('World-wide multi-lens discovery (moat/growth/multibagger/momentum/turnaround/income) '
                     'on non-US large caps, run through the SAME lenses as the US engine. '
                     + ('Feed confirmed live.' if status == 'live'
                        else 'World-stock fundamentals confirm on the next scan — table fills automatically.')),
            'n_universe': len(recs), 'fund_coverage': fcov, 'regions_live': ws.get('regions_live') or [],
            'n_picks': len(picks), 'picks': picks[:60],
            'region_mix': dict(reg_mix), 'sector_mix': dict(sec_mix), 'guardrail': guard,
        }
        if status == 'populating' and prev.get('picks'):
            # keep last-good picks visible but mark stale rather than blanking
            data['global_discovery']['prev_picks'] = prev.get('picks')
        log(f"  [Global discovery] status={status} universe={len(recs)} fund-cov={fcov} picks={len(picks)}")
    except Exception as e:
        log(f'  [Global discovery] failed: {e} — carrying last-good')
        data['global_discovery'] = prev


def build_m1_buylist(data, existing):
    """v1.188.0 -- M1 STEP 4: the automatic final buy list. Takes the top keystone-disciplined
    big-caps in the REGIME-FAVORED sectors (same regime + sector tables the Tab-6 render uses),
    runs the REAL deep scorer (score_im3 -- the full scorecard, NOT the quick keystone pre-score)
    on each, applies the group's strict 61% quality bar, ranks survivors on valuation (Attractive
    first) then strength, and marks two confirmation locks per name: Zacks rank <= 2 and
    appears-in-tracked-fund-holdings. Emits data['m1_buylist'] with a ranked <=8-name buys list
    (never padded: if fewer clear the bar, the list is honestly short). COST-BOUNDED: each name's
    deep score is carried M1_IM3_TTL_DAYS before re-fetching, and fresh fetches are capped at
    M1_IM3_BUDGET/run -- so the first run scores ~30 names and later runs mostly reuse. FREEZE-SAFE:
    additive block, reads already-built data (m2_universe/zacks_ranks/inst_consensus), touches no
    screen/TCE/Explosive/keystone path; per-name scorer errors (ABCL/GAU-class) fail soft to
    'not scored', never crash; carries last-good on total failure."""
    prev = (existing or {}).get('m1_buylist') or {}
    prev_scores = {}
    for b in (prev.get('scored') or []):
        if b.get('ticker') and b.get('im3_pct') is not None and b.get('scored_at'):
            prev_scores[b['ticker']] = b
    us = (data.get('macros') or {}).get('us') or {}
    regime = _m1_regime(us)
    favored = _M1_REGIME_FAVORED.get(regime, [])
    _mu = data.get('m2_universe') or {}
    disc = (_mu.get('disciplined') or []) + (_mu.get('disciplined_giants') or [])
    zr = data.get('zacks_ranks') or {}
    fund_set = set()
    for s in ((data.get('inst_consensus') or {}).get('stocks') or []):
        t = s.get('ticker') if isinstance(s, dict) else s
        if t:
            fund_set.add(str(t).upper())
    # ---- Step 2b: Booming-Sector Override (universal; see constants above) ----
    overrides = []
    try:
        import statistics as _st
        _rows_by_g, _all6, _alle = {}, [], []
        for _fr in (data.get('foundation_universe') or []):
            _gi = _M1_FINE_TO_GICS.get(_fr.get('sector'))
            if not _gi:
                continue
            _rows_by_g.setdefault(_gi, []).append(_fr)
            if _fr.get('perf_6m') is not None: _all6.append(_fr['perf_6m'])
            if _fr.get('eps_growth') is not None: _alle.append(_fr['eps_growth'])
        if len(_all6) >= 200:                      # need a real market baseline (perf feed live)
            _m6, _me = _st.median(_all6), _st.median(_alle) if _alle else None
            _zs = data.get('zacks_sectors') or {}
            _cand = []
            for _gi, _rs in _rows_by_g.items():
                if _gi in favored or len(_rs) < 10:
                    continue
                _s6 = [r['perf_6m'] for r in _rs if r.get('perf_6m') is not None]
                _se = [r['eps_growth'] for r in _rs if r.get('eps_growth') is not None]
                _g6 = _st.median(_s6) if _s6 else None
                _ge = _st.median(_se) if _se else None
                _zp = (_zs.get(_gi) or {}).get('pct_top')
                e1 = (_g6 is not None) and (_g6 >= _m6 + M1_OV_MOM_PTS)
                e2 = (_ge is not None) and (_me is not None) and (_ge >= _me + M1_OV_EPS_PTS)
                e3 = (_zp is not None) and (_zp >= M1_OV_ZACKS_PCT)
                _n = int(e1) + int(e2) + int(e3)
                if _n >= 2:
                    _cand.append({'sector': _gi, 'gates': _n,
                                  'evidence': {'med_6m': _g6, 'mkt_6m': _m6, 'med_eps_g': _ge,
                                               'mkt_eps_g': _me, 'zacks_pct_top': _zp,
                                               'e_momentum': e1, 'e_earnings': e2, 'e_zacks': e3}})
            _cand.sort(key=lambda c: (-c['gates'], -(c['evidence']['med_6m'] or -999)))
            overrides = _cand[:M1_OV_MAX]
            for _o in overrides:
                _ev = _o['evidence']
                log(f"  [M1 override] {_o['sector']} JOINS the pool ({_o['gates']}/3 gates): "
                    f"6M {_ev['med_6m']}% vs mkt {round(_m6,1)}% | EPSg {_ev['med_eps_g']}% vs mkt "
                    f"{round(_me,1) if _me is not None else None}% | Zacks-heat {_ev['zacks_pct_top']}% "
                    f"-- off-regime, same cash-conversion gate")
    except Exception as _e:
        log(f'  [M1 override] evidence pass skipped ({_e}) -- regime sectors only')
        overrides = []
    ov_set = {o['sector'] for o in overrides}
    favored_eff = favored + [o['sector'] for o in overrides]
    # ---- v1.209.0 Step 2c: SECTOR-BOOMING REFEREE (owner design 2026-07-08: 'the rulebook
    # nominates, the scoreboard referees'). The comprehensive Sector Booming engine (6 live
    # signals per GICS sector: Zacks heat, 200-DMA breadth, forward implications, regime fit,
    # relative strength, COT) now ANNOTATES + ORDERS every nominated sector and can PROMOTE any
    # sector its scoreboard rates 'Favoured' that neither the regime map nor the override lanes
    # nominated -- mirroring what M1-PK already does with psx_sector_booming. ADDITIVE by design:
    # with zero Favoured bands (weak breadth, e.g. today's 0F/3N/8L tape) the pool is exactly
    # what the rulebook + overrides built -- a cold scoreboard can never empty the buy list.
    boom_by = {}
    for _b in (data.get('sector_booming') or []):
        if isinstance(_b, dict) and _b.get('sector'):
            boom_by[_b['sector']] = _b
    promoted = [s for s, _b in boom_by.items() if _b.get('band') == 'Favoured' and s not in favored_eff]
    favored_eff += promoted
    def _fd(sec, src):
        _b = boom_by.get(sec) or {}
        return {'sector': sec, 'source': src, 'boom_score': _b.get('score'),
                'boom_band': _b.get('band'), 'boom_rank': _b.get('rank'),
                'boom_trend': _b.get('score_trend')}
    favored_detail = ([_fd(s, 'regime') for s in favored]
                      + [_fd(o['sector'], 'override') for o in overrides]
                      + [_fd(s, 'scoreboard') for s in promoted])
    favored_detail.sort(key=lambda d: (d['boom_rank'] is None, d['boom_rank'] if d['boom_rank'] is not None else 99))
    if promoted:
        log(f'  [M1 referee] Sector Booming PROMOTED {promoted} into the pool (band=Favoured)')
    log('  [M1 referee] Step-2 sectors refereed by Sector Booming: '
        + ', '.join('%s(%s,%s#%s)' % (d['sector'], d['source'], d['boom_band'] or 'n/a',
                                      d['boom_rank'] if d['boom_rank'] is not None else '-')
                    for d in favored_detail))
    # ---- candidate pool per favored sector = quick-score lane UNION market-cap lane UNION
    # Zacks-#1 lane (owner rule 2026-07-06: any #1-ranked name in a pooled sector passes through).
    # The size lane exists because the quick score is deliberately blunt (saturates at 100) and can
    # rank a sector giant behind a wall of ties -- the deep scorer, not the pre-score, should judge them.
    pool, seen = [], set()
    for g in favored_eff:
        rows = [r for r in disc if _M1_FINE_TO_GICS.get(r.get('sector')) == g]
        by_score = sorted(rows, key=lambda r: -(r.get('score') or 0))[:M1_PER_SECTOR]
        by_mcap = sorted(rows, key=lambda r: -(r.get('mcap_m') or 0))[:M1_MCAP_LANE]
        by_zacks1 = [r for r in rows if zr.get(r['ticker']) == 1]
        for r in by_score + by_mcap + by_zacks1:
            if r['ticker'] not in seen:
                seen.add(r['ticker'])
                pool.append(dict(r, gics=g, off_regime=(g in ov_set)))

    # v1.282.0 ZACKS-DISCOVERY LANE (owner-approved 2026-07-21): A-grade discoveries from the
    # pink tier -- large caps the canonical scorer already judged Grade A but which sit outside
    # M1's keystone lanes (live evidence: C, GOOGL, SCHW, ADP, DIS, FOXA, WFC) -- now JOIN the
    # M1 candidate pool. NO free pass: they face the same internal deep score, the same
    # cash-conversion gate, the same ranking as every other candidate; a non-favored sector is
    # honestly flagged off_regime. src='zacks_discovery' rides the record for provenance.
    try:
        _zd_src = list((data.get('zacks_radar') or {}).get('rows') or [])
        _zd_src += [r for r in (data.get('explosive_us') or [])
                    if isinstance(r, dict) and r.get('zacks_discovery')]
        _zd_added = []
        for _z in _zd_src:
            _t = _z.get('ticker')
            _im = _z.get('im3') if isinstance(_z.get('im3'), dict) else None
            if not _t or _t in seen or not _im or _im.get('grade') != 'A':
                continue
            _g = _M1_FINE_TO_GICS.get(_z.get('sector')) or _z.get('sector') or 'Unclassified'
            seen.add(_t)
            pool.append({'ticker': _t, 'name': _z.get('name') or _t, 'sector': _z.get('sector'),
                         'score': None, 'mcap_m': None,
                         'perf_ytd': _z.get('perf_ytd'), 'perf_1y': _z.get('perf_1y'),
                         'perf_6m': _z.get('perf_6m'), 'perf_3m': _z.get('perf_3m'),
                         'gics': _g, 'off_regime': (_g not in favored_eff),
                         'src': 'zacks_discovery'})
            _zd_added.append(_t)
        if _zd_added:
            log(f"  [M1 discovery lane] {len(_zd_added)} A-grade Zacks discovery(ies) join the pool: {_zd_added}")
    except Exception as _ze:
        log(f'  [M1 discovery lane] skipped: {type(_ze).__name__}')
    today = dt.date.today()
    M1_SCORER_REV = IM3_SCAN_REV   # buy-list carries follow the shared scoring-semantics rev
    _force = set()
    try:
        if os.path.exists('m1_force_rescore.json'):
            with open('m1_force_rescore.json') as _fh:
                _force = {str(x).upper() for x in json.load(_fh)}
            log(f"  [M1 force-rescore] {len(_force)} name(s) will bypass the {M1_IM3_TTL_DAYS}-day carry this run: {sorted(_force)}")
    except Exception as _e:
        log(f'  [M1 force-rescore] file unreadable ({_e}) -- ignored')
    if _force:
        pool.sort(key=lambda r: 0 if r['ticker'] in _force else 1)   # forced names use the budget first
    scored, fresh = [], 0
    for r in pool:
        t = r['ticker']
        rec = {'ticker': t, 'name': r.get('name') or t, 'sector': r['gics'],
               'off_regime': bool(r.get('off_regime')),
               'src': r.get('src'),
               'keystone': r.get('score'), 'price': None,
               'perf_ytd': r.get('perf_ytd'), 'perf_1y': r.get('perf_1y'),
               'perf_5y': r.get('perf_5y'), 'perf_6m': r.get('perf_6m'), 'perf_3m': r.get('perf_3m'),
               'im3_pct': None, 'im3_grade': None, 'valuation': None, 'scored_at': None}
        pv = prev_scores.get(t)
        age = None
        if pv:
            try:
                age = (today - dt.date.fromisoformat(pv['scored_at'])).days
            except Exception:
                age = None
        if pv and age is not None and age <= M1_IM3_TTL_DAYS and t not in _force \
                and pv.get('scorer_rev') == M1_SCORER_REV:
            rec.update({k: pv.get(k) for k in ('im3_pct', 'im3_grade', 'valuation', 'price', 'scored_at', 'scorer_rev')})
        elif fresh < M1_IM3_BUDGET:
            fresh += 1
            try:
                im3 = score_im3(t)
            except Exception as e:
                import traceback as _tb
                _fr = [l.strip() for l in _tb.format_exc().splitlines() if 'scanner.py' in l or 'im3' in l]
                _loc = (_fr[-1][:120] if _fr else '?')
                log(f'  [M1 buylist] scorer failed {t}: {e.__class__.__name__}: {str(e)[:60]} @ {_loc} -- not scored (soft)')
                im3 = None
            if im3:
                # v1.196.0 audit trail: persist WHY this score is what it is -- data source, the
                # full per-metric verdict/points table, and the raw input series the scorer judged.
                try:
                    data.setdefault('m1_im3_audit', {})[t] = {
                        'scored_at': today.isoformat(),
                        'src': globals().get('_IM3_LAST_SRC'),
                        'pct': im3.get('pct'), 'grade': im3.get('grade'),
                        'is_bank': bool(im3.get('is_bank')),
                        # v1.345.0 slim: the ONLY consumer of this list (index thin-coverage
                        # ratio) reads verdict alone; full per-metric detail lives on the scored
                        # row's own im3.metrics. inputs/iv below are UNTOUCHED (cash gate reads them).
                        'metrics': [{'verdict': m.get('verdict')}
                                    for m in (im3.get('metrics') or [])],
                        'inputs': globals().get('_IM3_LAST_INPUTS') or {},
                        'iv': {k: (im3.get('iv') or {}).get(k) for k in ('composite', 'mos_pct', 'price')},
                    }
                except Exception:
                    pass
                # valuation label: the separate im3_score.py split isn't in this path, so derive it
                # from THIS scorer's own margin-of-safety composite (price vs multi-method intrinsic
                # value): >=+15% cheap -> Attractive, within -10%..+15% -> Fair, worse -> Rich.
                val = im3.get('valuation')
                label = (val.get('label') if isinstance(val, dict) else val)
                mos = ((im3.get('iv') or {}).get('mos_pct'))
                if label is None and mos is not None:
                    label = 'Attractive' if mos >= 15 else ('Fair' if mos >= -10 else 'Rich')
                rec.update({'scorer_rev': M1_SCORER_REV,
                            'im3_pct': im3.get('pct'), 'im3_grade': im3.get('grade'),
                            'valuation': label,
                            'price': im3.get('price') or ((im3.get('iv') or {}).get('price')),
                            'scored_at': today.isoformat()})
            elif pv:   # stale carry beats a blank
                rec.update({k: pv.get(k) for k in ('im3_pct', 'im3_grade', 'valuation', 'price', 'scored_at', 'scorer_rev')})
            time.sleep(YF_DELAY * 2)
        elif pv:       # budget exhausted: stale carry beats a blank
            rec.update({k: pv.get(k) for k in ('im3_pct', 'im3_grade', 'valuation', 'price', 'scored_at', 'scorer_rev')})
        rec['zacks'] = zr.get(t)
        rec['zacks_ok'] = (rec['zacks'] is not None and rec['zacks'] <= 2)
        rec['fund_ok'] = t.upper() in fund_set
        scored.append(rec)
    if fresh and any(_IM3_SRC.values()):
        log(f'  [IM3 src] this run: ' + ', '.join(f'{k}={v}' for k, v in _IM3_SRC.items() if v))
    # audit-trail hygiene FIRST (moved above the gate in v1.204.0 -- the cash gate reads audit inputs):
    # carry prior audit rows for TTL-carried scores, prune names no longer pooled
    _prev_aud = (existing or {}).get('m1_im3_audit') or {}
    aud = data.setdefault('m1_im3_audit', {})
    _pool_ts = {r['ticker'] for r in scored}
    for _t in _pool_ts:
        if _t not in aud and _t in _prev_aud:
            # v1.345.0: re-slim carried rows in place -- prior-run fat metric entries would
            # otherwise ride the TTL carry indefinitely and the store would never converge.
            _pa = dict(_prev_aud[_t])
            _pa['metrics'] = [{'verdict': (_m or {}).get('verdict')}
                              for _m in (_pa.get('metrics') or [])]
            aud[_t] = _pa
    for _t in list(aud.keys()):
        if _t not in _pool_ts:
            del aud[_t]
    # v1.204.0 -- OWNER GATE REDESIGN ('cash is king'). Eligibility is the PTM cash chain judged on
    # the company's own filings (3-year cumulative, newest 3 filed years), NOT a scorecard percentage:
    #   G1 revenue -> profit : 3yr net profit > 0
    #   G2 profit  -> cash   : 3yr CFO / 3yr net profit >= M1_CASH_R_MIN
    #   G3 cash is king      : 3yr free cash flow > 0 (capex already paid)
    # Banks keep the System-B 61%% bar (cash-conversion is meaningless on a bank's statements).
    # Missing cash history (young spin-offs, e.g. GEV) = NOT eligible: cash must be demonstrated, never assumed.
    # Strength %% no longer gates -- it only ranks (after confirmation locks and valuation), and stays displayed.
    def _cash_chain(rec):
        a = aud.get(rec['ticker']) or {}
        if a.get('is_bank'):
            ok = rec['im3_pct'] is not None and rec['im3_pct'] >= M1_GATE_PCT
            rec['cash_gate'] = 'bank-pass' if ok else 'bank-fail'
            return ok
        inp = a.get('inputs') or {}
        def _c3(k):
            xs = [x for x in (inp.get(k) or [])[:3] if isinstance(x, (int, float))]
            return sum(xs) if xs else None
        c3, n3, f3 = _c3('cfo'), _c3('np'), _c3('fcf')
        if c3 is None or n3 is None or f3 is None:
            rec['cash_gate'] = 'no-data'
            return False
        r = (c3 / n3) if n3 > 0 else None
        if r is not None:
            rec['cash_r'] = round(r, 2)
        ok = (n3 > 0) and (r is not None and r >= M1_CASH_R_MIN) and (f3 > 0)
        rec['cash_gate'] = 'pass' if ok else 'fail'
        return ok
    # v1.205.0 -- an analyst Sell rating is a hard veto for the BUY LIST (never for the table):
    # a Zacks 4/5 name can still qualify and be displayed, but can never take a buy seat.
    eligible = [r for r in scored if r['im3_pct'] is not None and _cash_chain(r)
                and not ((r.get('zacks') or 0) >= 4)]
    _gate_counts = {}
    for r in scored:
        _gate_counts[r.get('cash_gate', 'unscored')] = _gate_counts.get(r.get('cash_gate', 'unscored'), 0) + 1
    _vord = {'Attractive': 0, 'Fair': 1, 'Rich': 2}
    eligible.sort(key=lambda r: (-(int(r['zacks_ok']) + int(r['fund_ok'])),
                                 _vord.get(r['valuation'], 3), -(r['im3_pct'] or 0)))
    buys = eligible[:8]
    data['m1_buylist'] = {
        'as_of': today.isoformat(), 'regime': regime, 'favored': favored,
        'override_sectors': overrides, 'favored_effective': favored_eff,
        'favored_detail': favored_detail,
        'gate_pct': M1_GATE_PCT, 'gate_type': 'cash_chain', 'cash_r_min': M1_CASH_R_MIN,
        'pool_n': len(pool), 'fresh_scored': fresh,
        'n_scored': sum(1 for r in scored if r['im3_pct'] is not None),
        'n_eligible': len(eligible), 'scored': scored, 'buys': buys,
    }
    log(f"  [M1 buylist] regime={regime} pool={len(pool)} fresh-scored={fresh} "
        f"deep-scored={data['m1_buylist']['n_scored']} cash-chain(CFO/NP>={M1_CASH_R_MIN})={_gate_counts.get('pass',0)} pass"
        f" + banks {_gate_counts.get('bank-pass',0)}/{_gate_counts.get('bank-pass',0)+_gate_counts.get('bank-fail',0)}"
        f" | fail={_gate_counts.get('fail',0)} no-cash-history={_gate_counts.get('no-data',0)}"
        f" -> buys={len(buys)}: {[b['ticker'] for b in buys]}")


# v1.249.0 STAGE CLOCK. The owner asked "why did the run take 8 minutes?" and data.json could not
# answer -- meta carried only scan_version/last_scan_utc/errors/warnings, so runtime was invisible
# without a GitHub Actions log (which is token-gated). That is a hole in the self-serve workflow.
# _stage() wraps any callable, records its wall-clock ms, and the totals ride out in meta.timings ->
# every future "what's slow?" is answerable straight from data.json, no log needed. Pure measurement:
# it changes NO behaviour and swallows nothing (exceptions propagate to the caller's own handler).
_STAGE_MS = {}


def _stage(name, fn, *a, **kw):
    _t = time.time()
    try:
        return fn(*a, **kw)
    finally:
        _STAGE_MS[name] = round((time.time() - _t) * 1000)




