# v1.292.0 SOURCE-LAYER UPGRADE (owner: 'why not bloomberg? ... first list all reliable news
# resources and then build the code'). Verified landscape: Reuters killed its public RSS;
# Bloomberg/WSJ/FT have no official free feeds (subscriber products). The legal free route to
# T1 headlines is Google News SCOPED queries (site:reuters.com / site:bloomberg.com) -- so every
# theme now fans out to THREE queries (general + Reuters-scoped + Bloomberg-scoped), and four
# DIRECT official publisher feeds (CNBC Top/Markets/Economy/Tech, MarketWatch Top) are fetched
# once per run and keyword-routed into themes. Per-feed item counts persist in
# narratives['source_health'] so source reachability audits itself every run.
NARR_DIRECT_FEEDS = [
    ('cnbc_top',      'https://www.cnbc.com/id/100003114/device/rss/rss.html'),
    ('cnbc_markets',  'https://www.cnbc.com/id/20910258/device/rss/rss.html'),
    ('cnbc_tech',     'https://www.cnbc.com/id/19854910/device/rss/rss.html'),
    ('marketwatch',   'https://feeds.content.dowjones.io/public/rss/mw_topstories'),
    # v1.293.0 (owner: 'why not international securities and brokers news feed?'):
    # primary GS/MS/JPM research is a regulated client-only product with NO public feeds
    # (MiFID-II unbundling) -- but its public EXHAUST, the ratings actions naming the firms,
    # is free: MarketBeat publishes a genuine analyst-ratings RSS.
    ('marketbeat_ratings', 'https://www.marketbeat.com/rss.ashx?type=ratings'),
]
NARR_THEME_KEYS = {   # keyword routing for direct-feed headlines -> themes
    'tariffs':   ('tariff', 'trade war', 'import dut', 'trade deal', 'trade policy'),
    'whitehouse': ('trump', 'white house', 'congress', 'washington', 'executive order'),
    'ai_infra':  ('ai ', 'artificial intelligence', 'datacenter', 'data center', 'nvidia'),
    'semis':     ('semiconductor', 'chip', 'foundry', 'tsmc'),
    'rates':     ('fed ', 'federal reserve', 'rate cut', 'rate hike', 'inflation', 'powell'),
    'energy':    ('oil', 'opec', 'crude', 'natural gas', 'energy prices'),
    'metals':    ('gold', 'silver', 'copper', 'mining'),
    'crypto':    ('bitcoin', 'crypto', 'ethereum'),
    'pharma':    ('fda', 'drug pric', 'pharma', 'biotech'),
    'pakistan':  ('pakistan', 'imf', 'karachi'),
    'defense':   ('defense', 'pentagon', 'military', 'nato'),
    'broker_calls': ('upgrade', 'downgrade', 'price target', 'initiates', 'maintains',
                     'overweight', 'underweight', 'raises', 'lowers', 'reiterates'),
    'psx_brokers': ('psx', 'kse-100', 'akd', 'topline', 'js global'),
}


def build_narratives(data, existing=None):
    """Theme-first news engine. Returns the narratives payload; never raises."""
    universe = {}
    for _lk in ('explosive_us', 'tce_us', 'explosive_psx', 'tce_psx', 'psx_candidates'):
        for r in (data.get(_lk) or []):
            if isinstance(r, dict) and r.get('ticker'):
                universe.setdefault(r['ticker'], (r.get('sector') or ''))
    for r in ((data.get('zacks_radar') or {}).get('rows') or []):
        if isinstance(r, dict) and r.get('ticker'):
            universe.setdefault(r['ticker'], (r.get('sector') or ''))
    for r in ((existing or {}).get('live_investment') or {}).get('holdings', []) or []:
        t = (r or {}).get('ticker') or (r or {}).get('symbol')
        if t:
            universe.setdefault(str(t).upper().split(':')[-1], (r.get('sector') or ''))

    def _tier(src):
        s2 = (src or '').lower()
        if any(k in s2 for k in NARR_T1): return 1
        if any(k in s2 for k in NARR_T2): return 2
        return 3

    def _sent(title):
        tl = (title or '').lower()
        sc = sum(1 for k in NARR_POS if k in tl) - sum(1 for k in NARR_NEG if k in tl)
        return 1 if sc > 0 else (-1 if sc < 0 else 0)

    def _event(title):
        tl = (title or '').lower()
        for name, keys in NARR_EVENTS:
            if any(k in tl for k in keys):
                return name
        return 'GENERAL'

    cutoff = dt.datetime.utcnow() - dt.timedelta(days=14)
    themes_out = []
    any_heads = False
    source_health = {}
    # v1.308.0 EFFICIENCY: 7 of 44 feeds returned NOTHING on the live run and always will --
    # marketbeat_ratings (UA-blocked) and the Reuters/Bloomberg scoped queries for ai_infra,
    # pakistan and psx_brokers (those wires simply do not cover Pakistani broker research).
    # That is 16%% of the fetch spent on guaranteed-empty calls, every run. A learned skip-list
    # rides data.json: 3 consecutive empties -> skip; retried every 20th run so a feed that
    # comes back is recovered automatically. No headline is ever lost -- only calls that have
    # repeatedly produced none are skipped.
    _EMPTY_STREAK_SKIP = 3
    _RETRY_EVERY = 20
    _prev_health = ((existing or {}).get('narratives') or {}).get('feed_health') or {}
    _run_no = int(((existing or {}).get('narratives') or {}).get('run_no') or 0) + 1
    def _skip_feed(lbl):
        h = _prev_health.get(lbl) or {}
        st = int(h.get('empty_streak') or 0)
        if st < _EMPTY_STREAK_SKIP:
            return False
        return (_run_no % _RETRY_EVERY) != 0      # periodic retry keeps it self-healing
    _skipped = []
    # ---- direct official publisher feeds: fetched ONCE, keyword-routed into themes ----
    _direct_by_theme = {}
    import concurrent.futures as _cf
    def _pull(pair):
        lbl, u = pair
        if _skip_feed(lbl):
            _skipped.append(lbl)
            return lbl, []
        try:
            return lbl, (_fetch_rss_entries(u) or [])
        except Exception:
            return lbl, []
    try:
        with _cf.ThreadPoolExecutor(max_workers=len(NARR_DIRECT_FEEDS)) as _ex:
            _direct = dict(_ex.map(_pull, NARR_DIRECT_FEEDS))
    except Exception:
        _direct = {lbl: [] for lbl, _u in NARR_DIRECT_FEEDS}
    for _lbl, _ents in _direct.items():
        source_health[_lbl] = len(_ents)
        for _e in _ents[:40]:
            _t3 = ((getattr(_e, 'title', '') or '')).lower()
            import re as _re4
            for _tid, _keys in NARR_THEME_KEYS.items():
                # v1.293.0 word-boundary routing: the audit caught 'GOLDman Sachs' routing to
                # the Metals theme via the bare substring 'gold' -- keys now match whole words.
                if any(_re4.search(r'\b' + _re4.escape(k.strip()) + r'\b', _t3) for k in _keys):
                    setattr(_e, '_narr_src', 'CNBC' if _lbl.startswith('cnbc')
                            else ('MarketBeat' if _lbl.startswith('marketbeat') else 'MarketWatch'))
                    _direct_by_theme.setdefault(_tid, []).append(_e)
                    break
    for th in NARR_THEMES:
        # v1.294.0: the live run proved Google's relevance ranking starves fresh news --
        # tariffs fetched 270 items, kept ZERO (all older than the 14-day window). when:14d
        # forces recency AT THE SOURCE for every query, general and scoped alike.
        _qb = th['q'].replace(' ', '+') + '+when:14d'
        # v1.295.0 FIX (owner paste: Metals theme showed chip/SpaceX/Uber Reuters headlines):
        # the scoped query already carries _qb (the theme terms) -- but Google's site: operator
        # with a broad theme phrase returned that publisher's general feed. Tighten with the
        # theme's most specific token quoted so site-scoped results stay ON-TOPIC.
        _core = th.get('core') or th['q'].split()[0]
        # v1.308.0: labels are THEME-QUALIFIED ('pakistan:reuters') so the learned skip-list can
        # match them -- source_health has always been keyed that way, but _pull was handed the
        # bare name, so the first cut of the skip only ever matched the direct feeds.
        _urls = [(th['id'] + ':google',    'https://news.google.com/rss/search?q=' + _qb + '&hl=en-US&gl=US&ceid=US:en'),
                 (th['id'] + ':reuters',   'https://news.google.com/rss/search?q=%22' + _core.replace(' ', '+') + '%22+' + _qb + '+site:reuters.com&hl=en-US&gl=US&ceid=US:en'),
                 (th['id'] + ':bloomberg', 'https://news.google.com/rss/search?q=%22' + _core.replace(' ', '+') + '%22+' + _qb + '+site:bloomberg.com&hl=en-US&gl=US&ceid=US:en')]
        # v1.294.0 FLOOD FIX (live run proof: scoped feeds returned 100 items each yet zero
        # survived): the general query's items filled ents[:60] before Reuters/Bloomberg were
        # ever reached. Scoped T1 feeds + direct publisher feeds now go FIRST; the general
        # aggregate fills whatever room remains.
        _by = {'google': [], 'reuters': [], 'bloomberg': []}
        try:
            with _cf.ThreadPoolExecutor(max_workers=3) as _ex:
                for _lblq, _got in _ex.map(_pull, _urls):
                    _lbl2 = _lblq.split(':')[-1]          # short name for the tagging below
                    source_health[_lblq] = len(_got)
                    if _lbl2 == 'reuters':
                        for _e in _got: setattr(_e, '_narr_src', 'Reuters')
                    elif _lbl2 == 'bloomberg':
                        for _e in _got: setattr(_e, '_narr_src', 'Bloomberg')
                    _by[_lbl2] = _got
        except Exception:
            pass
        ents = _by['reuters'] + _by['bloomberg'] + _direct_by_theme.get(th['id'], []) + _by['google']
        heads = []
        _seen_t = set()
        for e in ents[:60]:
            title = (getattr(e, 'title', '') or '').strip()
            if not title:
                continue
            pp = getattr(e, 'published_parsed', None)
            age_d = None
            if pp is not None:
                try:
                    _pd = dt.datetime(*pp[:6])
                    if _pd < cutoff:
                        continue
                    age_d = max(0, (dt.datetime.utcnow() - _pd).days)
                except Exception:
                    pass
            src = getattr(e, '_narr_src', '') or ''
            if not src:
                try:
                    src = (getattr(e, 'source', None) or {}).get('title') or ''
                except Exception:
                    try:
                        src = getattr(getattr(e, 'source', None), 'title', '') or ''
                    except Exception:
                        src = ''
            _tk3 = title.lower()[:70]
            if _tk3 in _seen_t:
                continue
            # v1.295.0: drop headlines that mention NONE of the theme's own query tokens
            # (kills 'SpaceX/Uber' bleed-through from a publisher's general Reuters feed).
            _thset = set(w for w in (th['q'].lower().replace('"', '').split()) if len(w) > 3)
            if _thset and not any(w in title.lower() for w in _thset) and getattr(e, '_narr_src', '') in ('Reuters', 'Bloomberg'):
                continue
            _seen_t.add(_tk3)
            heads.append({'t': title[:160], 'src': src[:40], 'tier': _tier(src),
                          'sent': _sent(title), 'event': _event(title), 'age_d': age_d})
            if len(heads) >= 10:
                break
        heads.sort(key=lambda h: (h['tier'], -(h['sent'] != 0)))
        # v1.293.0: broker-call headlines carry their own tickers -- '(NYSE:PSX)',
        # '(NASDAQ:MU)' -- extract and stamp them (universe members) as affected.
        _extracted = []
        try:
            import re as _re3
            for _h4 in heads:
                for _mt in _re3.findall(r'\((?:NYSE|NASDAQ|AMEX|OTC):\s*([A-Z][A-Z.\-]{0,6})\)', _h4['t']):
                    if _mt in universe and _mt not in _extracted:
                        _extracted.append(_mt)
        except Exception:
            pass
        affected = [t for t in th['tickers'] if t in universe]
        for _t5 in _extracted:
            if _t5 not in affected:
                affected.append(_t5)
        affected += [t for t, sec in universe.items()
                     if sec and sec in th['sectors'] and t not in affected]
        net = sum(h['sent'] for h in heads)
        t1n = sum(1 for h in heads if h['tier'] == 1)
        t2n = sum(1 for h in heads if h['tier'] == 2)
        # v1.294.0 QUALITY-WEIGHTED SCORE (live run: a zero-T1 crypto-blog cluster topped the
        # tab at 24 while Nikkei/Reuters themes sat below it): T1 dominates, T2 counts,
        # raw T3 breadth barely moves the needle.
        score = t1n * 6 + t2n * 2 + min(8, len(heads)) + abs(net) + min(8, len(affected)) // 2
        if heads:
            any_heads = True
        themes_out.append({'id': th['id'], 'title': th['title'], 'headlines': heads,
                           'net_sent': net, 't1_count': t1n, 'score': score,
                           'affected': affected[:24]})
    themes_out.sort(key=lambda x: -x['score'])

    def _recent_events(store, n=12):
        # v1.295.0 FIX (owner paste showed '? . .' rows): mat_events/insider_events are dicts
        # keyed by TICKER -> {'events': [{date,label/code,...}]}, not a flat list. Flatten
        # correctly, stamping the ticker from the key onto each event.
        outp = []
        try:
            if isinstance(store, dict):
                for _tk, _rec in store.items():
                    _evs = (_rec.get('events') if isinstance(_rec, dict) else _rec) or []
                    if not isinstance(_evs, list):
                        _evs = [_evs]
                    for ev in _evs:
                        if isinstance(ev, dict):
                            outp.append({'ticker': _tk,
                                         'date': ev.get('date') or ev.get('filed') or ev.get('transaction_date'),
                                         'title': str(ev.get('label') or ev.get('title') or ev.get('type')
                                                      or ev.get('code') or '')[:120]})
            elif isinstance(store, list):
                for ev in store:
                    if isinstance(ev, dict):
                        outp.append({'ticker': ev.get('ticker'),
                                     'date': ev.get('date') or ev.get('filed'),
                                     'title': str(ev.get('label') or ev.get('title') or ev.get('type') or '')[:120]})
            outp = [e for e in outp if e['ticker'] and e['title']]
            outp.sort(key=lambda x: str(x.get('date') or ''), reverse=True)
        except Exception:
            pass
        return outp[:n]

    def _insider_summary(store, n=12):
        # v1.295.0: insider_events is a per-ticker SUMMARY dict (buy/sell counts, net_buy_usd_6m,
        # cluster flags), not an events list -- surface the meaningful signals (net buying, CEO/CFO
        # buys, clusters), most recent first, buyers prioritised.
        rows = []
        try:
            for _tk, _r in (store or {}).items():
                if not isinstance(_r, dict):
                    continue
                _net = _r.get('net_buy_usd_6m')
                _bc, _sc = _r.get('buy_ct') or 0, _r.get('sell_ct') or 0
                if not (_bc or _sc):
                    continue
                _bits = []
                if _r.get('ceo_cfo_buy'): _bits.append('CEO/CFO BUY')
                if _r.get('cluster_buyers'): _bits.append(str(_r['cluster_buyers']) + ' cluster buyers')
                if _net is not None:
                    _bits.append(('net +$' if _net >= 0 else 'net -$') + format(abs(_net)/1e6, '.1f') + 'M 6m')
                _bits.append(str(_bc) + ' buys / ' + str(_sc) + ' sells')
                rows.append({'ticker': _tk, 'date': _r.get('last_date'),
                             'title': ' \u00b7 '.join(_bits),
                             '_buy': 1 if (_r.get('ceo_cfo_buy') or (_net or 0) > 0) else 0})
            rows.sort(key=lambda x: (x['_buy'], str(x.get('date') or '')), reverse=True)
        except Exception:
            pass
        return rows[:n]

    _feed_health = {}
    for _lbl, _n in source_health.items():
        _prev = (_prev_health.get(_lbl) or {})
        _streak = 0 if _n else int(_prev.get('empty_streak') or 0) + 1
        _feed_health[_lbl] = {'last_n': _n, 'empty_streak': _streak,
                              'skipped_this_run': _lbl in _skipped}
    for _lbl in _skipped:                       # keep streaks alive for skipped feeds
        _feed_health.setdefault(_lbl, dict(_prev_health.get(_lbl) or {}, skipped_this_run=True))
    if _skipped:
        log('  [Narratives] skipped %d feed(s) with %d+ consecutive empties: %s (retry on run %%%d)'
            % (len(_skipped), _EMPTY_STREAK_SKIP, ', '.join(sorted(set(_skipped))[:6]), _RETRY_EVERY))
    payload = {'as_of': dt.datetime.utcnow().isoformat() + 'Z',
               'source_health': source_health,
               'feed_health': _feed_health,
               'run_no': _run_no,
               'feeds_skipped': sorted(set(_skipped)),
               'themes': themes_out,
               'mat_recent': _recent_events(data.get('mat_events') or (existing or {}).get('mat_events')),
               'insider_recent': _insider_summary(data.get('insider_events') or (existing or {}).get('insider_events')),
               'universe_n': len(universe)}
    if not any_heads and (existing or {}).get('narratives', {}).get('themes'):
        prev = dict((existing or {})['narratives'])
        prev['stale'] = True
        log('  [Narratives] all theme feeds empty -> carrying last-good (stale-marked)')
        return prev
    log(f"  [Narratives] {sum(len(t2['headlines']) for t2 in themes_out)} headlines across "
        f"{sum(1 for t2 in themes_out if t2['headlines'])}/{len(themes_out)} themes; "
        f"universe {len(universe)} names; top: {themes_out[0]['title'] if themes_out else '-'}")
    return payload



