def _proj_range(px, series, comp, months):
    """Engine projection: a statistical range from the metal\u2019s OWN realised volatility,
    tilted by the driver composite. Deliberately NOT a target -- it answers \u2018given how much
    this metal actually moves, and which way the drivers lean, where is it likely to sit\u2019."""
    try:
        vals = [v for v in (series or []) if isinstance(v, (int, float))][-90:]
        if px is None or len(vals) < 20:
            return None
        rets = [(vals[i] / vals[i - 1] - 1.0) for i in range(1, len(vals)) if vals[i - 1]]
        if len(rets) < 15:
            return None
        mean = sum(rets) / len(rets)
        sd = (sum((r - mean) ** 2 for r in rets) / (len(rets) - 1)) ** 0.5
        horizon_days = 21 * months
        sig = sd * (horizon_days ** 0.5)                       # scale daily vol to the horizon
        drift = (comp / 100.0) * sig * 0.5                     # bias tilts the centre by half a sigma at |100|
        centre = px * (1 + drift)
        return {'months': months,
                'low': round(centre * (1 - sig), 2),
                'centre': round(centre, 2),
                'high': round(centre * (1 + sig), 2),
                'vol_pct': round(sig * 100, 1),
                'drift_pct': round(drift * 100, 1)}
    except Exception:
        return None


def build_metals_drivers(data):
    """v1.304.0 PER-METAL driver models (owner: 'what is pressuring each of the metals and what
    is favouring, what about silver? is ISM/LSM not a big factor for silver?').

    The owner is right, and it is the key distinction in this asset class: GOLD is a monetary
    metal -- industrial use is only ~5% of demand, so its price is set by real yields, the
    dollar, Fed policy and inflation. SILVER is BOTH: industrial applications are ~50-60% of
    demand (solar PV alone has gone from ~11% of demand in 2014 to ~29%), so manufacturing
    activity is silver's demand engine, and it ALSO inherits gold's macro sensitivity in
    amplified form. That is why one shared driver board was wrong: each metal needs its own
    weights. COPPER and the PGMs are industrial first. Weights below encode that research.
    Everything is computed from data the scanner already fetches. Never raises."""
    try:
        mac = data.get('macros') or {}
        us, met = (mac.get('us') or {}), (mac.get('metals') or {})
        n10, be = us.get('us_10y'), met.get('breakeven_10y')
        real = round(float(n10) - float(be), 2) if (n10 is not None and be is not None) else None
        _dsrc = met if met.get('dxy') is not None else us
        dxy, ddir, dtr = _dsrc.get('dxy'), _dsrc.get('dxy_wow_dir'), _dsrc.get('dxy_ma_trend')
        ip, ipdir, ipyoy = us.get('industrial_prod'), us.get('industrial_prod_mom_dir'), us.get('industrial_prod_yoy')
        gsr, fr, cpi = met.get('gs_ratio'), us.get('fed_rate'), us.get('cpi_yoy')

        def clamp(v): return max(-3, min(3, v))

        # ---- shared driver primitives (score = pressure on THIS metal, -3..+3) ----
        def d_real():
            if real is None: return None
            sc = -2 if real >= 2.5 else (-1 if real >= 1.5 else (2 if real <= 0.5 else (1 if real <= 1.0 else 0)))
            sc += 1 if us.get('us_10y_wow_dir') == 'down' else (-1 if us.get('us_10y_wow_dir') == 'up' else 0)
            return ('real_yield', '10-year REAL yield', real, '%', clamp(sc), us.get('us_10y_wow_dir'),
                    {'wow': us.get('us_10y_wow'), 'mom': us.get('us_10y_mom'), 'qoq': us.get('us_10y_qoq'), 'invert': True},
                    'Precious metals pay no income, so the real yield IS the cost of holding them. '
                    'At %.2f%% real (10Y %.2f%% minus %.2f%% breakeven inflation) that cost is %s.'
                    % (real, float(n10), float(be), 'high' if real >= 1.5 else 'low'))

        def d_dxy():
            if dxy is None: return None
            sc = (-1 if ddir == 'up' else (1 if ddir == 'down' else 0)) + \
                 (-1 if dtr == 'up' else (1 if dtr == 'down' else 0))
            return ('dxy', 'US dollar (DXY)', dxy, '', clamp(sc), ddir,
                    {'wow': _dsrc.get('dxy_wow'), 'mom': _dsrc.get('dxy_mom'), 'qoq': _dsrc.get('dxy_qoq'), 'invert': True},
                    'Metals are priced in dollars, so a firmer dollar mechanically pressures them. '
                    'DXY %.2f, %s on the week, %s versus its moving averages.' % (float(dxy), ddir or 'flat', dtr or 'flat'))

        def d_industrial(weight_note):
            if ip is None: return None
            sc = 0
            if ipyoy is not None:
                sc += 2 if ipyoy >= 2.0 else (1 if ipyoy >= 0.5 else (-2 if ipyoy <= -1.0 else (-1 if ipyoy < 0 else 0)))
            sc += 1 if ipdir == 'up' else (-1 if ipdir == 'down' else 0)
            return ('industrial', 'Industrial production (factory activity)', ip, 'idx', clamp(sc), ipdir,
                    {'wow': None, 'mom': us.get('industrial_prod_mom'), 'qoq': us.get('industrial_prod_qoq'), 'yoy': ipyoy, 'invert': False},
                    'Index %.2f, %s%.2f%% year on year and %s on the month. %s'
                    % (float(ip), '+' if (ipyoy or 0) >= 0 else '', float(ipyoy or 0), ipdir or 'flat', weight_note))

        def d_gsr():
            if gsr is None: return None
            sc = 2 if gsr >= 85 else (1 if gsr >= 75 else (-2 if gsr <= 55 else (-1 if gsr <= 62 else 0)))
            return ('gs_ratio', 'Gold-to-silver ratio', gsr, ':1', clamp(sc), None, None,
                    'It takes %.1f ounces of silver to buy an ounce of gold. The long-run band is roughly '
                    '60-80: above it silver is historically cheap against gold and tends to catch up; below '
                    'it silver is the expensive one. At %.1f silver looks %s.'
                    % (float(gsr), float(gsr), 'cheap' if gsr >= 75 else ('expensive' if gsr <= 62 else 'fairly priced')))

        def d_infl():
            if cpi is None: return None
            sc = 2 if cpi >= 4.0 else (1 if cpi >= 3.0 else (-1 if cpi < 2.0 else 0))
            return ('inflation', 'CPI inflation', cpi, '%', clamp(sc), us.get('cpi_yoy_mom_dir'),
                    {'wow': None, 'mom': us.get('cpi_yoy_mom'), 'qoq': us.get('cpi_yoy_qoq'), 'invert': False},
                    'Metals are bought as an inflation hedge. CPI at %.1f%% sits %s the 2%% target, which %s that case.'
                    % (float(cpi), 'well above' if cpi >= 3.0 else 'near', 'supports' if cpi >= 3.0 else 'weakens'))

        def d_fed():
            if fr is None: return None
            sc = 1 if fr <= 3.0 else (-1 if fr >= 4.5 else 0)
            return ('fed', 'Fed policy rate', fr, '%', sc, None, None,
                    'Cash competes with metal. A %.2f%% policy rate is %s hurdle for a non-yielding asset.'
                    % (float(fr), 'a low' if fr <= 3.0 else ('a real' if fr >= 4.5 else 'a moderate')))

        def d_cot(mk, label):
            pct, wow = met.get('cot_%s_pct' % mk), met.get('cot_%s_pct_wow' % mk)
            if pct is None: return None
            sc = -2 if pct >= 70 else (-1 if pct >= 55 else (2 if pct <= 20 else (1 if pct <= 35 else 0)))
            if wow is not None: sc += 1 if wow > 2 else (-1 if wow < -2 else 0)
            return ('cot', '%s speculative positioning' % label, pct, '% net/OI', clamp(sc),
                    met.get('cot_%s_pct_wow_dir' % mk),
                    {'wow': wow, 'mom': met.get('cot_%s_pct_mom' % mk), 'qoq': None, 'invert': False},
                    'Futures net length is %.1f%% of open interest%s. Positioning does not cause the move; it '
                    'shows how crowded the trade already is. Heavy length means a thin cushion, washed-out length means room to run.'
                    % (float(pct), (', %+.1f points on the week' % wow) if wow is not None else ''))

        def d_trend(mk, label):
            tr, rsi, px = met.get('%s_px_ma_trend' % mk), met.get('%s_px_rsi14' % mk), met.get('%s_px' % mk)
            if tr is None and rsi is None: return None
            sc = 1 if tr == 'up' else (-1 if tr == 'down' else 0)
            if rsi is not None: sc += -1 if rsi >= 70 else (1 if rsi <= 30 else 0)
            return ('trend', '%s price trend' % label, px, 'USD', clamp(sc), tr,
                    {'wow': met.get('%s_px_wow' % mk), 'mom': met.get('%s_px_mom' % mk), 'qoq': met.get('%s_px_qoq' % mk), 'invert': False},
                    'Price is %s its moving averages with RSI %s. Trend confirms a move, it does not cause one.'
                    % (tr or 'flat', ('%.1f' % rsi) if rsi is not None else 'n/a'))

        # ---- per-metal models: (driver, weight) ----
        MODELS = {
            'gold': {'label': 'Gold', 'nature': 'Monetary metal \u2014 industrial use is only about 5% of demand, so gold is priced almost entirely by macro.',
                     'rows': [(d_real(), 3), (d_dxy(), 2), (d_infl(), 2), (d_fed(), 2), (d_cot('gold', 'Gold'), 1), (d_trend('gold', 'Gold'), 1)]},
            'silver': {'label': 'Silver', 'nature': 'DUAL metal \u2014 roughly 50-60% of silver demand is industrial (solar PV alone is about 29%, up from 11% in 2014), so factory activity is its demand engine; on top of that it inherits gold\u2019s macro sensitivity in amplified form.',
                       'rows': [(d_industrial('Silver is half an industrial metal, so this is its demand engine \u2014 solar panels, electronics, EVs and data centres.'), 3),
                                (d_real(), 2), (d_dxy(), 2), (d_gsr(), 2), (d_cot('silver', 'Silver'), 1), (d_trend('silver', 'Silver'), 1)]},
            'copper': {'label': 'Copper', 'nature': 'Pure industrial metal \u2014 the classic growth barometer; no monetary bid at all.',
                       'rows': [(d_industrial('Copper is a direct read on manufacturing and construction activity.'), 3), (d_dxy(), 2),
                                (d_cot('copper', 'Copper'), 1), (d_trend('copper', 'Copper'), 1)]},
            'platinum': {'label': 'Platinum', 'nature': 'Industrial-first precious metal \u2014 autocatalysts and industry dominate, with a smaller investment bid.',
                         'rows': [(d_industrial('Platinum demand is led by autocatalysts and industrial use.'), 3), (d_dxy(), 2), (d_real(), 1), (d_trend('platinum', 'Platinum'), 1)]},
            'palladium': {'label': 'Palladium', 'nature': 'Almost entirely an autocatalyst metal \u2014 the most industrially exposed of the precious group, and structurally challenged by EV substitution.',
                          'rows': [(d_industrial('Palladium is an autocatalyst metal \u2014 vehicle production is nearly all of its demand.'), 3), (d_dxy(), 2), (d_trend('palladium', 'Palladium'), 1)]},
        }

        out_metals = {}
        for mk, cfg in MODELS.items():
            drv, tw, raw = [], 0, 0
            for row, wt in cfg['rows']:
                if not row: continue
                key, label, val, unit, sc, direction, trend, why = row
                drv.append({'key': key, 'label': label, 'value': val, 'unit': unit, 'score': sc,
                            'weight': wt, 'direction': direction, 'why': why, 'trend': trend,
                            'side': 'favouring' if sc > 0 else ('pressuring' if sc < 0 else 'neutral'),
                            'impact': abs(sc * wt)})
                tw += wt; raw += sc * wt
            if not drv: continue
            comp = round(raw / (tw * 3.0) * 100, 1)
            fav = [x for x in drv if x['score'] > 0]; pre = [x for x in drv if x['score'] < 0]
            agree = max(len(fav), len(pre)) / float(len(drv))
            conf = 'high' if (abs(comp) >= 35 and agree >= 0.6) else ('moderate' if abs(comp) >= 15 else 'low')
            if comp >= 30: bias, arrow = 'BULLISH', 'higher'
            elif comp >= 10: bias, arrow = 'LEAN BULLISH', 'mildly higher'
            elif comp <= -30: bias, arrow = 'BEARISH', 'lower'
            elif comp <= -10: bias, arrow = 'LEAN BEARISH', 'mildly lower'
            else: bias, arrow = 'NEUTRAL', 'range-bound'
            out_metals[mk] = {
                'label': cfg['label'], 'nature': cfg['nature'], 'price': met.get('%s_px' % mk),
                'composite': comp, 'bias': bias, 'confidence': conf,
                'favouring': sorted(fav, key=lambda x: -x['impact']),
                'pressuring': sorted(pre, key=lambda x: -x['impact']),
                'neutral': [x for x in drv if x['score'] == 0],
                'drivers': sorted(drv, key=lambda x: -x['impact']),
                'projection_1m': _proj_range(met.get('%s_px' % mk), met.get('%s_px_hist' % mk), comp, 1),
                'projection_2m': _proj_range(met.get('%s_px' % mk), met.get('%s_px_hist' % mk), comp, 2),
                'analyst': (lambda a: (dict(a, gap_pct=(round((a['consensus'] / float(met.get('%s_px' % mk)) - 1) * 100, 1)
                                                        if met.get('%s_px' % mk) else None))
                                       if a else None))(METAL_ANALYST_VIEW.get(mk)),
                'outlook': ('Over the next one to two months the macro and demand drivers point %s, '
                            'confidence %s (%d of %d drivers agree). This is a DIRECTIONAL BIAS from the '
                            'factors below, not a price target \u2014 a single policy surprise or geopolitical '
                            'shock can override the whole board.'
                            % (arrow, conf, max(len(fav), len(pre)), len(drv))),
            }
        gold_c = (out_metals.get('gold') or {}).get('composite', 0)
        payload = {'as_of': dt.datetime.utcnow().isoformat() + 'Z', 'real_yield': real,
                   'gs_ratio': gsr, 'metals': out_metals,
                   'composite': gold_c, 'bias': (out_metals.get('gold') or {}).get('bias'),
                   'not_covered': [
                       {'driver': 'Central-bank gold buying', 'why': 'The structural floor under gold since 2022. World Gold Council reports it QUARTERLY \u2014 no free live feed; would need a quarterly config entry.'},
                       {'driver': 'ETF flows (gold and silver)', 'why': 'Western investor demand; amplifies moves both ways and turns fast. World Gold Council publishes monthly; not currently plumbed.'},
                       {'driver': 'Solar PV installation and silver-thrifting data', 'why': 'Silver\u2019s single biggest industrial swing factor \u2014 panel makers are cutting silver per cell even as capacity grows. Silver Institute / BloombergNEF, annual and quarterly.'},
                       {'driver': 'Exchange and vault inventories', 'why': 'Drawdowns signal physical tightness; rebuilds signal the opposite. Published by COMEX/LBMA but not currently fetched.'},
                       {'driver': 'Geopolitical risk index', 'why': 'Drives safe-haven spikes; loosely proxied today by the Narratives tab\u2019s defence and White House themes.'}]}
        log('  [Metals drivers] real yield %s%% | ' % real
            + ' | '.join('%s %+.1f %s' % (v['label'], v['composite'], v['bias']) for v in out_metals.values()))
        return payload
    except Exception as e:
        log('  [Metals drivers] skipped: %s' % type(e).__name__)
        return {'error': type(e).__name__}


def build_ep_signal(data):
    """v1.302.0 (audit gap #2). The dashboard fetched Brent and WTI correctly but NOTHING
    acted on them, while the owner's standing rule is 'Arab Light > $60 = overweight E&P' and
    he holds XOM/CVX/COP/EOG. Arab Light is an OSP benchmark with no free live feed, so it is
    derived HONESTLY from Brent minus a small stated differential and labelled a proxy -- the
    trigger is never presented as an exact Arab Light print. Returns the signal; never raises."""
    try:
        us = (data.get('macros') or {}).get('us') or {}
        brent = us.get('brent')
        if brent is None:
            return {'fired': None, 'reason': 'Brent unavailable this run \u2014 trigger cannot be evaluated'}
        al = round(float(brent) - ARAB_LIGHT_DIFF_USD, 2)
        fired = al >= EP_TRIGGER_USD
        held = [t for t in EP_NAMES]
        grades = {}
        for r in (data.get('explosive_us') or []):
            if isinstance(r, dict) and r.get('ticker') in EP_NAMES and isinstance(r.get('im3'), dict):
                grades[r['ticker']] = r['im3'].get('grade')
        for t in EP_NAMES:
            if t not in grades:
                grades[t] = ((data.get('im3_grade_book') or {}).get(t) or {}).get('grade')
        sig = {
            'fired': bool(fired),
            'arab_light_proxy': al,
            'brent': round(float(brent), 2),
            'wti': us.get('wti'),
            'differential_usd': ARAB_LIGHT_DIFF_USD,
            'threshold': EP_TRIGGER_USD,
            'basis': ('Arab Light proxy = Brent \u2212 $%.2f official-selling-price differential '
                      '(no free live Arab Light feed; the differential is a stated constant, not a scrape)'
                      % ARAB_LIGHT_DIFF_USD),
            'brent_date': us.get('brent_date'),
            'action': ('OVERWEIGHT E&P \u2014 your standing rule fires: the crude benchmark is above $%.0f'
                       % EP_TRIGGER_USD) if fired else
                      ('NEUTRAL on E&P \u2014 the crude benchmark is below $%.0f' % EP_TRIGGER_USD),
            'names': EP_NAMES,
            'grades': grades,
            'brent_mom': us.get('brent_mom'),
            'brent_wow': us.get('brent_wow'),
        }
        log(f"  [E&P trigger] Arab Light proxy ${al} vs ${EP_TRIGGER_USD} -> "
            f"{'FIRED (overweight E&P)' if fired else 'neutral'} (Brent ${brent})")
        return sig
    except Exception as e:
        log(f'  [E&P trigger] skipped: {type(e).__name__}')
        return {'fired': None, 'reason': f'{type(e).__name__} while evaluating'}


def _round_floats(o, nd=4):
    """v1.301.0 (owner-approved size pass): data.json carried full 16-digit float repr
    (87.48824082784571) where 4 decimals is everything any tile, chip or chart displays --
    pure noise in a 9 MB file. Round ONLY at the write boundary, so every in-run calculation
    keeps full precision. Ints/bools/strings/None untouched; NaN/Inf pass through so the
    existing allow_nan=False guard still catches them."""
    if isinstance(o, bool):
        return o
    if isinstance(o, float):
        return o if o != o or o in (float('inf'), float('-inf')) else round(o, nd)
    if isinstance(o, dict):
        return {k: _round_floats(v, nd) for k, v in o.items()}
    if isinstance(o, list):
        return [_round_floats(v, nd) for v in o]
    return o

def main():
    _RUN_T0 = time.time()
    _STAGE_MS.clear()
    log('=' * 60)
    log(f'Dashboard scanner v{SCAN_VERSION} starting')
    log('=' * 60)
    _sec_row_contract_check()

    data = DEFAULT_DATA.copy()
    data['meta'] = {
        'scan_version':  SCAN_VERSION,
        'last_scan_utc': dt.datetime.utcnow().isoformat() + 'Z',
        'errors':        [],
        'warnings':      [],
    }

    try:
        data['macros']['us'] = _stage('fetch_us_macros', fetch_us_macros)
    except Exception as e:
        log(f'US macros crashed: {e}')
        data['meta']['errors'].append(f'us_macros: {e}')
        data['macros']['us'] = EXISTING.get('macros', {}).get('us', {})

    try:
        data['macros']['psx'] = _stage('fetch_psx_macros', fetch_psx_macros)
    except Exception as e:
        log(f'PSX macros crashed: {e}')
        data['meta']['errors'].append(f'psx_macros: {e}')
        data['macros']['psx'] = EXISTING.get('macros', {}).get('psx', {})

    try:
        data['macros']['metals'] = _stage('metals', fetch_metals)
    except Exception as e:
        log(f'Metals macros crashed: {e}')
        data['meta']['errors'].append(f'metals_macros: {e}')
        data['macros']['metals'] = EXISTING.get('macros', {}).get('metals', {})

    us_all_survivors = []
    try:
        us_result = _stage('screen_us', screen_us_universe)
        data['us_funnel']    = us_result['funnel']
        data['us_candidates'] = us_result['candidates']
        us_all_survivors     = us_result.get('all_survivors', us_result['candidates'])
    except Exception as e:
        log(f'US screening crashed: {e}')
        data['meta']['errors'].append(f'us_screen: {e}')
        data['us_funnel']    = EXISTING.get('us_funnel', [])
        data['us_candidates'] = EXISTING.get('us_candidates', [])
        us_all_survivors     = data['us_candidates']

    # Multibagger (Phase M-1): live fetch-and-score, ranked by CFO/CPAT. Freeze-safe, cannot crash run.
    try:
        data['us_multibagger'] = _stage('us_multibagger', build_us_multibagger, us_all_survivors)
    except Exception as e:
        log(f'  [Multibagger US] failed: {e} -- carrying last-good')
        data['us_multibagger'] = EXISTING.get('us_multibagger', [])

    # Foundation Universe (from TradingView): the shared live whole-market scan (M2 'universe
    # keystone'). First consumer = the Explosive screen -> add the accelerating large-caps that the
    # frozen 218-name curated list hid. Freeze-safe: on any miss the pool == us_all_survivors (prior
    # behaviour), and the existing survivors stay FIRST/unchanged so prior EXPLOSIVE verdicts hold.
    us_explosive_pool = us_all_survivors
    try:
        _foundation = _stage('foundation_universe', fetch_foundation_universe)
        if _foundation:
            data['foundation_universe'] = [
                {k: r.get(k) for k in ('ticker', 'name', 'sector', 'market_cap_m',
                                       'rev_growth', 'eps_growth', 'perf_6m', 'perf_3m', 'roic',
                                       'perf_ytd', 'perf_1y', 'perf_5y', 'close', 'price',
                                       'sma50', 'sma200',
                                       'earnings_per_share_forecast_next_fq', 'recommendation_mark',
                                       'average_volume_10d_calc', 'average_volume_60d_calc')}
                for r in _foundation]
            _adds = _foundation_explosive_additions(_foundation, us_all_survivors)
            us_explosive_pool = us_all_survivors + _adds
            log(f'  [Foundation Universe] TradingView america scan: {len(_foundation)} US-listed names '
                f'>= ${US_SMALL_CAP_MAX/1e9:.0f}bn (seamless with the $300M-$2bn small-cap band -> continuous '
                f'coverage); added top {len(_adds)} accelerating large/mid-caps to Explosive pool '
                f'({len(us_all_survivors)} -> {len(us_explosive_pool)})')
        else:
            data['foundation_universe'] = EXISTING.get('foundation_universe', [])
            log('  [Foundation Universe] empty/unreachable -> Explosive pool unchanged (prior behaviour)')
    except Exception as e:
        log(f'  [Foundation Universe] failed: {e} -- Explosive pool unchanged')
        data['foundation_universe'] = EXISTING.get('foundation_universe', [])
        us_explosive_pool = us_all_survivors

    # M1/M2 shared keystone (Layer 1): score the Foundation Universe + emit the 61% split.
    # Freeze-safe/data-only; feeds M1 Stage 8 and the front of M2. Never blocks the run.
    try:
        build_m2_universe(data)
    except Exception as e:
        log(f'  [M2 keystone] failed: {e} -- carrying last-good')
        data['m2_universe'] = EXISTING.get('m2_universe', {})

    # v1.209.0: the estimate-revision clock -- snapshot forward consensus daily; compute revision
    # signals once 30/90-day history accrues. Additive/freeze-safe; carries last-good.
    try:
        build_estimate_history(data, EXISTING)
    except Exception as e:
        log(f'  [Estimate clock] failed: {e}')

    # Wave R (Option C): per-sector medians for peer-relative IM3 (P/E, margins, ROE).
    # Isolated POST; failure carries last-good. Writes sector_medians.json for im3_score.py.
    try:
        data['sector_medians'] = _stage('sector_medians', fetch_sector_medians)
        try:
            probe_dividend_yield_columns()
        except Exception as _e:
            log(f'  [div-yield probe] skipped ({_e})')
        try:
            probe_data_sources_v199()
        except Exception as _e:
            log(f'  [v199 probe] skipped ({_e})')
        try:
            probe_cot_legacy()
        except Exception as _e:
            log(f'  [COT legacy probe] skipped ({_e})')
    except Exception as e:
        log(f'sector medians crashed: {e}')
        data['sector_medians'] = EXISTING.get('sector_medians', {}) or {}

    # Wave M-A step 2b: surface a clean top-level US sector-breadth block (% of each sector
    # at/above its 200-DMA) for the dashboard, derived from the same medians POST above.
    try:
        _sm = data.get('sector_medians') or {}
        data['sector_breadth'] = {
            sec: {'pct': v['breadth_200dma'], 'n': v.get('breadth_n', v.get('n')),
                  'above': round(v['breadth_200dma'] * v.get('breadth_n', v.get('n', 0)) / 100.0)}
            for sec, v in _sm.items() if isinstance(v, dict) and v.get('breadth_200dma') is not None
        }
        if not data['sector_breadth']:
            data['sector_breadth'] = EXISTING.get('sector_breadth', {}) or {}
    except Exception as e:
        log(f'sector breadth derive crashed: {e}')
        data['sector_breadth'] = EXISTING.get('sector_breadth', {}) or {}

    # Wave M-A step 2b (PSX): wide-universe PSX sector breadth (% above 200-DMA), own isolated POST.
    try:
        data['psx_sector_breadth'] = fetch_psx_sector_breadth() or (EXISTING.get('psx_sector_breadth', {}) or {})
    except Exception as e:
        log(f'psx sector breadth crashed: {e}')
        data['psx_sector_breadth'] = EXISTING.get('psx_sector_breadth', {}) or {}

    # Wave S Phase 2 (PSX): PSX sector MEDIANS (P/E, margins, ROE) + price-move (Perf.W/1M/3M), own isolated POST.
    try:
        data['psx_sector_medians'] = fetch_psx_sector_medians() or (EXISTING.get('psx_sector_medians', {}) or {})
    except Exception as e:
        log(f'psx sector medians crashed: {e}')
        data['psx_sector_medians'] = EXISTING.get('psx_sector_medians', {}) or {}

    # Wave S (PSX): PSX sector composite scores (v1.121.0)
    try:
        _psb = compute_psx_sector_booming(
            data.get('psx_sector_breadth', {}),
            data.get('psx_sector_medians', {}),
            (data.get('macros') or {}).get('psx') or {}
        )
        # WoW delta vs EXISTING (same pattern as US sector_booming)
        _prior_psb = {r['sector']: r['score'] for r in (EXISTING.get('psx_sector_booming') or [])
                      if isinstance(r, dict) and r.get('sector') and r.get('score') is not None}
        for _r in _psb:
            _sec = _r.get('sector'); _now = _r.get('score')
            _prev = _prior_psb.get(_sec)
            if _now is not None and _prev is not None:
                _d = round(_now - _prev, 1)
                _r['score_delta'] = _d
                _r['score_trend'] = 'rising' if _d >= 1.0 else ('falling' if _d <= -1.0 else 'flat')
        data['psx_sector_booming'] = _psb or EXISTING.get('psx_sector_booming', []) or []
    except Exception as _e:
        log(f'  [PSX Sector Booming] skipped: {type(_e).__name__}: {str(_e)[:50]}')
        data['psx_sector_booming'] = EXISTING.get('psx_sector_booming', []) or []

        # Wave PK-D: PSX PKR-devaluation alert (display/data-only multi-signal basket).
    try:
        _psx_m = dict((data.get('macros') or {}).get('psx') or {})
        _psx_m['_history_ref'] = data.get('history') or []
        # v1.314.32: fold this session's live street-level feeds into the basket. The kerb
        # and bullion builds run LATER in main() than this call, so read data-or-EXISTING --
        # at this point data has neither yet, so yesterday's premium is used (the exact
        # crowdedness/Wave-O precedent: these are calm, slow daily feeds, so last run's read
        # is today's truth; None -> the signal scores 0, never a regression).
        _kb = (data.get('psx_kerb') or EXISTING.get('psx_kerb') or {})
        _bl = (data.get('psx_bullion') or EXISTING.get('psx_bullion') or {})
        _psx_m['_kerb_premium'] = _kb.get('premium_pct')
        _psx_m['_gold_premium'] = _bl.get('implied_premium_pct')
        data['psx_devaluation'] = compute_psx_devaluation(_psx_m)
        _pkd = data['psx_devaluation']
        log(f'  [Wave PK-D] devaluation: {str(_pkd.get("level", "?")).upper()} '
            f'(score {_pkd.get("score")}/{_pkd.get("max_score")}) -> '
            + ', '.join(f'{k}={v.get("points")}' for k, v in (_pkd.get('signals') or {}).items()))
    except Exception as e:
        log(f'psx devaluation crashed: {e}')
        data['psx_devaluation'] = EXISTING.get('psx_devaluation', {}) or {}

    try:
        psx_result = _stage('screen_psx', screen_psx_universe)
        data['psx_funnel']    = psx_result['funnel']
        data['psx_candidates'] = psx_result['candidates']
        # Wave PSX-DPS: full-universe live feed from dps.psx.com.pk (confirmed reachable+static 2026-07-12).
        # ADDITIVE + guarded -> the TV-driven screening above is untouched; this only ADDS a data['psx_market_watch']
        # table (F5 full watchlist + TV-independent price/index-membership cross-check). Carries last-good on any miss.
        try:
            _mw = fetch_psx_market_watch()
            if _mw:
                data['psx_market_watch'] = {'as_of': dt.datetime.utcnow().isoformat() + 'Z', 'source': 'dps.psx.com.pk/market-watch',
                                            'n': len(_mw), 'rows': _mw}
            else:
                data['psx_market_watch'] = EXISTING.get('psx_market_watch', {})
        except Exception as _e:
            log(f'  [Wave PSX-DPS] error ({_e}) -> carry last-good'); data['psx_market_watch'] = EXISTING.get('psx_market_watch', {})
        # Wave PSX-PX: make the OFFICIAL dps.psx exchange close the PRIMARY price across the dashboard,
        # falling back to the TradingView scan close when a name is absent from market-watch. dps.psx carries
        # PRICE ONLY (no fundamentals) so ONLY the price is switched; every TV fundamental field is untouched.
        # v1.226.0 CORRECTION: data['psx_candidates'] is a list of rich DICTS (ticker/price/analyst{close}),
        # not the 7-tuple the v1.224.1 code assumed -- so the old isinstance(tuple) guard skipped every name
        # (the 751 run logged '0 names'). Verified against the literal data.json fixture: each candidate is
        # {'ticker': bare-symbol, 'price': ..., 'analyst': {'close': ...}, ...} and market-watch keys are the
        # same bare symbols. Both the top-level price AND analyst.close are set (consumers read both).
        try:
            _mw_rows = (data.get('psx_market_watch') or {}).get('rows') or {}
            if _mw_rows and data.get('psx_candidates'):
                _n_dps = _n_tv = 0
                for _c in data['psx_candidates']:
                    if not isinstance(_c, dict):
                        continue
                    _tkr = _c.get('ticker')
                    _dps = (_mw_rows.get(_tkr) or {}).get('price')
                    try:
                        _dps = float(_dps) if _dps is not None else None
                    except Exception:
                        _dps = None
                    if _dps is not None and _dps > 0:
                        _c['tv_price'] = _c.get('price')          # keep TV price for provenance / ratio basis
                        _c['price'] = _dps
                        if isinstance(_c.get('analyst'), dict):
                            _c['analyst']['tv_close'] = _c['analyst'].get('close')
                            _c['analyst']['close'] = _dps
                        _c['price_source'] = 'dps.psx'
                        _n_dps += 1
                    else:
                        _c['price_source'] = 'tv-fallback'
                        _n_tv += 1
                log(f'  [Wave PSX-PX] PSX price PRIMARY = dps.psx official close ({_n_dps} names), '
                    f'TV fallback ({_n_tv}); fundamentals stay TradingView')
        except Exception as _e:
            log(f'  [Wave PSX-PX] error ({_e}) -> prices unchanged (TV)')
        # Wave PSX-EOD: RETIRED as a live fetch (v1.228.0). Both free per-stock PSX-history endpoints were
        # proven blocked from the runner: timeseries/eod returns no-data (807 run), and /historical rate-limits
        # + connection-refuses bulk automated access (822 run: 28 ConnectionError / 5 http429 / 15 no-cols, 0
        # usable, 79s wasted). The exchange blocks datacenter bulk scraping. F1's 6-month leg is now served by
        # TradingView's Perf.6M instead (added to PSX_SCAN_COLS -- same proven scan, no extra request). We keep
        # last-good psx_eod_history so the dormant F1 secondary + any future paid PSX-history feed still work;
        # build_psx_eod_history stays DEFINED (zero runner cost) for that drop-in. No fetch -> ~79s reclaimed.
        data['psx_eod_history'] = EXISTING.get('psx_eod_history', {})
        # Wave Q Phase-1: bank-data overlays (display/context + sector evaluation; never the IG2 scoring series)
        try:
            _bank_syms = sorted({c.get('ticker') for c in data['psx_candidates']
                                 if c.get('ticker') and _is_true_bank(c.get('sector'), c.get('name'), c.get('ticker'))})
            data['bank_snapshot'] = fetch_bank_snapshot(_bank_syms)
        except Exception as _e:
            log(f'  [Wave Q snapshot] error ({_e})'); data['bank_snapshot'] = EXISTING.get('bank_snapshot', {})
        try:
            data['bank_sector'] = fetch_bank_sector_kpmg()
        except Exception as _e:
            log(f'  [Wave Q sector] error ({_e})'); data['bank_sector'] = EXISTING.get('bank_sector', {})
        # A (SCS -> IG2 fallback): write roe/adr/roa-trend overrides for partial banks (fill-missing only downstream)
        try:
            write_bank_ig2_overrides(data)
        except Exception as _e:
            log(f'  [Wave Q->IG2] override write error ({_e})')
        try:
            fetch_us_bank_ig2(data)   # Group-D: FDIC US-bank IG2 inputs -> MERGE into bank_ig2_overrides.json (consumer already wired, calib=us)
        except Exception as _e:
            log(f'  [US-bank IG2] error ({_e})')
    except Exception as e:
        log(f'PSX screening crashed: {e}')
        data['meta']['errors'].append(f'psx_screen: {e}')
        data['psx_funnel']    = EXISTING.get('psx_funnel', [])
        data['psx_candidates'] = EXISTING.get('psx_candidates', [])

    # Wave P Phase-1 + v1.48.0 change-tracking: AMC fund-ownership overlay + month-over-month FLOW
    # (DISPLAY ONLY; not a scored stream -> respects freeze). FMRs are MONTHLY PDFs, so the fetch is
    # throttled to once / 7 days (carry last-good between -> ~6x less load on fundbazaarglobal).
    try:
        _prev_fo = EXISTING.get('psx_fund_ownership', {}) or {}
        _last_fetch = _prev_fo.get('last_fetch_utc'); _age = None
        if _last_fetch:
            try:
                _age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(str(_last_fetch).replace('Z', ''))).days
            except Exception:
                _age = None
        if _age is not None and _age < 7 and _prev_fo.get('by_ticker'):
            log(f'  [Wave P FMR] fetch skipped ({_age}d ago, <7d) — carrying last-good fund-ownership + flows')
            data['psx_fund_ownership'] = _prev_fo
            _carry = _prev_fo.get('by_ticker', {})
            for _c in data['psx_candidates']:
                _o = _carry.get(_c.get('ticker'))
                if _o:
                    _c['fund_ownership'] = _o
        else:
            _fmr_by_ticker, _fmr_meta, _cur_per_fund = fetch_fmr_fund_ownership()
            if _fmr_by_ticker:
                _snaps = _prev_fo.get('snapshots') or []
                _prior_pf = _snaps[-1].get('per_fund') if _snaps else None
                _flows = _fmr_compute_flows(_cur_per_fund, _prior_pf) if _prior_pf else {}
                for _tk, _v in _fmr_by_ticker.items():
                    _fl = _flows.get(_tk)
                    if _fl:
                        _v.update(_fl)
                    else:
                        _v['flow'] = 'BASELINE'; _v['funds_delta'] = None; _v['weight_delta'] = None
                for _c in data['psx_candidates']:
                    _o = _fmr_by_ticker.get(_c.get('ticker'))
                    if _o:
                        _c['fund_ownership'] = _o
                # snapshot history: append current ONLY on a clean refresh (coverage not regressed +
                # content changed) so weekly re-fetches of the SAME monthly FMR never pollute the baseline
                def _sig(pf):
                    return frozenset((t, round(w, 1)) for fnd in pf for t, w in pf[fnd].items())
                _changed = (not _prior_pf) or (_sig(_cur_per_fund) != _sig(_prior_pf))
                _new_snaps = list(_snaps)
                if _changed and set(_cur_per_fund) >= (set(_prior_pf) if _prior_pf else set()):
                    _new_snaps.append({'ts': dt.datetime.utcnow().isoformat() + 'Z', 'per_fund': _cur_per_fund})
                    _new_snaps = _new_snaps[-4:]
                _n_mv = sum(1 for _v in _fmr_by_ticker.values()
                            if _v.get('flow') in ('ACCUMULATING', 'TRIMMING', 'NEW', 'EXITED'))
                log('  [Wave P FMR] flow: ' + ('BASELINE run (first deltas land next month)' if not _prior_pf
                    else f'{_n_mv} names moved vs prior snapshot; {len(_new_snaps)} snapshot(s) kept'))
                data['psx_fund_ownership'] = {'by_ticker': _fmr_by_ticker, 'meta': _fmr_meta,
                                              'snapshots': _new_snaps,
                                              'last_fetch_utc': dt.datetime.utcnow().isoformat() + 'Z'}
            else:
                data['psx_fund_ownership'] = _prev_fo
    except Exception as e:
        log(f'  [Wave P FMR] overlay error ({e}) -> skipped')
        data['psx_fund_ownership'] = EXISTING.get('psx_fund_ownership', {})

    # Wave PSX-R Phase-1: SCS Valuation Matrix overlay (DISPLAY/data only; weekly PDF -> throttle 7d,
    # carry last-good between). Never touches screening/scoring/TCE -> respects the Sept freeze.
    try:
        _prev_vm = EXISTING.get('psx_valuation_matrix', {}) or {}
        _vm_last = _prev_vm.get('last_fetch_utc'); _vm_age = None
        if _vm_last:
            try:
                _vm_age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(str(_vm_last).replace('Z', ''))).days
            except Exception:
                _vm_age = None
        if _vm_age is not None and _vm_age < 7 and _prev_vm.get('by_ticker') and ('suggested' in _prev_vm):
            log(f'  [Wave PSX-R valmatrix] fetch skipped ({_vm_age}d ago, <7d) — carrying last-good')
            data['psx_valuation_matrix'] = _prev_vm
        else:
            _vm = fetch_psx_valuation_matrix()
            if _vm.get('by_ticker'):
                _vm['last_fetch_utc'] = dt.datetime.utcnow().isoformat() + 'Z'
                data['psx_valuation_matrix'] = _vm
            else:
                data['psx_valuation_matrix'] = _prev_vm
    except Exception as e:
        log(f'  [Wave PSX-R valmatrix] overlay error ({e}) -> skipped')
        data['psx_valuation_matrix'] = EXISTING.get('psx_valuation_matrix', {})

    # Wave PSX-R Phase-3: SCS MTS leverage gauge (DISPLAY/data only; daily PDF; guarded, last-good).
    # Never touches screening/scoring/TCE -> respects the Sept freeze.
    try:
        probe_mts_sources()   # Wave PSX-R Phase-3b: hunt a live (non-frozen) MTS source; logging-only, gated
    except Exception as _e:
        warn(f'MTS probe failed (non-blocking): {_e}')
    try:
        # v1.223.1: MTS leverage gauge is now a MANUAL OVERRIDE (SBP_RESERVES precedent). Every free automated
        # source for the market-wide MTS total is confirmed dead (NCCPL 403 / Business Recorder JS / dps.psx
        # announcements JS / SCS PDF frozen 156d) -> the auto-fetchers fetch_brec_mts()/fetch_psx_mts() are
        # RETIRED (defined but no longer called; zero runner cost). The total comes from psx_macros_manual.json
        # else the in-repo baseline, with the honest as-of/stale flag intact -- exactly like sbp_reserves.
        _mts = build_psx_mts_live_or_manual()
        if _mts.get('market') or _mts.get('book'):
            _mts['last_fetch_utc'] = dt.datetime.utcnow().isoformat() + 'Z'
            data['psx_mts'] = _mts
        else:
            data['psx_mts'] = EXISTING.get('psx_mts', {})
    except Exception as e:
        log(f'  [Wave PSX-R MTS] overlay error ({e}) -> skipped')
        data['psx_mts'] = EXISTING.get('psx_mts', {})

    # v1.314.19: BR /ajax/ feeds -- kerb premium (Tab 4) + FIPI/LIPI flows (Tab 9/5)
    try:
        data['psx_kerb'] = build_psx_kerb(data)
    except Exception as e:
        log(f'  [BR kerb] builder error ({e}) -> carry')
        data['psx_kerb'] = EXISTING.get('psx_kerb', {'available': False, 'note': 'builder error'})
    try:
        data['psx_flows'] = build_psx_flows()
    except Exception as e:
        log(f'  [BR flows] builder error ({e}) -> carry')
        data['psx_flows'] = EXISTING.get('psx_flows', {'available': False, 'note': 'builder error'})
    # v1.314.26 Phase 3: KIBOR (Tab 2 defensive trigger) + official FX (Tab 4) + bullion (Tab 4/12)
    try:
        data['psx_kibor'] = build_psx_kibor()
    except Exception as e:
        log(f'  [BR kibor] builder error ({e}) -> carry')
        data['psx_kibor'] = EXISTING.get('psx_kibor', {'available': False, 'note': 'builder error'})
    try:
        data['psx_official_fx'] = build_psx_official_fx()
    except Exception as e:
        log(f'  [BR fx] builder error ({e}) -> carry')
        data['psx_official_fx'] = EXISTING.get('psx_official_fx', {'available': False, 'note': 'builder error'})
    try:
        data['psx_bullion'] = build_psx_bullion(data)
    except Exception as e:
        log(f'  [BR bullion] builder error ({e}) -> carry')
        data['psx_bullion'] = EXISTING.get('psx_bullion', {'available': False, 'note': 'builder error'})

    # v1.283.0: psx_msci block removed (see note at former fetch_psx_msci site).
    # v1.434.0: THE MISSING try: RESTORED. The v1.283.0 removal deleted this block's opening try:
    # and, because comments are invisible to indentation, the psx_market lines silently reattached
    # to the PRECEDING bullion except handler -- making a valid two-except try in which the breadth
    # fetch only ran if build_psx_bullion RAISED. Bullion never raises -> fetch_psx_market_stats was
    # unreachable since v1.283.0 (AST-proven: Try@24187 body=1 stmt, 2 handlers, fetch inside handler 1;
    # zero psx_market stage timing in every audited run). Tab 2 breadth panel blank was THIS, not TV.
    try:
        data['psx_market'] = _stage('psx_market', fetch_psx_market_stats)
        if not data['psx_market']:
            data['psx_market'] = EXISTING.get('psx_market', {})
    except Exception as e:
        log(f'  [Wave P breadth] error ({e}) -> skipped')
        data['psx_market'] = EXISTING.get('psx_market', {})

    _spy6, _spy_px = _spy_6mo_return()
    _prev_us = {r['ticker']: r['streams'].get('rev_est') for r in EXISTING.get('tce_us', [])
                if isinstance(r.get('streams'), dict)}
    _etf_stocks = (EXISTING.get('etf_overlap', {}) or {}).get('stocks', [])
    # v1.245.0 WAVE O INJECTION: whale NEW positions refill the starving discovery pool.
    # Read from the PRIOR run for the same reason the ETF names are (13F = quarterly, 45-day lag)
    # and because build_whale_13f runs AFTER run_tce in main() -- no reordering, no new fetch.
    _whale_stocks = whale_new_position_names(EXISTING)
    _us_pool = merge_tce_pool(data['us_candidates'], _etf_stocks, _whale_stocks)
    _n_etf = sum(1 for c in _us_pool if c.get('src') == 'etf')
    _n_whale = sum(1 for c in _us_pool if c.get('src') == 'whale')
    log(f'  US TCE pool: {len(_us_pool) - _n_etf - _n_whale} screen + {_n_etf} ETF-consensus '
        f'+ {_n_whale} whale new-position = {len(_us_pool)}'
        + (f"  [Wave O injection: {', '.join(c['ticker'] for c in _us_pool if c.get('src') == 'whale')}]"
           if _n_whale else '  [Wave O injection: none -- no prior whale data yet]'))
    # Wave O L1: attach TV FactSet analyst rows (US counterpart to D2). Best-effort.
    # v1.52 (P2b): fetch over the UNION of the TCE pool AND the explosive survivors. Previously
    # only the pool got analyst rows, so the explosive forward leg (_forward_boost) read a missing
    # c['analyst_row'] and returned F1/FR=None on EVERY explosive record. One POST, no extra cost.
    _us_analyst = fetch_us_analyst_block(
        [c.get('ticker') for c in _us_pool] + [c.get('ticker') for c in us_all_survivors])
    for _c in _us_pool:
        _ar = _us_analyst.get(_c.get('ticker'))
        _c['analyst'] = _ar
        if not _c.get('sector') and isinstance(_ar, dict) and _ar.get('sector'):
            _c['sector'] = _ar['sector']   # v1.89.0: ETF-consensus large-caps (AMAT/LRCX/AVGO/MU/NVDA/... 20 names) enter merge_tce_pool with sector='' (the ETF-overlap carries ticker+name+weight only); inherit the TV sector the analyst POST already returns so tce_us + the Results vs-sector read are populated. Never fabricated (no analyst sector -> stays blank); display-only -> respects the freeze.
    _prev_fwd_us = {r['ticker']: r['streams'].get('fwd_eps') for r in EXISTING.get('tce_us', [])
                    if isinstance(r.get('streams'), dict) and r['streams'].get('fwd_eps') is not None}
    # P2b: explosive survivors read c['analyst_row'] + c['prev_fwd_eps'] in _forward_boost.
    # Additive/safe: a miss -> None -> F1/FR=None (prior behaviour); forward leg never blocks.
    for _c in us_all_survivors:
        _c['analyst_row']  = _us_analyst.get(_c.get('ticker'))
        _c['prev_fwd_eps'] = _prev_fwd_us.get(_c.get('ticker'))
    try:
        data['tce_us'] = _stage('run_tce_us', run_tce, _us_pool, market='us',
                                  max_count=len(_us_pool), spy_6mo_ret=_spy6,
                                  prev_rev=_prev_us, prev_fwd=_prev_fwd_us)
    except Exception as e:
        log(f'US TCE crashed: {e}')
        data['meta']['errors'].append(f'us_tce: {e}')
        data['tce_us'] = EXISTING.get('tce_us', [])

    try:
        _prev_psx = {r['ticker']: r['streams'].get('rev_est') for r in EXISTING.get('tce_psx', [])
                     if isinstance(r.get('streams'), dict)}
        _prev_fwd = {r['ticker']: r['streams'].get('fwd_eps') for r in EXISTING.get('tce_psx', [])
                     if isinstance(r.get('streams'), dict) and r['streams'].get('fwd_eps') is not None}
        data['tce_psx'] = _stage('run_tce_psx', run_tce, data['psx_candidates'], market='psx',
                                  max_count=max(len(data['psx_candidates']), 10),
                                  spy_6mo_ret=_spy6, prev_rev=_prev_psx, prev_fwd=_prev_fwd)
    except Exception as e:
        log(f'PSX TCE crashed: {e}')
        data['meta']['errors'].append(f'psx_tce: {e}')
        data['tce_psx'] = EXISTING.get('tce_psx', [])

    # Forward-validation: log this run's TCE-pool picks (HIGH/WATCH/IGNORE) + entry price + benchmark;
    # re-price off-pool open picks so they mature on a live price; track forward return AND alpha over time.
    try:
        _today = dt.date.today().isoformat()
        _rows = []; _pool = set()
        # v1.37: the PSX ledger price must share one basis with the screen + _reprice_psx (both TV
        # pakistan/scan close). streams['price'] for PSX is the TCE's yahoo:.KA momentum-fetch snapshot
        # (a different vendor, systematically ~0-10% off), so for PSX rows prefer the candidate's
        # tv_scan price -> entry and maturity re-price land on the same source (no spurious offset).
        _psx_tv = {c['ticker']: c.get('price') for c in data.get('psx_candidates', []) if c.get('price')}
        for _mkt, _key in (('us', 'tce_us'), ('psx', 'tce_psx')):
            for r in data.get(_key, []):
                pr = r.get('streams', {}).get('price') if isinstance(r.get('streams'), dict) else None
                if _mkt == 'psx':
                    pr = _psx_tv.get(r['ticker'], pr)   # screen tv_scan price for PSX (US keeps Yahoo)
                if r.get('tier') in ('HIGH', 'WATCH', 'IGNORE') and pr:
                    _rows.append({'ticker': r['ticker'], 'tier': r['tier'], 'market': _mkt, 'price': pr})
                    _pool.add(r['ticker'])
        # Gap-1: live-reprice OPEN predictions whose ticker isn't in this run's pool (else they freeze stale at maturity)
        _pp = (EXISTING.get('tce_predictions') or {}).get('predictions', [])
        _open_us  = sorted({p['ticker'] for p in _pp if not p.get('resolved')
                            and p.get('market', 'us') == 'us' and p.get('days_open', 0) < PRED_HORIZON_DAYS
                            and p['ticker'] not in _pool})
        _open_psx = sorted({p['ticker'] for p in _pp if not p.get('resolved')
                            and p.get('market') == 'psx' and p.get('days_open', 0) < PRED_HORIZON_DAYS
                            and p['ticker'] not in _pool})
        _extra = {}
        _extra.update(_reprice_us(_open_us))
        _extra.update(_reprice_psx(_open_psx))
        # Gap-2: benchmark levels for alpha — SPY (already fetched for the guardrail) + KSE-100 (PSX macros)
        _bench = {'us': _spy_px, 'psx': safe_get(data, 'macros', 'psx', 'kse100')}
        data['tce_predictions'] = update_tce_predictions(EXISTING.get('tce_predictions'), _today, _rows,
                                                         extra_prices=_extra, bench=_bench)
        _s = data['tce_predictions']['summary']
        if _s.get('psx_rebaselined'):
            log(f"  ↻ PSX re-baseline (L3 follow-up): reset {_s['psx_rebaselined']} open PSX prediction(s) "
                f"from the stale dps.psx basis to the correct TV basis (one-time)")
        log(f"TCE predictions: {_s['total_logged']} logged, {_s['open']} open "
            f"(re-priced {len(_extra)}/{len(_open_us) + len(_open_psx)} off-pool); "
            f"HIGH matured={_s['HIGH']['matured']} hit={_s['HIGH']['hit_rate']} alpha={_s['HIGH']['avg_alpha_pct']} lift={_s['HIGH']['lift_vs_ignore']}; "
            f"WATCH matured={_s['WATCH']['matured']} hit={_s['WATCH']['hit_rate']}; "
            f"IGNORE matured={_s['IGNORE']['matured']} hit={_s['IGNORE']['hit_rate']}")
    except Exception as e:
        log(f'TCE prediction logger failed: {e}')
        data['tce_predictions'] = EXISTING.get('tce_predictions', {})

    _seed_sigt_cache(EXISTING)   # v1.277.0 TIMING: carry the Signal T quarterly-OP cache forward (no re-fetch every run)
    try:
        data['explosive_us'] = _stage('explosive_us', run_explosive, us_explosive_pool, market='us')
        data['explosive_stmt_cache'] = _EXPLOSIVE_CACHE_OUT   # v1.112.1: persist the US s
        data['sigt_quarterly_cache'] = _SAT_Q_CACHE_OUT   # v1.277.0: persist Signal T quarterly cache across runstatement cache in data.json (committed -> survives to next run)
        log(f"  [Signal T] quarterly data on {_SIGT_STATS['had_data']}/{_SIGT_STATS['seen']} US names; "
            f"{_SIGT_STATS['fired']} turnaround hook(s) fired "
            f"({'stockanalysis primary + SEC fallback' if _SIGT_STATS['had_data'] else 'NO quarterly data reached the hook -- check source'})")
        if _SIGT_FAIL_REASONS:  # v1.341.0: WHY the remaining empty fetches actually failed, not just a count
            for _reason, _info in sorted(_SIGT_FAIL_REASONS.items(), key=lambda kv: -kv[1]['n']):
                log(f"    [Signal T fail] {_reason}: {_info['n']} ticker(s), e.g. {_info['tickers'][:10]}")
    except Exception as e:
        log(f'US explosive crashed: {e}')
        data['meta']['errors'].append(f'us_explosive: {e}')
        data['explosive_us'] = EXISTING.get('explosive_us', [])
        data['explosive_stmt_cache'] = EXISTING.get('explosive_stmt_cache', {})   # v1.112.1: carry the cache forward on crash (don't wipe it)

    try:
        data['explosive_psx'] = _stage('explosive_psx', run_explosive, data['psx_candidates'], market='psx')
    except Exception as e:
        log(f'PSX explosive crashed: {e}')
        data['meta']['errors'].append(f'psx_explosive: {e}')
        data['explosive_psx'] = EXISTING.get('explosive_psx', [])

    try:
        data['rate_path'] = _stage('rate_path', fetch_rate_path)
    except Exception as e:
        log(f'Rate path crashed: {e}')
        data['rate_path'] = EXISTING.get('rate_path', [])

    # v1.11: COT index/commodity futures for US sector gating (SP500/Crude/10yr/VIX/NASDAQ)
    # v1.356.0: CFTC publishes weekly -- skip the fetch while the carried payload is <72h old.
    try:
        _cot_prev = EXISTING.get('cot_futures') or {}
        _cot_fresh = False
        try:
            _cot_ts = _cot_prev.get('as_of')
            if _cot_ts:
                _cot_age = (dt.datetime.now(dt.timezone.utc)
                            - dt.datetime.fromisoformat(str(_cot_ts).replace('Z', '+00:00'))).total_seconds()
                _cot_fresh = _cot_age < 72 * 3600
        except Exception:
            _cot_fresh = False
        if _cot_fresh and _cot_prev:
            data['cot_futures'] = _cot_prev
            log('  [COT] carried (fresh <72h) -- CFTC publishes weekly; next fetch when the stamp ages out')
        else:
            data['cot_futures'] = _stage('cot_futures', fetch_cot_futures)
    except Exception as e:
        log(f'COT futures crashed: {e}')
        data['meta']['errors'].append(f'cot_futures: {e}')
        data['cot_futures'] = EXISTING.get('cot_futures', {})

    # Wave C: US recession watch (FRED recession series + ForexFactory weekly calendar)
    try:
        data['recession'] = _stage('recession', fetch_recession)
        try:
            _cal429 = (data.get('recession') or {}).get('calendar') or []
            _enrich_econ_actuals(_cal429)              # v1.430.0: FRED actuals, in place
            merge_econ_announced(data, _cal429)        # v1.429.0
        except Exception as _eae:
            log('  [Econ announced] merge skipped: %s' % type(_eae).__name__)
            data['econ_announced'] = EXISTING.get('econ_announced', []) or []
    except Exception as e:
        log(f'Recession watch crashed: {e}')
        data['meta']['errors'].append(f'recession: {e}')
        data['recession'] = EXISTING.get('recession', {})

    # v1.435.0: US Growth strip -- OWN try (v1.434 lesson: never share a try with another stage)
    try:
        _gn_te = ((data.get('recession') or {}).get('signals') or {}).get('gdpnow', {}).get('value')
        data['us_growth'] = _stage('us_growth', lambda: build_us_growth(existing_gdpnow=_gn_te))
        if not (data['us_growth'] or {}).get('tiles'):
            data['us_growth'] = EXISTING.get('us_growth', data.get('us_growth') or {})
    except Exception as e:
        warn('[US growth] %s: %s' % (type(e).__name__, str(e)[:80]))
        data['us_growth'] = EXISTING.get('us_growth', {})


    # v1.11: Zacks #1/#2 grouped by GICS sector (fixed S&P universe + this run's survivors)
    # Cadence gate: Zacks ranks update ~weekly, but the scrape costs ~17 min. Skip it if the
    # last scrape is <7 days old and carry forward last-good (sector breadth is stable
    # intra-week); otherwise scrape and stamp the date.
    _prev_z = EXISTING.get('zacks_sectors', {}) or {}
    _prev_scraped = _prev_z.get('_scraped_utc') if isinstance(_prev_z, dict) else None
    _z_age = None
    _z_fresh = False
    if _prev_scraped:
        try:
            _z_age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(str(_prev_scraped).replace('Z', ''))).days
            _z_fresh = _z_age < 7
        except Exception:
            _z_fresh = False
    try:
        # P7 bootstrap: only honor the weekly skip when a per-ticker rank map ALREADY exists to
        # carry forward. On the first v1.57+ run EXISTING has no zacks_ranks (prior versions
        # discarded it), so force one scrape now to populate it — otherwise the ⚡Z chips can't
        # appear until the 7-day window happens to open. After this, the carry-forward works.
        _have_ranks = bool(EXISTING.get('zacks_ranks'))
        if _z_fresh and _have_ranks:
            log(f'  → Zacks scrape skipped (last scrape {_z_age}d ago, <7d) — carrying forward last-good')
            data['zacks_sectors'] = _prev_z
            data['zacks_ranks'] = EXISTING.get('zacks_ranks', {}) or {}
        else:
            if _z_fresh and not _have_ranks:
                log('  → Zacks per-ticker rank map absent (first v1.57 run) — forcing a one-time scrape to populate zacks_ranks (P7 bootstrap)')
            # v1.337.0: is_bank explosive_us rows exit the growth-screen pipeline into the separate
            # bank-model path before this point, so they were never in us_all_survivors and never got
            # a real Zacks fetch (measured: 8/9 had no rank at all). Merge them in explicitly.
            _bank_rows = [r for r in (data.get('explosive_us') or [])
                          if r.get('is_bank') or str(r.get('verdict', '')).upper().startswith('FINANCIAL')]
            data['zacks_sectors'], _zranks = fetch_zacks_sectors(us_all_survivors + _bank_rows)
            # P7: persist the per-ticker Zacks rank map, MERGING over the prior map so a name
            # not scraped this run keeps its last-good rank (the scrape is weekly / partial).
            data['zacks_ranks'] = {**(EXISTING.get('zacks_ranks') or {}), **(_zranks or {})}
            # Wave T3 sector rotation: change in each sector's Zacks #1/#2 breadth vs the prior
            # scrape (None when no prior). Computed only on a fresh scrape; on skip days the
            # carried-forward _prev_z already holds the last pct_top_chg.
            for _sec, _v in data['zacks_sectors'].items():
                if isinstance(_v, dict) and 'pct_top' in _v:
                    _pp = _prev_z.get(_sec) if isinstance(_prev_z, dict) else None
                    _prevpt = _pp.get('pct_top') if isinstance(_pp, dict) else None
                    _v['pct_top_chg'] = round(_v['pct_top'] - _prevpt, 1) if isinstance(_prevpt, (int, float)) else None
            data['zacks_sectors']['_scraped_utc'] = dt.datetime.utcnow().isoformat() + 'Z'
    except Exception as e:
        log(f'Zacks sectors crashed: {e}')
        data['meta']['errors'].append(f'zacks_sectors: {e}')
        data['zacks_sectors'] = EXISTING.get('zacks_sectors', {})
        data['zacks_ranks'] = EXISTING.get('zacks_ranks', {}) or {}

    # Phase 0-A: World LEI — 9-country OECD leading indicators via FRED
    try:
        data['world_lei'] = _stage('world_lei', fetch_world_lei)
        if not data['world_lei']:
            data['world_lei'] = EXISTING.get('world_lei', {}) or {}
    except Exception as _e:
        log(f'  [World LEI] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['world_lei'] = EXISTING.get('world_lei', {}) or {}

    # Phase 0-B: US Diffusion — 15-indicator economic diffusion index (PURE, no network)
    try:
        # ── v1.260.0 THE ACTUAL GAP ────────────────────────────────────────────────────────
        # The compass has scored 15 of 16 for weeks with 'Recession probability' missing, and I
        # spent versions blaming FRED and hunting sources. It was NEVER a fetch problem. The value
        # is fetched successfully EVERY run -- it just lands in data['recession']['signals']
        # ['recession_prob'] while compute_us_diffusion reads _v('recession_prob') from
        # data['macros']['us']. Two halves that never met: a plumbing gap, not a source failure.
        # No amount of swapping FRED for TradingView would ever have fixed it.
        # ORDER VERIFIED against main()'s real call order (per the pipeline rule): fetch_recession
        # runs at ~line 547, this at ~610, so the value exists here. Pure pass-through -- no new
        # fetch, no new source, no scoring rule changed; the indicator simply gets counted at last.
        try:
            _rp = ((data.get('recession') or {}).get('signals') or {}).get('recession_prob') or {}
            _rpv = _rp.get('value')
            if _rpv is not None and data.get('macros', {}).get('us') is not None:
                data['macros']['us']['recession_prob'] = float(_rpv)
                if _rp.get('date'):
                    data['macros']['us']['recession_prob_date'] = _rp['date']
                log(f"  [Compass] recession_prob {_rpv}% wired through from data['recession'] "
                    f"-> the 16th indicator can finally be scored")
        except Exception as _rpe:
            log(f'  [Compass] recession_prob pass-through skipped: {_rpe}')

        data['us_diffusion'] = compute_us_diffusion(
            data.get('macros', {}).get('us', {}),
            (data.get('macros', {}).get('metals', {}) or {}).get('walcl_change'))
        # v1.244.0 ECONOMY CLOCK -- both markets. Reads only macros already fetched above
        # (pipeline-safe: macros.us / macros.psx are populated well before this point, same
        # inputs compute_us_diffusion is reading on the line above). Wrapped, carries last-good.
        try:
            data['econ_clock'] = build_econ_clock(
                data.get('macros', {}).get('us', {}),
                data.get('macros', {}).get('psx', {}))
            if not data['econ_clock']:
                data['econ_clock'] = EXISTING.get('econ_clock', {}) or {}
        except Exception as _ec:
            log(f"  [Econ clock] crashed: {_ec}")
            data['econ_clock'] = EXISTING.get('econ_clock', {}) or {}
        if not data['us_diffusion']:
            data['us_diffusion'] = EXISTING.get('us_diffusion', {}) or {}
    except Exception as _e:
        log(f'  [US Diffusion] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['us_diffusion'] = EXISTING.get('us_diffusion', {}) or {}

    # Phase 0-C: Country RS — 9-country equity momentum + USD-adjusted return ranking
    try:
        data['country_rs'] = _stage('country_rs', fetch_country_rs)
        if not data['country_rs']:
            data['country_rs'] = EXISTING.get('country_rs', []) or []
    except Exception as _e:
        log(f'  [Country RS] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['country_rs'] = EXISTING.get('country_rs', []) or []

    # Phase 0-D: Sector Booming — reuses already-fetched zacks_sectors + cot_futures (PURE)
    try:
        _met_cot_arg = (data.get('macros') or {}).get('metals') or {}
        _us_quad = ((data.get('econ_clock') or {}).get('us') or {}).get('quadrant')
        # Wave S evidence pre-pass: compute the bottom-up GICS evidence FIRST (pure, foundation-only)
        # so the top-down engine's breadth + relative-strength signals read live data, not a flat 50.
        # (The final data['bottom_up_sectors'] is still built later WITH sector_booming for the agree flag.)
        try:
            _bu_evidence = build_bottom_up_sectors(data.get('foundation_universe', []))
        except Exception:
            _bu_evidence = []
        data['sector_booming'] = compute_sector_booming(
            data.get('zacks_sectors', {}),
            data.get('cot_futures', {}),
            metals_data=_met_cot_arg,
            regime_quad=_us_quad,
            sector_breadth=data.get('sector_breadth', {}),
            bottom_up=_bu_evidence,
        )
        if not data['sector_booming']:
            data['sector_booming'] = EXISTING.get('sector_booming', []) or []
    except Exception as _e:
        log(f'  [Sector Booming] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['sector_booming'] = EXISTING.get('sector_booming', []) or []
    # Wave S (v1.344.0): sector-selection verdict for both markets -- placed AFTER econ_clock (line above)
    # and sector_booming so every input already exists (pipeline-validation rule).
    try:
        data['sector_selection'] = build_sector_selection(data, EXISTING)
        # Wave R (v1.349.0): the narrative reads sector_selection -- placed immediately after it.
        try:
            data['psx_macro_narrative'] = build_psx_macro_narrative(data, EXISTING)
        except Exception as _pn:
            log(f'  [PSX narrative] crashed: {type(_pn).__name__}')
            data['psx_macro_narrative'] = EXISTING.get('psx_macro_narrative', {}) or {}
    except Exception as _se:
        log(f'  [Sector Selection] crashed: {type(_se).__name__}')
        data['sector_selection'] = EXISTING.get('sector_selection', {}) or {}
    # Wave T enrichment (v1.120.0): annotate each sector with score_delta + score_trend.
    # Compares today's score to EXISTING['sector_booming'] prior-run scores.
    # From run 2 onwards every sector carries a WoW direction. Graceful: first run
    # or missing prior → delta=None/trend=None (never fabricated, index falls back to '—').
    try:
        _prior_sb = {
            r['sector']: r['score']
            for r in (EXISTING.get('sector_booming') or [])
            if isinstance(r, dict) and r.get('sector') and r.get('score') is not None
        }
        _trended = 0
        for _r in data.get('sector_booming', []):
            if not isinstance(_r, dict):
                continue
            _sec = _r.get('sector')
            _now = _r.get('score')
            _prev = _prior_sb.get(_sec)
            if _now is not None and _prev is not None:
                _delta = round(_now - _prev, 1)
                _r['score_delta'] = _delta
                _r['score_trend'] = (
                    'rising'  if _delta >=  1.0 else
                    'falling' if _delta <= -1.0 else 'flat'
                )
                _trended += 1
            else:
                _r['score_delta'] = None
                _r['score_trend'] = None
        if _trended:
            log(f'  [Sector Booming delta] {_trended} sectors trended '
                f'(rising={sum(1 for r in data["sector_booming"] if r.get("score_trend")=="rising")}'
                f' falling={sum(1 for r in data["sector_booming"] if r.get("score_trend")=="falling")}'
                f' flat={sum(1 for r in data["sector_booming"] if r.get("score_trend")=="flat")})')
        else:
            log('  [Sector Booming delta] no prior run scores — delta pending next run')
    except Exception as _e:
        log(f'  [Sector Booming delta] skipped: {type(_e).__name__}: {str(_e)[:50]}')

    # Phase 2 (World ETF Engine): global sector theme from country_rs — no new network call
    try:
        data['global_theme'] = compute_global_sector_theme(data.get('country_rs', []))
        if not data['global_theme']:
            data['global_theme'] = EXISTING.get('global_theme', []) or []
    except Exception as _e:
        log(f'  [Global Theme] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['global_theme'] = EXISTING.get('global_theme', []) or []

    # Phase 3 (World ETF Engine): resolve top signals to buyable UCITS ETFs
    try:
        data['etf_recommendations'] = build_etf_recommendations(
            data.get('country_rs', []),
            data.get('sector_booming', []),
            data.get('global_theme', []),
            data.get('world_lei', {}),          # v1.215.0: leading-indicator gate inputs
            data.get('us_diffusion', {}),
        )
    except Exception as _e:
        log(f'  [ETF Recommendations] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['etf_recommendations'] = EXISTING.get('etf_recommendations', []) or []

    # v1.215.0: BOTTOM-UP booming sectors from the foundation winners' own sectors (cross-check to top-down).
    try:
        data['bottom_up_sectors'] = build_bottom_up_sectors(
            data.get('foundation_universe', []), data.get('sector_booming', []))
        if not data['bottom_up_sectors']:
            data['bottom_up_sectors'] = EXISTING.get('bottom_up_sectors', []) or []
    except Exception as _e:
        log(f'  [Bottom-up sectors] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['bottom_up_sectors'] = EXISTING.get('bottom_up_sectors', []) or []

    # v1.215.0: LIVE self-discovered UCITS-ETF momentum list -> replaces the frozen upload as the primary
    # Momentum-Watch. Falls back to the embedded _MOMENTUM_WATCH (from ETF_Universe.xlsx) if the live screen
    # returns nothing (segment outage), so the tab never goes empty. The file becomes an optional safety seed.
    try:
        _live_disc = _stage('etf_discovery', build_live_etf_discovery, min_aum_m=50.0)   # v1.215.3: $50M floor (aum is absolute currency; range $7.7M..$36.8bn) drops tiny/illiquid funds, keeps every real candidate
    except Exception as _e:
        log(f'  [ETF discovery] crashed: {type(_e).__name__}: {str(_e)[:60]} -- falling back to embedded list')
        _live_disc = []
    data['etf_live_discovery'] = _live_disc or EXISTING.get('etf_live_discovery', []) or []
    if data['etf_live_discovery']:
        data['etf_momentum_watch'] = data['etf_live_discovery']   # LIVE list is now the Momentum-Watch source
        # v1.303.0: publish an honest flag instead of an impossible number
        try:
            _bad = 0
            for _f in (data.get('etf_momentum_watch') or []):
                if not isinstance(_f, dict):
                    continue
                _ok, _why = _etf_perf_sane(_f)
                if not _ok:
                    _f['perf_suspect'] = _why
                    _f['live_ytd'] = None
                    _bad += 1
            if _bad:
                log(f'  [ETF watch] {_bad} fund(s) flagged perf_suspect (implausible return rejected)')
        except Exception as _pe:
            log(f'  [ETF watch] perf guard skipped: {type(_pe).__name__}')
        data['etf_momentum_source'] = 'live'
    else:
        data['etf_momentum_watch'] = _MOMENTUM_WATCH               # embedded fallback (ETF_Universe.xlsx seed)
        data['etf_momentum_source'] = 'embedded'
    data['etf_hydrogen_watch'] = _HYDROGEN_WATCH      # Hydrogen Economy Thematic Watch (5 funds, confirmed ISINs)
    data['etf_emerging_themes_watch'] = _EMERGING_THEMES_WATCH  # v1.143.0: AI/Cybersecurity/Quantum/Space (15 funds)
    data['etf_metals_etc_watch'] = _METALS_ETC_WATCH  # Physical metal ETCs (7 funds: Gold x2, Silver, Platinum, Palladium, Copper + a precious-metals basket)
    # v1.215.3: fill the live-discovery funds' holdings from the watchlists/look-through the dashboard already
    # carries (zero fetch), then probe justETF for the still-uncovered funds so the next version wires exact
    # holdings for the rest (Korea/Taiwan/semis leaders that aren't in any curated list).
    try:
        _attach_discovery_holdings(data, EXISTING)
    except Exception as _e:
        log(f'  [discovery holdings] pass crashed: {type(_e).__name__}: {str(_e)[:60]}')
    # v1.137.0: Pakistan UCITS proxy as its own top-level field, sourced from the existing
    # catalog entry (zero new data) -- for display on Tab 2 (Pakistan) and Tab 7 (Allocation
    # Zone), NOT Tab 16 (removed from there per owner instruction, that removal stands).
    _pak_cat = _ETF_CATALOG.get('Equity Pakistan') or []
    data['etf_pakistan_proxy'] = dict(_pak_cat[0]) if _pak_cat else None

    # Phase 6 (World ETF Engine) — enrich each recommendation with a live price via the
    # proven ISIN-filter resolver (uk/scan → USD, germany/scan fallback → EUR).
    # v1.132.0: extended beyond etf_recommendations to ALSO price the Hydrogen Watch
    # (4 funds) and Metals ETC Watch (3 funds) — same resolver, same cost class (7 more
    # ISINs, 1-2 TV scan requests each).
    # v1.137.0: Momentum-Watch (55 funds) is NOW ALSO included, reversing the v1.132.0
    # exclusion. That exclusion was about avoiding an unnecessary LIVE PRICE display for a
    # YTD-focused list -- but ticker and price come from the SAME resolver call (there is no
    # cheaper way to get one without the other), and the owner explicitly asked for a real,
    # verified ticker on every ETF section of the dashboard rather than 55 more hardcoded
    # strings to trust blindly. Live price is a side effect of getting the ticker honestly;
    # the Momentum-Watch table still leads with YTD, price/ticker are a secondary field.
    _n_priced = 0
    for _rec in (data.get('etf_recommendations') or []):
        _isin = (_rec.get('fund') or {}).get('isin')
        if not _isin:
            continue
        try:
            _lp = resolve_etf_live_price(_isin)
            if _lp:
                _rec['fund']['live_price']  = _lp['close']
                _rec['fund']['live_sym']    = _lp['sym']
                _rec['fund']['live_ccy']    = _lp['currency']
                _rec['fund']['live_exch']   = _lp['exchange']
                _rec['fund']['live_ytd']    = _lp.get('ytd')
                _rec['fund']['live_ret_1y'] = _lp.get('ret_1y')
                _rec['fund']['live_sma50']  = _lp.get('sma50')
                _rec['fund']['live_sma200'] = _lp.get('sma200')
                _rec['fund']['live_chg']    = _lp.get('change')  # v1.214.2: carry daily change for Live-Investment reuse
                _n_priced += 1
        except Exception:
            pass
    for _watch_list in (data.get('etf_hydrogen_watch') or []), (data.get('etf_emerging_themes_watch') or []), (data.get('etf_metals_etc_watch') or []), (data.get('etf_momentum_watch') or []), ([data['etf_pakistan_proxy']] if data.get('etf_pakistan_proxy') else []):
        for _w in _watch_list:
            _isin = _w.get('isin')
            if not _isin:
                continue
            try:
                _lp = resolve_etf_live_price(_isin)
                if _lp:
                    _w['live_price']  = _lp['close']
                    _w['live_sym']    = _lp['sym']
                    _w['live_ccy']    = _lp['currency']
                    _w['live_exch']   = _lp['exchange']
                    _w['live_ytd']    = _lp.get('ytd')
                    _w['live_ret_1y'] = _lp.get('ret_1y')
                    _w['live_sma50']  = _lp.get('sma50')
                    _w['live_sma200'] = _lp.get('sma200')
                    _w['live_chg']    = _lp.get('change')  # v1.214.2: daily change so reused Live-Investment holdings show Today
                    _n_priced += 1
            except Exception:
                pass
    if _n_priced:
        log(f'  [ETF live prices] {_n_priced} fund(s) priced via isin-filter resolver (recs + hydrogen + emerging-themes + metals + momentum watch) -- now incl. live YTD/1Y (v1.141.0)')
        try:
            _all_etf = []
            for _r in (data.get('etf_recommendations') or []):
                if isinstance(_r.get('fund'), dict): _all_etf.append(_r['fund'])
            for _lname in ('etf_hydrogen_watch','etf_emerging_themes_watch','etf_metals_etc_watch','etf_momentum_watch'):
                _all_etf.extend(data.get(_lname) or [])
            if data.get('etf_pakistan_proxy'): _all_etf.append(data['etf_pakistan_proxy'])
            _e200 = sum(1 for e in _all_etf if e.get('live_sma200') is not None)
            _e50 = sum(1 for e in _all_etf if e.get('live_sma50') is not None)
            log(f'  [MA probe] ETFs {_e200}/{len(_all_etf)} with SMA200, {_e50}/{len(_all_etf)} with SMA50 (confirms TV 50/200-DMA coverage for the ETF live-price lists before the index MA columns are wired)')
        except Exception:
            pass

    # v1.150.0: holdings auto-fill is RESTRICTED to a verified ISIN allowlist. The v1.149.0 blind
    # bare-symbol fetch collided once -- iShares Digital Security (Dist), LSE ticker 'SHLD', resolved on
    # stockanalysis to a US DEFENSE ETF (RTX/GD/LMT/NOC/PLTR): the WRONG fund. A confident-but-wrong
    # holding is worse than a blank one, so we no longer fetch by unverified symbol. Only the four ISINs
    # below -- each audited against the run that first filled it, holdings match the theme -- are fetched,
    # and each is PINNED to its confirmed bare symbol; if live_sym resolves to anything else we skip
    # (defence against a future ticker reassignment). Every other placeholder stays 'not sourced' until a
    # per-ISIN verified source (justETF / issuer factsheet) is wired -- never guessed.
    _EMH_HOLD_OK = {
        'IE00BF16M727': 'CIBR',   # First Trust Nasdaq Cybersecurity  -> PANW/FTNT/CRWD/CSCO/AVGO (cyber) ✓
        'IE00BLPK3577': 'WCBR',   # WisdomTree Cybersecurity          -> CRWD/DDOG/PANW/FTNT/TENB (cyber) ✓
        'IE000W8WMSL2': 'WQTM',   # WisdomTree Quantum Computing      -> QBTS/RGTI/IONQ/IBM      (quantum) ✓
        'IE000YU9K6K2': 'JEDI',   # VanEck Space Innovators           -> RDW/UMAC/LUNR/RKLB      (space)   ✓
    }
    _emh = data.get('etf_emerging_themes_watch') or []
    _h_fill = 0; _h_try = 0
    for _w in _emh:
        _want = _EMH_HOLD_OK.get(_w.get('isin'))
        if not _want:
            continue
        _sym = str(_w.get('live_sym') or '').split(':')[-1].strip().upper()
        if _sym != _want:          # resolved to an unexpected symbol -> refuse (collision guard)
            continue
        _h_try += 1
        try:
            _rows = fetch_etf_holdings(_sym)
        except Exception:
            _rows = []
        if _rows and len(_rows) >= 3:
            _top = sorted(_rows, key=lambda h: (h.get('weight') or 0), reverse=True)[:5]
            _w['holdings'] = ', '.join('%s %.1f%%' % (h['ticker'], h['weight']) for h in _top)
            _w['holdings_live'] = True
            _h_fill += 1
    if _h_try:
        log('  [Emerging holdings] verified-allowlist filled %d/%d funds (collision-safe; rest need justETF/issuer)' % (_h_fill, _h_try))

    # v1.151.0: iShares/BlackRock funds -> authoritative holdings CSV by ISIN (issuer's own daily file).
    # ISIN-keyed via the UK product-screener, so it cannot grab the wrong fund. Covers the 5 iShares UCITS
    # here that have no US sibling. Any failure leaves the card 'not sourced' -- never guessed.
    _ISHARES_EMH = {
        'IE00BG0J4C88',  # iShares Digital Security UCITS ETF (Acc)
        'IE00BG0J4841',  # iShares Digital Security UCITS ETF (Dist)
        'IE000C6ITGC8',  # iShares Quantum Computing UCITS ETF (Acc)
        'IE000A9G9R73',  # iShares Space Technologies UCITS ETF (Acc)
        'IE000X59ZHE2',  # iShares AI Infrastructure UCITS ETF (Acc)
    }
    _ish_fill = 0; _ish_try = 0
    for _w in _emh:
        if _w.get('isin') not in _ISHARES_EMH:
            continue
        _ish_try += 1
        try:
            _rows = fetch_ishares_holdings(_w.get('isin'))
        except Exception:
            _rows = []
        if _rows and len(_rows) >= 3:
            _top = sorted(_rows, key=lambda h: (h.get('weight') or 0), reverse=True)[:5]
            _w['holdings'] = ', '.join('%s %.1f%%' % (h['ticker'], h['weight']) for h in _top)
            _w['holdings_live'] = True
            _ish_fill += 1
    if _ish_try:
        log('  [Emerging holdings] iShares issuer-file filled %d/%d funds (BlackRock authoritative CSV by ISIN)' % (_ish_fill, _ish_try))

    # v1.215.13 (owner: "holdings with NAMES"): 20 emerging-theme funds carried DESCRIPTIONS posing as
    # holdings ("Global copper miners", "Smart-grid infrastructure") or "not sourced" -- placeholders
    # by the v1.215.10 principle. This pass fills them with REAL constituents: (1) reuse from this
    # run's momentum/discovery records (same ISIN, real names already fetched), (2) per-ISIN cache
    # carried in data, (3) fetch_justetf_holdings (proven 23/25). Baked description stays only as a
    # last-resort fallback when all three miss; success overwrites it. Explicit ISIN set = deterministic.
    try:
        _EMH_DESC = {  # descriptive/not-sourced baked holdings -> want real names
            'IE00BGV5VN51','IE00BK5BCD43','IE00BDVPNG13','LU1861132840',          # AI x4
            'IE00BYPLS672','IE0007Y8Y157',                                        # Cyber L&G, Quantum VanEck
            'IE0002PG6CA6','IE000FP52WM7','IE000UDFKE13','IE000ROSD5J6',          # Lithium/RareEarth x4
            'IE00BLCHJ534','IE000O7Q2E56','IE000J80JTL1','IE000CK5G8J7',          # Datacenter/Grid x4
            'IE00063FT9K6','IE0003Z9E2Y3','IE000UL6CLP7','LU1834983550',          # Copper x2, Silver, BasicRes
            'IE000NDWFGA5','IE0005YK6564','IE000M7V94E1',                          # Uranium x3
        }
        _ej_cache = dict((EXISTING or {}).get('_emh_hold_cache') or {})
        _reuse_map = {}
        for _lst in (data.get('etf_momentum_watch') or []), (data.get('etf_live_discovery') or []):
            for _r in _lst:
                _h = _r.get('holdings')
                if _r.get('isin') and isinstance(_h, str) and ',' in _h and _h.lower() not in ('not sourced',):
                    _reuse_map.setdefault(_r['isin'], _h)
        _ej_r = _ej_c = _ej_f = 0; _ej_budget = 25; _ej_still = []
        for _w in (data.get('etf_emerging_themes_watch') or []):
            _iz = _w.get('isin')
            if _iz not in _EMH_DESC or _w.get('holdings_live'):
                continue
            if _iz in _reuse_map:
                _w['holdings'] = _reuse_map[_iz]; _ej_r += 1; continue
            if _iz in _ej_cache:
                _w['holdings'] = _ej_cache[_iz]; _ej_c += 1; continue
            if _ej_f >= _ej_budget:
                _ej_still.append('%s (budget)' % _iz); continue
            _got = None
            try:
                _got = fetch_justetf_holdings(_iz)
            except Exception:
                _got = None
            _ej_f += 1
            if _got:
                _w['holdings'] = _got; _ej_cache[_iz] = _got
            else:
                _ej_still.append(_iz)
        data['_emh_hold_cache'] = _ej_cache
        log('  [Emerging holdings] theme-fund real-name fill: %d reuse + %d cache + %d justETF-fetched / %d targeted%s'
            % (_ej_r, _ej_c, _ej_f, len(_EMH_DESC), ('; still descriptive: ' + ', '.join(_ej_still)) if _ej_still else ''))
    except Exception as _e:
        log('  [Emerging holdings] theme-fund fill crashed: %s: %s' % (type(_e).__name__, str(_e)[:60]))

    # v1.148.0: Hydrogen-watch notes are COMPUTED LIVE from this run's own values (weakest-YTD +
    # smallest-AUM/liquidity), overwriting any hardcoded seed notes so a note can never go stale or
    # contradict the numbers beside it. A fund that is not actually the weakest or the smallest carries
    # no note. This runs after live prices resolve (above), so it reads live_ytd/size_m_eur for this run.
    _hyw = data.get('etf_hydrogen_watch') or []
    if _hyw:
        for _w in _hyw:
            _w['note'] = None
        def _hy_ytd(w):
            v = w.get('live_ytd')
            if not isinstance(v, (int, float)):
                v = w.get('ytd')
            return v if isinstance(v, (int, float)) else None
        _hy_rated = [w for w in _hyw if _hy_ytd(w) is not None]
        _hy_weak = min(_hy_rated, key=_hy_ytd) if len(_hy_rated) >= 2 else None
        if _hy_weak is not None:
            _hy_weak['note'] = 'Weakest YTD of the %d tracked (%.1f%%) this run' % (len(_hy_rated), _hy_ytd(_hy_weak))
        _hy_sized = [w for w in _hyw if isinstance(w.get('size_m_eur'), (int, float))]
        _hy_minsz = min((w['size_m_eur'] for w in _hy_sized), default=None)
        if _hy_minsz is not None:
            _hy_small = [w for w in _hy_sized if w['size_m_eur'] == _hy_minsz]
            _hy_liq = 'Smallest AUM (\u20ac%gm)%s -- check liquidity before trading' % (_hy_minsz, ' (tied)' if len(_hy_small) > 1 else '')
            for _w in _hy_small:
                _w['note'] = (_w['note'] + ' \u00b7 ' + _hy_liq) if _w.get('note') else _hy_liq
        log('  [Hydrogen notes] recomputed live: weakest=%s, smallest-AUM=%s' % (
            _hy_weak['name'][:20] if _hy_weak else 'n/a',
            ('%gm' % _hy_minsz) if _hy_minsz is not None else 'n/a'))

    # v1.142.0: World ETF Engine Phase 3 close-out -- (a) Results-tab live tracker vs ACWI
    # (reuses the same resolver/enrichment just completed above) and (b) the Stock->UCITS
    # equivalence bridge onto TCE HIGH + Explosive positive-verdict picks (both markets,
    # already fully computed earlier in this run). Both freeze-safe, data-only.
    track_etf_recommendations(data, EXISTING)
    attach_ucits_proxies(data)
    build_recommended_etf_trackers(data)
    try:
        _stage('live_investment', build_live_investment, data, EXISTING)  # v1.211.0: owner's live IBKR ETF portfolio
        build_live_lookthrough(data, EXISTING)  # v1.213.0: top-10 holdings + Asian analyst overlay + news + coverage probe
    except Exception as _e:
        log(f'  [Live Investment] call failed: {_e} — carrying last-good')
        if EXISTING.get('live_investment'): data['live_investment']=EXISTING['live_investment']

    # P7: join the per-ticker Zacks Rank onto the US Explosive records (US only — Zacks
    # has no PSX coverage). The dashboard renders a ⚡Z chip for rank #1/#2. Last-good
    # carry-forward in data['zacks_ranks'] means a weekly-skipped run still labels names.
    _zr = data.get('zacks_ranks') or {}
    for _r in data.get('explosive_us', []):
        if isinstance(_r, dict):
            _r['zacks_rank'] = _zr.get(_r.get('ticker'))

    # Smart-Money ETF Holdings Overlap (Part D) — weekly cadence (holdings barely move).
    _zacks_tops = []
    for _sec, _v in (data.get('zacks_sectors') or {}).items():
        if isinstance(_v, dict):
            _zacks_tops += _v.get('top_tickers', [])
    _prev_etf = EXISTING.get('etf_overlap', {}) or {}
    _etf_fresh = False; _etf_age = None
    _es = _prev_etf.get('_scraped_utc') if isinstance(_prev_etf, dict) else None
    if _es:
        try:
            _etf_age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(str(_es).replace('Z',''))).days
            # fresh only if young AND produced by the current scanner version — so any ETF-code
            # fix (new version) forces a one-time re-run instead of carrying forward stale output
            _etf_fresh = _etf_age < 7 and _prev_etf.get('_etf_code_ver') == _ETF_OVERLAP_CODE_VER  # v1.112.0 F4: decouple from SCAN_VERSION
        except Exception:
            _etf_fresh = False
    try:
        # v1.252.0 CACHE BUG (39s/run, every run, forever). The 7-day cache above could NEVER engage:
        # it required _prev_etf['stocks'] to be TRUTHY, but fetch_etf_holdings has been FMP-premium-gated
        # for months and returns 0/30, so 'stocks' is always [] -> falsy -> re-fetch all 30 dead ETFs
        # EVERY run at ~39s (15s of it literal time.sleep(0.5) x30). Proof it contributes nothing:
        # tce_us by src = {screen 15, whale 11, etf 0}. Cache the ATTEMPT, not just a successful result:
        # an empty list is still a valid, recent answer. isinstance(..., list) is True for [] and False
        # for a missing key, so a first run / a code-version bump still forces one real attempt.
        if _etf_fresh and isinstance(_prev_etf.get('stocks'), list):
            log(f"  → ETF holdings overlap skipped (last attempt {_etf_age}d ago, <7d; "
                f"{len(_prev_etf.get('stocks') or [])} consensus stocks) — carrying forward last-good")
            data['etf_overlap'] = _prev_etf
        else:
            _r12 = [{'etf': t, 'zacks_rank': 1} for t in TOP_ETFS]
            _hmap = {}; _src = []
            for _e in _r12:
                _tk = _e['etf']
                _hmap[_tk] = fetch_etf_holdings(_tk)
                _nm, _ytd, _y1 = ETF_META.get(_tk, (_tk, None, None))
                _m = fetch_etf_meta(_tk)
                _src.append({'ticker': _tk, 'name': _nm, 'ytd': _ytd, 'y1': _y1,
                             'y3': _m['y3'], 'expense': _m['expense']})
                time.sleep(0.5)
            _stocks = build_etf_overlap(_r12, _hmap, _zacks_tops)
            _got = sum(1 for v in _hmap.values() if v)
            data['etf_overlap'] = {
                '_scraped_utc': dt.datetime.utcnow().isoformat() + 'Z',
                '_scan_version': SCAN_VERSION,
                '_etf_code_ver': _ETF_OVERLAP_CODE_VER,
                'etfs_scanned': len(TOP_ETFS),
                'etfs_with_holdings': _got,
                'source_etfs': _src,
                'stocks': _stocks,
            }
            log(f'  ETF overlap: {_got}/{len(TOP_ETFS)} ETFs returned holdings -> top {len(_stocks)} consensus stocks')
    except Exception as e:
        log(f'ETF overlap crashed: {e}')
        data['meta']['errors'].append(f'etf_overlap: {e}')
        data['etf_overlap'] = EXISTING.get('etf_overlap', {})

    # Wave Z: Institutional fund consensus (double-confirmed smart money) — 7-day cache
    try:
        _prev_ic = EXISTING.get('inst_consensus', {})
        _ic_fresh = False
        try:
            _ic_age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(
                _prev_ic.get('_scraped_utc','2000-01-01T00:00:00').replace('Z',''))
            ).total_seconds() / 86400
            _ic_fresh = _ic_age < 7 and bool(_prev_ic.get('stocks'))
        except Exception:
            pass
        if _ic_fresh:
            log(f'  → Wave Z inst_consensus skipped (last scrape {_ic_age:.0f}d ago, <7d) — carrying forward last-good')
            data['inst_consensus'] = _prev_ic
        else:
            _fund_map = {}
            for _ft in TOP_INST_FUNDS:
                _h = fetch_fund_holdings(_ft)
                if _h:
                    _fund_map[_ft] = _h
                    log(f'  [Wave Z] {_ft}: {len(_h)} holdings')
            # v1.289.0 WAVE-Z v2 (root-caused: the box sat EMPTY forever because its ETF leg --
            # fetch_etf_holdings -- has been FMP-premium-dead 0/30 since ~v1.252, starving
            # compute_inst_consensus; the FUND leg works, 11 funds fetched live). The dead leg is
            # RETIRED and the second confirmation now comes from the 13F WHALE top holdings
            # (live, refreshing daily, ticker-stamped since v1.242): a stock is double-confirmed
            # smart money when >=2 institutional funds AND >=2 whales hold it.
            _whale_map = {}
            # v1.290.0 ORDER FIX (caught by the box's own instrumentation on its first live run:
            # whales_used=0 while whale_13f sat fresh in the same file): this Wave-Z block runs
            # BEFORE build_whale_13f in main(), so data['whale_13f'] doesn't exist yet at this
            # point in the run. Whale holdings are stable day-to-day -> read the freshly-built
            # dict if a future re-order ever provides it, else LAST RUN's from EXISTING.
            _wh_src = (data.get('whale_13f') or EXISTING.get('whale_13f') or {})
            for _w in (_wh_src.get('whales') or []):
                _wn = _w.get('name') or '?'
                for _h in (_w.get('top_holdings') or []):
                    _wt = _h.get('ticker')
                    if _wt:
                        _e2 = _whale_map.setdefault(_wt, {'n': 0, 'names': []})
                        if _wn not in _e2['names']:
                            _e2['n'] += 1
                            _e2['names'].append(_wn)
            _ic_stocks = []
            _fund_by_tk = {}
            for _fn, _hl in _fund_map.items():
                for _t2 in (_hl or []):
                    _e3 = _fund_by_tk.setdefault(str(_t2).upper(), {'n': 0, 'names': []})
                    if _fn not in _e3['names']:
                        _e3['n'] += 1
                        _e3['names'].append(_fn)
            for _tk2, _fe in _fund_by_tk.items():
                _we = _whale_map.get(_tk2)
                if _fe['n'] >= 2 and _we and _we['n'] >= 2:
                    _ic_stocks.append({
                        'ticker': _tk2,
                        'fund_count': _fe['n'], 'funds': _fe['names'][:6],
                        'whale_count': _we['n'], 'whales': _we['names'][:6],
                        'combined_score': min(100, _fe['n'] * 20 + _we['n'] * 12),
                    })
            _ic_stocks.sort(key=lambda r: -r['combined_score'])
            data['inst_consensus'] = {
                '_scraped_utc': dt.datetime.utcnow().isoformat() + 'Z',
                'funds_fetched': len(_fund_map),
                'whales_used': len(_wh_src.get('whales') or []),
                'basis': 'institutional funds x 13F whales (ETF-holdings leg retired: FMP-dead 0/30 since ~v1.252)',
                'stocks': _ic_stocks,
            }
            log(f'  [Wave Z v2] consensus: {len(_ic_stocks)} double-confirmed name(s) '
                f'({len(_fund_map)} funds x {len(_whale_map)} whale-held tickers)')
    except Exception as _e:
        log(f'  [Wave Z] inst_consensus crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['inst_consensus'] = EXISTING.get('inst_consensus', {})

    data['meta']['warnings'] = list(WARNINGS)

    # Carry IM3 forward from the last good data.json. The scanner doesn't SCORE IM3
    # (im3_score.py does, as a separate workflow step), but it rebuilds explosive_us/tce_us
    # from scratch each run with no 'im3' field — so it must re-attach two things or the
    # dashboard's IM3 panel blanks out on any run where the IM3 step is skipped:
    #   1. im3_explosive_tickers (the list) — so the workflow's change-detection has a real
    #      previous list to compare against and can skip re-scoring on stable days.
    #   2. the per-record 'im3' score dicts, keyed by ticker — so a skipped re-score keeps
    #      the prior scores. When names DO change, the IM3 step re-runs and overwrites these.
    if 'im3_explosive_tickers' not in data:
        data['im3_explosive_tickers'] = EXISTING.get('im3_explosive_tickers', [])

    # v1.286.0 ROOT CAUSE OF EVERY FULL RE-SCORE (owner's 15-minute-job audit, finally proven):
    # the workflow writes FOUR MORE state keys into data.json after scoring -- and this rebuild
    # DROPPED ALL OF THEM every scan. The trigger's staleness check defaults stale=True when
    # im3_last_scored_utc is missing, so EVERY run concluded 'stale' and full-rescored ~190
    # names (~2-4 min added to every job; the incremental logic never operated once; the
    # 'durable hash' fix was right but this deletion erased it before the trigger could read
    # it). Carrying them forward ends the loop: the next trigger finally sees a fresh clock +
    # matching hash -> genuinely incremental runs.
    for _wk in ('im3_last_scored_utc', 'im3_scorer_hash', 'im3_errors', 'im3_stamp_reason'):
        if _wk not in data and _wk in EXISTING:
            data[_wk] = EXISTING[_wk]

    # v1.49.0: carry IM3 forward per-MARKET so PSX scores survive a scanner-only run too.
    # (Pre-1.49 this looped US keys ONLY -> explosive_psx/tce_psx/psx_candidates were rebuilt
    #  with no 'im3' and the dashboard PSX IM3 column blanked to "Pending next scan" on any run
    #  where the separate im3_score.py step was skipped — the recurring PSX-blank bug.)
    # Grouped by market so a US/PSX ticker collision can never cross-attach a score.
    # v1.58.2: VERSION-AWARE carry-forward. A carried im3 dict is re-attached ONLY when its
    # 'ver' matches the CURRENT im3_score.py IM3_VERSION, so a record can never keep a
    # stale-engine grade. Background: a name that was deep-scored once and then drops out of
    # the daily.yml re-score set (explosive / financial / TCE-HIGH) is carried forward every
    # run forever — so a few NOT-EXPLOSIVE rows were still showing an old 2.9.x grade while
    # every other NOT-EXPLOSIVE row correctly showed "Pending". A stale-version score is now
    # DROPPED to None: if the name is still in the re-score set, the daily.yml self-heal
    # (missing_im3) re-scores it fresh this same run; if it isn't, it shows an honest
    # "Pending" instead of an old-engine number — consistent with its peers.
    # The current scorer version is parsed from im3_score.py (the same file daily.yml locates
    # it in) with a CLEAN regex — NOT daily.yml's `.strip('"\'')`, which leaves the trailing
    # inline comment attached; replicating that would mismatch EVERY ver and blank the whole
    # board (the v1.49.0 PSX-blank regression). If the version can't be read (file absent / no
    # match) _cur_im3_ver is None and EVERY score is carried = pre-1.58.2 behaviour, so this
    # guard can never itself blank a score.
    import re as _re_im3
    _cur_im3_ver = None
    try:
        with open('im3_score.py') as _vf:
            for _vl in _vf:
                _vm = _re_im3.match(r'\s*IM3_VERSION\s*=\s*[\'"]([^\'"]+)[\'"]', _vl)
                if _vm:
                    _cur_im3_ver = _vm.group(1); break
    except Exception:
        _cur_im3_ver = None

    def _im3_carry_ok(cached, live_px):
        """v1.272.3 CORPORATE-ACTION GUARD (owner's Explosive-tab audit find): SNDK/WDC/UMAC carried
        IM3 scores priced on a pre-split/spin share basis (scorer price vs live price drift 12-42%),
        making their IV / MoS chips wrong until re-scored. A cached score whose scoring-time price
        diverges >10% from today's live price is NOT carried -- the name returns to Pending and the
        30/run rotation re-scores it on the correct basis automatically."""
        try:
            cpx = (cached or {}).get('price')
            if cpx and live_px and abs(float(cpx) / float(live_px) - 1.0) > 0.10:
                return False
        except Exception:
            pass
        return True

    _t_carry = time.time()   # v1.287.0: untimed-block timer A
    _carried = 0; _dropped_stale = 0; _ca_skipped = []
    for _grp in (('explosive_us', 'tce_us'),
                 ('explosive_psx', 'tce_psx', 'psx_candidates')):
        _im3_prev = {}
        for _key in _grp:
            for _r in EXISTING.get(_key, []):
                if isinstance(_r, dict) and _r.get('im3') is not None and _r.get('ticker'):
                    _pv = _r['im3'].get('ver') if isinstance(_r['im3'], dict) else None
                    _sr = _r['im3'].get('scan_rev') if isinstance(_r['im3'], dict) else None
                    # v1.277.2 KEEP-LAST-GOOD (owner audit: AVGO/NEM/LLY went BLANK because this
                    # branch DELETED their 2.27.0 grades before the im3 step re-scored, and the
                    # re-score then crashed for them -- wipe-before-rescore destroyed last-good).
                    # A version/rev mismatch now MARKS the grade stale_ver instead of dropping it:
                    # the tab keeps showing the last real grade (with a 're-scoring' chip, index
                    # v5.240), the workflow's self-heal treats stale_ver as missing and re-scores,
                    # and a successful fresh score simply overwrites the mark.
                    if (_cur_im3_ver is not None and _pv != _cur_im3_ver) or                        (_sr is not None and _sr != IM3_SCAN_REV):
                        _dropped_stale += 1          # counter kept: now counts MARKED-stale, not deleted
                        if isinstance(_r['im3'], dict):
                            _r['im3'] = dict(_r['im3'], stale_ver=True)
                    # NOTE: grades with NO scan_rev belong to the canonical im3_score.py engine
                    # (adaptive per-name max, ver-gated above) -- carry them; they are current, not stale.
                    _im3_prev[_r['ticker']] = _r['im3']
        if not _im3_prev:
            continue
        for _key in _grp:
            for _r in data.get(_key, []):
                if isinstance(_r, dict) and _r.get('im3') is None and _r.get('ticker') in _im3_prev:
                    _cim = _im3_prev[_r['ticker']]
                    if not _im3_carry_ok(_cim, _r.get('price')):
                        _ca_skipped.append(_r['ticker']); continue  # v1.272.3 corporate-action guard
                    _r['im3'] = _cim; _carried += 1
    if _carried:
        log(f'  Carried forward {_carried} last-good IM3 score(s) onto rebuilt records')
    if _ca_skipped:
        log(f'  [IM3 guard] {len(_ca_skipped)} score(s) dropped for >10% price-basis drift (corporate action) -> re-score: ' + ', '.join(sorted(set(_ca_skipped))[:8]))
    if _dropped_stale:
        log(f'  Marked {_dropped_stale} stale-version IM3 score(s) (ver != {_cur_im3_ver}) -> re-score/Pending')

    # v1.274.1 WAVE ETF-X (MOVED): run AFTER im3 grades are attached/carried onto explosive_us
    # (the v1.274.0 call-site at ~18103 ran ~412 lines BEFORE the im3 carry-forward here, so every
    # top-scorer read grade=None -> 0 shortlisted. Pipeline-order rule: verify against runtime order.)
    try:
        data['etf_explosive_verified'] = build_explosive_etf_verified(data, EXISTING)
        if not (data['etf_explosive_verified'].get('etfs')) and (EXISTING.get('etf_explosive_verified') or {}).get('etfs'):
            data['etf_explosive_verified'] = EXISTING['etf_explosive_verified']
    except Exception as _e:
        log(f'  [ETF-X verified] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['etf_explosive_verified'] = EXISTING.get('etf_explosive_verified', {}) or {}

    _STAGE_MS['carry_forward'] = round((time.time() - _t_carry) * 1000)   # v1.287.0 timer A end
    _t_tail = time.time()   # v1.287.0: untimed-block timer B (radar + trailing builders to write)
    # v1.308.0 TAIL SPLIT: tail_builders is 100.9s -- a third of the run -- and nobody could say
    # WHICH feature owns it. These are plain checkpoint assignments (no calls moved or wrapped),
    # so they cannot change behaviour; _tail_mark() records the gap since the last checkpoint.
    _t_mark = [time.time()]
    def _tail_mark(name):
        _now = time.time()
        _STAGE_MS['tail.' + name] = round((_now - _t_mark[0]) * 1000)
        _t_mark[0] = _now
    # v1.309.0: the 'etf_and_prices' checkpoint was removed -- it fired immediately after the
    # timer started and so measured 0.0s by construction. The ETF pricing work runs BEFORE the
    # tail region entirely, so there was never anything for it to capture. Honest labels only.
    # v1.278.0 Zacks Strong-Buy Radar (uses the existing weekly zacks_ranks; zero new fetching)
    try:
        data['zacks_radar'] = build_zacks_radar(data, existing=EXISTING)
    except Exception as _e:
        log(f'  [Zacks radar] crashed: {type(_e).__name__}: {str(_e)[:60]}')
        data['zacks_radar'] = EXISTING.get('zacks_radar', {}) or {}

    def _json_safe(o):
        # NaN / Infinity are NOT valid JSON; the browser's JSON.parse rejects them.
        # Convert to None (null) recursively so data.json is spec-valid.
        if isinstance(o, float):
            return None if (math.isnan(o) or math.isinf(o)) else o
        if isinstance(o, dict):
            return {k: _json_safe(v) for k, v in o.items()}
        if isinstance(o, (list, tuple)):
            return [_json_safe(v) for v in o]
        return o

    # Wave T: append today's snapshot to the rolling daily history store (inside data.json).
    build_momentum_signals(data, EXISTING)
    append_history(data, EXISTING)
    compute_trends(data)
    # v1.188.0: M1 Step 4 -- the real-scored final buy list (additive, freeze-safe, carries last-good).
    try:
        _stage('m1_buylist', build_m1_buylist, data, EXISTING)
        build_psx_topdown(data, EXISTING)
        _stage('m2_watch', build_m2_watch, data, EXISTING)
        build_psx_m2_watch(data, EXISTING)  # v1.210.0: PSX turnaround watch, same process as US
        # v1.251.0 WAVE PSXD-A RETIRED -- the free path is a COVERAGE gap, proven not assumed.
        # The v1.249.0 [mettis diag] settled it in ONE run: /Equity returned HTTP 200, 68,663 bytes,
        # 197 anchors and only FIVE '(PSX:' tags; /latest returned ONE. The parser found 5 of the 5
        # that exist -- it is not broken, the page simply does not carry the names. Across two runs
        # the tagged tickers were GTYR/IMS/SFL/SHDT/STL, NONE of them in the 48-name PSX engine pool.
        # So the panel could only ever show companies the owner does not track. Retiring it rather
        # than leaving something that looks informative and is not -- and this is the call I committed
        # to in advance if the diag showed coverage rather than parse. Saves ~2.5s/run.
        # fetch_mettis_psx_events / classify_psx_headline / build_psx_events stay DEFINED + DORMANT
        # for a licensed feed to drop into (the D-PSX-HISTORY-RETIRE / build_psx_eod_history precedent).
        # PSXD-B (real insider dealing) remains a SPEND decision: Sarmaaya (PSX-authorised, has exactly
        # the page, robots-disallowed for scraping), PSX Market Data licensing, or Mettis MG-APIs.
        data['psx_events'] = {}
        build_m1m2_etf_proxies(data)        # v1.230.0 Wave ETF-M: UCITS proxies + GICS themes (needs m1_buylist/psx_topdown/m2_watch above)
        # v1.220.1: PB MUST run after the builders above -- first live run proved main()'s runtime
        # order differs from file order (the [PB] log fired 6 lines BEFORE [M1 buylist]/[PSX topdown],
        # so both books composed empty). Inside the same try: if the buy lists fail, PB carries
        # last-good via its own wrapper.
        build_pb_portfolio(data, EXISTING)
        # v1.238.0 FIX (pipeline order): Wave SEC now runs LAST -- it consumes M2/Multibagger/Explosive
        # (all built above) AND stamps the adverse sentinel onto the PB book, which is built one line up.
        # In v1.237.0 SEC ran BEFORE PB, so the sentinel stamped a book that didn't exist yet -> 0 flags.
        _tail_mark('radar_m1_m2')
        data['narratives'] = _stage('narratives', build_narratives, data, EXISTING)
        data['ep_signal'] = build_ep_signal(data)   # v1.302.0: the oil rule finally acts
        _tail_mark('narratives')
        data['metals_drivers'] = build_metals_drivers(data)   # v1.303.0: what moves metals
        # v1.299.0 NARRATIVE PROPAGATION (cross-tab rule): a stock sitting inside a live news
        # theme showed nothing on the Explosive / TCE / M2 / pink rows. Stamp the theme titles
        # onto every consuming record so each tab can badge it. Display-only, no scoring change.
        try:
            _nmap = {}
            for _th in ((data.get('narratives') or {}).get('themes') or []):
                if not _th.get('headlines'):
                    continue
                for _t9 in (_th.get('affected') or []):
                    _e9 = _nmap.setdefault(_t9, {'themes': [], 'sent': 0, 't1': 0, 'news': []})
                    _e9.setdefault('news', [])
                    if _th['title'] not in _e9['themes']:
                        _e9['themes'].append(_th['title'])
                        _e9['sent'] += (_th.get('net_sent') or 0)
                        _e9['t1'] += (_th.get('t1_count') or 0)
                        # v1.311.0 (owner: 'when i hover over the news tag, why cant it show the
                        # actual news items on tab 10?'). The badge carried theme NAMES only --
                        # the headline text existed on the theme but was never propagated, so the
                        # tooltip could not show a single story. Carry the top headlines (Tier-1
                        # first, then freshest) so the hover shows the actual news.
                        for _h9 in sorted((_th.get('headlines') or [])[:12],
                                          key=lambda _x: ((_x.get('tier') or 3),
                                                          (_x.get('age_d') if _x.get('age_d') is not None else 99)))[:3]:
                            _ttl = (_h9.get('t') or '').strip()
                            if _ttl and not any(_n.get('t') == _ttl for _n in _e9['news']):
                                _e9['news'].append({'t': _ttl[:150],
                                                    'src': _h9.get('src') or '',
                                                    'tier': _h9.get('tier'),
                                                    'age_d': _h9.get('age_d')})
                        _e9['news'] = _e9['news'][:5]
            _stamped = 0
            _pools = [data.get('explosive_us') or [], data.get('explosive_psx') or [],
                      data.get('tce_us') or [], data.get('tce_psx') or [],
                      ((data.get('zacks_radar') or {}).get('rows') or [])]
            for _lane in ('watch_turnaround', 'watch_quality', 'watch_speculative'):
                _pools.append(((data.get('m2_watch') or {}).get(_lane) or []))
            for _pool in _pools:
                for _r9 in _pool:
                    if isinstance(_r9, dict) and _r9.get('ticker') in _nmap:
                        _r9['narr'] = _nmap[_r9['ticker']]
                        _stamped += 1
            log(f'  [Narratives] theme badge stamped on {_stamped} record(s) across '
                f'{len(_pools)} pools ({len(_nmap)} distinct tickers in live themes)')
        except Exception as _ne:
            log(f'  [Narratives] badge propagation skipped: {type(_ne).__name__}')
        _tail_mark('narr_propagation')
        # v1.311.0 CATALYST CALENDAR (owner-approved 24 Jul: 'go ahead'). Call-site is AFTER
        # explosive/radar/m2/tce and after narrative propagation, so every pool it reads and every
        # signal it pairs with (incl. r['narr']) already exists -- verified against main()'s real
        # order, the pipeline-order rule. Isolated fetch: cannot regress any other engine.
        try:
            data['catalyst_calendar'] = build_catalyst_calendar(data)
        except Exception as _ce:
            data['catalyst_calendar'] = {'status': f'skipped: {type(_ce).__name__}', 'rows': [],
                                         'n_dated': 0, 'n_window': 0}
        _tail_mark('catalyst_calendar')
        # v1.311.0 OP/NP HONEST REASON (owner: 'Why NP/OP columns is empty for most of the stocks
        # in the tab?'). MEASURED, not assumed: all 48 zacks_radar pink rows carry op/np None BY
        # DESIGN -- they are built from the foundation SCREEN and company statements are never
        # downloaded for discovery names (v1.279.0) -- plus a tail of explosive rows whose fetched
        # statements genuinely publish no operating-profit line. A bare dash explained neither.
        # Every blank now states WHICH it is, so nothing on the tab is unexplained.
        try:
            _rad_ids = set()
            for _rr in ((data.get('zacks_radar') or {}).get('rows') or []):
                if isinstance(_rr, dict) and _rr.get('ticker'):
                    _rad_ids.add(_rr['ticker'])
            _nreason = 0
            for _pool in [data.get('explosive_us') or [],
                          ((data.get('zacks_radar') or {}).get('rows') or [])]:
                for _r8 in _pool:
                    if not isinstance(_r8, dict):
                        continue
                    if _r8.get('op_growth') is None or _r8.get('np_growth') is None:
                        if _r8.get('zacks_discovery') or _r8.get('ticker') in _rad_ids:
                            _r8['opnp_reason'] = 'screen row -- company statements are not downloaded for Zacks discovery names, so operating and net profit are honestly blank rather than guessed'
                        else:
                            _r8['opnp_reason'] = 'the fetched statements publish no operating-profit line for this filer, so the cell is left blank rather than filled with a substitute figure'
                        _nreason += 1
            log(f'  [Tab10] OP/NP blank reason stamped on {_nreason} row(s)')
        except Exception as _oe:
            log(f'  [Tab10] OP/NP reason pass skipped: {type(_oe).__name__}')
        _stage('whale_13f', build_whale_13f, data, EXISTING)     # v1.240.1 Wave 13F: run BEFORE the Wave-SEC Form-4 burst (fresh SEC connection)
        # v1.245.0 CROWDEDNESS cross-tab propagation: stamp the flag onto the M1 buy list (built
        # above at build_m1_buylist, so it exists here -- verified against main()'s call order, the
        # pipeline-order rule). Display/context only: never removes a name, never changes a score.
        try:
            _cw = ((data.get('whale_13f') or {}).get('crowd_by_ticker') or {})
            if _cw:
                _n = 0
                for _b in ((data.get('m1_buylist') or {}).get('buys') or []):
                    _c = _cw.get(_b.get('ticker'))
                    if _c:
                        _b['crowded'] = bool(_c.get('crowded'))
                        _b['crowd_holders'] = _c.get('n_holders')
                        _b['crowd_pct'] = _c.get('pct_whales')
                        if _c.get('crowded'):
                            _n += 1
                log(f"  [Crowdedness] stamped onto M1 buy list: {_n} crowded of "
                    f"{len(((data.get('m1_buylist') or {}).get('buys') or []))} buys")
        except Exception as _ce:
            log(f"  [Crowdedness] buy-list stamp skipped: {_ce}")
        _tail_mark('whale_and_crowding')
        # v1.415.0: SEC-filings daily cache -- the Form4/8-K crawl (~90s) runs once per 20h, not every scan.
        _sf_prev = str(EXISTING.get('sec_filings_as_of') or '')
        _sf_fresh = False
        try:
            if _sf_prev:
                _sf_age = (dt.datetime.utcnow() - dt.datetime.fromisoformat(_sf_prev.replace('Z', ''))).total_seconds()
                _sf_fresh = 0 <= _sf_age < 20 * 3600
        except Exception:
            _sf_fresh = False
        if _sf_fresh and (EXISTING.get('insider_events') or EXISTING.get('mat_events')):
            data['insider_events'] = EXISTING.get('insider_events', {}) or {}
            data['mat_events'] = EXISTING.get('mat_events', {}) or {}
            data['sec_meta'] = EXISTING.get('sec_meta', {}) or {}
            data['sec_filings_as_of'] = _sf_prev
            log('  [SEC filings] carried (fresh <20h; crawl skipped)')
            try:
                sec_filings_consumers(data)   # v1.416.0: stamps run on carried events -- no chip loss
            except Exception as _sce:
                log('  [SEC filings] consumer stamps on carry failed: %s' % type(_sce).__name__)
        else:
            _stage('sec_filings', build_sec_filings, data)         # v1.237.0 Wave SEC: Form 4 insider + 8-K events
            data['sec_filings_as_of'] = dt.datetime.utcnow().isoformat() + 'Z'
    except Exception as e:
        log(f'  [M1 buylist] failed: {e} -- carrying last-good')
        data['m1_buylist'] = EXISTING.get('m1_buylist', {})

    # Wave T: per-item shortlist performance tracker (first-seen date+price -> % since, per tab + sectors).
    # v1.209.0: moved AFTER the buy-list/M2-watch block so the new M2 lanes stamp entry prices the
    # SAME run they are flagged (previously ran before those payloads existed this run).
    # v1.310.0: this checkpoint brackets _stage('sec_filings', ...) exactly, so it always
    # reproduced that stage's own timer (proved: both read 57.4s to the decimal). It is not a
    # second cost -- it is the SAME window seen twice. Kept only as a boundary marker for the
    # tail breakdown, and named so nobody adds it to a total.
    _tail_mark('_same_as_sec_filings')
    track_shortlists(data, EXISTING)

    # v1.186.0: live sovereign-health feed (debt-to-GDP + Moody's rating, US + Pakistan). Context/display
    # only, freeze-safe; carries last-good on failure so it never blocks the run.
    try:
        _tail_mark('shortlist_tracker')
        fetch_countryeconomy(data, EXISTING)
    except Exception as e:
        log(f'  [countryeconomy] feed failed: {e} -- carrying last-good')
        data['countryeconomy'] = EXISTING.get('countryeconomy', {})

    # v1.312.0: TAB 19 RECOMMENDED ETFs & STOCKS — the dashboard's own curated multi-engine
    # buy list + live YTD/1Y/3Y/5Y. Call-site here (after im3 carry-forward, m1_buylist,
    # narratives, sec_filings) so every engine flag is present. Wrapped; carries last-good.
    try:
        build_recommended_tab(data, EXISTING)
    except Exception as e:
        log(f'  [Recommended tab] call failed: {e} — carrying last-good')
        data['recommended_tab'] = EXISTING.get('recommended_tab', {})

    # v1.313.0 GLOBAL DISCOVERY PACKAGE — all additive, wrapped, carry last-good.
    try:
        build_world_stocks(data, EXISTING)
    except Exception as e:
        log(f'  [World stocks] call failed: {e}')
        data['world_stocks'] = EXISTING.get('world_stocks', {})
    try:
        build_factor_fund_lines(data, EXISTING)
    except Exception as e:
        log(f'  [Factor fund-lines] call failed: {e}')
        data['factor_fund_lines'] = EXISTING.get('factor_fund_lines', {})
    try:
        build_policy_catalyst(data, EXISTING)
    except Exception as e:
        log(f'  [Policy catalyst] call failed: {e}')
        data['policy_catalyst'] = EXISTING.get('policy_catalyst', {})
    # v1.438.0: policy-radar price stamps MOVED HERE from mid-main (v1.437.0 mis-placement:
    # the stamp ran ~1,000 lines before build_policy_catalyst existed in data -> silent empty
    # early-return, 0/28 stamped, no warning -- the exact pipeline-order failure D-123/D-124
    # guard against, caught by the live payload audit). Runs AFTER the radar builder, own try.
    try:
        _stage('policy_px', lambda: stamp_policy_tickers(data))
    except Exception as e:
        warn('[policy px] %s: %s' % (type(e).__name__, str(e)[:80]))
    try:
        build_global_discovery(data, EXISTING)
    except Exception as e:
        log(f'  [Global discovery] call failed: {e}')
        data['global_discovery'] = EXISTING.get('global_discovery', {})
    try:
        build_quarterly_acceleration(data, EXISTING)
    except Exception as e:
        log(f'  [Quarterly accel] call failed: {e}')
        data['quarterly_acceleration'] = EXISTING.get('quarterly_acceleration', {})
        data['qaccel_store'] = EXISTING.get('qaccel_store', {})

    # v1.214.4: ONE-SHOT ETF-screener runner probe (gated ETF_SCREENER_PROBE, logging-only, freeze-safe).
    # Confirms whether TV can live-rank UCITS ETFs by return -> the live self-discovering engine that would
    # retire the quarterly ETF_Universe.xlsx upload. Wrapped so it can never block the run or the write.
    try:
        probe_etf_screener()
    except Exception as e:
        log(f'  [ETF screener probe] failed: {e} (ignored -- logging-only, no data touched)')

    try:
        with open(OUTPUT_PATH, 'w') as f:
            # v1.249.0: stage clock -> meta, so runtime is answerable from data.json alone
            try:
                _tot = round(time.time() - _RUN_T0, 1)
                _tail_mark('countryeconomy')
                _STAGE_MS['tail_builders'] = round((time.time() - _t_tail) * 1000)   # v1.287.0 timer B end
                # v1.308.0: report the memo's effect so the saving is visible, not asserted
                try:
                    data['meta']['etf_price_memo'] = dict(_ETF_PRICE_MEMO_STATS)
                except Exception:
                    pass
                # v1.289.0 TRUTH FIX: this persist previously sat at the EARLY meta-init anchor and
                # snapshotted the counters BEFORE run_explosive populated them -> data showed 0/0/0
                # forever and masqueraded as a dead evaluator. The evaluator was healthy all along
                # (it runs every scan; quarterlies come from the seeded cache). Snapshot at END.
                try:
                    data['sigt_stats'] = dict(_SIGT_STATS)
                except Exception:
                    pass
                # v1.342.0: persist the WHY, not just the aggregate count -- self-serve diagnosable
                # from data.json alone, no console-log access needed.
                try:
                    data['sigt_fail_reasons'] = dict(_SIGT_FAIL_REASONS)
                except Exception:
                    pass
                data['meta']['runtime_sec'] = _tot
                # v1.310.0 TIMING HIERARCHY FIX. _STAGE_MS mixed THREE levels in one flat dict:
                #   (a) ordinary stages, (b) tail_builders -- a PARENT window, and
                #   (c) tail.* -- its CHILDREN, which sum to exactly the parent (74.1s = 74.1s).
                # Any naive sum therefore counted the tail twice AND sec_filings twice, giving
                # sum 352.0s against a 278.9s run, i.e. an impossible 'untimed' of -73.1s.
                # The numbers were never wrong -- the aggregation was. Split the levels so a
                # total is always safe to take.
                _tail_children = {k: v for k, v in _STAGE_MS.items() if k.startswith('tail.')}
                _flat = {k: v for k, v in _STAGE_MS.items() if not k.startswith('tail.')}
                data['meta']['timings_ms'] = dict(sorted(_flat.items(), key=lambda kv: -kv[1]))
                if _tail_children:
                    data['meta']['timings_tail_ms'] = dict(sorted(
                        _tail_children.items(), key=lambda kv: -kv[1]))
                # sec_filings runs INSIDE the tail window, so it is already inside
                # tail_builders; exclude it when accounting for time, and report honestly.
                _accounted = sum(v for k, v in _flat.items() if k != 'sec_filings') / 1000.0
                data['meta']['timing_accounting'] = {
                    'runtime_sec': _tot,
                    'accounted_sec': round(_accounted, 1),
                    'unattributed_sec': round(_tot - _accounted, 1),
                    'note': ('timings_ms is flat and non-overlapping; timings_tail_ms breaks '
                             'tail_builders down and must NOT be added to the total; '
                             'sec_filings runs inside tail_builders and is excluded from '
                             'accounted_sec to avoid double counting'),
                }
                # v1.287.0: swallow detail rides meta (was print-only in the 403-walled log)
                if _SWALLOW_DETAIL:
                    data['meta']['swallowed'] = {k: dict(v) for k, v in _SWALLOW_DETAIL.items()}
                # v1.250.0: pool sizes beside the timings -- run_tce cost is per-NAME and Wave O
                # (v1.245.0) took the US pool 15 -> 26, so the timing is only readable next to this.
                data['meta']['pool_sizes'] = {
                    'tce_us': len(data.get('tce_us') or []),
                    'tce_psx': len(data.get('tce_psx') or []),
                    'sec_names': len(data.get('mat_events') or {}),
                }
                _top = list(data['meta']['timings_ms'].items())[:6]
                log(f"  [Timing] total {_tot}s"
                    + (('  |  slowest: ' + ', '.join(f'{k} {v/1000:.1f}s' for k, v in _top)) if _top else ''))
            except Exception:
                pass
            # v1.320.0: ESTATE/DOMICILE FLAG -- stamp the deterministic ISIN-derived estate status
            # onto every ETF row across every payload that displays funds (Tab 9/14/16/20). Objective
            # per-fund attribute, no fetch; renderers can colour SAFE-UCITS green / US-SITUS + KRX red.
            try:
                def _stamp_est(_t, _iz):
                    if isinstance(_t, dict) and _iz:
                        _e = _etf_estate_status(_iz)
                        _t['domicile'] = _e['domicile']; _t['estate_status'] = _e['estate_status']; _t['tax_note'] = _e['tax_note']
                        return 1
                    return 0
                _est_n = 0
                for _r in (data.get('etf_momentum_watch') or []):
                    _est_n += _stamp_est(_r, _r.get('isin'))
                for _r in (data.get('etf_live_discovery') or []):
                    _est_n += _stamp_est(_r, _r.get('isin'))
                for _r in (data.get('etf_recommendations') or []):
                    _f = _r.get('fund') or {}
                    _est_n += _stamp_est(_f, _f.get('isin'))
                for _r in ((data.get('etf_explosive_verified') or {}).get('etfs') or []):
                    _est_n += _stamp_est(_r, _r.get('isin'))
                for _tk in ('m1_etf_tracker', 'm2_etf_tracker', 'tce_etf_tracker', 'explosive_etf_tracker'):
                    _tv = data.get(_tk)
                    _rows = _tv.get('rows') if isinstance(_tv, dict) else _tv
                    for _r in (_rows or []):
                        _est_n += _stamp_est(_r, _r.get('isin'))
                # v1.321.0 (Component C): estate flag on Tab 17 held positions too (stocks carry ISIN)
                for _r in ((data.get('live_investment') or {}).get('holdings') or []):
                    _est_n += _stamp_est(_r, _r.get('isin'))
                # v1.321.0 (Component A-data): CANONICAL ETF-ROW fields so every tab colours YTD and shows
                # holdings identically -- ONE ytd_pct (live-preferred, else static) + n_holdings on every
                # ETF payload. Fixes the dual ytd/live_ytd ambiguity and the list/count/string holdings split.
                def _canon(_r):
                    if not isinstance(_r, dict):
                        return
                    _ly = _r.get('live_ytd'); _sy = _r.get('ytd')
                    _r['ytd_pct'] = _ly if isinstance(_ly, (int, float)) else (_sy if isinstance(_sy, (int, float)) else None)
                    _h = _r.get('holdings')
                    if isinstance(_h, list):
                        _r['n_holdings'] = len(_h)
                    elif _r.get('n_stocks') is not None:
                        _r['n_holdings'] = _r.get('n_stocks')
                    else:
                        _r.setdefault('n_holdings', None)
                _canon_n = 0
                for _key in ('etf_momentum_watch', 'etf_live_discovery'):
                    for _r in (data.get(_key) or []):
                        _canon(_r); _canon_n += 1
                for _r in (data.get('etf_recommendations') or []):
                    _canon(_r.get('fund') or {}); _canon_n += 1
                for _r in ((data.get('etf_explosive_verified') or {}).get('etfs') or []):
                    _canon(_r); _canon_n += 1
                for _tk in ('m1_etf_tracker', 'm2_etf_tracker', 'tce_etf_tracker', 'explosive_etf_tracker'):
                    _tv = data.get(_tk); _rows = _tv.get('rows') if isinstance(_tv, dict) else _tv
                    for _r in (_rows or []):
                        _canon(_r); _canon_n += 1
                log(f'[Estate flag] stamped {_est_n} rows; [Canon ETF] normalised {_canon_n} rows (ytd_pct + n_holdings)')
            except Exception as _ee:
                log(f'[Estate flag] pass skipped: {_ee}')
            # v1.323.0 (Component D): consolidate engine agreement into the Recommended verdict
            try:
                build_recommended(data)
                _stamp_rebalance_top_picks(data)  # v1.334.0: pipeline-order-safe, runs after recommended exists
            except Exception as _rce:
                log('[Recommended] pass skipped: %s' % _rce)
            # v1.353.0 WAVE Z: independent of recommended; runs at the tail with the other overlays.
            try:
                data['wave_z'] = build_wave_z(data, EXISTING)
            except Exception as _wze:
                log('[Wave Z] skipped: %s' % type(_wze).__name__)
                data['wave_z'] = EXISTING.get('wave_z', {}) or {}
            # v1.361.0: real ETF holdings coverage first (cached 5d), then MOAT reads it.
            try:
                data['moat_cover'] = build_moat_cover(EXISTING)
            except Exception as _mce:
                log('[MOAT cover] skipped: %s' % type(_mce).__name__)
                data['moat_cover'] = EXISTING.get('moat_cover', {}) or {}
            try:
                stamp_trend_ladder(data)   # v1.422.0 (display-only)
            except Exception as _tle:
                log('  [Trend Ladder] skipped: %s' % type(_tle).__name__)
            # v1.417.0: persist the recorded statement figures so the next run reads, not refetches.
            try:
                _ss = _stmt_store()
                data['sec_stmt_store'] = {'cfo_cpat': _ss['cfo_cpat'], 'qrows': _ss['qrows']}
            except Exception:
                data['sec_stmt_store'] = EXISTING.get('sec_stmt_store', {}) or {}
            # v1.397.0: shared ETF-holdings index (one source every tab reads).
            try:
                data['etf_holdings_index'] = build_etf_holdings_index(data)
                log('  [ETF index] %d stocks across %d ETFs'
                    % (data['etf_holdings_index']['n_stocks'], data['etf_holdings_index']['n_etfs']))
            except Exception as _eie:
                log('[ETF index] skipped: %s' % type(_eie).__name__)
                data['etf_holdings_index'] = EXISTING.get('etf_holdings_index', {}) or {}
            # v1.398.0 PHASE 2: annotate already-built discovery rows with the ETF-holder signal.
            try:
                _hidx = (data.get('etf_holdings_index') or {}).get('by_stock') or {}
                if _hidx:
                    for _lk in ('explosive_us', 'multibagger_us'):
                        _lst = data.get(_lk)
                        if isinstance(_lst, list):
                            for _r in _lst:
                                if isinstance(_r, dict) and _r.get('ticker'):
                                    _hh = _hidx.get(str(_r['ticker']).upper()) or []
                                    _r['etf_holders'] = _hh[:8]
                                    _r['etf_holder_count'] = len(_hh)
                    # v1.408.0: Tab 19 overlap -- stamp held_via on recommended stocks already inside the
                    # owner's held funds (real constituent sets: EDGAR twins + the 3x single-stock notes).
                    try:
                        _cov = ((data.get('moat_cover') or {}).get('by_etf')) or {}
                        _held_sets = {}
                        for _hf, _tw in (('SMH', 'SMH'), ('ITWN', 'EWT'), ('FLXK', 'EWY'), ('KSTR', 'KSTR')):
                            if _cov.get(_tw):
                                _held_sets[_hf] = set(_cov[_tw])
                        _held_sets['AMD3'] = {'AMD'}
                        _held_sets['TSM3'] = {'TSM'}
                        # v1.412.0: ADR alias -- the Taiwan fund holds 2330 (TSM's local line)
                        for _hf2, _ss2 in list(_held_sets.items()):
                            if 'TSM' in _ss2 or '2330' in _ss2:
                                _ss2.update({'TSM', '2330'})
                        _rst = (data.get('recommended') or {}).get('stocks')
                        if isinstance(_rst, list) and _held_sets:
                            for _r in _rst:
                                if isinstance(_r, dict) and _r.get('ticker'):
                                    _hv = sorted(_hf for _hf, _ss in _held_sets.items() if str(_r['ticker']).upper() in _ss)
                                    if _hv:
                                        _r['held_via'] = _hv
                    except Exception:
                        pass
                    # v1.406.0: global_discovery is {'picks': [...]} -- annotate its picks too.
                    _gd = (data.get('global_discovery') or {}).get('picks')
                    if isinstance(_gd, list):
                        for _r in _gd:
                            if isinstance(_r, dict) and _r.get('ticker'):
                                _hh = _hidx.get(str(_r['ticker']).upper()) or []
                                _r['etf_holders'] = _hh[:8]
                                _r['etf_holder_count'] = len(_hh)
                    log('  [ETF index] annotated discovery rows')
            except Exception as _ap:
                log('[ETF index] annotate skipped: %s' % type(_ap).__name__)
            # v1.357.0 WAVE MOAT: after wave_z (reads its fund_cache) and all engine outputs.
            try:
                data['moat'] = build_moat_universe(data, EXISTING)
                try:
                    stamp_trend_moat_only(data)   # v1.426.0: stamps must land AFTER the rebuild
                except Exception as _tme:
                    log('  [Trend Ladder] moat re-stamp skipped: %s' % type(_tme).__name__)
            except Exception as _moe:
                log('[MOAT] skipped: %s' % type(_moe).__name__)
                data['moat'] = EXISTING.get('moat', {}) or {}
            # v1.350.0: TipRanks overlay -- AFTER recommended exists (it reads the list), before stamps/write.
            try:
                data['tipranks'] = fetch_tipranks_overlay(data, EXISTING)
            except Exception as _tre:
                log('[TipRanks] overlay skipped: %s' % type(_tre).__name__)
                data['tipranks'] = EXISTING.get('tipranks', {}) or {}
            # v1.348.0: self-serve freshness stamps at the FINAL write -- every stage has run and
            # recorded its timing by this point (relocated from mid-main, where cot_futures had not
            # yet run and its stamp could never fire -- placement caught by the pipeline-order rule).
            try:
                _asof_now = dt.datetime.now(dt.timezone.utc).isoformat()
                _tms = (data.get('meta') or {}).get('timings_ms') or {}
                if isinstance(data.get('cot_futures'), dict) and _tms.get('cot_futures'):
                    data['cot_futures']['as_of'] = _asof_now
                if isinstance(data.get('metals_drivers'), dict) and _tms.get('metals'):
                    data['metals_drivers']['as_of'] = _asof_now
                if isinstance((data.get('macros') or {}).get('metals'), dict) and _tms.get('metals'):
                    data['macros']['metals']['as_of'] = _asof_now
                if isinstance(data.get('estimate_history'), dict):
                    data['estimate_history']['as_of'] = _asof_now
            except Exception:
                pass
            _t_json = time.time()   # v1.287.0 timer C (log-only; file closes before meta could carry it)
            # v1.296.0: minified write (separators, no indent) -- indent=2 spent ~5.6MB of the
            # file on whitespace alone; JSON.parse reads it identically. ~12MB -> ~6.3MB.
            # v1.431.0: payload soft-ceiling sentinel. Serialize once; if over the ceiling, record the
            # breach (with the top-3 largest keys) into meta.warnings -- which by this point is a COPY of
            # WARNINGS (set upstream), so the payload dict is appended directly -- then re-serialize so the
            # warning ships in the same run's data.json. Normal (under-ceiling) runs keep a single pass.
            _ser = _round_floats(_json_safe(data))
            _txt = json.dumps(_ser, separators=(',', ':'), default=str, allow_nan=False)
            if len(_txt) > PAYLOAD_SOFT_CEILING_MB * 1e6:
                try:
                    _big = sorted(((_k, len(json.dumps(_v, separators=(',', ':'), default=str)))
                                   for _k, _v in _ser.items()), key=lambda _x: -_x[1])[:3]
                    _msg = ('data.json %.2f MB exceeds the %.1f MB soft ceiling -- largest: %s'
                            % (len(_txt) / 1e6, PAYLOAD_SOFT_CEILING_MB,
                               ', '.join('%s %dKB' % (_k, _s // 1024) for _k, _s in _big)))
                    warn(_msg)
                    data['meta']['warnings'].append(_msg)
                    _ser = _round_floats(_json_safe(data))
                    _txt = json.dumps(_ser, separators=(',', ':'), default=str, allow_nan=False)
                except Exception as _sce:
                    log('  [size sentinel] skipped: %s' % type(_sce).__name__)
            f.write(_txt)
        log(f'data.json written ({OUTPUT_PATH.stat().st_size} bytes)'
            + (f' in {time.time() - _t_json:.1f}s' if '_t_json' in dir() else ''))
    except Exception as e:
        log(f'Failed to write data.json: {e}')
        sys.exit(1)

    log('=' * 60)
    log('Scanner completed')
    log(f'  Hard errors: {len(data["meta"]["errors"])}')
    log(f'  Warnings (degraded data): {len(data["meta"]["warnings"])}')
    for w in data['meta']['warnings']:
        log(f'      - {w}')
    if _SWALLOWED:                                   # v1.112.0 (F6): surface swallowed exceptions
        log(f'  Swallowed (silent) exceptions: {dict(sorted(_SWALLOWED.items()))}')
        data['meta']['swallowed'] = dict(_SWALLOWED)
    log(f'  US macros: '
        f'{len([k for k in data["macros"]["us"] if not k.endswith(("_date","_source"))])}')
    log(f'  PSX macros: '
        f'{len([k for k in data["macros"]["psx"] if not k.endswith(("_date","_source"))])}')
    log(f'  KSE-100: {data["macros"]["psx"].get("kse100")} '
        f'({data["macros"]["psx"].get("kse100_source")}, '
        f'as of {data["macros"]["psx"].get("kse100_date")})')
    log(f'  WTI/Brent: {data["macros"]["us"].get("wti")} / '
        f'{data["macros"]["us"].get("brent")} '
        f'({data["macros"]["us"].get("wti_source")}, '
        f'as of {data["macros"]["us"].get("wti_date")})')
    log(f'  US candidates: {len(data["us_candidates"])}')
    log(f'  PSX candidates: {len(data["psx_candidates"])}')
    log(f'  US TCE HIGH: '
        f'{sum(1 for r in data["tce_us"] if r.get("tier") == "HIGH")}')
    log(f'  PSX TCE HIGH: '
        f'{sum(1 for r in data["tce_psx"] if r.get("tier") == "HIGH")}')
    log(f'  Recession: {data.get("recession",{}).get("risk","—")} '
        f'(score {data.get("recession",{}).get("score","—")}, '
        f'{len(data.get("recession",{}).get("calendar",[]))} cal events)')
    log('=' * 60)


if __name__ == '__main__':
    main()
